#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define MLX91219_AIN0_GPIO 17
#define MLX91219_SCL_GPIO 18
#define MLX91219_SDA_GPIO 19
#define SAMPLE_RATE_MS 500
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_MS)
#define SENSITIVITY_VOLTS_PER_A 40.0
#define ZERO_CURRENT_OFFSET_VOLTS -0.5
#define ZERO_CURRENT_OFFSET_AMPS 0.0
#define SAMPLE_SIZE 16
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_MS)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_ads1115();
int read_ads1115(int16_t *adc_value);
float convert_to_current(int16_t adc_value);
void log_current(float current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int ads1115_gain;
    int ads1115_sample_rate;
    int ads1115_sample_period_us;
    int mlx91219_gpio;
    int mlx91219_sda_gpio;
    int mlx91219_scl_gpio;
} config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the ADS1115
int init_ads1115() {
    // Configure ADS1115 for single-shot mode
    char config_data[2] = {0x80, 0x00}; // Configure register
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], config_data + 1, 1) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Configure AIN0 for single-ended mode
    char config_data_ain0[2] = {0x80, 0x00}; // Configure register
    if (i2cWriteI2CBlockData(i2c_handle, config_data_ain0[0], config_data_ain0 + 1, 1) < 0) {
        fprintf(stderr, "Error writing to AIN0 config register\n");
        return -1;
    }

    // Configure gain
    char config_data_gain[2] = {0x80, 0x00}; // Configure register
    if (i2cWriteI2CBlockData(i2c_handle, config_data_gain[0], config_data_gain + 1, 1) < 0) {
        fprintf(stderr, "Error writing to gain config register\n");
        return -1;
    }

    // Configure sample rate
    char config_data_sample_rate[2] = {0x80, 0x00}; // Configure register
    if (i2cWriteI2CBlockData(i2c_handle, config_data_sample_rate[0], config_data_sample_rate + 1, 1) < 0) {
        fprintf(stderr, "Error writing to sample rate config register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the ADS1115
int read_ads1115(int16_t *adc_value) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) < 0) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    *adc_value = (int16_t)((buffer[1] << 8) | buffer[0]);
    return 0;
}

// Function to convert ADC value to current
float convert_to_current(int16_t adc_value) {
    float current = (float)adc_value * SENSITIVITY_VOLTS_PER_A / 2.0;
    return current;
}

// Function to log current to the console
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Current: %.4f A\n", timestamp, current);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MLX91219_GPIO, PI_OUTPUT);
    gpioSetMode(MLX91219_SCL_GPIO, PI_OUTPUT);
    gpioSetMode(MLX91219_SDA_GPIO, PI_INPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t adc_value;
    float current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&adc_value) < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to current
        current = convert_to_current(adc_value);

        // Log current
        log_current(current);

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

