int read_analog_sensor() {
    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) {
        return -1; // Indicate error
    }
    return adc_value;
}

// Map ADC value to temperature (10-40°C)
float map_to_temperature(int adc_value) {
    // Linear mapping (example: 0-1023 -> 10-40°C)
    float temperature = (float)adc_value / 1023.0 * 40.0 + 10.0;
    return temperature;
}

// Log data to CSV file
void log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Flame Detection System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read analog sensor
        int adc_value = read_analog_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading analog sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Map ADC value to temperature
        float temperature = map_to_temperature(adc_value);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        log_data(current_time, 0, temperature);

        // Check for flame detection
        if (temperature < FLAME_THRESHOLD) {
            printf("Flame detected!\n");
            log_data(current_time, 1, temperature);
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

