#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define HEAT_SENSOR_PIN 23
#define BUZZER_PIN 27

// Define constants
#define DEBOUNCE_TIME_MS 50
#define BUZZER_DURATION_SEC 2
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define SAMPLE_RATE_MS 100
#define SAMPLE_DURATION_MS 100
#define SAMPLE_COUNT (SAMPLE_RATE_MS * SAMPLE_DURATION_MS)

// Define ADC channel
#define ADC_CHANNEL 0

// Define temperature thresholds
#define TEMPERATURE_THRESHOLD_LOW 60.0
#define TEMPERATURE_THRESHOLD_HIGH 80.0

// Global variables
static volatile int running = 1;
static int flame_detected = 0;
static int temperature_above_threshold = 0;
static int flame_event_time = 0;
static int flame_event_count = 0;
static int i2c_handle;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int read_adc(int channel);
float convert_adc_to_temperature(int adc_value);
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void flame_detected_callback(int gpio, int level, uint32_t tick);

// Flame sensor ISR callback
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Rising edge
        flame_detected = 1;
        flame_event_time = tick;
        flame_event_count++;
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(HEAT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to read ADC value from the specified channel
int read_adc(int channel) {
    int adc_value = i2cReadWordData(i2c_handle, channel);
    if (adc_value < 0) {
        fprintf(stderr, "I2C read failed: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

// Function to convert ADC value to temperature
float convert_adc_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // and a gain of 4.096V/1024 (assuming 10-bit ADC)
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float temperature = (voltage - 0.5) * 100.0; // Assuming 0.5V offset
    return temperature;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioDelay(BUZZER_DURATION_SEC * 1000); // Wait for 2 seconds
    deactivate_buzzer();
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("fire_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the buzzer
void deregister_isr() {
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_detected_callback, NULL);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Register ISR for flame sensor
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_detected_callback, NULL);

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);

        // Check for flame detection
        if (flame_detected) {
            if (temperature > TEMPERATURE_THRESHOLD_HIGH) {
                log_event("Flame detected!");
                activate_buzzer();
                temperature_above_threshold = 1;
                flame_event_time = 0;
                flame_event_count = 0;
            }
        } else {
            if (temperature > TEMPERATURE_THRESHOLD_LOW && temperature < TEMPERATURE_THRESHOLD_HIGH) {
                if (temperature_above_threshold == 0) {
                    flame_event_time = 0;
                    flame_event_count = 0;
                    flame_detected = 0;
                    temperature_above_threshold = 0;
                }
                flame_event_count++;
            }
        }

        // Debounce
        if (flame_event_count > DEBOUNCE_TIME_MS) {
            flame_event_time = 0;
            flame_event_count = 0;
            flame_detected = 0;
            temperature_above_threshold = 0;
        }

        // Sample and log
        if (flame_detected) {
            if (flame_event_time == 0) {
                flame_event_time = time(NULL);
            }
            flame_event_count++;
        } else {
            flame_event_time = 0;
            flame_event_count = 0;
        }

        gpioDelay(SAMPLE_DURATION_MS);
    }

    // Cleanup
    deregister_isr();
    deactivate_buzzer();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

