#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define ADC scaling factors
#define ADC_SCALE_FACTOR 1024.0 // 10-bit ADC

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int log_data(float temperature, int flame_status);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    return (adc_value / ADC_SCALE_FACTOR) * 40.0 - 40.0;
}

// Log data to CSV file
int log_data(float temperature, int flame_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, flame_status);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,Flame\n");
    }
    rewind(log_file);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_temperature(adc_value);

        int flame_status = gpioRead(FLAME_SENSOR_PIN);
        if (flame_status < 0) {
            fprintf(stderr, "Error reading flame sensor\n");
            continue; // Skip to the next iteration
        }

        if (flame_status == 1) {
            printf("Flame detected!\n");
        } else {
            printf("No flame\n");
        }

        if (log_data(temperature, flame_status) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

