#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49
#define SENSOR1_REG 0x00
#define SENSOR2_REG 0x01
#define SENSOR1_DATA_LEN 2
#define SENSOR2_DATA_LEN 2
#define SAMPLE_RATE 100 // ms
#define SAMPLE_PERIOD (SAMPLE_RATE * 1000) // us
#define LOG_FILE "audio_log.txt"
#define ERROR_VALUE -999.0

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_data;
    float sound_pressure_level;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int addr);
int read_sensor_data(int handle, int reg, int data_len, sensor_data_t *data);
float convert_to_sound_pressure(int16_t raw_data, float sensitivity);
void log_data(FILE *fp, float avg_sound_pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read data from sensor
int read_sensor_data(int handle, int reg, int data_len, sensor_data_t *data) {
    char buf[data_len];
    int result = i2cReadI2CBlockData(handle, reg, buf, data_len);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device at address 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Convert raw data to sound pressure level
float convert_to_sound_pressure(int16_t raw_data, float sensitivity) {
    // Assuming a linear relationship between raw data and sound pressure
    // This is a simplified example; a more accurate model would be needed for a real application.
    return (float)raw_data / sensitivity;
}

// Log data to file
void log_data(FILE *fp, float avg_sound_pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f dB\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_sound_pressure);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor1_data, sensor2_data;
    float avg_sound_pressure;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, SENSOR1_REG, SAMPLE_PERIOD, &sensor1_data) == 0) {
            if (read_sensor_data(i2c_handle2, SENSOR2_REG, SAMPLE_PERIOD, &sensor2_data) == 0) {
                // Convert data to sound pressure
                sensor1_data.raw_data = sensor1_data.raw_data * 2; // Assuming 2x sensitivity
                sensor2_data.raw_data = sensor2_data.raw_data * 2; // Assuming 2x sensitivity

                // Calculate average sound pressure level
                avg_sound_pressure = (float)sensor1_data.raw_data + (float)sensor2_data.raw_data;
                log_data(log_file, avg_sound_pressure);
            } else {
                fprintf(stderr, "Error reading sensor 2 data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1 data\n");
        }

        gpioDelay(SAMPLE_PERIOD); // Delay for sampling period
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

