    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read data from sensor
