    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc1_value = read_adc(ADC_CHANNEL);
        int adc2_value = read_adc(ADC_CHANNEL);

        if (adc1_value == -1 || adc2_value == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate RMS values
        int mic1_rms = calculate_rms(adc1_value);
        int mic2_rms = calculate_rms(adc2_value);

        // Log events
        time_t current_time = time(NULL);
        log_event(current_time, mic1_rms, mic2_rms);

        // Control LED
        if (mic1_rms > THRESHOLD && mic2_rms > THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);   // Wait for 500ms
            control_led(0); // Turn off LED
        }

        // Wait for the next window
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Audio monitoring stopped.\n");
    return 0;
}

