#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MLX91204_ADDR 0x48
#define LED_GPIO 17
#define THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_current_buffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int channel);
float convert_to_current(int raw_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX91204_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from the ADS1115
int read_ads1115(int channel) {
    char buf[2];
    int result;

    // Read the single-ended channel A0 value
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ADS1115: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert to a signed 16-bit integer
    int16_t signed_value = (int16_t)raw_value;

    // Scale the value to the range 0-4095 (assuming +/- 4.5V range)
    float voltage = (float)signed_value / 4096.0 * 5.0; // 5V reference

    // Convert to current (assuming 0.5V/A)
    float current = (voltage - 0.5) / 0.5;

    return current;
}

// Function to convert raw ADC value to current
float convert_to_current(int raw_value) {
    // Scale the value to the range 0-100A
    float voltage = (float)raw_value / 4096.0 * 5.0; // 5V reference
    float current = (voltage - 0.5) / 0.5; // 0.5V/A

    return current;
}

// Function to add a value to the circular buffer
void add_to_buffer(float current) {
    current_current_buffer.buffer[current_current_buffer.head] = current;
    current_current_buffer.head = (current_current_buffer.head + 1) % BUFFER_SIZE;
    if (current_current_buffer.count < BUFFER_SIZE) {
        current_current_buffer.count++;
    }
}

// Function to calculate the average current
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < current_current_buffer.count; i++) {
        sum += current_current_buffer.buffer[i];
    }
    return sum / current_current_buffer.count;
}

// Function to control the LED
void control_led(float average_current) {
    if (average_current > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    current_current_buffer.head = 0;
    current_current_buffer.count = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_ads1115(0);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED
        control_led(average_current);

        // Print current reading
        printf("Current: %.2f A\n", current);

        // Wait for 10ms
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

