    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(MOTOR_GPIO, 0); // Turn off motor
        log_data(current);
        gpioDelay(1000000); // Wait 1 second
        gpioWrite(MOTOR_GPIO, 1); // Re-enable motor
        log_data(current);
    } else {
        gpioWrite(MOTOR_GPIO, 1); // Keep motor on
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

