#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MLX90834_ADDR 0x48
#define ADS1115_ADDR 0x40
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_DELAY_US 1000 // 1 second

// Sensor Addresses
#define MLX90834_REG_CONFIG 0x00
#define MLX90834_REG_PRESS_MSB 0x01
#define MLX90834_REG_PRESS_LSB 0x02
#define MLX90834_REG_TEMP_MSB 0x03
#define MLX90834_REG_TEMP_LSB 0x04

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_SINGLE_ENDED_CONFIG 0x01
#define ADS1115_REG_SINGLE_ENDED_DATA_MSB 0x02
#define ADS1115_REG_SINGLE_ENDED_DATA_LSB 0x03

// Global Variables
int i2c_handle_mlx90834 = -1;
int i2c_handle_ads1115 = -1;
int running = 1;

// Function Prototypes
int initialize_sensor(int i2c_handle);
int read_pressure(int i2c_handle);
int read_temperature(int i2c_handle);
float convert_pressure(int adc_value);
float convert_temperature(int adc_value);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(GPIO_LED, 0); // Turn off LED
    if (i2c_handle_mlx90834 != -1) {
        i2cClose(i2c_handle_mlx90834);
    }
    if (i2c_handle_ads1115 != -1) {
        i2cClose(i2c_handle_ads1115);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the MLX90834 sensor
int initialize_sensor(int i2c_handle) {
    // Configure MLX90834 for single-ended mode and gain of 2/3
    char config_data[2];
    config_data[0] = MLX90834_REG_CONFIG;
    config_data[1] = (0x01 << 4) | (0x01 << 2) | 0x01; // Single-ended, gain 2/3, channel AIN0
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to MLX90834 config register.\n");
        return -1;
    }

    // Configure ADS1115 for single-ended mode and gain of 2/3
    char config_data_ads1115[2];
    config_data_ads1115[0] = ADS1115_REG_CONFIG;
    config_data_ads1115[1] = (0x01 << 4) | (0x01 << 2) | 0x01; // Single-ended, gain 2/3, channel AIN0
    if (i2cWriteDevice(i2c_handle, config_data_ads1115, 2) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register.\n");
        return -1;
    }

    return 0;
}

// Read pressure from the MLX90834 sensor
int read_pressure(int i2c_handle) {
    char msb, lsb;
    int adc_value;

    // Read MSB and LSB of pressure data
    if (i2cReadDevice(i2c_handle, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB from MLX90834.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB from MLX90834.\n");
        return -1;
    }

    adc_value = ((int)msb << 8) | (int)lsb;
    return adc_value;
}

// Read temperature from the ADS1115 sensor
int read_temperature(int i2c_handle) {
    char msb, lsb;
    int adc_value;

    // Read MSB and LSB of temperature data
    if (i2cReadDevice(i2c_handle, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB from ADS1115.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB from ADS1115.\n");
        return -1;
    }

    adc_value = ((int)msb << 8) | (int)lsb;
    return adc_value;
}

// Convert ADC value to pressure (kPa)
float convert_pressure(int adc_value) {
    // Linear transfer function (0V = 0 kPa, 5V = 400 kPa)
    float pressure = (float)adc_value / 4096.0 * 400.0;
    return pressure;
}

// Convert ADC value to temperature (°C)
float convert_temperature(int adc_value) {
    // Simplified linear NTC approximation (1V = 0°C, 2V = 100°C)
    float temperature = (float)adc_value / 4096.0 * 100.0;
    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connections
    i2c_handle_mlx90834 = i2cOpen(I2C_BUS, MLX90834_ADDR, 0);
    if (i2c_handle_mlx90834 < 0) {
        fprintf(stderr, "Error opening I2C connection to MLX90834: %d\n", i2c_handle_mlx90834);
        gpioTerminate();
        return 1;
    }

    i2c_handle_ads1115 = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle_ads1115 < 0) {
