// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MCP3008_VCC 3.3
#define MCP3008_CURRENT_MAX 10.0 // 10A
#define MCP3008_CURRENT_MIN 0.0  // 0A
#define MCP3008_CURRENT_OFFSET 0.0 // 0V
#define MCP3008_ADC_RESPONSE_SIZE (1024 * 8) // 10-bit ADC response
#define LOG_FILE "current_log.txt"
#define OVERCURRENT_THRESHOLD 10.0 // 10A
#define OVERCURRENT_EVENT "OVERCURRENT"
#define GPIO_SHUTDOWN_PIN 27

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float adc_to_current(float voltage);
void log_current(float voltage, float current);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Null byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * MCP3008_VCC / 1024.0;
}

// Function to convert ADC value to current
float adc_to_current(float voltage) {
    return voltage * MCP3008_CURRENT_OFFSET / MCP3008_VCC * MCP3008_CURRENT_MAX;
}

// Function to log current with timestamp
void log_current(float voltage, float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Voltage: %.3fV, Current: %.3fA\n", timestamp, voltage, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close SPI and log file
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as output for shutdown
    gpioSetMode(GPIO_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN_PIN, 0); // Initially HIGH

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert ADC value to current
        float current = adc_to_current(voltage);

        // Log current
        log_current(voltage, current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT EVENT: Current = %.3fA, Voltage = %.3fV\n", current, voltage);
            gpioWrite(GPIO_SHUTDOWN_PIN, 1); // Set GPIO27 HIGH
            gpioDelay(5000000); // 5 seconds
            gpioWrite(GPIO_SHUTDOWN_PIN, 0); // Set GPIO27 LOW
            printf("Motor shutdown triggered.\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

