void cleanup() {
    printf("Cleaning up...\n");
    set_alarm(0); // Turn off alarm
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            log_reading(voltage);

            if (voltage > VOLTAGE_THRESHOLD) {
                set_alarm(1); // Turn on alarm
                gpioDelay(ALARM_DURATION_MS * 1000); // Wait for alarm duration
                set_alarm(0); // Turn off alarm
            }
        } else {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

