#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MLX90830_ADDR 0x48
#define SAMPLE_RATE_HZ 1
#define SAMPLE_DELAY_MS 100
#define SENSOR_COUNT 3
#define SENSOR_OFFSET 0.5
#define SENSOR_SCALE 0.1
#define SENSOR_OFFSET_MIN 0.0
#define SENSOR_OFFSET_MAX 100.0
#define SENSOR_SCALE_MIN 0.0
#define SENSOR_SCALE_MAX 100.0
#define SENSOR_OFFSET_MIN_MAX (SENSOR_OFFSET_MIN + SENSOR_OFFSET_MAX)
#define SENSOR_SCALE_MIN_MAX (SENSOR_SCALE_MIN + SENSOR_SCALE_MAX)

// Global variables
int i2c_handles[SENSOR_COUNT];
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int i2c_handle;
    float voltage;
    float pressure;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_adc(int i2c_handle);
float convert_to_voltage(int adc_value);
float convert_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    for (int i = 0; i < SENSOR_COUNT; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, MLX90830_ADDR + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device for sensor %d: %d\n", i, i2c_handles[i]);
            return -1;
        }
        printf("I2C device opened for sensor %d\n", i);
    }
    return 0;
}

// Read ADC value from MLX90830
int read_adc(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADC value: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (float)adc_value * (1.0 / 1023.0);
}

// Convert voltage to pressure
float convert_to_pressure(float voltage) {
    return voltage * SENSOR_SCALE;
}

// Log pressure data to file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    for (int i = 0; i < SENSOR_COUNT; i++) {
        i2cClose(i2c_handles[i]);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int adc_value = read_adc(i2c_handles[i]);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC value from sensor %d\n", i);
                continue; // Skip to the next sensor
            }

            float voltage = convert_to_voltage(adc_value);
            float pressure = convert_to_pressure(voltage);

            if (pressure < SENSOR_OFFSET_MIN || pressure > SENSOR_OFFSET_MAX) {
                fprintf(stderr, "Invalid pressure reading from sensor %d: %.2f\n", i, pressure);
                continue; // Skip to the next sensor
            }

            log_pressure(pressure);
        }
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

