#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 10 // 10-bit ADC
#define ADC_SENSITIVITY 300.0 // mV/g
#define IMPACT_THRESHOLD 2.0  // g
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold ADC data
typedef struct {
    int16_t adc_value;
} adc_data_t;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
adc_data_t convert_to_adc_value(int adc_value);
void log_data(adc_data_t adc_value);
void impact_detected(adc_data_t adc_value);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to raw ADC value
adc_data_t convert_to_adc_value(int adc_value) {
    adc_data_t adc_data;
    adc_data.adc_value = adc_value;
    return adc_data;
}

// Function to log data to file
void log_data(adc_data_t adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, adc_value.adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to detect impact
void impact_detected(adc_data_t adc_value) {
    if (adc_value.adc_value > ADC_SENSITIVITY * IMPACT_THRESHOLD) {
        fprintf(stderr, "IMPACT DETECTED! ADC Value: %d\n", adc_value.adc_value);
        fprintf(log_file, "IMPACT DETECTED! ADC Value: %d\n", adc_value.adc_value);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
