#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the Si1172 sensor
#define SI1172_I2C_ADDR 0x49

// Define the register addresses for the Si1172
#define SI1172_REG_MEAS_CMD 0xC0
#define SI1172_REG_FIFO_DATA 0x00
#define SI1172_REG_FIFO_SIZE 0x01
#define SI1172_REG_FIFO_DATA_END 0x0F

// Define the command to trigger a measurement
#define SI1172_MEAS_CMD 0x00

// Define the I2C bus and handle
#define I2C_BUS 1
#define I2C_HANDLE 0

// Define the log file name
#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int hr;
    int spo2;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1172_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the Si1172
int read_sensor_data(sensor_data_t *data) {
    char buf[8];
    int bytes_read;

    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_CMD, SI1172_MEAS_CMD) < 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        data->error_flag = 1;
        return -1;
    }

    // Wait for the measurement to complete (at least 10ms)
    gpioDelay(10);

    // Read the FIFO data
    bytes_read = i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, buf, 8);
    if (bytes_read != 8) {
        fprintf(stderr, "Failed to read data from FIFO: %d\n", bytes_read);
        data->error_flag = 2;
        return -1;
    }

    // Extract the raw PPG data (16-bit)
    data->hr = (buf[0] << 8) | buf[1];
    data->spo2 = (buf[3] << 8) | buf[4];

    // Extract the error flag from the FIFO size register
    data->error_flag = (buf[5] & 0x01) ? 1 : 0;

    return 0;
}

// Function to log the sensor data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s,%d,%d,%d\n", timestamp, data.hr, data.spo2, data.error_flag);

    if (fprintf(log_file, "%s", log_entry) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close the log file
    fclose(log_file);

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

