    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.flow_rate);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Starting flow monitoring...\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to flow rate
        float flow_rate = adc_to_flow_rate(adc_value);

        // Validate flow rate
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
            flow_rate = FLOW_ERROR_THRESHOLD; // Set to error value
        }

        // Log data
        SensorData data;
        data.flow_rate = flow_rate;
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for 1 second
        gpioDelay(1000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

