#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to microphone 1
#define GATE_THRESHOLD 0.5 // Threshold for gate control
#define GATE_DURATION_MS 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float process_audio(int left_channel, int right_channel);
void gate_control(float audio_left, float audio_right);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to process audio data
float process_audio(int left_channel, int right_channel) {
    // Simple noise cancellation algorithm
    float processed_audio = 0.0;
    if (left_channel > 0) {
        processed_audio += left_channel;
    }
    if (right_channel > 0) {
        processed_audio += right_channel;
    }
    return processed_audio;
}

// Function to control gate based on audio levels
void gate_control(float audio_left, float audio_right) {
    if (audio_left > GATE_THRESHOLD && audio_right > GATE_THRESHOLD) {
        printf("Gate ON\n");
    } else {
        printf("Gate OFF\n");
    }
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio data from MCP3008
        int left_channel = read_mcp3008(MCP3008_CHANNEL);
        int right_channel = read_mcp3008(MCP3008_CHANNEL);

        if (left_channel < 0 || right_channel < 0) {
            fprintf(stderr, "Error: Failed to read audio data\n");
            continue; // Skip to the next iteration
        }

        // Process audio data
        float left_audio = process_audio(left_channel, 0);
        float right_audio = process_audio(0, right_channel);

        // Gate control
        gate_control(left_audio, right_audio);

        // Print audio data
        printf("Left: %.2f, Right: %.2f\n", left_audio, right_audio);

        // Delay
        gpioDelay(GATE_DURATION_MS * 1000); // Delay in microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

