#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define BUZZER_DURATION_MS 1000
#define ERROR_LOG_FILE "error.log"
#define ERROR_LOG_SIZE 1024
#define NUM_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_temperature(float voltage);
int log_data(float raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    // Assuming a linear relationship between ADC value and voltage
    // This is a simplified example; adjust based on your sensor's characteristics
    return (float)adc_value * 3.3 / 1023.0;
}

// Function to convert voltage to temperature
float voltage_to_temperature(float voltage) {
    // Assuming a linear relationship between voltage and temperature
    // This is a simplified example; adjust based on your sensor's characteristics
    return (voltage - 0.5) * 100.0;
}

// Function to log data to file
int log_data(float raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    if (flame_detected) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer ON
        gpioDelay(BUZZER_DURATION_MS);
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to temperature
        float temperature = voltage_to_temperature(voltage);

        // Log data
        if (log_data(adc_value, voltage, voltage, temperature, 0) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Check for flame detection
        int flame_detected = (voltage > 1.0) ? 1 : 0; // Assuming voltage above 1.0V is flame

        // Control buzzer
        control_buzzer(flame_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
