#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL_SEC 1
#define MOISTURE_THRESHOLD_LOW 0.5
#define MOISTURE_THRESHOLD_HIGH 0.8
#define MOISTURE_THRESHOLD_ERROR 0.6
#define MOISTURE_THRESHOLD_ERROR_LOW 0.4
#define MOISTURE_THRESHOLD_ERROR_HIGH 0.9
#define MOISTURE_THRESHOLD_ERROR_LOW_LOW 0.2
#define MOISTURE_THRESHOLD_ERROR_LOW_HIGH 0.8
#define MOISTURE_THRESHOLD_ERROR_HIGH_LOW 0.6
#define MOISTURE_THRESHOLD_ERROR_HIGH_HIGH 0.4

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void log_data(float moisture);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Clamp ADC value to [0, 1023]
    adc_value = (adc_value > 1023) ? 1023 : adc_value;
    adc_value = (adc_value < 0) ? 0 : adc_value;

    // Calculate moisture percentage
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    if (moisture < 0) moisture = 0.0;
    if (moisture > 100) moisture = 100.0;

    return moisture;
}

// Function to log data to file
void log_data(float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to clean up resources
void cleanup() {
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        SAMPLE_INTERVAL_SEC = atoi(argv[1]);
        if (SAMPLE_INTERVAL_SEC <= 0) {
            fprintf(stderr, "Error: Invalid sample interval. Using default 1 second.\n");
            SAMPLE_INTERVAL_SEC = 1;
        }
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture = calculate_moisture(adc_value);
            if (moisture >= 0) {
                log_data(moisture);
                printf("Moisture: %.2f%%\n", moisture);
            } else {
                fprintf(stderr, "Error: Failed to calculate moisture\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay in microseconds
    }

    // Clean up and exit
    cleanup();
    return 0;
}

