    adc_value = (adc_value < 0) ? 0 : adc_value;

    // Calculate moisture percentage
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    if (moisture < 0) moisture = 0.0;
    if (moisture > 100) moisture = 100.0;

    return moisture;
}

// Function to log data to file
void log_data(float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to clean up resources
void cleanup() {
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        SAMPLE_INTERVAL_SEC = atoi(argv[1]);
        if (SAMPLE_INTERVAL_SEC <= 0) {
            fprintf(stderr, "Error: Invalid sample interval. Using default 1 second.\n");
            SAMPLE_INTERVAL_SEC = 1;
        }
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture = calculate_moisture(adc_value);
            if (moisture >= 0) {
                log_data(moisture);
                printf("Moisture: %.2f%%\n", moisture);
            } else {
                fprintf(stderr, "Error: Failed to calculate moisture\n");
            }
        } else {
