// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VOLTAGE_THRESHOLD 0.5
#define VOLTAGE_MAX 3.3
#define VOLTAGE_MIN 0.0
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_SCALE (VOLTAGE_MAX - VOLTAGE_MIN) / ADC_MAX
#define PRESSURE_SCALE (VOLTAGE_MAX - VOLTAGE_MIN) / ADC_MAX
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 150.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
} SensorData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
