int read_mcp3008(int channel);
int convert_to_moisture(int adc_value);
void log_data(int adc_value, int moisture_percentage);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to moisture percentage
int convert_to_moisture(int adc_value) {
    if (adc_value < ADC_VALUE_MIN) {
        return MIN_ADC_VALUE;
    } else if (adc_value > ADC_VALUE_MAX) {
        return MAX_ADC_VALUE;
    } else {
        return 100 - ((float)(adc_value - ADC_VALUE_MIN) / (float)(ADC_VALUE_MAX - ADC_VALUE_MIN)) * 100;
    }
}

// Function to log data to console and file
void log_data(int adc_value, int moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ADC Value: %d, Moisture: %d%%\n", timestamp, adc_value, moisture_percentage);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "[%s] ADC Value: %d, Moisture: %d%%\n", timestamp, adc_value, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Sensor Data Logger\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to moisture percentage
        int moisture_percentage = convert_to_moisture(adc_value);

        // Log the data
        log_data(adc_value, moisture_percentage);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up and exit
    cleanup();
    return 0;
}

