#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define SENSOR_COUNT 4
#define CSV_FILE "environmental_data.csv"
#define LOG_FILE "error_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int channel;
    float voltage;
} sensor_data_t;

// Function prototypes
int spi_init(int spi_device, int spi_speed, int cs_pin);
int spi_read_channel(int spi_fd, int channel);
float convert_to_voltage(int adc_value);
int log_data(FILE *fp, sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int spi_init(int spi_device, int spi_speed, int cs_pin) {
    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer[SENSOR_COUNT];
    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)spi_fd;
    transfer[0].rx_buf = NULL;
    transfer[0].len = 0;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = spi_speed;
    transfer[0].bits_per_word = 8;
    transfer[0].cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Read data from MCP3008 ADC
int spi_read_channel(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)spi_fd;
    transfer[0].rx_buf = rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (float)adc_value * VREF / 1024.0;
}

// Log data to CSV file
int log_data(FILE *fp, sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, data->channel, data->voltage, data->voltage, data->voltage);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, 0);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data[SENSOR_COUNT];
        int adc_values[SENSOR_COUNT];

        // Read sensor data
        for (int i = 0; i < SENSOR_COUNT; i++) {
            adc_values[i] = spi_read_channel(spi_fd, i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue; // Skip to the next channel
            }
            sensor_data[i].channel = i;
            sensor_data[i].voltage = convert_to_voltage(adc_values[i]);
        }

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

