#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VH400_ADC_VALUE 0 // ADC value from VH400
#define MOISTURE_THRESHOLD 300
#define HYSTERESIS 600
#define PUMP_GPIO 17
#define PUMP_ON_TIME_MS 5000
#define LOG_BUFFER_SIZE 20

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
int log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_moisture_level();
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read moisture level from VH400
int read_moisture_level() {
    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return -1; // Indicate error
    }
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    pump_state = state;
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    log_buffer[log_index] = (int)moisture_level;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System\n");

    while (1) {
        int moisture_level = read_moisture_level();
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        int pump_state = control_pump(moisture_level < HYSTERESIS ? 1 : 0); // Turn pump on if below hysteresis

        log_data(moisture_level, pump_state);

        printf("Moisture Level: %d, Pump State: %d\n", moisture_level, pump_state);

        sleep(5);
    }

    return 0;
}

