#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define MAX30102 registers
#define MAX30102_PART_ID_REG 0xFF
#define MAX30102_MODE_CONFIG_REG 0x06
#define MAX30102_MODE_CONFIG_VALUE 0x40
#define MAX30102_SPO2_CONFIG_REG 0x08
#define MAX30102_SPO2_CONFIG_VALUE 0x27
#define MAX30102_LED1_PA_REG 0x09
#define MAX30102_LED2_PA_REG 0x0A
#define MAX30102_FIFO_DATA_REG 0x07

// Define constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_PERIOD_US (SAMPLE_INTERVAL_MS * 1000)
#define SAMPLE_PERIOD_NS (SAMPLE_INTERVAL_MS * 1000000)
#define SAMPLE_PERIOD_US_PERIOD (SAMPLE_PERIOD_NS / SAMPLE_INTERVAL_MS)
#define SAMPLE_PERIOD_NS_PERIOD (SAMPLE_PERIOD_NS / 1000000)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_max30102_data(int *red, int *ir);
float calculate_spo2(int red, int ir);
float calculate_heart_rate(int ir);
void log_data(float spo2, float heart_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MAX30102_MODE_CONFIG_REG, MAX30102_MODE_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error: Could not reset MAX30102\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, MAX30102_LED1_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error: Could not set LED1_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MAX30102_LED2_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error: Could not set LED2_PA\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MAX30102_MODE_CONFIG_REG, MAX30102_MODE_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error: Could not set MODE_CONFIG\n");
        return -1;
    }

    // Configure SPO2 mode
    if (i2cWriteByteData(i2c_handle, MAX30102_SPO2_CONFIG_REG, MAX30102_SPO2_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error: Could not set SPO2_CONFIG\n");
        return -1;
    }

    return 0;
}

// Read data from the MAX30102 sensor
int read_max30102_data(int *red, int *ir) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, MAX30102_FIFO_DATA_REG, buf, 6);

    if (result != 6) {
        fprintf(stderr, "Error: Could not read data from MAX30102 (read %d bytes)\n", result);
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];

    return 0;
}

// Calculate SpO2 percentage
float calculate_spo2(int red, int ir) {
    // Ratio of red to IR signals
    float ratio = (float)red / (float)ir;

    // Calculate SpO2 percentage (example formula, adjust as needed)
    float spo2_percentage = (ratio - 0.5) * 100; // Example: 0.5 is the average ratio

    // Clamp SpO2 percentage to the valid range (0-100)
    if (spo2_percentage < 0) {
        spo2_percentage = 0;
    } else if (spo2_percentage > 100) {
        spo2_percentage = 100;
    }

    return spo2_percentage;
}

// Calculate heart rate (example formula, adjust as needed)
float calculate_heart_rate(int ir) {
    // Example: Calculate heart rate based on IR signal
    float heart_rate = (float)ir / 100.0; // Example: Divide IR by 100 to get heart rate in BPM

    // Clamp heart rate to the valid range (60-200 BPM)
    if (heart_rate < 60) {
        heart_rate = 60;
    } else if (heart_rate > 200) {
        heart_rate = 200;
    }

    return heart_rate;
}

// Log data to a file
void log_data(float spo2, float heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, SpO2: %.2f, Heart Rate: %.2f\n", timestamp, spo2, heart_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int red, ir;
    float spo2, heart_rate;

    while (!terminate) {
        // Read data from MAX30102 sensor
        if (read_max30102_data(&red, &ir) == 0) {
            // Calculate SpO2 percentage and heart rate
            spo2 = calculate_spo2(red, ir);
            heart_rate = calculate_heart_rate(ir);

            // Log data
            log_data(spo2, heart_rate);

            // Print data to console
            printf("Spo2: %.2f%% (%.2f BPM), Heart Rate: %.2f BPM\n", spo2, heart_rate, heart_rate);
        } else {
            fprintf(stderr, "Error: Could not read MAX30102 data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

