float adc_to_gas_value(int adc_value) {
    // Assuming a linear relationship between ADC value and gas concentration
    // This is a placeholder; replace with actual calibration data
    return (float)adc_value / ADC_RESOLUTION * 100.0; // Example: 100% gas concentration at ADC value of 1024
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to gas sensor value
        float gas_value = adc_to_gas_value(adc_value);

        // Control buzzer
        control_buzzer(gas_value < GAS_THRESHOLD);

        // Print gas sensor value and buzzer state
        printf("Gas Sensor: ADC Value = %d, Gas Value = %.2f, Buzzer = %s\n", adc_value, gas_value, gas_value < GAS_THRESHOLD ? "ON" : "OFF");

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Close SPI handle and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

