#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_GPIO 17
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *ain0_line = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_pcf8591(int fd, int channel);
int configure_pcf8591(int fd, int channel, int mode);
int read_sample(int fd, int channel);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl-C detected. Exiting...\n");
        program_running = 0;
    }
}

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// PCF8591 configuration function
int configure_pcf8591(int fd, int channel, int mode) {
    uint8_t control_byte[3];
    int result;

    control_byte[0] = 0x01; // Single-ended mode
    control_byte[1] = 0x00; // Channel 0
    control_byte[2] = 0x00; // Disable analog output

    result = write(fd, control_byte, 3);
    if (result < 0) {
        perror("Error writing to PCF8591");
        return -1;
    }

    return 0;
}

// PCF8591 sample reading function
int read_sample(int fd, int channel) {
    uint8_t buffer[3];
    int result;

    // Read 3 bytes (AIN0, MSB, LSB)
    result = read(fd, buffer, 3);
    if (result < 0) {
        perror("Error reading from PCF8591");
        return -1;
    }

    // Combine MSB and LSB to get the 16-bit value
    int16_t raw_value = (buffer[0] << 8) | buffer[1];

    // Convert to the ADC value (0-1023)
    int adc_value = (int)((float)raw_value / 1023.0 * 255.0);

    return adc_value;
}

// PCF8591 read function
int read_pcf8591(int fd, int channel) {
    uint8_t buffer[3];
    int result;

    // Read 3 bytes (AIN0, MSB, LSB)
    result = read(fd, buffer, 3);
    if (result < 0) {
        perror("Error reading from PCF8591");
        return -1;
    }

    // Combine MSB and LSB to get the 16-bit value
    int16_t raw_value = (buffer[0] << 8) | buffer[1];

    // Convert to the ADC value (0-1023)
    int adc_value = (int)((float)raw_value / 1023.0 * 255.0);

    return adc_value;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, PCF8591_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Configure PCF8591
    if (configure_pcf8591(i2c_fd, 0, 0) < 0) {
        fprintf(stderr, "PCF8591 configuration failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for AIN0
    ain0_line = gpiod_line_request(AIN0_GPIO);
    if (!ain0_line) {
        perror("Error requesting GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sample from PCF8591
        int adc_value = read_sample(i2c_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading PCF8591. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Print ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    close(i2c_fd);
    if (ain0_line) {
        gpiod_line_release(ain0_line);
    }

    return 0;
}

