#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define SENSOR_CHANNEL AIN0
#define SENSOR_VOLTAGE_SCALE 3.3 / 2.5
#define SENSOR_Gauss_THRESHOLD 500
#define SAMPLE_RATE 1 // Hz
#define BUFFER_SIZE 10
#define GPIO_PIN 27
#define LOG_FILE "/var/log/ss49e.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(float *voltage);
float convert_voltage_to_gauss(float voltage);
void add_to_buffer(CircularBuffer *buffer, float voltage);
float calculate_rolling_average(CircularBuffer *buffer, int size);
void signal_handler(int signal);
void log_event(const char *message);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(float *voltage) {
    char buf[2];
    int result;

    // Read two bytes from the ADS1115
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        log_event("Failed to read from ADS1115.");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    *voltage = (float)((buf[0] << 8) | buf[1]) / 32768.0; // Convert to volts
    return 0;
}

// Function to convert voltage to Gauss
float convert_voltage_to_gauss(float voltage) {
    return voltage * SENSOR_VOLTAGE_SCALE;
}

// Function to add a reading to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float voltage) {
    buffer->buffer[buffer->head] = voltage;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average of the buffer
float calculate_rolling_average(CircularBuffer *buffer, int size) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...");
    terminate = 1;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Function to cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioWrite(GPIO_PIN, 0); // Turn off motor
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    float voltage;
    CircularBuffer buffer;
    int i;

    // Initialize syslog
    openlog("ss49e", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Configure GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure motor is off initially

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Main loop
    while (!terminate) {
        // Read voltage from ADS1115
        if (read_ads1115(&voltage) == 0) {
            // Convert voltage to Gauss
            float gauss = convert_voltage_to_gauss(voltage);

            // Add reading to circular buffer
            add_to_buffer(&buffer, voltage);

            // Calculate rolling average
            float rolling_average = calculate_rolling_average(&buffer, BUFFER_SIZE);

            // Check if rolling average exceeds threshold
            if (rolling_average > SENSOR_Gauss_THRESHOLD) {
                log_event("Motor shutdown due to high Gauss reading.");
                gpioWrite(GPIO_PIN, 1); // Turn on motor
                gpioDelay(1000); // Keep motor on for 1 second
                gpioWrite(GPIO_PIN, 0); // Turn off motor
                log_event("Motor shutdown complete.");
            }

            // Log the reading
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Voltage: %.2f V, Gauss: %.2f Gauss", voltage, gauss);
            log_event(log_message);
        } else {
            log_event("Failed to read voltage from ADS1115.");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

