    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to moisture percentage
        float moisture_percentage = adc_to_moisture(adc_value);

        // Control pump
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            control_pump(1); // Activate pump
            log_event("Moisture level below threshold, activating pump.");
            gpioDelay(WATERING_CYCLE_DURATION * 1000); // Wait for watering cycle
            control_pump(0); // Deactivate pump
            log_event("Pump deactivated after watering cycle.");
        } else {
            control_pump(0); // Deactivate pump
        }

        // Wait for watering interval
        gpioDelay(WATERING_INTERVAL_DURATION * 1000); // Wait for interval
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

