#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define PGA_GAIN 4.096
#define LED_GPIO 17
#define THRESHOLD 100.0
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD (1.0 / SAMPLE_RATE)
#define SAMPLE_COUNT (SAMPLE_RATE * 1000) // 100 ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *adc_value);
float convert_to_gauss(int16_t adc_value);
float calculate_magnetic_field(float gauss_value);
void blink_led(int duration_ms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *adc_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data from ADS1115: %d\n", result);
        return -1;
    }

    *adc_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert ADC value to Gauss
float convert_to_gauss(int16_t adc_value) {
    return (float)adc_value / PGA_GAIN;
}

// Calculate magnetic field strength in Gauss
float calculate_magnetic_field(float gauss_value) {
    return gauss_value * 0.001; // Convert Gauss to Gauss
}

// Blink LED for a specified duration
void blink_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(duration_ms);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(duration_ms);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int threshold = 100.0;
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: 100.0 Gauss\n");
            threshold = 100.0;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t adc_value;
    float gauss_value;
    float magnetic_field;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&adc_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(adc_value);

            // Calculate magnetic field strength
            magnetic_field = calculate_magnetic_field(gauss_value);

            // Check if field exceeds threshold
            if (magnetic_field > threshold) {
                // Blink LED
                blink_led(1000); // Blink for 1 second
            }

            // Print magnetic field strength
            printf("Gauss: %.2f, Magnetic Field: %.2f Gauss\n", gauss_value, magnetic_field);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

