#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define CS_PIN 8

// MCP3008 command
#define MCP3008_START_BIT 0x01
#define MCP3008_CONFIG_BYTE 0x00
#define MCP3008_SINGLE_ENDED_CHANNEL 0x40

// Global variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_open(const char *device, int mode);
int spi_read(int fd, unsigned char *data, int len);
int spi_write(int fd, unsigned char *data, int len);
int spi_close(int fd);
int read_mcp3008(int fd, unsigned char channel);
float read_adc(int fd, unsigned char channel);
void print_adc_value(float voltage);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error getting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read function
int spi_read(int fd, unsigned char *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
