// Function to map ADC value to PWM duty cycle
int map_adc_to_pwm(int adc_value) {
    // Linear mapping
    int pwm_value = (int)((adc_value / ADC_MAX_VALUE) * VIBRATION_MOTOR_1_PWM_FREQUENCY);
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > VIBRATION_MOTOR_1_PWM_FREQUENCY) pwm_value = VIBRATION_MOTOR_1_PWM_FREQUENCY;
    return pwm_value;
}

