#include <pigpio.h>

// Constants
#define MAX9814_ADDR 0x68
#define BH1750_ADDR 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_RATE 5 // seconds
#define SAMPLE_PERIOD SAMPLE_RATE * 60 // milliseconds
#define MAX_SAMPLE_COUNT 1000
#define MAX_SAMPLE_DURATION 180 // seconds

// Global variables
int i2c_fd;
int spi_fd;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int addr);
int init_spi(int channel, int speed, int mode);
int read_max9814(int channel, int *adc_value);
int read_bh1750(int i2c_fd, int *lux);
int log_data(FILE *fp, int sound_level, int light_level, int error_code);
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int adc_value;
    int lux;
    int error_code;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize SPI
int init_spi(int channel, int speed, int mode) {
    int fd = open("/dev/spidev", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    char buf[10];
    buf[0] = SPI_MODE;
    buf[1] = mode;
    buf[2] = 0; // Mode 0
    buf[3] = 0; // Mode 0
    buf[4] = 0; // Mode 0
    buf[5] = 0; // Mode 0
    buf[6] = 0; // Mode 0
    buf[7] = 0; // Mode 0
    buf[8] = 0; // Mode 0
    buf[9] = 0; // Mode 0

    if (write(fd, buf, 10) < 0) {
        perror("Error writing to SPI device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read ADC value from MAX9814
int read_max9814(int channel, int *adc_value) {
    char buf[2];
    buf[0] = 0x00; // Start bit
    buf[1] = (channel << 4) | 0x01; // Single-ended mode, channel select
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to MAX9814");
        return -1;
    }
    gpioDelay(2); // Wait 2ms

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from MAX9814");
        return -1;
    }

    *adc_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read light level from BH1750
int read_bh1750(int i2c_fd, int *lux) {
    char buf[2];
    buf[0] = 0x10; // High resolution mode command
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to BH1750");
        return -1;
    }
    gpioDelay(2); // Wait 2ms

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

