void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MAX9814_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    int adc_value, lux;
    int error_code;

    while (!terminate) {
        // Read MAX9814
        if (read_max9814(MAX9814_ADDR, &adc_value) == 0) {
            // Read BH1750
            if (read_bh1750(i2c_fd, &lux) == 0) {
                // Log data
                log_data(csv_file, adc_value, lux, 0); // Assuming error code is 0

                // Print to console
                printf("Sound Level: %d, Light Level: %d, Error Code: %d\n", adc_value, lux, error_code);
            } else {
                error_code = 1; // BH1750 read error
            }
        } else {
            error_code = 1; // MAX9814 read error
        }

        gpioDelay(SAMPLE_PERIOD * 1000); // Delay for sample period
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);
    close(spi_fd);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

