        log_data(co2_ppm, gpioRead(FAN_GPIO));

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_fan(0); // Turn off fan
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

