// Define GPIO pins
#define VALVE_GPIO 17
#define SPI_CE8 8
#define SPI_CE9 9
#define SPI_CE10 10

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define SPI channel
#define SPI_CHANNEL 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define ADC range
#define ADC_RANGE 1023

// Define PWM range
#define PWM_RANGE 100

// Define PWM duty cycle range
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 100

// Define log file name
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float calculate_average(int adc_value1, int adc_value2, int adc_value3);
float map_value(float average, float min_value, float max_value);
void set_pwm(int gpio, int duty_cycle);
void log_data(int adc_value1, int adc_value2, int adc_value3, float average, float duty_cycle);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate average of ADC values
float calculate_average(int adc_value1, int adc_value2, int adc_value3) {
    float sum = 0.0;
    int count = 0;

    // Check for missing values
    if (adc_value1 == -1 || adc_value2 == -1 || adc_value3 == -1) {
        return -1.0; // Indicate error
    }

    sum += adc_value1;
    sum += adc_value2;
    sum += adc_value3;
    count++;

    if (count > 0) {
        return sum / count;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to map average ADC value to valve opening
float map_value(float average, float min_value, float max_value) {
    if (average < min_value) {
        return min_value;
    }
    if (average > max_value) {
        return max_value;
    }
    return average;
}

// Function to set PWM duty cycle
void set_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < PWM_DUTY_CYCLE_MIN) {
        duty_cycle = PWM_DUTY_CYCLE_MIN;
    } else if (duty_cycle > PWM_DUTY_CYCLE_MAX) {
        duty_cycle = PWM_DUTY_CYCLE_MAX;
    }

    gpioPWM(gpio, duty_cycle);
}

