    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC values
        int adc_value1 = read_adc(MCP3008_CHANNEL);
        int adc_value2 = read_adc(MCP3008_CHANNEL + 1);
        int adc_value3 = read_adc(MCP3008_CHANNEL + 2);

        // Calculate average ADC value
        float average = calculate_average(adc_value1, adc_value2, adc_value3);

        // Map average ADC value to valve opening
        float duty_cycle = map_value(average, 0.0, 100.0);

        // Set PWM duty cycle
        set_pwm(VALVE_GPIO, (int)duty_cycle);

        // Log data
        log_data(adc_value1, adc_value2, adc_value3, average, duty_cycle);

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

