        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    gpioTerminate();

    return 0;
}

