#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024
#define ADC_VREF 3.3
#define PPM_THRESHOLD 50.0
#define PPM_LIMIT 20.0
#define PPM_THRESHOLD_LIMIT 20.0
#define LOG_FILE "alcohol_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
int classify_reading(float ppm);
void log_reading(float ppm);
void log_error(const char *message);
void signal_handler(int signal);
int spi_transfer(int tx[], int rx[], int len);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid MCP3008 channel");
        return -1;
    }

    char tx[3] = {0x01, (0x08 | (channel << 4)), 0x00};
    char rx[3];

    if (spi_transfer(tx, rx, 3) != 0) {
        log_error("Failed to read from MCP3008");
        return -1;
    }

    return rx[1]; // Return the ADC value
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (float)adc_value * 0.5;
}

// Function to classify the alcohol reading
int classify_reading(float ppm) {
    if (ppm > PPM_THRESHOLD) {
        return 1; // Above threshold
    } else if (ppm < PPM_LIMIT) {
        return 0; // Below limit
    } else {
        return 2; // Within limit but above threshold
    }
}

// Function to log the alcohol reading
void log_reading(float ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, PPM: %.2f\n", timestamp, ppm);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(error_log_file);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to transfer data over SPI
int spi_transfer(int tx[], int rx[], int len) {
    int result = 0;
    for (int i = 0; i < len; i++) {
        result |= tx[i] << (8 * i);
    }
    return result;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("Failed to read ADC value");
            continue; // Retry
        }

        float ppm = adc_to_ppm(adc_value);
        int reading_type = classify_reading(ppm);

        log_reading(ppm);
        log_error(""); // Reset log after reading

        if (reading_type == 1) {
            log_error("Alcohol detected! Limit exceeded.");
        } else if (reading_type == 0) {
            log_error("Sobriety confirmed.");
        } else if (reading_type == 2) {
            log_error("Alcohol level within acceptable range.");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

