    fflush(error_log_file);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to transfer data over SPI
int spi_transfer(int tx[], int rx[], int len) {
    int result = 0;
    for (int i = 0; i < len; i++) {
        result |= tx[i] << (8 * i);
    }
    return result;
}

int main() {
