        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate average ambient sound level
        float average_ambient = calculate_average_ambient(adc_value);

        // Print ADC value and average ambient level
        printf("ADC Value: %d, Average Ambient: %.2f\n", adc_value, average_ambient);

        // Debounce LED control
        if (adc_value > NOISE_THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(10);   // Wait 10ms
            control_led(0); // Turn LED off
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED, 0); // Turn off LED
    gpioTerminate();

