#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define SLPM_TO_VOLTAGE_FACTOR 0.5
#define SLPM_TO_AIRFLOW_FACTOR 4.5
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int vref;
    float slpm_to_voltage_factor;
    float slpm_to_airflow_factor;
    char *log_file;
} Config;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert voltage to airflow
float voltage_to_airflow(float voltage) {
    return (voltage - VREF) * SLPM_TO_AIRFLOW_FACTOR;
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Airflow (SLPM)\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .vref = VREF,
        .slpm_to_voltage_factor = SLPM_TO_VOLTAGE_FACTOR,
        .slpm_to_airflow_factor = SLPM_TO_AIRFLOW_FACTOR,
        .log_file = LOG_FILE
    };

    if (initialize() != 0) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        float voltage = (float)adc_value * VREF / 1024.0;
        float airflow = voltage_to_airflow(voltage);

        log_data(airflow);

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

