int server_socket = -1;

// Function prototypes
int spi_init(void);
int spi_read_channel(int channel);
int spi_write_channel(int channel, int value);
int read_csv_file(const char *filename, char *buffer, size_t buffer_size);
int log_data(const char *filename, int channel, int value);
int send_data(const char *filename, int channel, int value);
void signal_handler(int sig);
