#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cjson.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define LED_ON_DELAY_MS 1000
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_ATTEMPTS 5
#define MAX_RECONNECT_DELAY_MS 60000

// Global variables
static struct mosquitto *mosq = NULL;
static int reconnect_attempts = 0;
static int reconnect_delay = 1; // Initial delay in milliseconds
static int led_state = 0; // Initial LED state (0 = off, 1 = on)
static volatile sig_atomic_t running = 1;

// Function prototypes
void signal_handler(int signal);
int connect_mqtt(const char *broker, int port);
int subscribe_mqtt(const char *topic, void *userdata);
int publish_mqtt(const char *topic, const char *payload);
int parse_json(const char *payload, int *led_state);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Connect to MQTT broker
int connect_mqtt(const char *broker, int port) {
    int rc;
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    rc = mosquitto_connect(mosq, broker, port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq, true, true);
    mosquitto_loop_stop(mosq, true);

    return 0;
}

// Subscribe to MQTT topic
int subscribe_mqtt(const char *topic, void *userdata) {
    int rc;
    int retries = 0;

    while (retries < MAX_RECONNECT_ATTEMPTS) {
        rc = mosquitto_subscribe(mosq, NULL, topic, QoS_LEVEL_0, false);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Subscribed to %s\n", topic);
            return 0; // Success
        } else {
            fprintf(stderr, "Error subscribing to %s: %s\n", topic, mosquitto_strerror(rc));
            retries++;
            sleep(retries * 10); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to subscribe to %s after %d retries.\n", topic, MAX_RECONNECT_ATTEMPTS);
    return -1; // Failure
}

// Publish JSON payload to MQTT topic
int publish_mqtt(const char *topic, const char *payload) {
    int rc;
    int retries = 0;

    while (retries < MAX_RECONNECT_ATTEMPTS) {
        rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Published %s to %s\n", payload, topic);
            return 0; // Success
        } else {
            fprintf(stderr, "Error publishing %s to %s: %s\n", payload, topic, mosquitto_strerror(rc));
            retries++;
            sleep(retries * 10); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to publish %s to %s after %d retries.\n", payload, topic, MAX_RECONNECT_ATTEMPTS);
    return -1; // Failure
}

// Parse JSON payload
int parse_json(const char *payload, int *led_state) {
    cJSON *root = cJSON_Parse(payload);
    if (root == NULL) {
        fprintf(stderr, "Error: Could not parse JSON\n");
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (cJSON_IsBoolean(led_state_json)) {
        *led_state = cJSON_IsBool(led_state_json) ? 1 : 0;
    } else {
        fprintf(stderr, "Error: Invalid JSON format: led_state is not a boolean\n");
        cJSON_Delete(root);
        return -1;
    }

    cJSON *clean_json = cJSON_Remove(root, "led_state");
    cJSON_Delete(root);

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int rc;
    int retries = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize MQTT
    if (connect_mqtt(MQTT_BROKER, MQTT_PORT) != 0) {
        cleanup();
        return 1;
    }

    // Subscribe to MQTT topic
    if (subscribe_mqtt(MQTT_TOPIC, NULL) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
