            free(payload);
            cleanup();
            return 1;
        }

        // Parse JSON payload
        if (parse_json(payload, &led_state) != 0) {
            fprintf(stderr, "Error: Failed to parse JSON payload\n");
            free(payload);
            cleanup();
            return 1;
        }

        // Publish LED state
        if (publish_mqtt(MQTT_TOPIC, (led_state == 1) ? "1" : "0") != 0) {
            fprintf(stderr, "Error: Failed to publish LED state\n");
        }

        free(payload);

        sleep(1); // Delay before next message
    }

