#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SOUND_SENSOR_DO 17
#define ALARM_LED 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor value
int read_sound_sensor() {
    int sensor_value = gpiod_line_get_value(SOUND_SENSOR_DO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sound sensor value.\n");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the alarm LED
void control_alarm_led(int state) {
    if (gpiod_line_set_value(ALARM_LED, state) < 0) {
        fprintf(stderr, "Error setting alarm LED value.\n");
    }
}

// Function to simulate the alarm
void simulate_alarm() {
    printf("Simulating alarm...\n");
    control_alarm_led(1); // Turn on the alarm
    sleep(1);
    control_alarm_led(0); // Turn off the alarm
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    if (gpiod_chip_open_by_index(0) < 0) {
        fprintf(stderr, "Error opening GPIO chip.\n");
        return 1;
    }

    // Open the sound sensor line
    if (gpiod_line_request(SOUND_SENSOR_DO, 0) < 0) {
        fprintf(stderr, "Error requesting line for sound sensor.\n");
        gpiod_chip_close(0);
        return 1;
    }

    // Open the alarm LED line
    if (gpiod_line_request(ALARM_LED, 0) < 0) {
        fprintf(stderr, "Error requesting line for alarm LED.\n");
        gpiod_chip_close(0);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the sound sensor value
        int sound_level = read_sound_sensor();

        // Check for error during sound sensor reading
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break; // Exit the loop if there's an error
        }

        // Print the sound level reading
        printf("Sound Level: %d\n", sound_level);

        // Check for alarm condition (DO is LOW)
        if (sound_level == 0) {
            // Blink the alarm LED
            control_alarm_led(1);
            simulate_alarm();
            control_alarm_led(0);
        }

        // Delay for 100 ms
        usleep(100000); // 100 ms
    }

    // Clean up GPIO lines before exiting
    gpiod_line_release(SOUND_SENSOR_DO);
    gpiod_line_release(ALARM_LED);

    // Close the GPIO chip
    gpiod_chip_close(0);

    return 0;
}

