// Function to open the GPIO chip
int open_chip(const char *chip_id) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Open the chip
    chip = gpiod_chip_open(CHIP_ID, GPIOD_CHIP_READ_ONLY);
    if (!chip) {
        perror("gpiod_chip_open failed");
        return -1;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the event
    ret = request_event(GPIO_PIN, "vibration-monitor", GPIOD_LINE_FALLING_EDGE);
    if (ret < 0) {
        perror("request_event failed");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Wait for the event
    ret = wait_for_event(GPIO_PIN, GPIOD_LINE_FALLING_EDGE, 1000); // 1 second timeout
    if (ret < 0) {
        perror("wait_for_event failed");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Read the line
    ret = read_line(GPIO_PIN, line->line_buffer, sizeof(line->line_buffer));
    if (ret < 0) {
        perror("read_line failed");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return -1;
