void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;
}

// Function to log an event to a file
void log_event(const char *filename, int pin, int state) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, GPIO%d, %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pin, state ? "HIGH" : "LOW");
    fclose(fp);
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    if (gpiod_chip_open_by_name("gpiochip0") < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_get_name(0));
        return 1;
    }

    // Open the GPIO line for input
    if (gpiod_line_request_input(FLAME_SENSOR_GPIO, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", gpiod_line_get_name(FLAME_SENSOR_GPIO));
        gpiod_chip_close(0);
        return 1;
    }

    // Set up signal handling for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpiod_chip_close(0);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpiod_chip_close(0);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting...\n");
            break;
        }

        if (sensor_value == 1) {
            printf("Flame detected!\n");
            log_event(LOG_FILE, FLAME_SENSOR_GPIO, 1);
        } else {
            printf("No flame detected.\n");
            log_event(LOG_FILE, FLAME_SENSOR_GPIO, 0);
        }

        sleep(1);
    }

    // Clean up GPIO resources
    gpiod_line_release(FLAME_SENSOR_GPIO);
    gpiod_chip_close(0);

    printf("Exiting.\n");
    return 0;
}

