#define MCP4725_ADDR 0x62
#define TMP36_CHANNEL 0
#define TMP36_RESOLUTION 10.0 // 10mV/°C
#define TMP36_MIN 0.0
#define TMP36_MAX 50.0
#define TMP36_SCALE (TMP36_MAX - TMP36_MIN)
#define VOLTAGE_SCALE (3.3 / TMP36_MAX)
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define VOLTAGE_OFFSET (VOLTAGE_MIN + TMP36_MIN * VOLTAGE_SCALE)
#define VOLTAGE_RANGE (VOLTAGE_MAX - VOLTAGE_MIN)
#define VOLTAGE_SCALE_FACTOR (VOLTAGE_RANGE / VOLTAGE_MAX)
#define VOLTAGE_OFFSET_FACTOR (VOLTAGE_RANGE / VOLTAGE_MAX)
#define VOLTAGE_MIN_FACTOR (VOLTAGE_MIN / VOLTAGE_MAX)
#define VOLTAGE_MAX_FACTOR (VOLTAGE_MAX / VOLTAGE_MAX)
#define VOLTAGE_MIN_SCALE (VOLTAGE_MIN / VOLTAGE_MAX)
#define VOLTAGE_MAX_SCALE (VOLTAGE_MAX / VOLTAGE_MAX)
#define VOLTAGE_MIN_SCALE_FACTOR (VOLTAGE_MIN_SCALE / VOLTAGE_MAX_SCALE)
#define VOLTAGE_MAX_SCALE_FACTOR (VOLTAGE_MAX_SCALE / VOLTAGE_MAX_SCALE)
#define VOLTAGE_MIN_SCALE_FACTOR_FACTOR (VOLTAGE_MIN_SCALE_FACTOR / VOLTAGE_MAX_SCALE_FACTOR)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
float voltage_to_temperature(float voltage);
int write_mcp4725(float voltage);
void log_data(float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC reading to temperature in Celsius
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * VOLTAGE_MAX;
    float temperature = (voltage - VOLTAGE_MIN) / VOLTAGE_SCALE * TMP36_MAX;
    return temperature;
}

