    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(TMP36_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Convert voltage to temperature
        float voltage = voltage_to_temperature(temperature);

        // Write voltage to MCP4725
        if (write_mcp4725(voltage) != 0) {
            fprintf(stderr, "Error: Failed to write voltage to MCP4725\n");
        }

        // Log data
        log_data(temperature, voltage);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

