// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNELS [0, 1, 2]
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_adc_to_moisture(int adc_value);
int log_data(float moisture1, float moisture2, float moisture3);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d)\n", channel);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0; // Indicate error
    }

    return (1.0 - (float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
int log_data(float moisture1, float moisture2, float moisture3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Indicate error
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture1, moisture2, moisture3);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Soil Moisture Monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        float moisture1 = -1.0;
        float moisture2 = -1.0;
        float moisture3 = -1.0;

        for (int i = 0; i < 3; i++) {
            int adc_value = read_mcp3008(MCP3008_CHANNELS[i]);
            if (adc_value >= 0) {
                moisture1 = convert_adc_to_moisture(adc_value);
                if (moisture1 >= 0) {
                    moisture2 = convert_adc_to_moisture(adc_value);
                    if (moisture2 >= 0) {
                        moisture3 = convert_adc_to_moisture(adc_value);
                        if (moisture3 >= 0) {
                            log_data(moisture1, moisture2, moisture3);
                        }
                    }
                }
            }
        }

        // Sleep for 60 seconds
        gpioDelay(SLEEP_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

