#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define LED_GPIO 16
#define SENSOR_GPIO 26
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024
#define ADC_MAX_VALUE (ADC_RESOLUTION - 1)
#define ADC_MIN_VALUE 0
#define ADC_THRESHOLD (ADC_MAX_VALUE - 0.7 * ADC_RESOLUTION)
#define DEBOUNCE_DURATION 50 // ms
#define DEBOUNCE_PERIOD (DEBOUNCE_DURATION * 1000) // ms

// Global variables
static volatile int running = 1;
static int adc_value = 0;
static int debounce_count = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_adc(int channel);
int convert_adc_to_level(int adc_value);
void control_led(int state);
void log_detection(int adc_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Read ADC value from the specified channel
int read_adc(int channel) {
    if (channel < 0 || channel > ADC_CHANNEL) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    int adc_value = 0;
    int i;

    for (i = 0; i < ADC_RESOLUTION; i++) {
        gpioSetMode(SENSOR_GPIO, PI_INPUT);
        gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN); // Ensure pull-down is active
        adc_value |= (gpioRead(SENSOR_GPIO) << i);
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    return adc_value;
}

// Convert ADC value to analog level (0-1023)
int convert_adc_to_level(int adc_value) {
    return (adc_value * ADC_RESOLUTION) / ADC_MAX_VALUE;
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Log detection event to file
void log_detection(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - ADC Value: %d\n", timestamp, adc_value);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("clap_detector.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            gpioDelay(DEBOUNCE_PERIOD); // Wait before retrying
            continue;
        }

        int level = convert_adc_to_level(adc_value);

        if (level > ADC_THRESHOLD) {
            printf("Clap detected!\n");
            log_detection(adc_value);
            control_led(1); // Turn on LED
            gpioDelay(DEBOUNCE_DURATION); // Debounce
            control_led(0); // Turn off LED
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works)
    control_led(0); // Ensure LED is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

