#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200.0

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float gpio_to_voltage(int pin);
float distance_to_mm(float voltage);
void log_distance(float distance);
void activate_feeder();
void deactivate_feeder();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
