#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 5.0          // Voltage reference
#define AGND 0.0          // Ground
#define VDD 3.3           // Voltage of MLX91211 VDD
#define ADC_CHANNEL 0      // MCP3008 channel for MLX91211
#define ADC_RESOLUTION 1024 // 10-bit ADC resolution
#define ADC_MAX_VALUE 1023  // Maximum ADC value (10-bit)
#define ADC_MIN_VALUE 0    // Minimum ADC value (10-bit)
#define LOG_FILE "current_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float adc_to_current(float voltage);
void log_current(float voltage, float current);
void signal_handler(int signal);

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x80 | (channel << 4)); // Single-ended mode, channel select
    tx[2] = 0x00; // Don't care

    // Transfer data
    spiXfer(SPI_CHANNEL, tx, rx, 3);

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (VREF / ADC_RESOLUTION);
}

// Function to convert ADC value to current
float adc_to_current(float voltage) {
    return (voltage - VREF) * (50.0 / ADC_RESOLUTION);
}

