#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200
#define LOG_FILE "/home/pi/security_cam/motion_log.txt"

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to syslog
void log_event(const char* message) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, message);
    closelog();
}

// Function to capture a JPEG image
int capture_image() {
    char timestamp[21];
    snprintf(timestamp, sizeof(timestamp), "%s.jpg", get_iso8601_timestamp());

    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s", timestamp);

    int status = system(command);
    if (status == -1) {
        log_event("Error capturing image.");
        return -1;
    }
    return 0;
}

// Function to cleanup pigpio resources
void cleanup() {
    gpioTerminate();
    log_event("pigpio terminated.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Security camera started.");

    // Main loop
    while (1) {
        // Poll GPIO17
        int gpio_value = gpioRead(GPIO_PIN);
        if (gpio_value == 1) {
            // Motion detected
            log_event("Motion detected!");

            // Capture image
            if (capture_image() == 0) {
                log_event("Image capture successful.");
            } else {
                log_event("Image capture failed.");
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

            // Read GPIO again
            gpio_value = gpioRead(GPIO_PIN);
            if (gpio_value == 1) {
                // Motion detected again
                log_event("Motion detected again.");
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    return 0;
}

