// Function to initialize GPIO pins
int initialize_gpio() {
    // Initialize libgpiod
    if (gpiod_chip_create(&chip, "pan_tilt_system", GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to create chip\n");
        return -1;
    }

    if (gpiod_chip_get_line(chip, PAN_SERVO_GPIO) < 0) {
        fprintf(stderr, "Error: Failed to get line %d\n", PAN_SERVO_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_chip_get_line(chip, TILT_SERVO_GPIO) < 0) {
        fprintf(stderr, "Error: Failed to get line %d\n", TILT_SERVO_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_chip_get_line(chip, PAN_BUTTON_GPIO_PIN) < 0) {
        fprintf(stderr, "Error: Failed to get line %d\n", PAN_BUTTON_GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_chip_get_line(chip, TILT_BUTTON_GPIO_PIN) < 0) {
        fprintf(stderr, "Error: Failed to get line %d\n", TILT_BUTTON_GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_chip_get_line(chip, PAN_BUTTON_GPIO_PIN) < 0) {
        fprintf(stderr, "Error: Failed to get line %d\n", PAN_BUTTON_GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO directions
    if (gpiod_line_set_direction(pan_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set direction for pan_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_direction(tilt_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set direction for tilt_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_direction(pan_button_line, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set direction for pan_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_direction(tilt_button_line, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set direction for tilt_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pull-up/down resistors
    if (gpiod_line_set_pull_up_down(pan_line, GPIOD_LINE_PULL_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up for pan_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_pull_up_down(tilt_line, GPIOD_LINE_PULL_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up for tilt_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pull-down resistors
    if (gpiod_line_set_pull_up_down(pan_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for pan_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_pull_up_down(tilt_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for tilt_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pull-down resistors for buttons
    if (gpiod_line_set_pull_up_down(pan_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for pan_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_pull_up_down(tilt_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for tilt_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pull-down resistors for buttons
    if (gpiod_line_set_pull_up_down(pan_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for pan_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_pull_up_down(tilt_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for tilt_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pull-down resistors for buttons
    if (gpiod_line_set_pull_up_down(pan_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for pan_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_set_pull_up_down(tilt_button_line, GPIOD_LINE_PULL_DOWN) < 0) {
        fprintf(stderr, "Error: Failed to set pull-down for tilt_button_line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

