#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width range
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Function prototypes
void signal_handler(int signal);
void setup_gpio();
void cleanup_gpio();
void set_servo_pulse_width(int gpio, int pulse_width);

// Global variables
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Setup GPIO pins
void setup_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set servo pins to center position
    set_servo_pulse_width(PAN_SERVO_PIN, 1500);
    set_servo_pulse_width(TILT_SERVO_PIN, 1500);
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Stop servos
    set_servo_pulse_width(PAN_SERVO_PIN, 0);
    set_servo_pulse_width(TILT_SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();
}

// Set servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width) {
    if (gpio < 0 || gpio > 7) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return;
    }

    // Ensure pulse width is within range
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Pulse width out of range: %d\n", pulse_width);
        return;
    }

    // Convert pulse width to microseconds
    int microseconds = (int)(pulse_width / 10.0);

    // Set PWM duty cycle (0-1000)
    gpioServo(gpio, microseconds);
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO pins
    setup_gpio();

    printf("Camera Pan-Tilt System\n");
    printf("Press UP button to increase servo position, DOWN button to decrease, LEFT to move left, RIGHT to move right.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int up_pressed = gpioRead(UP_BUTTON_PIN) == PI_LOW;
        int down_pressed = gpioRead(DOWN_BUTTON_PIN) == PI_LOW;
        int left_pressed = gpioRead(LEFT_BUTTON_PIN) == PI_LOW;
        int right_pressed = gpioRead(RIGHT_BUTTON_PIN) == PI_LOW;

        // Check for button presses
        if (up_pressed) {
            // Increment servo position
            set_servo_pulse_width(PAN_SERVO_PIN, 1500 + 10);
        } else if (down_pressed) {
            // Decrement servo position
            set_servo_pulse_width(PAN_SERVO_PIN, 1500 - 10);
        } else if (left_pressed) {
            // Move left
            set_servo_pulse_width(PAN_SERVO_PIN, 1500 - 10);
        } else if (right_pressed) {
            // Move right
            set_servo_pulse_width(PAN_SERVO_PIN, 1500 + 10);
        }

        // Delay for 50ms
        usleep(50000); // 50ms
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

