#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define GPIO_PIN 17
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 5000
#define DEBOUNCE_DURATION_MS 2000
#define LOG_FILE "motion_log.txt"

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;
static int motion_detected = 0;

// Structure to hold motion data
typedef struct {
    time_t timestamp;
    int motion_detected;
} MotionData;

// Function prototypes
int initialize_gpio();
int read_motion_sensor();
void debounce_motion(int gpio_pin);
void log_motion_event();
void send_motion_data(const char *filename);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initializes the pigpio library and sets GPIO17 as an input with a pull-down resistor.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Reads the PIR sensor value from GPIO17.
int read_motion_sensor() {
    return gpioRead(GPIO_PIN);
}

// Debounces the motion sensor reading.
void debounce_motion(int gpio_pin) {
    gpioDelay(DEBOUNCE_DURATION_MS * 1000); // Convert ms to microseconds
    if (read_motion_sensor() == 1) {
        motion_detected = 1;
    }
}

// Logs the motion event to a file.
void log_motion_event() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s Motion Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Sends the motion data to the server using libcurl.
void send_motion_data(const char *filename) {
    CURL *curl;
    CURLcode res;
    char response[256];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://%s:%d/upload?filename=%s", SERVER_IP, SERVER_PORT, filename);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Set timeout to 10 seconds

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Motion data sent: %s\n", response);
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
    }
    curl_global_cleanup();
}

// Callback function for libcurl to write the response to the response buffer.
size_t write_callback(char *ptr, size_t size, size_t nmemb, void *userdata) {
    size_t real_size = size * nmemb;
    char *response = (char *)userdata;
