#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define PIR_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define IMAGE_DIR "/home/pi/images"
#define IMAGE_FILENAME_PREFIX "motion_capture_"
#define IMAGE_FILENAME_SUFFIX ".jpg"
#define DEBOUNCE_TIMEOUT_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_pir_sensor();
int debounce_motion(int gpio, int level, int timeout_ms);
int capture_image();
int save_image(const char *filename);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", SPI_DEVICE);
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    char tx_buf[1];
    char rx_buf[1];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x00; // Don't care
    tx_buf[2] = 0x00; // Don't care
    tx_buf[3] = 0x00; // Don't care

    memset(rx_buf, 0, sizeof(rx_buf));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 1;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Transfer SPI data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", SPI_DEVICE);
        return -1;
    }

    // Extract PIR signal (0 or 1)
    int pir_value = (rx_buf[0] == 0x01) ? 1 : 0;

    return pir_value;
}

// Debounce motion detection
int debounce_motion(int gpio, int level, int timeout_ms) {
    static int last_level = 0;
    static struct timespec last_change_time = {0, 0};
    struct timespec current_time;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (level == 1) {
        if (current_time.tv_sec - last_change_time.tv_sec > timeout_ms) {
            last_level = 1;
            return 1; // Motion detected
        }
    } else {
        if (current_time.tv_sec - last_change_time.tv_sec > timeout_ms) {
            last_level = 0;
            return 0; // Motion stopped
        }
    }

    ret = gpioRead(gpio);
    if (ret == level) {
        last_level = level;
        return 0; // Motion still detected
    }

    last_change_time.tv_sec = current_time.tv_sec;
    last_change_time.tv_nsec = current_time.tv_nsec;

    return 1; // Motion detected
}

// Capture image
int capture_image() {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", IMAGE_FILENAME_PREFIX);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Failed to execute libcamera-still command: %s\n", command);
        return -1;
    }

    return 0;
}

// Save image
int save_image(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    fwrite(image_data, 1, image_size, fp);
    fclose(fp);

    return 0;
}

// Log event
int log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value == 1) {
            printf("Motion detected!\n");
            if (debounce_motion(PIR_GPIO, 1, DEBOUNCE_TIMEOUT_MS)) {
                printf("Motion detected, capturing image...\n");
                if (capture_image() != 0) {
                    fprintf(stderr, "Failed to capture image\n");
                } else {
                    printf("Image saved to %s\n", IMAGE_FILENAME_PREFIX);
                    if (save_image(IMAGE_FILENAME_PREFIX) != 0) {
                        fprintf(stderr, "Failed to save image\n");
                    }
                }
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioTerminate();
    fclose(log_file);
    close(spi_fd);

    return 0;
}

