#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define servo angles (degrees)
#define PAN_ANGLE 90
#define TILT_ANGLE 90

// Define servo limits (degrees)
#define PAN_LIMIT 0
#define TILT_LIMIT 180

// Define servo pulse width range (microseconds)
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500

// Define servo movement speed (degrees per second)
