    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", TEMP_FILE);
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature from file: %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
