    // Calculate the number of pixels to draw each character
    int pixels_per_char = font_width * font_height / 10;

    // Calculate the total number of pixels to draw the text
    int total_pixels = 0;
    for (i = 0; i < strlen(text); i++) {
        total_pixels += pixels_per_char * font_size;
    }

    // Calculate the number of rows needed to display the text
    int rows = (total_pixels + font_height - 1) / font_height;

    // Calculate the number of columns needed to display the text
    int columns = total_pixels / font_width;

    // Initialize the OLED display
    oled_clear();
    oled_draw_pixel(x, y, 0x00); // Clear the display
    oled_draw_pixel(x + columns - 1, y, 0x00); // Clear the display

    // Draw the text
