// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LCD_RS, PI_OUTPUT);
    gpioSetMode(LCD_EN, PI_OUTPUT);
    gpioSetMode(LCD_D4, PI_OUTPUT);
    gpioSetMode(LCD_D5, PI_OUTPUT);
    gpioSetMode(LCD_D6, PI_OUTPUT);
    gpioSetMode(LCD_D7, PI_OUTPUT);

    gpioWrite(LCD_RS, 1); // LCD initially off
    gpioWrite(LCD_EN, 1);  // Enable LCD
    gpioWrite(LCD_D4, 0); // Clear LCD
    gpioWrite(LCD_D5, 0); // Clear LCD
    gpioWrite(LCD_D6, 0); // Clear LCD
    gpioWrite(LCD_D7, 0); // Clear LCD

    return 0;
}

