#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for row and column
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COLUMN_PINS {14, 15, 18, 23, 24, 25, 8, 7}

// Define the number of rows and columns
#define ROWS 8
#define COLS 8

// Define the common anode LED matrix size
#define MATRIX_SIZE (ROWS * COLS)

// Define the delay between columns (in milliseconds)
#define DELAY_MS 150

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    if (gpiod_chip_open_by_name("gpiochip0", GPIOD_LINE_DIRECTION_OUTPUT, &chip) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_error(chip));
        return -1;
    }

    for (int i = 0; i < ROW_PINS.length; i++) {
        if (gpiod_line_request_output(chip, ROW_PINS[i], 0) < 0) {
            fprintf(stderr, "Error requesting output for row pin %d: %s\n", ROW_PINS[i], gpiod_line_error(chip, ROW_PINS[i]));
            gpiod_chip_close(chip);
            return -1;
        }
    }

    for (int i = 0; i < COLUMN_PINS.length; i++) {
        if (gpiod_line_request_output(chip, COLUMN_PINS[i], 0) < 0) {
            fprintf(stderr, "Error requesting output for column pin %d: %s\n", COLUMN_PINS[i], gpiod_line_error(chip, COLUMN_PINS[i]));
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Function to initialize the LED matrix
int initialize_matrix() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            if (gpiod_line_request_output(chip, COLUMN_PINS[j], 0) < 0) {
                fprintf(stderr, "Error requesting output for column %d, row %d: %s\n", j, i, gpiod_line_error(chip, COLUMN_PINS[j], i));
                return -1;
            }
            if (gpiod_line_request_input(chip, ROW_PINS[i], 0) < 0) {
                fprintf(stderr, "Error requesting input for row %d, column %d: %s\n", i, j, gpiod_line_error(chip, ROW_PINS[i], j));
                return -1;
            }
            if (gpiod_line_request_input(chip, ROW_PINS[i], 1) < 0) {
                fprintf(stderr, "Error requesting input for row %d, column %d: %s\n", i, j, gpiod_line_error(chip, ROW_PINS[i], j));
                return -1;
            }
        }
    }
    return 0;
}

// Function to set the LED matrix
void set_matrix(int row, int column, int state) {
    if (gpiod_line_set_value(chip, ROW_PINS[row], state) < 0) {
        fprintf(stderr, "Error setting value for row %d, column %d: %s\n", row, column, gpiod_line_error(chip, ROW_PINS[row], column));
    }
    if (gpiod_line_set_value(chip, COLUMN_PINS[column], state) < 0) {
        fprintf(stderr, "Error setting value for column %d, row %d: %s\n", column, row, gpiod_line_error(chip, COLUMN_PINS[column], row));
    }
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            set_matrix(i, j, 0);
        }
    }
}

// Function to animate the LED matrix
void animate_matrix() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            set_matrix(i, j, 1);
            usleep(DELAY_MS * 1000); // Delay in milliseconds
            set_matrix(i, j, 0);
        }
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize LED matrix
    if (initialize_matrix() < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Animate the LED matrix
    animate_matrix();

    // Cleanup GPIO
    gpiod_chip_close(chip);

    return 0;
}

