#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    int distance;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int read_distance(int handle);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int handle) {
    char buf[2];
    int distance;

    // Write the register address to read from
    if (i2cWriteByteData(handle, DISTANCE_REG, 0) != 0) {
        fprintf(stderr, "Failed to write register address\n");
        return -1;
    }

    // Read two bytes from the sensor
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read distance\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    distance = (buf[0] << 8) | buf[1];

    return distance;
}

// Log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%d\n", timestamp, data.distance);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, MLX75031_ADDR) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        data.timestamp = time(NULL);
        data.distance = read_distance(i2c_handle);

        if (data.distance != -1) {
            log_data(log_file, data);
        } else {
            fprintf(stderr, "Failed to read distance, skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

