    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, red, green, blue, proximity);
    fflush(csv_file); // Ensure data is written to file immediately
}

