#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_ADDR 0x39

// APDS9960 registers
#define APDS9960_REG_ID 0x92
#define APDS9960_REG_ENABLE 0x80
#define APDS9960_REG_ATIME 0x81
#define APDS9960_REG_WTIME 0x83
#define APDS9960_REG_PPULSE 0x8E
#define APDS9960_REG_CONTROL 0xF1
#define APDS9960_REG_CONFIG2 0x90

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// I2C bus
#define I2C_BUS 1

// CSV file name
#define CSV_FILE "color_proximity_log.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_apds9960();
int read_apds9960_data(int *red, int *green, int *blue, int *proximity);
void log_data(int red, int green, int blue, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the APDS9960 sensor
int initialize_apds9960() {
    int status;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, APDS9960_REG_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading APDS9960 ID register: %d\n", status);
        return -1;
    }
    if (status != 0xAB) {
        fprintf(stderr, "APDS9960 ID check failed: 0x%02X != 0xAB\n", status);
        return -1;
    }

    // Enable the sensor
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_ENABLE, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 ENABLE register: %d\n", status);
        return -1;
    }

    // Configure ATIME, WTIME, PPULSE, CONTROL, and CONFIG2
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_ATIME, 0xDB);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 ATIME register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_WTIME, 0xF6);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 WTIME register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_PPULSE, 0x87);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 PPULSE register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_CONTROL, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 CONTROL register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, APDS9960_REG_CONFIG2, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to APDS9960 CONFIG2 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read data from the APDS9960 sensor
int read_apds9960_data(int *red, int *green, int *blue, int *proximity) {
    int red_raw, green_raw, blue_raw, proximity_raw;

    // Read RGB data
    red_raw = i2cReadWordData(i2c_handle, 0x96);
    green_raw = i2cReadWordData(i2c_handle, 0x98);
    blue_raw = i2cReadWordData(i2c_handle, 0x9A);

    if (red_raw < 0 || green_raw < 0 || blue_raw < 0) {
        fprintf(stderr, "Error reading RGB data\n");
        return -1;
    }

    // Read proximity data
    proximity_raw = i2cReadByteData(i2c_handle, 0x9C);
    if (proximity_raw < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    *red = red_raw;
    *green = green_raw;
    *blue = blue_raw;
    *proximity = proximity_raw;

    return 0;
}

// Log data to CSV file
void log_data(int red, int green, int blue, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, red, green, blue, proximity);
    fflush(csv_file); // Ensure data is written to file immediately
}

int main() {
    int red, green, blue, proximity;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the APDS9960 sensor
    if (initialize_apds9960() != 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read data from the sensor
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            // Log the data
            log_data(red, green, blue, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 milliseconds
        gpioDelay(100);
    }

    // Close I2C bus and CSV file
    i2cClose(i2c_handle);
    fclose(csv_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

