#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define RESULT_RANGE_STATUS 0x14
#define RESULT_INTERVAL_MS 100
#define TIMEOUT_US 100
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_vl53l0x();
int read_distance();
void log_distance(int distance_mm);
void signal_handler(int signal);
void cleanup();

// Structure to hold VL53L0X registers
typedef struct {
    uint8_t sysrange_start;
    uint8_t result_interrupt_status;
    uint8_t result_range_status;
} vl53l0x_regs_t;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize VL53L0X sensor
int init_vl53l0x() {
    // Reset the sensor (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Reset command
        fprintf(stderr, "Failed to reset VL53L0X\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (example configuration, adjust as needed)
    vl53l0x_regs_t regs = {
        .sysrange_start = 0x01, // Example: Set system range start
        .result_interrupt_status = 0x01, // Example: Set interrupt status
        .result_range_status = 0x01 // Example: Set result range status
    };

    if (i2cWriteI2CBlockData(i2c_handle, 0x00, (char *)&regs, sizeof(regs)) < 0) {
        fprintf(stderr, "Failed to write to VL53L0X registers\n");
        return -1;
    }

    gpioDelay(10); // Wait for configuration to take effect

    return 0;
}

// Function to read distance from VL53L0X sensor
int read_distance() {
    // Read 14 bytes from the sensor
    char buffer[14];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x14, (char *)buffer, 14);

    if (bytes_read != 14) {
        fprintf(stderr, "Failed to read distance: %d bytes read\n", bytes_read);
        return -1;
    }

    // Combine the first two bytes to form the 16-bit distance value
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to log distance measurement
void log_distance(int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(TIMEOUT_US); // Wait for timeout before next measurement
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

