#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define CH101_ADDR 0x45
#define I2C_BUS 1
#define MEASUREMENT_DURATION_US 50000 // 50ms
#define SAMPLE_INTERVAL_MS 200
#define BUFFER_SIZE 10

static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Structure to hold sensor data
typedef struct {
    int distance;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor(int i2c_handle, int *distance);
void log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the CH101 sensor
int read_sensor(int i2c_handle, int *distance) {
    char buf[2];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Trigger measurement command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(MEASUREMENT_DURATION_US);

    // Read 16-bit distance value
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the raw data to distance in millimetres
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Log data to file
void log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        // Read distance from sensor
        if (read_sensor(i2c_handle, &sensor_data.distance) == 0) {
            // Log data
            log_data(log_file, sensor_data.distance);

            printf("Distance: %d mm\n", sensor_data.distance);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

