// Define constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_led();
int read_distance();
void log_distance(float distance);
void control_led(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LED GPIO
int init_led() {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn off LED initially
    return 0;
}

// Read distance from the sensor
int read_distance() {
    char buf[2];
    int distance;

    // Send measurement command (example, adjust based on datasheet)
    buf[0] = 0x01; // Example command
    buf[1] = 0x00; // Example data

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    // Read 2 bytes of data (adjust based on datasheet)
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    distance = (buf[0] << 8) | buf[1]; // Combine bytes

    return distance;
}

// Log distance to file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED
    if (init_led() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic Time-of-Flight sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

