#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int proximity;
    int ambient;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int result;

    // Read proximity data
    result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read proximity data: %d\n", result);
        return -1;
    }

    data->proximity = (buf[0] << 8) | buf[1];

    // Read ambient light data
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ambient light data: %d\n", result);
        return -1;
    }

    data->ambient = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to log sensor data
int log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

