#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

