int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int read_distance();
void log_distance(int distance);
void control_led(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance() {
    char buf[2];
    int distance;

    // Read WHO_AM_I register
    if (i2cWriteByte(i2c_handle, WHO_AM_I_REG) != 0) {
        fprintf(stderr, "Error writing WHO_AM_I register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    // Check WHO_AM_I register
    if (buf[0] != 0x01) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", buf[0]);
        return -1;
    }

    // Read distance data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];
    return distance;
}

