#define SI1182_REG_IRQ_STATUS 0x25
#define SI1182_REG_RESULT_LSB 0x2A
#define SI1182_REG_RESULT_MSB 0x2B

// Define the proximity threshold (adjust as needed)
#define PROXIMITY_THRESHOLD 500

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the Si1182 sensor
int init_si1182() {
    // Initialize the sensor by writing 0x01 to the CONFIG register
    if (i2cWriteByteData(i2c_handle, SI1182_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the 16-bit proximity value from the sensor
int read_proximity() {
    int lsb, msb;

    // Read the LSB
    lsb = i2cReadByteData(i2c_handle, SI1182_REG_RESULT_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", lsb);
        return -1;
    }

    // Read the MSB
    msb = i2cReadByteData(i2c_handle, SI1182_REG_RESULT_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", msb);
        return -1;
    }

    // Combine the LSB and MSB to form the 16-bit proximity value
    return (msb << 8) | lsb;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the proximity value
        int proximity = read_proximity();

        // Check for errors during proximity reading
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity value\n");
        } else {
            // Check if the proximity value is within the threshold
            if (proximity >= PROXIMITY_THRESHOLD) {
                // Print the proximity value
                printf("Proximity: %d\n", proximity);
            }
        }

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Close the I2C bus and terminate the pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

