#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <time.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4C
#define I2C_SLAVE_ADDR 0x00
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Function to handle signals (Ctrl-C, etc.)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, unsigned char reg) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word: %s\n", strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to convert raw distance to millimetres
float convert_distance(unsigned int raw_value) {
    return (float)raw_value * 0.125;
}

int main() {
    int i2c_fd;
    struct timespec sleep_time;
    struct sigaction sa;
    int retry_count = 0;
    unsigned int raw_distance;
    float distance;

    // Register signal handlers for graceful shutdown
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set up nanosleep loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds

    // Main loop
    while (1) {
        // Read distance from the sensor
        raw_distance = read_i2c_word(i2c_fd, I2C_SLAVE_ADDR);
        if (raw_distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            retry_count++;
            if (retry_count > I2C_RETRY_COUNT) {
                fprintf(stderr, "Maximum retry count reached, exiting.\n");
                close(i2c_fd);
                return 1;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Convert raw distance to millimetres
        distance = convert_distance(raw_distance);

        // Print the distance
        printf("Distance: %.2f mm\n", distance);

        // Wait for the next reading
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

