    sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds

    // Main loop
    while (1) {
        // Read distance from the sensor
        raw_distance = read_i2c_word(i2c_fd, I2C_SLAVE_ADDR);
        if (raw_distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            retry_count++;
            if (retry_count > I2C_RETRY_COUNT) {
                fprintf(stderr, "Maximum retry count reached, exiting.\n");
                close(i2c_fd);
                return 1;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Convert raw distance to millimetres
        distance = convert_distance(raw_distance);

        // Print the distance
        printf("Distance: %.2f mm\n", distance);

        // Wait for the next reading
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

