// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_DURATION 10 // microseconds
#define ECHO_DURATION_MIN 200 // microseconds
#define ECHO_DURATION_MAX 3800 // microseconds
#define TIMEOUT_US 200000 // microseconds (200ms)

// Global variables
volatile int trigger_state = 1; // 1 for high, 0 for low
volatile int echo_start_time = 0; // Time of echo start
volatile int echo_end_time = 0; // Time of echo end

// Function prototypes
int initialize_gpio();
int trigger_pulse();
int measure_echo();
double calculate_distance(int pulse_width);
void log_data(double distance);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Trigger the HC-SR04 sensor
int trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Measure the echo pulse width
int measure_echo() {
    int start_time = gpioTick();
    int end_time = start_time;

    // Wait for echo to start
    while (gpioRead(ECHO_PIN) == 0 && start_time < ECHO_DURATION_MIN) {
        start_time = gpioTick();
    }

    if (start_time >= ECHO_DURATION_MIN) {
        echo_start_time = start_time;
        echo_end_time = start_time;
    } else {
        fprintf(stderr, "Echo start timeout: %d\n", ECHO_DURATION_MIN);
        return -1; // Timeout
    }

    // Wait for echo to end
    while (gpioRead(ECHO_PIN) == 1 && end_time > ECHO_DURATION_MIN) {
        end_time = gpioTick();
    }

    if (end_time > ECHO_DURATION_MIN) {
        echo_end_time = end_time;
        return 0; // Timeout
    } else {
        fprintf(stderr, "Echo end timeout: %d\n", ECHO_DURATION_MIN);
        return -1; // Timeout
    }
}

// Calculate distance in centimeters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0 || pulse_width > 3800) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1.0; // Indicate error
    }

    // Distance in centimeters = (pulse_width * 0.0343) / 2
    return (double)pulse_width * 0.0343 / 2.0;
}

// Log data to console
void log_data(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %.2f cm\n", timestamp, distance);
}

// Cleanup GPIO pins and terminate pigpio
void cleanup() {
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 Ultrasonic Sensor Data Logger\n");

    while (1) {
        // Trigger the sensor
        if (trigger_pulse() != 0) {
            fprintf(stderr, "Error triggering sensor\n");
            cleanup();
            return 1;
        }

        // Measure the echo pulse width
        int pulse_width = measure_echo();
        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring echo pulse width\n");
            cleanup();
            return 1;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);
        if (distance < 0) {
            fprintf(stderr, "Error calculating distance\n");
            cleanup();
            return 1;
        }

        // Log the data
        log_data(distance);

        // Wait for 1 second
        gpioDelay(1000); // 1 second = 1000 milliseconds
    }

    return 0;
}

