#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart(const char *device, speed_t baud_rate);
int configure_uart(int fd, struct termios *termios_ptr);
int read_uart(int fd, char *buffer, int max_len);
int parse_header(const char *buffer, int *magic_word, int *range_resolution);
int parse_range_profile(const char *buffer, int *range_bins, int *range_resolution);
int detect_intrusion(int range_bins, int distance);
int log_intrusion(const char *timestamp, int distance);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Initialize UART
int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios termios_settings;
    if (tcgetattr(fd, &termios_settings) != 0) {
        perror("Error getting termios settings");
        close(fd);
        return -1;
    }

    termios_settings.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;
    termios_settings.c_iflag = IGNPAR;
    termios_settings.c_oflag = 0;
    termios_settings.c_lflag = 0;

    if (tcsetattr(fd, TCSANOW, &termios_settings) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Configure UART
int configure_uart(int fd, struct termios *termios_ptr) {
    if (tcsetattr(fd, TCSANOW, termios_ptr) != 0) {
        perror("Error setting termios attributes");
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return bytes_read;
}

// Parse header
int parse_header(const char *buffer, int *magic_word, int *range_resolution) {
    if (strncmp(buffer, "MAGIC_WORD", 8) != 0) {
        return -1;
    }
    *magic_word = buffer[8];
    if (strncmp(buffer + 9, "RANGE_RESOLUTION", 13) != 0) {
        return -1;
    }
    *range_resolution = atoi(buffer + 12);
    return 0;
}

// Parse range profile
int parse_range_profile(const char *buffer, int *range_bins, int *range_resolution) {
    int i;
    for (i = 0; i < 64; i++) {
        if (strncmp(buffer + (i * 16), "BIN", 3) == 0) {
            range_bins[i] = atoi(buffer + (i * 16) + 3);
        }
    }
    *range_resolution = atoi(buffer + (64 * 16) + 3);
    return 0;
}

// Detect intrusion
int detect_intrusion(int range_bins, int distance) {
    if (distance < range_bins) {
        return 1; // Intrusion detected
    }
    return 0; // No intrusion
}

// Log intrusion
int log_intrusion(const char *timestamp, int distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
    fprintf(log_file, "%s,Intrusion Detected,Distance: %d meters\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Ensure LED is off initially

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Configure UART
    if (configure_uart(uart_fd, &termios_settings) == -1) {
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    char buffer[256];
    int magic_word, range_resolution;
    int range_bins[64];
    int intrusion_detected = 0;

    printf("Starting intrusion detection...\n");

    while (program_running) {
        // Read data from UART
        ssize_t bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Parse header
            if (parse_header(buffer, &magic_word, &range_resolution) == 0) {
                // Parse range profile
                if (parse_range_profile(buffer + 64, range_bins, &range_resolution) == 0) {
                    // Detect intrusion
                    if (detect_intrusion(range_bins, range_resolution)) {
                        intrusion_detected = 1;
                    }

                    // Log intrusion
                    if (intrusion_detected) {
                        time_t rawtime;
                        struct tm *timeinfo;
                        time(&rawtime);
                        timeinfo = localtime(&rawtime);
                        char timestamp[20];
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                        log_intrusion(timestamp, range_resolution);
                    }
                }
            } else {
                fprintf(stderr, "Error parsing range profile header\n");
            }
        } else if (bytes_read == -1) {
            perror("Error reading from UART");
            break;
        } else {
            usleep(100000); // Check every 100ms
        }
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

