#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDR 0x69
#define GPIO_ALERT 17
#define DISTANCE_THRESHOLD 10.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void log_distance(int distance);
void check_alert(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x31, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Log the distance to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %d\n", timestamp, distance);
    fclose(fp);
}

// Check for alert based on distance
void check_alert(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1); // Set GPIO HIGH
        printf("Alert triggered! Distance: %d cm\n", distance);
    } else {
        gpioWrite(GPIO_ALERT, 0); // Set GPIO LOW
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_ALERT, 0); // Ensure GPIO is LOW before exiting
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic Time-of-Flight sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance;

        // Read distance
        if (read_distance(&distance) == 0) {
            // Log the distance
            log_distance(distance);

            // Check for alert
            check_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

