// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x60
#define MEASUREMENT_COMMAND 0x00
#define MEASUREMENT_DURATION_US 50000 // 50ms
#define LOG_FILE "distance_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    int distance_cm;
} SensorData;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_distance(int *distance);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Triggers a measurement on the MLX75030
int trigger_measurement() {
    char buf[2];
    buf[0] = MEASUREMENT_COMMAND;
    buf[1] = 0; // Dummy value for measurement command
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the distance from the MLX75030
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(MEASUREMENT_DURATION_US);

    // Read distance data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Convert the data to a signed 16-bit integer
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Logs the data to a CSV file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d\n", timestamp, data.distance_cm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    SensorData data;

    // Main loop
    while (program_running) {
        if (trigger_measurement() == 0) {
            if (read_distance(&distance) == 0) {
                data.timestamp = time(NULL);
                data.distance_cm = distance;
                log_data(data);
            } else {
                fprintf(stderr, "Error reading distance, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

