#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int event_type);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the event to the log file
void log_event(int sensor_id, int event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Determine the event type based on sensor values
        int event_type;
        if (sensor1_value == 1) {
            event_type = 'DETECTED';
        } else if (sensor2_value == 1) {
            event_type = 'DETECTED';
        } else {
            event_type = 'CLEARED';
        }

        // Log the event
        log_event(1, event_type);

        // Delay for 10 milliseconds
        gpioDelay(10);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

