// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// VL53L5CX register addresses (example, adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x01
#define VL53L5CX_REG_SYSTEM_START 0x02
#define VL53L5CX_REG_SYSTEM_STOP 0x03
#define VL53L5CX_REG_SYSTEM_RESET 0x04
#define VL53L5CX_REG_SYSTEM_INTERRUPT_ENABLE 0x05
#define VL53L5CX_REG_SYSTEM_INTERRUPT_STATUS 0x06
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x07
#define VL53L5CX_REG_SYSTEM_INTERRUPT_ENABLE_CLEAR 0x08
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR_CLEAR 0x09
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR_CLEAR_CLEAR 0x0A
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR_CLEAR_CLEAR_CLEAR 0x0B
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR_CLEAR_CLEAR_CLEAR_CLEAR 0x0C
