#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C address of the MLX75030 sensor
#define MLX75030_I2C_ADDR 0x4C

// Define the I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the register address for distance measurement (example, adjust based on datasheet)
#define DISTANCE_REG 0x00 // Example register address

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a distance measurement from the MLX75030 sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int distance;

    // Read 2 bytes from the distance register
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    distance = (buf[0] << 8) | buf[1];

    return distance;
}

// Function to log the distance measurement with a timestamp
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %d mm\n", timestamp, distance);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int distance = read_distance(i2c_handle);

        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(100); // Wait 100 milliseconds
    }

    // The following lines will never be reached in normal execution
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

