#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100.0
#define I2C_ERROR_LOG_FILE "i2c_error.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int state);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x00) < 0) {
        log_error("Failed to perform soft reset");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set slave device address
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x0001) < 0) {
        log_error("Failed to set slave device address");
        return -1;
    }

    // Set system mode
    if (i2cWriteByteData(i2c_handle, 0x0007, 0x07) < 0) {
        log_error("Failed to set system mode");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, 0x0096, 0x00) < 0) {
        log_error("Failed to start ranging");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char buf[2];
    int distance;

    if (i2cReadI2CBlockData(i2c_handle, 0x0096, buf, 2) != 2) {
        log_error("Failed to read distance");
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

// Log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen(I2C_ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        log_error("Failed to initialize VL53L1X sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Turn buzzer on
            } else {
                control_buzzer(0); // Turn buzzer off
            }
        } else {
            log_error("Failed to read distance");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

