#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 343.0 // m/s
#define TIMEOUT_THRESHOLD 50.0 // ms
#define SERVO_PULSE_WIDTH_MIN 2000 // us
#define SERVO_PULSE_WIDTH_MAX 2000 // us
#define SERVO_PULSE_WIDTH_STEP 100 // us
#define SERVO_MIN_ANGLE -90.0
#define SERVO_MAX_ANGLE 90.0
#define LOG_FILE "sensor_data.log"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int trigger_sensor();
int measure_distance();
int map_distance_to_angle(int distance);
void control_servo(int angle);
void log_data(int distance, int angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_servo(0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioWrite(ECHO_PIN, 1);     // Ensure echo is high initially

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Measure the distance using the HC-SR04 sensor
int measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    long start_time = 0, end_time = 0;
    int pulse_count = 0;

    // Wait for echo to start
    while (gpioRead(ECHO_PIN) == 0 && pulse_count < 100) {
        start_time = gpioTick();
        pulse_count++;
    }
    if (pulse_count >= 100) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1;
    }

    // Wait for echo to end
    while (gpioRead(ECHO_PIN) == 1 && pulse_count < 100) {
        end_time = gpioTick();
        pulse_count++;
    }
    if (pulse_count >= 100) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1;
    }

    long pulse_duration = end_time - start_time;

    // Calculate distance in centimeters
    int distance = (int)(pulse_duration * SPEED_OF_SOUND / 2.0);

    return distance;
}

// Map distance to servo angle
int map_distance_to_angle(int distance) {
    if (distance < 0) {
        return SERVO_MIN_ANGLE;
    } else if (distance > 400) {
        return SERVO_MAX_ANGLE;
    } else {
        return (int)((distance - 0) / 400.0 * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);
    }
}

// Control the servo motor
void control_servo(int angle) {
    if (angle < SERVO_MIN_ANGLE) {
        angle = SERVO_MIN_ANGLE;
    } else if (angle > SERVO_MAX_ANGLE) {
        angle = SERVO_MAX_ANGLE;
    }

    gpioServo(SERVO_PIN, angle);
}

// Log data to file
void log_data(int distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d, Angle: %d\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
