void echo_callback(int gpio, int level, uint32_t tick);
void cleanup();
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt callback function for echo pulse
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
    } else if (level == 0) {
        echo_end_time = tick;
        echo_duration = tick - echo_start_time;
        echo_start_time = 0;
        echo_end_time = 0;
        valid_readings = 0;
    }
}

