#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19

// Define I2C address and register addresses
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL53L1X_REG_RANGE_STATUS 0x004
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x006
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x014

// Define constants
#define DISTANCE_THRESHOLD 200 // mm
#define TIMEOUT_US 50000       // 50ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_vl53l1x();
int read_distance(int *distance);
void control_gate(int open);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int initialize_vl53l1x() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Reset command
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set measurement mode (continuous ranging)
    status = i2cWriteByteData(i2c_handle, 0x01, 0x01); // Set measurement mode
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X measurement mode set failed: %d\n", status);
        return -1;
    }

    // Set timeout duration (adjust as needed)
    status = i2cWriteByteData(i2c_handle, 0x02, TIMEOUT_US); // Set timeout duration
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X timeout duration set failed: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    int status;
    unsigned char data[2];
    int distance_mm;

    // Read range status
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGE_STATUS, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X range status read failed: %d\n", status);
        return -1;
    }

    // Combine high and low bytes
    distance_mm = (data[0] << 8) | data[1];

    // Check for error (e.g., timeout)
    if (distance_mm == 0) {
        fprintf(stderr, "Error: VL53L1X timeout error\n");
        return -1;
    }

    *distance = distance_mm;
    return 0;
}

// Control the gate actuator
void control_gate(int open) {
    gpioWrite(GATE_OPEN_PIN, open);
    gpioWrite(GATE_CLOSE_PIN, !open);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);

    // Initialize VL53L1X sensor
    if (initialize_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Check if object is detected within threshold
            if (distance < DISTANCE_THRESHOLD) {
                // Open gate
                control_gate(1);
                log_event("Object detected and gate opened");
            } else {
                // Close gate
                control_gate(0);
                log_event("Object detected but no object within threshold");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        // Wait for 500ms
        gpioDelay(500);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_gate(0); // Ensure gate is closed before exiting
    gpioWrite(GATE_OPEN_PIN, 0); // Ensure gate is closed
    gpioWrite(GATE_CLOSE_PIN, 1); // Ensure gate is open
    fclose(log_file);
    gpioTerminate();

    return 0;
}

