#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define SPEED_OF_SOUND 343.0 // m/s
#define TIMEOUT_US 50000 // 50ms
#define TIMEOUT_MS 50000 // 50ms
#define MAX_DISTANCE 400.0 // 400 cm
#define MIN_DISTANCE 2.0  // 2 cm
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile sig_atomic_t running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int gpiod_request_output(int gpio, const char *name);
int gpiod_request_input(int gpio, const char *name);
int gpiod_release(int gpio);
int gpiod_get_value(int gpio);
int gpiod_set_value(int gpio, int value);
int gpiod_get_value_ex(int gpio, int *value);
int gpiod_get_value_ex(int gpio, int *value);
int gpiod_get_value_ex(int gpio, int *value);
float measure_distance(int echo_gpio);
void log_distance(float distance);
void signal_handler(int sig);

// Helper function to request a GPIO line
int gpiod_request_output(int gpio, const char *name) {
    int fd = gpiod_request_output(gpio, name);
    if (fd < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return fd;
}

// Helper function to request an input GPIO line
int gpiod_request_input(int gpio, const char *name) {
    int fd = gpiod_request_input(gpio, name);
    if (fd < 0) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return fd;
}

// Helper function to release a GPIO line
int gpiod_release(int gpio) {
    int fd = gpiod_release(gpio);
    if (fd < 0) {
        fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return fd;
}

// Helper function to get the value of a GPIO line
int gpiod_get_value(int gpio) {
    int value = gpiod_get_value_ex(gpio, NULL);
    if (value < 0) {
        fprintf(stderr, "Error getting value for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return value;
}

// Helper function to set the value of a GPIO line
int gpiod_set_value(int gpio, int value) {
    int fd = gpiod_set_value(gpio, value);
    if (fd < 0) {
        fprintf(stderr, "Error setting value for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return fd;
}

// Helper function to get the value of a GPIO line with timeout
int gpiod_get_value_ex(int gpio, int *value) {
    int fd = gpiod_get_value(gpio);
    if (fd < 0) {
        return -1;
    }
    int retries = 3;
    int timeout_us = TIMEOUT_US;
    while (retries > 0) {
        if (gpiod_get_value(gpio) < 0) {
            fprintf(stderr, "Error getting value for GPIO %d (retry %d)\n", gpio, retries);
            retries--;
            usleep(1000); // Wait 1ms before retrying
            continue;
        }
        *value = gpiod_get_value(gpio);
        if (*value >= 0) {
            return 0; // Success
        }
        usleep(1000); // Wait 1ms before retrying
        retries--;
    }
    return -1; // Failure after retries
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance(int echo_gpio) {
    int trigger_value = 1;
    int echo_value = 0;
    int timeout_count = 0;

    // Trigger the sensor
    if (gpiod_set_value(trigger_gpio, trigger_value) < 0) {
        fprintf(stderr, "Error setting trigger GPIO %d to high\n", trigger_gpio);
        return -1.0;
    }
    usleep(10); // 10us trigger pulse

    // Measure the echo pulse width
    while (gpiod_get_value_ex(echo_gpio, &echo_value) == 0) {
        timeout_count++;
        usleep(1); // Check every 1us
    }

    if (timeout_count > TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo on GPIO %d\n", echo_gpio);
        return -1.0;
    }

    // Measure the echo pulse width
    while (gpiod_get_value_ex(echo_gpio, &echo_value) == 0) {
        timeout_count++;
        usleep(1); // Check every 1us
    }

