// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 27
#define I2C_HANDLE 1
#define READ_DELAY_MS 100

// VL53L1X Registers
#define REG_XSHUT 0x00
#define REG_RANGE_CONFIG 0x01
#define REG_START_RANGE 0x02
#define REG_RESULT_RANGE 0x03
#define REG_RESULT_STATUS 0x04
#define REG_RESULT_DISTANCE0 0x08
#define REG_RESULT_DISTANCE1 0x09
#define REG_RESULT_DISTANCE2 0x0A
#define REG_RESULT_DISTANCE3 0x0B
#define REG_RESULT_DISTANCE4 0x0C
#define REG_RESULT_DISTANCE5 0x0D
#define REG_RESULT_DISTANCE6 0x0E
#define REG_RESULT_DISTANCE7 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
int log_data(time_t timestamp, int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// VL53L1X Initialization function
int init_vl53l1x() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_XSHUT, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to reset VL53L1X");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, REG_RANGE_CONFIG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to configure VL53L1X");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_START_RANGE, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int read_distance() {
    char buffer[2];
    int distance;

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, REG_RESULT_DISTANCE0, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to log data to syslog
int log_data(time_t timestamp, int distance, int status) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp_str, distance, status);
    return 0;
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioWrite(GPIO_TRIGGER, 0); // Ensure it's initially low

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance();
        if (distance < 0) {
            syslog(LOG_ERR, "Failed to read distance, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Get timestamp
        time_t now = time(NULL);

        // Log data
        log_data(now, distance, 0); // Status is 0 for successful read

        // Wait for 100ms
        gpioDelay(READ_DELAY_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

