#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X Registers
#define REG_MODEL_ID 0x010F
#define REG_RANGE_MODE 0x0021
#define REG_START_RANGE 0x0015
#define REG_RANGE_STATUS 0x0089
#define REG_DISTANCE_LOW 0x0089
#define REG_DISTANCE_HIGH 0x008A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check model ID
    int model_id = gpioRead(VL53L1X_ADDR);
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID: 0x%X\n", model_id);
        return -1;
    }

    // Set ranging mode
    if (gpioWrite(VL53L1X_ADDR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Start ranging
    if (gpioWrite(VL53L1X_ADDR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char buf[2];
    int distance;

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, REG_DISTANCE_LOW, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];

    return distance;
}

// Control the gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_GPIO, 1); // Open gate
    } else {
        gpioWrite(GATE_GPIO, 0); // Close gate
    }
}

// Log data to file
void log_data(int distance, int gate_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Distance: %d mm, Gate: %s\n", timestamp, distance, gate_state ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to file immediately
}

