#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SOUND_SPEED 34300.0 // cm/s
#define MAX_DISTANCE 400.0  // cm
#define MIN_DISTANCE 2.0   // cm
#define TIMEOUT_US 30000     // 30 ms
#define SERVO_PULSE_WIDTH_MIN 500
#define SERVO_PULSE_WIDTH_MAX 2500
#define SERVO_PULSE_WIDTH_STEP 100
#define SERVO_DEBOUNCE_DELAY_US 10000 // 10 ms

// Define servo parameters
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t alert_flag = 0;

// Function prototypes
int trigger_pulse();
int echo_pulse();
float calculate_distance(int pulse_width);
float map_distance_to_angle(float distance);
int map_angle_to_pulse_width(float angle);
int gpio_alert_callback(int gpio, int level, uint32_t tick, void *userdata);
int gpio_servo_command(int gpio, int pulse_width);
int log_data(float distance, float angle);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
int trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Function to measure the echo pulse width
int echo_pulse() {
    int pulse_width = 0;
    int i;

    // Wait for the echo pin to go high
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo high.\n");
        return -1; // Indicate timeout error
    }

    // Measure the pulse width
    for (i = 0; i < 1000; i++) {
        if (gpioRead(ECHO_PIN) == 1) {
            pulse_width++;
        }
        gpioDelay(1); // Check every 1 us
    }

    pulse_width++; // Add one more check

    return pulse_width;
}

// Function to calculate the distance from the pulse width
float calculate_distance(int pulse_width) {
    return (float)pulse_width * SOUND_SPEED / 2.0;
}

// Function to map the distance to an angle for the servo
float map_distance_to_angle(float distance) {
    // Non-linear mapping (logarithmic)
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 180.0;
    if (angle < 0.0) angle = 0.0;
    if (angle > 180.0) angle = 180.0;
    return angle;
}

// Function to map the angle to a pulse width for the servo
int map_angle_to_pulse_width(float angle) {
    // Linear mapping (adjust as needed)
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    return pulse_width;
}

// Function to handle the alert callback
int gpio_alert_callback(int gpio, int level, uint32_t tick, void *userdata) {
    if (level == 1) { // Rising edge
        alert_flag = 1;
    } else if (level == 0) { // Falling edge
        alert_flag = 0;
    }
    return 0;
}

// Function to control the servo
int gpio_servo_command(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width for servo command.\n");
        return -1;
    }

    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width to %d us.\n", pulse_width);
        return -1;
    }
    return 0;
}

// Function to log the data to a CSV file
int log_data(float distance, float angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register alert callback
    if (gpioSetAlertFuncEx(ECHO_PIN, gpio_alert_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register alert callback.\n");
        gpioTerminate();
        return 1;
    }

    // Set servo initial pulse width
    gpioServo(SERVO_PIN, SERVO_MIN_PULSE_WIDTH);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance tracking started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the echo pulse width
        int pulse_width = echo_pulse();
        if (pulse_width < 0) {
            fprintf(stderr, "Error: Echo pulse width measurement failed.\n");
            continue; // Skip to the next iteration
        }

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Map the distance to an angle
        float angle = map_distance_to_angle(distance);

        // Map the angle to a pulse width
        int pulse_width_val = map_angle_to_pulse_width(angle);

        // Set the servo pulse width
        if (gpio_servo_command(SERVO_PIN, pulse_width_val) != 0) {
            fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        }

        // Log the data
        if (log_data(distance, angle) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Stop the servo
    gpioServo(SERVO_PIN, SERVO_MIN_PULSE_WIDTH);

    // Close the CSV file
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp != NULL) {
        fprintf(fp, "NULL,NULL\n");
        fclose(fp);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

