#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define GPIO_INTERRUPT 27
#define PROXIMITY_THRESHOLD 1000
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int address);
int init_gpio(int gpio_pin);
int read_proximity(int i2c_handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_proximity(int proximity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to read proximity from Si1102
int read_proximity(int i2c_handle) {
    char buf[2];
    int proximity = -1; // Initialize to an invalid value

    if (i2cReadI2CBlockData(i2c_handle, 0x08, buf, 2) != 2) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    proximity = (buf[0] << 8) | buf[1];
    return proximity;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *sensor_data = (sensor_data_t *)user_data;
    int proximity = read_proximity(i2c_handle);

    if (proximity >= 0) {
        sensor_data->proximity = proximity;
        log_proximity(proximity);
    } else {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
    }
}

// Function to log proximity data
void log_proximity(int proximity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Proximity: %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int i2c_address = SI1102_ADDR;
    int threshold = PROXIMITY_THRESHOLD;
    int gpio_pin = GPIO_INTERRUPT;

    // Parse command-line arguments
    if (argc > 1) {
        i2c_address = strtol(argv[1], NULL, 0);
    }
    if (argc > 2) {
        threshold = strtol(argv[2], NULL, 0);
    }
    if (argc > 3) {
        gpio_pin = strtol(argv[3], NULL, 0);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(gpio_pin) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. I2C address: 0x%x, threshold: %d, GPIO pin: %d\n", i2c_address, threshold, gpio_pin);

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

