#define SPEAKER_FREQUENCY_MIN 200.0
#define SPEAKER_FREQUENCY_MAX 2000.0
#define SPEAKER_FREQUENCY_STEP 50.0
#define TIMEOUT_US 10000 // 10 ms timeout
#define TIMEOUT_MS 100 // 100 ms timeout

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_timeout = 0;
volatile int frequency = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
void set_speaker_frequency(int frequency);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioTrigger(TRIGGER_PIN, 10, 0); // 10 us trigger pulse
    echo_start = gpioTick();
    echo_timeout = 0;
}

// Callback function for echo timeout
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_timeout++;
        if (echo_timeout > TIMEOUT_MS) {
            echo_timeout = 0;
            fprintf(stderr, "Error: Echo timeout!\n");
            frequency = 0; // Set frequency to 0 to avoid error tone
        }
    }
}

// Function to set the speaker frequency using PWM
void set_speaker_frequency(int frequency) {
    if (frequency < SPEAKER_FREQUENCY_MIN || frequency > SPEAKER_FREQUENCY_MAX) {
        fprintf(stderr, "Error: Invalid frequency: %d Hz\n", frequency);
        frequency = 0; // Set frequency to 0 to avoid error tone
    }

    // Map distance to frequency using logarithmic formula
    frequency = 200 * exp(50.0 * (double)(echo_end - echo_start) / 50.0);

    // Set PWM duty cycle
    gpioPWM(SPEAKER_PIN, (int)(frequency * 100.0)); // pigpio PWM range is 0-1000
}

// Function to cleanup resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(SPEAKER_PIN, 1000); // Set PWM range to 0-1000
    gpioSetPWMfrequency(SPEAKER_PIN, 1000); // Set PWM frequency to 1000 Hz

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for echo timeout
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_sensor();
        set_speaker_frequency(frequency);
        gpioDelay(10); // Delay for 10 ms
    }

    return 0;
}

