// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 400
#define PWM_FREQUENCY_MIN_DIST 200
#define PWM_FREQUENCY_MAX_DIST 2000
#define PWM_FREQUENCY_MIN_DIST 200
#define PWM_FREQUENCY_MAX_DIST 2000
#define TIMEOUT_DISTANCE 100

// Global variables
static volatile int running = 1;
static float distance = 0.0;
static float frequency = 0.0;

// Function prototypes
int initialize_gpio();
int read_distance();
float calculate_frequency(float distance);
void set_buzzer_frequency(float frequency);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Read distance from HC-SR04 sensor
int read_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_DISTANCE) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_DISTANCE) {
        fprintf(stderr, "Timeout reading distance\n");
        return -1; // Indicate timeout
    }

    // Measure echo pulse width in microseconds
    int pulse_width = gpioRead(ECHO_PIN);
    return pulse_width;
}

// Calculate frequency from distance using linear mapping
float calculate_frequency(float distance) {
    if (distance < 0.0) {
        return 0.0;
    }

    float frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (distance / MAX_DIST) + PWM_FREQUENCY_MIN_DIST;
    if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }
    if (frequency < PWM_FREQUENCY_MIN_DIST) {
        frequency = PWM_FREQUENCY_MIN_DIST;
    }

    return frequency;
}

// Set buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    }
    if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }

    gpioPWM(BUZZER_PIN, frequency);
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read distance
        int pulse_width = read_distance();
        if (pulse_width < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate frequency
        float frequency = calculate_frequency(pulse_width);

        // Set buzzer frequency
        set_buzzer_frequency(frequency);

        // Print distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay for 10 ms
        gpioDelay(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

