volatile int echo_end = 0;
volatile int echo_timeout = 0;

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

int trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

int echo_pulse() {
    int start_time = 0, end_time = 0;

    // Wait for echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && echo_timeout == 0) {
        echo_timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (echo_timeout > 0) return -1; // Timeout

    start_time = gpioTick();

    // Wait for echo pin to go low
    while (gpioRead(ECHO_PIN) == 1 && echo_timeout == 0) {
        echo_timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (echo_timeout > 0) return -1; // Timeout

    end_time = gpioTick();

    return (end_time - start_time) / 1000000; // Return pulse width in microseconds
}

double calculate_distance(int pulse_width) {
    if (pulse_width < 2 || pulse_width > 400) {
        return -1.0; // Indicate invalid reading
    }

    return (pulse_width / 29.1) * 2; // Convert to cm
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_pulse() == 0) {
            echo_start = gpioTick();
            echo_timeout = 0;
            echo_end = 0;
            echo_start = 0; // Reset timeout
        }

        int pulse_width = echo_pulse();
        if (pulse_width < 0) {
            fprintf(stderr, "Error in echo_pulse()\n");
            running = 0; // Exit loop if echo_pulse() fails
            continue;
        }

        double distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
        } else {
            if (distance < 2 || distance > 400) {
                fprintf(stderr, "Distance reading too high or too low: %.2f cm\n", distance);
