                if (distance < 10) {
                    fprintf(stderr, "Too close! Distance: %.2f cm\n", distance);
                } else {
                    printf("Distance: %.2f cm\n", distance);
                }
            }
        }

        gpioDelay(500); // Wait 500 ms
    }

    gpioTerminate();
    return 0;
}

