#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_CS 8          // CE0

// Define sensor registers
#define REG_MEAS_MODE 0x01
#define REG_RANGE_MODE 0x02
#define REG_START_TRIGGER 0x03
#define REG_RESULT_DATA 0x04

// Define constants for distance calculation
#define DISTANCE_SCALE_FACTOR 0.01 // mm/cm
#define MAX_DISTANCE 5000.0       // mm

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t distance;
} sensor_data_t;

// Function prototypes
int spi_init();
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t data);
int read_distance();
void log_distance(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a register
int spi_read_register(int reg, uint8_t *data, int len) {
    int result = spiXfer(spi_handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Write data to a register
int spi_write_register(int reg, uint8_t data) {
    int result = spiXfer(spi_handle, (char *)&data, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance() {
    uint8_t data[2];
    if (spi_read_register(REG_RESULT_DATA, data, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t distance = (data[0] << 8) | data[1];

    // Validate the distance value
    if (distance < 0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance value: %d\n", distance);
        return -1;
    }

    return distance;
}

// Log distance to a file
void log_distance(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, data.distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (mm)\n");
    }

    // Main loop
    while (!terminate) {
        sensor_data_t distance_data = read_distance();
        if (distance_data.distance >= 0) {
            log_distance(distance_data);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

