#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 registers
#define SI1120_REG_ALS 0x22
#define SI1120_REG_PS1 0x23
#define SI1120_REG_PART_ID 0x00

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_als(int *als_low, int *als_high);
int si1120_read_ps1(int *ps1_low, int *ps1_high);
int si1120_read_part_id(int *part_id);
void log_reading(int als_low, int als_high, int ps1_low, int ps1_high, int part_id);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the Si1120 sensor
int si1120_init() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1120.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify Part ID
    if (si1120_read_part_id(&part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID.\n");
        return -1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1120 sensor initialized successfully.\n");
    return 0;
}

// Reads ALS data from the sensor
int si1120_read_als(int *als_low, int *als_high) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, SI1120_REG_ALS, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ALS data.\n");
        return -1;
    }

    *als_low = (buf[0] << 8) | buf[1];
    *als_high = (buf[1] << 8) | buf[0];

    return 0;
}

// Reads PS1 data from the sensor
int si1120_read_ps1(int *ps1_low, int *ps1_high) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, SI1120_REG_PS1, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read PS1 data.\n");
        return -1;
    }

    *ps1_low = (buf[0] << 8) | buf[1];
    *ps1_high = (buf[1] << 8) | buf[0];

    return 0;
}

// Reads part ID from the sensor
int si1120_read_part_id(int *part_id) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, SI1120_REG_PART_ID, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read Part ID.\n");
        return -1;
    }

    *part_id = (buf[0] << 8) | buf[1];

    return 0;
}

// Logs the reading to a file
void log_reading(int als_low, int als_high, int ps1_low, int ps1_high, int part_id) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, ALS: %d, %d, PS1: %d, %d, Part ID: 0x%02X\n",
            timestamp, als_low, als_high, ps1_low, ps1_high, part_id);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Error: Failed to initialize Si1120 sensor.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int als_low, als_high, ps1_low, ps1_high, part_id;

        // Read ALS data
        if (si1120_read_als(&als_low, &als_high) == 0) {
            si1120_read_ps1(&ps1_low, &ps1_high);
            si1120_read_part_id(&part_id);

            // Combine data and log
            log_reading(als_low, als_high, ps1_low, ps1_high, part_id);
        } else {
            fprintf(stderr, "Error: Failed to read ALS data.\n");
        }

        gpioDelay(500); // Delay for 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

