#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define TRIGGER_PULSE_DURATION 10  // us
#define BUZZER_DURATION_MS 500    // ms
#define DISTANCE_THRESHOLD 20.0   // cm

// Global variables
volatile int trigger_count = 0;
volatile int echo_start_time = 0;
volatile int echo_end_time = 0;
volatile int echo_duration = 0;
volatile int distance_below_threshold = 0;

// Function prototypes
void trigger_callback(int gpio, int level, uint32_t tick);
void echo_callback(int gpio, int level, uint32_t tick);
void buzzer_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int trigger_pin;
    int echo_pin;
    int buzzer_pin;
} gpio_config_t;

// Function to handle signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Callback function for trigger pin
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        trigger_count++;
        echo_start_time = tick;
    }
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
        echo_end_time = tick;
        echo_duration = tick - echo_start_time;
        distance_below_threshold = (echo_duration > 0) ? (double)echo_duration / 0.0343 : 0; // Calculate distance
    }
}

// Callback function for buzzer pin
void buzzer_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        gpioDelay(BUZZER_DURATION_MS * 1000); // Delay for buzzer duration
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set interrupt handlers
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL); // Set echo pin callback
    gpioSetAlertFuncEx(TRIGGER_PIN, trigger_callback, NULL); // Set trigger pin callback

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_DURATION);
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        echo_start_time = 0;
        echo_end_time = 0;
        echo_duration = 0;
        distance_below_threshold = 0;

        gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL); // Set echo pin callback

        // Wait for echo to start
        while (echo_start_time == 0) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Measure echo pulse width
        echo_start_time = 0;
        echo_end_time = 0;
        echo_duration = 0;
        distance_below_threshold = 0;

        gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL); // Set echo pin callback

        // Wait for echo to end
        while (echo_end_time == 0) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Calculate distance
