#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0     // cm
#define MIN_DISTANCE 200.0      // cm
#define SERVO_PULSE_WIDTH 2000  // us
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_PULSE_WIDTH_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_timeout = 0;
volatile int distance_cm = 0.0;
volatile float servo_angle = 0.0;

// Function prototypes
float get_distance();
void set_servo_angle(float angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

// Function to get distance in centimeters
float get_distance() {
    if (echo_timeout > 0) {
        return -1.0; // Timeout error
    }

    // Measure pulse width
    echo_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && echo_start < echo_end) {
        echo_start = gpioTick();
    }
    if (echo_start == echo_end) {
        echo_timeout++;
        return -1.0; // Timeout error
    }

    echo_end = gpioTick();
    echo_timeout = 0;

    // Calculate pulse width in microseconds
    int pulse_width = echo_end - echo_start;

    // Calculate distance in centimeters
    distance_cm = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 to get one-way distance

    return distance_cm;
}

// Function to set servo angle
void set_servo_angle(float angle) {
    if (angle < 0.0 || angle > 180.0) {
        fprintf(stderr, "Error: Angle must be between 0.0 and 180.0\n");
        return;
    }

    // Map angle to pulse width range
    int pulse_width = (int)((angle - 0.0) * SERVO_PULSE_WIDTH_RANGE / 180.0 + SERVO_MIN_PULSE_WIDTH);

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin to low to start the measurement
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10); // Small delay to allow the sensor to settle

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        float distance = get_distance();

        if (distance > 0.0) {
            set_servo_angle(distance * 100.0); // Map distance to servo angle
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, servo_angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    return 0;
}

