#define SERVO_PIN 18

// Define constants
#define TIMEOUT_US 50000
#define SERVO_PULSE_WIDTH_US 500
#define SERVO_MAX_ANGLE 180
#define SERVO_MIN_ANGLE 0
#define SOUND_SPEED 343.0 // m/s
#define MAX_DISTANCE 400.0 // cm
#define MIN_DISTANCE 20.0  // cm

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
    set_servo_angle(SERVO_MIN_ANGLE); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high
    int timeout = TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout
    }

    // Wait for echo to go low
    timeout = TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1);
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout
    }

    // Calculate pulse duration in microseconds
    long long pulse_duration = gpioTick() - gpioTick(ECHO_PIN);

    // Calculate distance in centimeters
    float distance = (pulse_duration * SOUND_SPEED) / 2.0;

    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    // Map angle to pulse width (0-2500 us)
    int pulse_width = (int)((float)angle / SERVO_MAX_ANGLE * 2500.0);

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set initial servo angle to 0 degrees
    set_servo_angle(SERVO_MIN_ANGLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            // Map distance to servo angle
            int angle = (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);

            // Set servo angle
            set_servo_angle(angle);

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop the servo
    set_servo_angle(SERVO_MIN_ANGLE);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

