#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the I2C address of the Si7005 sensor
#define SI7005_I2C_ADDR 0x40

// Define the register addresses
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

// Define the temperature and humidity conversion factors
#define TEMP_FACTOR 175.72
#define HUMID_FACTOR 125.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the Si7005 sensor
int init_si7005() {
    // Open the I2C bus
    i2c_handle = i2cOpen(1, SI7005_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Write to the CONFIG register
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    // Wait for the sensor to be ready (at least 10ms)
    gpioDelay(10000); // 10ms

    return 0;
}

// Function to read the temperature from the Si7005 sensor
float read_temperature() {
    char buf[2];
    int bytes_read;

    // Read two bytes from the temperature register
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1000.0; // Indicate an error
    }

    // Combine the two bytes to form the temperature value
    int raw_temperature = (buf[0] << 8) | buf[1];
    return (float)raw_temperature / TEMP_FACTOR;
}

// Function to read the humidity from the Si7005 sensor
float read_humidity() {
    char buf[2];
    int bytes_read;

    // Read two bytes from the humidity register
    bytes_read = i2cReadI2CBlockData(i2c_handle, HUMID_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", bytes_read);
        return -1000.0; // Indicate an error
    }

    // Combine the two bytes to form the humidity value
    int raw_humidity = (buf[0] << 8) | buf[1];
    return (float)raw_humidity / HUMID_FACTOR;
}

// Function to log the temperature and humidity readings
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the Si7005 sensor
    if (init_si7005() != 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the temperature and humidity
        float temperature = read_temperature();
        float humidity = read_humidity();

        // Log the readings
        log_data(temperature, humidity);

        // Wait for 2 seconds
        sleep(2);
    }

    // Close the I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

