#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int sht40_init();
int sht40_read_temperature(float *temperature);
int sht40_read_humidity(float *humidity);
int sht40_validate_checksum(unsigned char *data, int data_len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SHT40 sensor
int sht40_init() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the SHT40 sensor
int sht40_read_temperature(float *temperature) {
    unsigned char data[6];
    int result;

    // Send measurement command (0xFD)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Dummy write
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate checksums
    if (sht40_validate_checksum(data, 6) != 0) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    *temperature = -45 + 175 * (data[0] << 8 | data[1]) / 65535.0;

    return 0;
}

// Function to read humidity from the SHT40 sensor
int sht40_read_humidity(float *humidity) {
    unsigned char data[6];
    int result;

    // Send measurement command (0xFD)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Dummy write
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate checksums
    if (sht40_validate_checksum(data, 6) != 0) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to humidity (percentage)
    *humidity = -6 + 125 * (data[2] << 8 | data[3]) / 65535.0;

    return 0;
}

// Function to validate the checksum
int sht40_validate_checksum(unsigned char *data, int data_len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[data_len - 1] ? 0 : -1;
}

// Function to log the temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (sht40_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (sht40_read_temperature(&temperature) == 0 && sht40_read_humidity(&humidity) == 0) {
            // Log the data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature or humidity\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

