void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read temperature from STS30-DIS sensor
float read_temperature() {
    char buf[2];
    int bytes_read;
    int16_t raw_temperature;

    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        log_error("Failed to read temperature data");
        return -1000.0; // Indicate error with a very low temperature
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    raw_temperature = raw_temperature >> 4; // Shift right by 4 bits

    // Convert raw temperature to Celsius (datasheet formula)
    float temperature = (float)raw_temperature / 16384.0 * 165.0 - 40.0;

    return temperature;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Log error to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(error_log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE_NAME, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature >= -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature, skipping logging.");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    fclose(error_log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

