// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x36
#define READ_COMMAND 0x08
#define READ_DATA_LENGTH 9
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_CHECK_SIZE 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
int validate_checksum(const unsigned char *data, int data_length);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the SDP810 sensor
int configure_sensor() {
    // Send command to start continuous measurement
    if (i2cWriteByteData(i2c_handle, 0x00, MEASUREMENT_COMMAND) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    // Send command to read 9 bytes of data
    if (i2cWriteByteData(i2c_handle, 0x00, READ_COMMAND) < 0) {
        fprintf(stderr, "Failed to send read command\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    return 0;
}

// Read sensor data from the SDP810
int read_sensor_data(sensor_data_t *data) {
    unsigned char buffer[READ_DATA_LENGTH];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, READ_DATA_LENGTH);

    if (bytes_read != READ_DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    // Validate checksum
    if (validate_checksum(buffer, READ_DATA_LENGTH) != 0) {
        fprintf(stderr, "Checksum validation failed\n");
        return -1;
    }

