    data->differential_pressure = (float)((buffer[0] << 8) | buffer[1]) / 10.0;
    data->temperature = (float)((buffer[2] << 8) | buffer[3]) / 10.0;

    return 0;
}

// Validate CRC-8 checksum
int validate_checksum(const unsigned char *data, int data_length) {
    unsigned char checksum = 0;
    for (int i = 0; i < data_length; i++) {
        checksum ^= data[i];
    }

    for (int i = 0; i < data_length - CRC_CHECK_SIZE; i++) {
        if (data[i] != checksum) {
            return -1; // Checksum error
        }
    }

    return 0; // Checksum is valid
}

