#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_COMMAND 0x21
#define RETRY_ATTEMPTS 3
#define RETRY_DELAY_MS 100
#define I2C_READ_RETRIES 3
#define I2C_READ_DELAY_MS 50
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sdp31(int i2c_handle, sensor_data_t *data);
int send_trigger_command(int i2c_handle);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
int log_data(const char *filename, float pressure_pa, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads data from the SDP31 sensor
int read_sdp31(int i2c_handle, sensor_data_t *data) {
    char buffer[6];
    int retries = 0;
    int result;

    while (retries < RETRY_ATTEMPTS) {
        result = i2cReadDevice(i2c_handle, buffer, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == RETRY_ATTEMPTS) {
        fprintf(stderr, "Failed to read SDP31 after %d retries\n", RETRY_ATTEMPTS);
        return -1; // Failure after all retries
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->pressure_pa = (float)raw_pressure / 60.0;
    data->temperature_c = (float)raw_temperature / 200.0;

    return 0;
}

// Sends the trigger command to the SDP31
int send_trigger_command(int i2c_handle) {
    char command[2] = {TRIGGER_COMMAND >> 8, TRIGGER_COMMAND & 0xFF};
    int retries = 0;
    int result;

    while (retries < RETRY_ATTEMPTS) {
        result = i2cWriteDevice(i2c_handle, command, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to send trigger command after %d retries\n", RETRY_ATTEMPTS);
    return -1; // Failure after all retries
}

// Reads data from the SDP31 sensor
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buffer[6];
    int retries = 0;
    int result;

    while (retries < RETRY_ATTEMPTS) {
        result = i2cReadDevice(i2c_handle, buffer, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == RETRY_ATTEMPTS) {
        fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_ATTEMPTS);
        return -1; // Failure after all retries
    }

    // Verify checksum
    if (buffer[0] != (buffer[1] + buffer[2] + buffer[3] + buffer[4])) {
        fprintf(stderr, "Checksum error\n");
        return -1; // Checksum error
    }

    return 0;
}

// Logs the data to a file
int log_data(const char *filename, float pressure_pa, float temperature_c) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fclose(fp);
    return 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log the data
            if (log_data(LOG_FILE, sensor_data.pressure_pa, sensor_data.temperature_c) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

