    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log the data
            if (log_data(LOG_FILE, sensor_data.pressure_pa, sensor_data.temperature_c) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

