#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sts30(int i2c_handle, float *temperature);
int validate_checksum(const unsigned char *data, int data_len, unsigned char *crc);
void log_data(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads temperature from the STS30-DIS sensor
int read_sts30(int i2c_handle, float *temperature) {
    unsigned char data[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            break; // Success
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    if (retries == MAX_RETRIES) {
        log_error("I2C read failed after multiple retries.");
        return -1; // Indicate failure
    }

    // Validate checksum
    if (!validate_checksum(data, 3, data + 1)) {
        log_error("Checksum validation failed.");
        return -1; // Indicate failure
    }

    // Convert raw data to temperature
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45 + 175 * (float)raw_temperature / 65535.0;

    return 0; // Indicate success
}

// Validates the CRC-8 checksum
int validate_checksum(const unsigned char *data, int data_len, unsigned char *crc) {
    unsigned char crc_value = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc_value ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_value & 0x80) {
                crc_value = (crc_value << 1) ^ 0x31;
            } else {
                crc_value <<= 1;
            }
        }
    }
    if (crc_value != data[data_len - 1]) {
        return 0; // Checksum failed
    }
    return 1; // Checksum passed
}

// Logs the temperature reading to a file
void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Logs errors to a file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(error_log_file, "%s,ERROR: %s\n", timestamp, message);
    fflush(error_log_file);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature;
    int retries;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sts30(i2c_handle, &temperature) == 0) {
                log_data(temperature);
                break; // Success, exit retry loop
            } else {
                log_error("Failed to read temperature, retrying...");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == MAX_RETRIES) {
            log_error("Failed to read temperature after multiple retries.");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

