#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define SHT40_CMD 0xFD
#define SHT40_RETRIES 3
#define SHT40_RETRY_DELAY_MS 10
#define SHT40_READ_DELAY_MS 50
#define LOG_FILE "sht40_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sht40(int *raw_temperature, int *raw_humidity);
float convert_temperature(int raw_temperature);
float convert_humidity(int raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(int *raw_temperature, int *raw_humidity) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < SHT40_RETRIES) {
        result = i2cWriteByte(i2c_handle, SHT40_CMD);
        if (result < 0) {
            fprintf(stderr, "Error writing command: %d\n", result);
            retries++;
            gpioDelay(SHT40_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(SHT40_READ_DELAY_MS * 1000); // Delay in microseconds

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            *raw_temperature = (buf[0] << 8) | buf[1];
            *raw_humidity = (buf[3] << 8) | buf[4];
            return 0; // Success
        } else {
