#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <pthread.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define PRESSURE_SCALE 240.0
#define TEMPERATURE_SCALE 200.0
#define PRESSURE_OFFSET -45.0
#define TEMPERATURE_OFFSET -45.0
#define LOG_FILE "airflow_data.txt"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
pthread_mutex_t log_mutex;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c(void);
int read_sdp800(int fd, sensor_data_t *data);
int validate_crc(unsigned char crc, unsigned char data);
float convert_pressure(unsigned int raw_pressure);
float convert_temperature(unsigned int raw_temperature);
void log_data(sensor_data_t data);
void send_data_to_server(sensor_data_t data);
void signal_handler(int sig);
void *send_data_thread(void *arg);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
}

// Initialize I2C interface
int init_i2c(void) {
    int fd;
    struct i2c_smbus_device *smbus;

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Initialize SMBus
    smbus = i2c_smbus_open(fd, I2C_RETRY_COUNT, I2C_RETRY_DELAY_MS);
    if (!smbus) {
        syslog(LOG_ERR, "Failed to open SMBus: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from SDP800 sensor
int read_sdp800(int fd, sensor_data_t *data) {
    unsigned char cmd[2] = {0x36, 0x2F}; // Continuous measurement command
    unsigned char buffer[12];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, cmd, 2) != 2) {
            syslog(LOG_ERR, "Failed to write command to sensor: %s", strerror(errno));
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        if (read(fd, buffer, 12) != 12) {
            syslog(LOG_ERR, "Failed to read data from sensor: %s", strerror(errno));
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // CRC check
        if (validate_crc(buffer[0], buffer[1]) &&
            validate_crc(buffer[4], buffer[5]) &&
            validate_crc(buffer[8], buffer[9]) &&
            validate_crc(buffer[12], buffer[13])) {

            // Convert data
            data->pressure = convert_pressure(buffer[0]);
            data->temperature = convert_temperature(buffer[4]);

            return 0; // Success
        } else {
            syslog(LOG_ERR, "CRC check failed, retrying...");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    syslog(LOG_ERR, "Failed to read data from sensor after multiple retries.");
    return -1; // Failure
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation
int validate_crc(unsigned char crc, unsigned char data) {
    return crc8(data, 1) == crc;
}

// Convert raw pressure to Pascals
float convert_pressure(unsigned int raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE;
}

// Convert raw temperature to degrees Celsius
float convert_temperature(unsigned int raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE;
}

// Log data to file
void log_data(sensor_data_t data) {
    pthread_mutex_lock(&log_mutex);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    pthread_mutex_unlock(&log_mutex);
}

// Send data to server
void send_data_to_server(sensor_data_t data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];
    int ret;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return;
    }

    // Configure server address
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return;
    }

    // Prepare data for sending
    snprintf(buffer, sizeof(buffer), "%.2f,%.2f", data.pressure, data.temperature);

    // Send data
    ret = send(sockfd, buffer, strlen(buffer), 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
    } else {
        syslog(LOG_INFO, "Sent data: %s", buffer);
    }

    // Close socket
    close(sockfd);
}

// Send data to server in a separate thread
void *send_data_thread(void *arg) {
    sensor_data_t data;
    while (program_running) {
        if (read_sdp800(i2c_fd, &data) == 0) {
            send_data_to_server(data);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data, retrying...");
        }
        usleep(100000); // 100ms delay
    }
    pthread_exit(NULL);
}

int main(void) {
    // Initialize syslog
    openlog("airflow_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting.");
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Create send_data_thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, send_data_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create send_data_thread: %s", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sensor_data_t data;
        if (read_sdp800(i2c_fd, &data) == 0) {
            if (validate_crc(crc8(data.pressure, 2), data.pressure) &&
                validate_crc(crc8(data.temperature, 2), data.temperature)) {
                log_data(data);
            } else {
                syslog(LOG_WARNING, "CRC check failed, skipping data logging.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data, retrying...");
        }
        usleep(100000); // 100ms delay
    }

    // Cleanup
    pthread_join(thread_id, NULL);
    fclose(log_file);
    close(i2c_fd);
    closelog();

    return 0;
}

