            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data, retrying...");
        }
        usleep(100000); // 100ms delay
    }

    // Cleanup
    pthread_join(thread_id, NULL);
    fclose(log_file);
    close(i2c_fd);
    closelog();

