// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD 28.0
#define HUMIDITY_THRESHOLD 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int init_i2c();
int read_si7021(int i2c_handle, float *temperature, float *humidity);
void control_fan(float temperature);
void log_reading(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the Si7021 sensor
int read_si7021(int i2c_handle, float *temperature, float *humidity) {
    char buf[2];
    int result;

    // Trigger measurement command (Hold Master, Trigger, Repeat)
    buf[0] = 0xE3; // Temperature measurement command
    buf[1] = 0x00; // Repeat count = 0
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (at least 10ms)

    // Read temperature and humidity data
    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the raw temperature and humidity values
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[0] << 8) | data[1];

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (Temperature: %.2f °C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (Temperature: %.2f °C)\n", temperature);
    }
}

