    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int retry_count = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si7021(i2c_handle, &temperature, &humidity) == 0) {
            // Control the fan
            control_fan(temperature);

            // Log the reading
            log_reading(temperature, humidity);

            // Check for sensor absence
            if (temperature < -50.0 || temperature > 150.0) {
                fprintf(stderr, "Sensor absent: Temperature = %.2f °C, Humidity = %.2f %%\n", temperature, humidity);
                retry_count++;
                if (retry_count >= RETRY_COUNT) {
                    fprintf(stderr, "Retry limit reached. Turning off fan.\n");
                    gpioWrite(FAN_GPIO, 0);
                    cleanup();
                    return 0;
                }
                gpioDelay(RETRY_DELAY_MS);
                continue;
            }

            // Check for hysteresis
            if (temperature > TEMP_THRESHOLD && humidity < HUMIDITY_THRESHOLD) {
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
                control_fan(temperature);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            retry_count++;
            if (retry_count >= RETRY_COUNT) {
                fprintf(stderr, "Retry limit reached. Turning off fan.\n");
                gpioWrite(FAN_GPIO, 0);
                cleanup();
                return 0;
            }
            gpioDelay(RETRY_DELAY_MS);
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

