#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// CRC-8 checksum polynomial
#define CRC_POLYNOMIAL 0x31

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, int command);
int read_data(int handle, char *buffer, int count);
int verify_crc(int handle, char *buffer, int count);
int read_sensor_data(int handle, sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(int handle, int command) {
    char cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write command: %d\n", command);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(int handle, char *buffer, int count) {
    if (i2cReadDevice(handle, buffer, count) != count) {
        fprintf(stderr, "Failed to read data: %d\n", count);
        return -1;
    }
    return 0;
}

// Verify CRC-8 checksum
int verify_crc(int handle, char *buffer, int count) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == buffer[count - 1];
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    if (verify_crc(handle, buffer, 9) != 0) {
        return -1;
    }

    // Extract CO2, temperature, and humidity data
    data->co2 = (buffer[0] << 8) | buffer[1];
    data->temperature = -45 + 175 * (buffer[3] >> 8) / (2 << 16);
    data->humidity = 100 * (buffer[3] & 0xFF) / (2 << 16);

    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Start periodic measurement
        if (send_command(i2c_handle, 0x21B1) != 0) {
            fprintf(stderr, "Failed to start periodic measurement\n");
            cleanup();
            return 1;
        }
        gpioDelay(1000); // Wait for measurement to complete (adjust as needed)

        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup();
            return 1;
        }

        // Log data
        log_data(sensor_data);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

