#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50
#define MAX_READINGS 3
#define MAX_TH_VALUE 4096
#define MIN_TH_VALUE 0
#define MAX_TH_VALUE 4096
#define MIN_TL_VALUE 0
#define MAX_TL_VALUE 4096

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_temperature();
float convert_temperature(int raw_temp);
void log_temperature(float temperature);
void signal_handler(int signal);

// Function to read temperature from TMP05 sensor
int read_temperature() {
    int high_count = 0;
    int low_count = 0;
    int total_count = 0;

    // Wait for the signal to go high
    while (gpioRead(GPIO_PIN) == 0 && running) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (!running) return -1; // Exit if signal received

    high_count = gpioRead(GPIO_PIN);
    low_count = gpioRead(GPIO_PIN);
    total_count = high_count + low_count;

    // Calculate the pulse width (TH)
    int TH = (total_count - high_count) * 2; // Pulse width is twice the difference

    // Calculate the total cycle time (TL)
    int TL = total_count - TH;

    // Calculate the temperature
    float temperature = 4215 - (2143 * TH / TL);

    // Check for division by zero
    if (TL == 0) {
        fprintf(stderr, "Error: TL is zero. Temperature cannot be calculated.\n");
        return -1;
    }

    return (int)temperature;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    return (float)raw_temp / 10.0;
}

// Function to log temperature to a file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
