#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_MEASURE 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_CHECK_SIZE 8
#define CRC_CHECK_VALUE 0xFF
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t process_data(uint8_t *data, int len);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < CRC_CHECK_SIZE; j++) {
            crc = (crc >> 1) ^ CRC_POLYNOMIAL;
            if (crc & 0x80) {
                crc = ~crc;
            }
        }
    }
    return (crc == data[len - CRC_CHECK_SIZE]);
}

// Process raw data and convert to pressure and temperature
sensor_data_t process_data(uint8_t *data, int len) {
    sensor_data_t result;
    result.pressure = (float)((data[0] << 8) | data[1]) / 10.0;
    result.temperature = (float)((data[2] << 8) | data[3]) / 10.0;
    return result;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        uint8_t buffer[9];
        int result;

        // Send command
        result = send_command(i2c_handle, CMD_MEASURE);
        if (result != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            gpioDelay(10); // Wait 10ms before retrying
            continue;
        }

        // Wait for conversion (45 ms)
        gpioDelay(45);

        // Read data
        result = read_data(i2c_handle, buffer, 9);
        if (result != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(10); // Wait 10ms before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(buffer, 9)) {
            fprintf(stderr, "CRC check failed!\n");
            continue;
        }

        // Process data
        sensor_data_t data = process_data(buffer, 9);

        // Log data
        log_data(data);

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

