#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define SAMPLE_INTERVAL_SEC 5
#define CSV_FILENAME "environment.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, unsigned char *data);
sensor_data_t process_sensor_data(unsigned char *data);
int validate_crc(unsigned char data[], unsigned char crc);
int write_data_to_csv(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Read data from SHT35-DIS-B sensor
int read_sensor_data(int handle, unsigned char *data) {
    int result = i2cReadI2CBlockData(handle, 0x00, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read data from sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data (convert to Celsius and percentage)
sensor_data_t process_sensor_data(unsigned char *data) {
    unsigned char msb = data[0];
    unsigned char lsb = data[1];
    unsigned char crc = data[2];
    unsigned char xlsb = data[3];

    sensor_data_t sensor_data;
    sensor_data.temperature = -45 + 175 * (msb >> 8) / 65535.0;
    sensor_data.humidity = 100 * (lsb >> 8) / 65535.0;

    return sensor_data;
}

// Validate CRC-8 checksum
int validate_crc(unsigned char data[], unsigned char crc) {
    unsigned char checksum = 0;
    for (int i = 0; i < 6; i++) {
        checksum += data[i];
    }

    if (checksum != crc) {
        fprintf(stderr, "CRC checksum error: data[0] = 0x%02X, data[1] = 0x%02X, data[2] = 0x%02X, data[3] = 0x%02X, data[4] = 0x%02X, data[5] = 0x%02X, crc = 0x%02X\n",
                data[0], data[1], data[2], data[3], data[4], data[5], crc);
        return -1;
    }
    return 0;
}

// Write data to CSV file
int write_data_to_csv(FILE *fp, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

