    result = i2cWriteByte(handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 9 bytes of data
    result = i2cReadDevice(handle, (char *)data, SAMPLE_SIZE);
    if (result != SAMPLE_SIZE) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Validate CRC-8
