        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0x00);
}

