#define CMD_READ 0x3603
#define CMD_WRITE 0x3604
#define CMD_READ_WRITE 0x3605
#define CRC_POLYNOMIAL 0x31
#define PRESSURE_SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int i2c_read_word(int handle, unsigned char reg);
int i2c_write_word(int handle, unsigned char reg, unsigned char value);
int i2c_read_bytes(int handle, unsigned char reg, char *buf, int len);
int i2c_write_bytes(int handle, unsigned char reg, char *buf, int len);
int validate_crc(unsigned char data[], int len);
float convert_pressure(int raw_pressure);
void log_data(float pressure);
void signal_handler(int signal);

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read a word from the SDP800 sensor
int i2c_read_word(int handle, unsigned char reg) {
    char buf[2];
    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "Error writing register address for read.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading word from sensor.\n");
        return -1;
    }
    return (int)buf[0] | ((int)buf[1] << 8);
}

// Function to write a word to the SDP800 sensor
int i2c_write_word(int handle, unsigned char reg, unsigned char value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing word to sensor.\n");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from the sensor
int i2c_read_bytes(int handle, unsigned char reg, char *buf, int len) {
    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "Error writing register address for read.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, len) != len) {
        fprintf(stderr, "Error reading bytes from sensor.\n");
        return -1;
    }
    return 0;
}

// Function to write multiple bytes to the sensor
int i2c_write_bytes(int handle, unsigned char reg, char *buf, int len) {
    if (i2cWriteDevice(handle, buf, len) != len) {
        fprintf(stderr, "Error writing bytes to sensor.\n");
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[len - 1];
}

