#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define PWM_RANGE 1000
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    float flow_rate;
} SensorData;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
SensorData read_sensor_data(int i2c_handle);
float convert_raw_to_flow(SensorData data);
void set_fan_pwm(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Read sensor data from I2C
SensorData read_sensor_data(int i2c_handle) {
    SensorData data;
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        data.raw_flow = 0; // Set to 0 on error
        data.flow_rate = 0.0; // Set to 0.0 on error
        return data;
    }

    // Combine the two bytes into a 16-bit word
    data.raw_flow = (buf[0] << 8) | buf[1];

    // Mask off the status bits and shift right by 2
    data.raw_flow = data.raw_flow & 0x3FFF; // Mask off status bits
    data.raw_flow >>= 2;

    // Convert to flow rate
    data.flow_rate = (float)data.raw_flow / 1638.0;

    return data;
}

// Convert raw flow data to flow rate
float convert_raw_to_flow(SensorData data) {
    return data.flow_rate;
}

// Set PWM duty cycle based on flow rate
void set_fan_pwm(float flow_rate) {
    if (flow_rate < 0) {
        flow_rate = 0.0;
    }
    if (flow_rate > 10.0) {
        flow_rate = 10.0;
    }
    int duty_cycle = (int)(flow_rate * PWM_PERIOD / 10.0);
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Log data to file
void log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data(i2c_handle);
        float flow_rate = convert_raw_to_flow(data);
        set_fan_pwm(flow_rate);
        log_data(flow_rate);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

