#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define AVG_BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[AVG_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int initialize_i2c();
int read_temperature(int *temperature);
float convert_to_celsius(int raw_value);
void add_to_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from STLM75
int read_temperature(int *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_value) {
    return (float)raw_value / 16384.0 * 255.0;
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % AVG_BUFFER_SIZE;
    if (temp_buffer.count < AVG_BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Function to calculate the average temperature from the circular buffer
float calculate_average() {
    if (temp_buffer.count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < temp_buffer.count; i++) {
        sum += temp_buffer.buffer[i];
    }
    return sum / temp_buffer.count;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    // Main loop
    while (!terminate) {
        int raw_temperature;
        float temperature;

        // Read temperature
        if (read_temperature(&raw_temperature) == 0) {
            // Convert to Celsius
            temperature = convert_to_celsius(raw_temperature);

            // Add to buffer
            add_to_buffer(temperature);

            // Calculate average temperature
            float average_temperature = calculate_average();

            // Control LED
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping this iteration.\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

