    temp_buffer.count = 0;

    // Main loop
    while (!terminate) {
        int raw_temperature;
        float temperature;

        // Read temperature
        if (read_temperature(&raw_temperature) == 0) {
            // Convert to Celsius
            temperature = convert_to_celsius(raw_temperature);

            // Add to buffer
            add_to_buffer(temperature);

            // Calculate average temperature
            float average_temperature = calculate_average();

            // Control LED
            control_led(average_temperature);
        } else {
