int verify_crc(const unsigned char *data, int data_len);
void log_data(float co2, float temperature, float humidity);
void control_ventilation(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 implementation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int *co2, float *temperature, float *humidity) {
    unsigned char data[18];
    int co2_raw, temperature_raw, humidity_raw;

    // Read measurement command
    if (i2cWriteByteData(handle, CMD_MEASURE, 0) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }
    gpioDelay(1); // Wait for measurement to complete (at least 1ms)

    // Read 18 bytes of data
    if (i2cReadDevice(handle, (char *)data, 18) != 18) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // CRC check
    if (verify_crc(data, 18) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract sensor data
    co2_raw = (data[0] << 8) | data[1];
    temperature_raw = (data[3] << 8) | data[4];
    humidity_raw = (data[6] << 8) | data[7];

    // Convert raw data to physical units
    *co2 = (float)co2_raw / 100.0;
    *temperature = -45 + (175 * (float)temperature_raw / 65535.0);
    *humidity = (float)humidity_raw / 100.0;

    return 0;
}

// Function to verify CRC-8 checksum
int verify_crc(const unsigned char *data, int data_len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[data_len - 1];
}

