    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control ventilation
void control_ventilation(float co2) {
    if (co2 > OFF_THRESHOLD) {
        printf("CO2: %.2f ppm, OFF\n", co2);
    } else if (co2 < LOW_THRESHOLD) {
        printf("CO2: %.2f ppm, LOW\n", co2);
    } else if (co2 > HIGH_THRESHOLD) {
        printf("CO2: %.2f ppm, HIGH\n", co2);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, SCD30_ADDR) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    int co2, temperature, humidity;
    int co2_raw, temperature_raw, humidity_raw;
    unsigned char data[18];
    int co2_crc, temperature_crc, humidity_crc;

    while (!terminate) {
