            temperature_crc = crc8(data + 6, 2);
            humidity_crc = crc8(data + 8, 2);

            if (co2_crc != data[6] || temperature_crc != data[8] || humidity_crc != data[10]) {
                fprintf(stderr, "CRC checksum mismatch\n");
                continue; // Skip to the next iteration
            }

            // Verify CRC
            if (verify_crc(data, 18) != 0) {
                fprintf(stderr, "CRC check failed\n");
                continue; // Skip to the next iteration
            }

            // Extract sensor data
            co2_raw = (data[0] << 8) | data[1];
            temperature_raw = (data[3] << 8) | data[4];
            humidity_raw = (data[6] << 8) | data[7];

            // Convert raw data to physical units
            co2 = (float)co2_raw / 100.0;
            temperature = -45 + (175 * (float)temperature_raw / 65535.0);
            humidity = (float)humidity_raw / 100.0;

            // Log data
            log_data(co2, temperature, humidity);

            // Control ventilation
            control_ventilation(co2);

            // Print data
            printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

