#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>

// Configuration Register (0x02)
#define HDC1000_CONFIG_REG 0x00
#define HDC1000_CONFIG_REG_MSB 0x01
#define HDC1000_CONFIG_REG_LSB 0x02
#define HDC1000_CONFIG_REG_VALUE 0x00

// Temperature and Humidity Registers (0x00, 0x01)
#define HDC1000_TEMP_REG 0x00
#define HDC1000_HUMIDITY_REG 0x01

// Global variables
int i2c_fd;
int i2c_address;
int i2c_bus;
int i2c_dev_fd;

// Signal handler for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, int reg);
int i2c_write_register(int fd, int reg, int value);
int i2c_read_raw(int fd, int reg, char *buf, int len);
int i2c_write_raw(int fd, int reg, int value, char *buf, int len);
int i2c_read_temperature(int fd);
int i2c_read_humidity(int fd);
float convert_temperature(int raw);
float convert_humidity(int raw);
void log_data(float temperature, float humidity);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_raw(int fd, int reg, char *buf, int len) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            memcpy(buf, &result, len);
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    syslog(LOG_ERR, "I2C read failed after multiple retries");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_raw(int fd, int reg, int value, char *buf, int len) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result >= 0) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    syslog(LOG_ERR, "I2C write failed after multiple retries");
    return -1; // Failure
}

// Function to read a single byte from the I2C device
int i2c_smbus_read_byte_data(int fd, int reg) {
    if (reg < 0 || reg > 0x7F) {
        syslog(LOG_ERR, "Invalid register address: 0x%02X", reg);
        return -1;
    }

    char buf[1];
    if (i2c_write_register(fd, reg, 0x00, buf, 1) < 0) {
        syslog(LOG_ERR, "Failed to write register address 0x%02X", reg);
        return -1;
    }

    usleep(10000); // Wait for conversion (at least 10ms)

    if (i2c_read_raw(fd, reg, buf, 1) < 0) {
        syslog(LOG_ERR, "Failed to read byte from register 0x%02X", reg);
        return -1;
    }

    return buf[0];
}

// Function to write a single byte to the I2C device
int i2c_smbus_write_byte_data(int fd, int reg, int value) {
    if (reg < 0 || reg > 0x7F) {
        syslog(LOG_ERR, "Invalid register address: 0x%02X", reg);
        return -1;
    }

    char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (i2c_write_register(fd, reg, value, buf, 2) < 0) {
        syslog(LOG_ERR, "Failed to write byte to register 0x%02X", reg);
        return -1;
    }

    return 0;
}

// Function to read temperature from the HDC1000
int i2c_read_temperature(int fd) {
    char buf[2];
    if (i2c_read_raw(fd, HDC1000_TEMP_REG, buf, 2) < 0) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to read humidity from the HDC1000
int i2c_read_humidity(int fd) {
    char buf[2];
    if (i2c_read_raw(fd, HDC1000_HUMIDITY_REG, buf, 2) < 0) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw) {
    return (float)raw / 65536.0 * 165.0 - 40.0;
}

// Function to convert raw humidity to %RH
float convert_humidity(int raw) {
    return (float)raw / 65536.0 * 100.0;
}

// Function to log temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...");
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("hdc1000_i2c", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    if (argc > 1) {
        i2c_address = strtol(argv[1], NULL, 0);
        if (i2c_address < 0 || i2c_address > 0x7F) {
            syslog(LOG_ERR, "Invalid I2C address: 0x%02X", i2c_address);
            closelog();
            return 1;
        }
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set I2C bus
    i2c_bus = 1; // I2C bus 1 on Raspberry Pi
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        syslog(LOG_ERR, "Failed to set I2C bus: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Open I2C device
    i2c_dev_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_dev_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        close(i2c_fd);
        close(i2c_dev_fd);
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read temperature and humidity
        int raw_temperature = i2c_read_temperature(i2c_fd);
        int raw_humidity = i2c_read_humidity(i2c_fd);

        if (raw_temperature == -1 || raw_humidity == -1) {
            syslog(LOG_ERR, "Failed to read sensor data");
            sleep(5);
            continue;
        }

        // Convert raw data to Celsius and %RH
        float temperature = convert_temperature(raw_temperature);
        float humidity = convert_humidity(raw_humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait for 5 seconds
        sleep(5);
