#define PRESSURE_REGISTER 0x00 // Example register address

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read pressure data from the MLX90833 sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int result;

    // Read two bytes from the pressure register
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure value to Pascals (example conversion, adjust based on datasheet)
    float pressure_pa = (float)raw_pressure / 10.0; // Example conversion

    return (int)pressure_pa; // Return the pressure value
}

int main() {
