#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x36
#define CRC_8_POLYNOMIAL 0x31
#define MEASUREMENT_DURATION_US 800000 // 8 ms
#define READ_RETRIES 3
#define READ_DELAY_US 100000 // 100 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t crc_check;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(sensor_data_t *data);
int verify_crc(const uint8_t *data, int data_len);
float convert_pressure(const sensor_data_t *data);
int log_data(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger continuous measurement
int trigger_measurement() {
    char cmd[2] = {CONTINUOUS_MEASUREMENT_COMMAND >> 8, CONTINUOUS_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    data->raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc_check = (int16_t)((buffer[2] << 8) | buffer[3]);

    return 0;
}

// Verify CRC checksum
int verify_crc(const uint8_t *data, int data_len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[data_len - 1]);
}

// Convert raw pressure to Pascals
float convert_pressure(const sensor_data_t *data) {
    return (float)data->raw_pressure / 60.0;
}

// Log data to CSV file
int log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Trigger continuous measurement
    if (trigger_measurement() != 0) {
        fprintf(stderr, "Failed to trigger continuous measurement\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    int retries = 0;
    int result;

    while (program_running) {
        // Wait for measurement to complete
        while (retries < READ_RETRIES) {
            result = read_sensor_data(&sensor_data);
            if (result == 0) {
                break;
            } else {
                fprintf(stderr, "Read failed, retrying (%d/%d)\n", retries + 1, READ_RETRIES);
                retries++;
                gpioDelay(READ_DELAY_US);
            }
        }

        if (result == 0) {
            // Verify CRC
            if (verify_crc(&sensor_data.raw_pressure, 2)) {
                // Convert pressure
                float pressure = convert_pressure(&sensor_data);

                // Log data
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Read failed after multiple retries\n");
        }

        gpioDelay(READ_DELAY_US);
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

