// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_COMMAND 0x00
#define MEASUREMENT_DURATION_US 40000 // 40 ms
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1000000 // 1 MB
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_hih6130(int i2c_handle, uint8_t *data);
int validate_sensor_status(uint8_t status);
SensorData convert_to_sensor_data(uint8_t raw_data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from HIH6130 sensor
int read_hih6130(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate sensor status bits
int validate_sensor_status(uint8_t status) {
    return (status & 0x01) ? 1 : 0; // Check if sensor is present
}

// Convert raw data to temperature and humidity
SensorData convert_to_sensor_data(uint8_t raw_data) {
    SensorData data;
    data.temperature = (float)raw_data * 165.0 / 16383.0 - 40.0;
    data.humidity = (float)raw_data * 100.0 / 16383.0;
    return data;
}

// Log data to file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t raw_data[4];
    SensorData sensor_data;

    printf("Starting data logging...\n");

    while (!terminate) {
        // Trigger measurement
        if (write(i2c_handle, MEASUREMENT_COMMAND, 1) != 1) {
            fprintf(stderr, "Error triggering measurement\n");
            continue; // Skip to the next iteration
        }
        gpioDelay(MEASUREMENT_DURATION_US);

        // Read data from sensor
        if (read_hih6130(i2c_handle, raw_data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Skip to the next iteration
        }

        // Validate sensor status
        if (!validate_sensor_status(raw_data[0])) {
            fprintf(stderr, "Sensor not present\n");
            continue; // Skip to the next iteration
        }

        // Convert raw data to sensor data
        sensor_data = convert_to_sensor_data(raw_data[0]);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

