#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1
#define I2C_HANDLE -1
#define LOG_FILE "environment_data.txt"
#define MEASUREMENT_COMMAND 0xFD
#define HIGH_PRECISION_MODE 0x00
#define CRC_POLYNOMIAL 0x31
#define CRC_CHECK_SIZE 2

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int read_sht40(int handle, float *temperature, float *humidity);
int validate_crc(unsigned char data[], int data_len, unsigned char polynomial, unsigned char initial_value);
SensorData convert_data(unsigned char raw_data[], int raw_temp, int raw_hum);
void log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from SHT40 sensor
int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(handle, 0x00, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (validate_crc(data, 2, CRC_POLYNOMIAL, CRC_CHECK_SIZE) != 0) {
        fprintf(stderr, "CRC checksum failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = -45 + 175 * (data[0] >> 8) / 65535.0;
    *humidity = -6 + 125 * (data[0] & 0xFF) / 65535.0;

    return 0;
