#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
float get_average_temperature();
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer temperature_buffer = {0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            float average_temperature = get_average_temperature();
            printf("Temperature: %.2f °C\n", average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping this sample.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    // Convert to big-endian
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 16384.0; // Convert to Celsius

    return 0;
}

// Add temperature to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer.buffer[temperature_buffer.head] = temperature;
    temperature_buffer.head = (temperature_buffer.head + 1) % BUFFER_SIZE;
    if (temperature_buffer.count < BUFFER_SIZE) {
        temperature_buffer.count++;
    }
}

// Get the average temperature from the circular buffer
float get_average_temperature() {
    if (temperature_buffer.count == 0) {
        return 0.0; // Return 0 if the buffer is empty
    }

    float sum = 0.0;
    for (int i = 0; i < temperature_buffer.count; i++) {
        sum += temperature_buffer.buffer[i];
    }
    return sum / temperature_buffer.count;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

