#define SHTC3_STATUS 0x00
#define SHTC3_TEMP_MSB 0x01
#define SHTC3_TEMP_LSB 0x02
#define SHTC3_TEMP_CRC8 0x03
#define SHTC3_HUM_MSB 0x04
#define SHTC3_HUM_LSB 0x05
#define SHTC3_HUM_CRC8 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
unsigned char crc8_table[256] = {
    0x00, 0x07, 0x06, 0x0F, 0x0E, 0x0D, 0x1C, 0x1B, 0x1A, 0x19, 0x18, 0x17, 0x16, 0x0F, 0x0E, 0x0D, 0x0C, 0x0B, 0x0A, 0x09, 0x08, 0x07, 0x06, 0x05, 0x04, 0x03, 0x02, 0x01, 0x00
};

// Function prototypes
int initialize_i2c();
int read_sensor_data(float *temperature, float *humidity);
int validate_data(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    char buf[6];
    int status;

    // Send measurement command
    status = i2cWriteByteData(i2c_handle, SHTC3_MEAS_CMD, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", status);
        return -1;
    }

    // Wait for conversion (at least 12.4 ms)
    gpioDelay(12000); // 12.4 ms

    // Read 6 bytes of data
    status = i2cReadI2CBlockData(i2c_handle, SHTC3_TEMP_MSB, buf, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Validate data
