        *temperature = (float)buf[0] * 256.0 + buf[1];
        *humidity = (float)buf[3] * 256.0 + buf[4];
        return 0;
    } else {
        fprintf(stderr, "Invalid sensor data: Temperature = %.2f, Humidity = %.2f\n", buf[0], buf[1]);
        return -1;
    }
