    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&temperature, &humidity) == 0) {
            // Validate data
            if (validate_data(temperature, humidity)) {
                // Log data
                log_data(temperature, humidity);

                // Print valid readings to stdout
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Invalid sensor data: Temperature = %.2f, Humidity = %.2f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

