#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"

int i2c_handle;
FILE *log_file;

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(1);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        handle_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read temperature from the TMP117
int read_temperature() {
    char buf[2];
    int result;

    // Read two bytes from the temperature register
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        handle_error("Failed to read temperature data");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert the raw temperature to Celsius
    float temperature = (float)raw_temp / 16384.0f * 0.0078125f;

    return (int)temperature;
}

// Function to log the temperature reading
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        handle_error("pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int temperature = read_temperature();
        if (temperature >= 0) {
            log_temperature(temperature);
        } else {
            handle_error("Failed to read temperature after multiple attempts");
        }
        gpioDelay(1000); // Wait for 1 second
    }

    return 0; // This line will never be reached due to the infinite loop
}

