#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define LOG_FILE "airflow.log"
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define MAX_PRESSURE_PA 5.0
#define MAX_TEMPERATURE_C 20.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(const uint8_t *data, int len);
int convert_raw_data(const uint8_t *data, int len, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 implementation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int retries = 0;
    int result;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 9);
        if (result == 9) {
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (result != 9) {
        fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRY_COUNT);
        return -1;
    }

    // Validate CRC
    if (validate_crc(buffer, 9) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data
    if (convert_raw_data(buffer, 9, data) != 0) {
        fprintf(stderr, "Raw data conversion failed\n");
        return -1;
    }

    return 0;
}

// Function to validate CRC-8
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[len - 1];
}

// Function to convert raw data
int convert_raw_data(const uint8_t *data, int len, sensor_data_t *data) {
    data->pressure = (int16_t)((data[0] << 8) | data[1]);
    data->temperature = (int16_t)((data[2] << 8) | data[3]);
    data->status = data[4];

    return 0;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%u\n", timestamp, data->pressure, data->temperature, data->status);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (sensor_data.pressure > MAX_PRESSURE_PA || sensor_data.pressure < MIN_PRESSURE_PA) {
                fprintf(stderr, "Pressure exceeds maximum allowed value: %.2f Pa\n", sensor_data.pressure);
            }
            if (sensor_data.temperature > MAX_TEMPERATURE_C || sensor_data.temperature < MIN_TEMPERATURE_C) {
                fprintf(stderr, "Temperature exceeds maximum allowed value: %.2f C\n", sensor_data.temperature);
            }
            if (sensor_data.status == 0x00) {
                log_data(&sensor_data);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

