#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMPERATURE_THRESHOLD 28.0
#define TEMPERATURE_HYSTERESIS 27.0
#define LED_ON_TIME_MS 500
#define LED_OFF_TIME_MS 500
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100

// Global variables
int i2c_fd;
int led_gpio;
struct gpiod_chip *chip;

// Function prototypes
int read_stts2004(int fd, int *temperature);
float convert_temperature(int raw_temperature);
void control_led(int gpio, int state);
void log_temperature(float temperature);
void signal_handler(int signum);
int setup_i2c(int bus, int addr);
int setup_gpio(int gpio, int direction);
int setup_led(int gpio, int state);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        control_led(led_gpio, 0); // Turn off LED
        close(i2c_fd);
        gpio_unexport(led_gpio);
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read temperature from STTS2004
int read_stts2004(int fd, int *temperature) {
    uint8_t buffer[2];
    int retries = 0;
    int result;

    while (retries < I2C_RETRY_COUNT) {
        result = i2c_smbus_read_byte_data(fd, 0x00);
        if (result >= 0) {
            buffer[0] = (uint8_t)result;
            buffer[1] = 0; // Dummy byte
            result = i2c_smbus_write_byte_data(fd, 0x00, 0); // Dummy byte
            if (result >= 0) {
                *temperature = (int16_t)((buffer[0] << 8) | buffer[1]);
                return 0; // Success
            } else {
                fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
                retries++;
                usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            }
        } else {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }
    fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure after all retries
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / 16384.0 * 0.0625;
}

// Function to control the LED
void control_led(int gpio, int state) {
    gpio_set_value(gpio, state);
}

// Function to log the temperature to stdout
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

// Function to setup I2C
int setup_i2c(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to setup GPIO
int setup_gpio(int gpio, int direction) {
    struct gpiod_line_request request;
    request.line = gpio;
    request.direction = direction;
    request.value = 0; // Initialize to 0

    int ret = gpiod_line_request_set(chip, &request);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to setup LED GPIO
int setup_led(int gpio, int state) {
    struct gpiod_line_request request;
    request.line = gpio;
    request.direction = GPIOD_DIRECTION_OUT;
    request.value = state;

