void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        control_led(led_gpio, 0); // Turn off LED
        close(i2c_fd);
        gpio_unexport(led_gpio);
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read temperature from STTS2004
int read_stts2004(int fd, int *temperature) {
    uint8_t buffer[2];
    int retries = 0;
    int result;

    while (retries < I2C_RETRY_COUNT) {
        result = i2c_smbus_read_byte_data(fd, 0x00);
        if (result >= 0) {
            buffer[0] = (uint8_t)result;
            buffer[1] = 0; // Dummy byte
            result = i2c_smbus_write_byte_data(fd, 0x00, 0); // Dummy byte
            if (result >= 0) {
                *temperature = (int16_t)((buffer[0] << 8) | buffer[1]);
                return 0; // Success
            } else {
                fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
                retries++;
                usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            }
        } else {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }
    fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRY_COUNT);
