#define CMD_MEASURE 0x362F
#define CMD_READ 0x00
#define CMD_WRITE 0x00
#define CRC_POLYNOMIAL 0x31
#define CRC_VALUE 0x31
#define SAMPLE_INTERVAL_MS 4500
#define DATA_READ_SIZE 9

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(const uint8_t *data, int data_len);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from SDP800-500Pa
int read_sensor_data(sensor_data_t *data) {
    char buf[DATA_READ_SIZE];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, DATA_READ_SIZE);

    if (bytes_read != DATA_READ_SIZE) {
        fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    // CRC check
    if (validate_crc(buf, DATA_READ_SIZE) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract sensor data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[2] << 8) | buf[3]);
    data->scale_factor = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int data_len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[data_len - 1]);
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n",
            timestamp, data.pressure, data.temperature, data.scale_factor);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

