#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_RH_COMMAND 0xF3
#define MEASURE_TEMP_COMMAND 0xF5
#define MEASURE_HOLD_COMMAND 0xE0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "environment.log"
#define ERROR_LOG_FILE "error.log"

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_si7021(int i2c_handle, float *temperature, float *humidity);
int validate_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
int i2c_write_byte(int i2c_handle, int byte);
int i2c_read_byte(int i2c_handle, int byte);

// Function to read a single byte from I2C
int i2c_read_byte(int i2c_handle, int byte) {
    int result = i2cReadByteData(i2c_handle, byte);
    if (result < 0) {
        fprintf(stderr, "Error reading byte 0x%02X: %d\n", byte, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to I2C
int i2c_write_byte(int i2c_handle, int byte) {
    int result = i2cWriteByteData(i2c_handle, byte);
    if (result < 0) {
        fprintf(stderr, "Error writing byte 0x%02X: %d\n", byte, result);
        return -1;
    }
    return 0;
}

// Function to read a single byte from I2C with retry
int i2c_read_byte_with_retry(int i2c_handle, int byte, int retries, int delay_ms) {
    int result = i2c_read_byte(i2c_handle, byte);
    if (result >= 0) return result;

    for (int i = 0; i < retries; ++i) {
        result = i2c_read_byte(i2c_handle, byte);
        if (result >= 0) return result;
        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error reading byte 0x%02X after %d retries\n", byte, retries);
    return -1;
}

// Function to read temperature and humidity from the Si7021
int read_si7021(int i2c_handle, float *temperature, float *humidity) {
    int raw_temperature, raw_humidity;

    // Measure Relative Humidity
    if (i2c_write_byte(i2c_handle, MEASURE_HOLD_COMMAND) != 0) {
        fprintf(stderr, "Error writing 0xE0 to measure humidity\n");
        return -1;
    }
    gpioDelay(RETRY_DELAY_MS * 1000); // Wait for measurement (at least 20ms)

    if (i2c_read_byte_with_retry(i2c_handle, MEASURE_HOLD_COMMAND, RETRY_COUNT, RETRY_DELAY_MS) != 0) {
        fprintf(stderr, "Error reading 0xE0\n");
        return -1;
    }

    raw_humidity = i2c_read_byte(i2c_handle, 0x00);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity\n");
        return -1;
    }

    raw_temperature = i2c_read_byte(i2c_handle, 0x00);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return -1;
    }

    // Convert raw values
    *humidity = (float)raw_humidity / 65536.0 * 100.0;
    *temperature = (float)raw_temperature / 65536.0 * 175.72 - 46.85;

    return 0;
}

// Function to validate the sensor ID
int validate_sensor(int i2c_handle) {
    int id = i2c_read_byte(i2c_handle, 0x00);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    // Check for Si7021 ID
    if (id != 0x60) {
        fprintf(stderr, "Incorrect Si7021 ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, float *temperature, float *humidity) {
    int raw_temperature, raw_humidity;

    // Measure Relative Humidity
    if (i2c_write_byte(i2c_handle, MEASURE_RH_COMMAND) != 0) {
        fprintf(stderr, "Error writing 0xF3 to measure humidity\n");
        return -1;
    }
    gpioDelay(RETRY_DELAY_MS * 1000); // Wait for measurement (at least 20ms)

    if (i2c_read_byte_with_retry(i2c_handle, MEASURE_HOLD_COMMAND, RETRY_COUNT, RETRY_DELAY_MS) != 0) {
        fprintf(stderr, "Error reading 0xF3\n");
        return -1;
    }

    raw_humidity = i2c_read_byte(i2c_handle, 0x00);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity\n");
        return -1;
    }

    raw_temperature = i2c_read_byte(i2c_handle, 0x00);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return -1;
    }

    // Convert raw values
    *humidity = (float)raw_humidity / 65536.0 * 100.0;
    *temperature = (float)raw_temperature / 65536.0 * 175.72 - 46.85;

    return 0;
}

// Function to log data to a file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

