#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define CONFIG_REG 0x03

// Configuration values
#define CONFIG_VALUE 0x0000 // 14-bit resolution, normal mode

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC1080 sensor
int configure_sensor() {
    // Configure for 14-bit resolution, normal mode
    char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = CONFIG_VALUE;
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int bytes_read;

    // Read temperature data
    bytes_read = i2cReadDevice(i2c_handle, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temp = (buffer[0] << 8) | buffer[1];
    int raw_humidity = (buffer[3] << 8) | buffer[4];

    data->temperature = (float)raw_temp / 65536.0;
    data->humidity = (float)raw_humidity / 65536.0;

    return 0;
}

// Log the sensor data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping log entry.\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

