#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_MEASURE 0x3615
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    int scale_factor;
} SensorData;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int read_sensor_data(SensorData *data);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
int validate_sensor_data(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(SensorData *data) {
    char buf[9];
    int bytes_read;
    int retries = 0;

    while (retries < I2C_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 9);
        if (bytes_read == 9) {
            // Validate data
            if (validate_sensor_data(*data) == 0) {
                // Convert data
                data->pressure = convert_pressure(buf[0]);
                data->temperature = convert_temperature(buf[2]);
                data->scale_factor = buf[3];
                return 0; // Success
            } else {
                fprintf(stderr, "Sensor data validation failed\n");
            }
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            retries++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", I2C_RETRIES);
    return -1; // Failure
}

// Convert raw pressure to Pascals
float convert_pressure(int raw_pressure) {
    return (float)raw_pressure / 256.0;
}

// Convert raw temperature to degrees Celsius
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Validate sensor data
int validate_sensor_data(SensorData data) {
    if (data.pressure < 0.0 || data.pressure > 500.0 ||
        data.temperature < -40.0 || data.temperature > 125.0) {
        fprintf(stderr, "Invalid sensor data: Pressure = %.2f Pa, Temperature = %.2f C\n", data.pressure, data.temperature);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(SensorData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.pressure, data.temperature, data.scale_factor);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_handle);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    SensorData sensor_data;

    // Main loop
    while (!terminate) {
