#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_MEASUREMENT_COMMAND 0x21B1
#define READ_PERIODIC_MEASUREMENT_COMMAND 0xE000
#define BUFFER_CAPACITY 100
#define LOG_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE_PATH "/var/log/scd40_error.log"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_CAPACITY];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int send_start_periodic_measurement();
int read_scd40(float *co2, float *temperature, float *humidity);
void add_reading(float co2, float temperature, float humidity);
void log_error(const char *message);
void log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        log_error("Error opening I2C");
        return -1;
    }
    return 0;
}

// Function to send the start-periodic-measurement command
int send_start_periodic_measurement() {
    char command[2];
    command[0] = START_MEASUREMENT_COMMAND >> 8;
    command[1] = START_MEASUREMENT_COMMAND & 0xFF;
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending start-periodic-measurement command: %d\n", result);
        log_error("Error sending start-periodic-measurement command");
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40 sensor
int read_scd40(float *co2, float *temperature, float *humidity) {
    char command[2];
    command[0] = READ_PERIODIC_MEASUREMENT_COMMAND >> 8;
    command[1] = READ_PERIODIC_MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending read periodic measurement command: %d\n", result);
        log_error("Error sending read periodic measurement command");
        return -1;
    }

    gpioDelay(10); // Wait for measurement (adjust as needed)

    char buffer[9];
    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        log_error("Error reading data");
        return -1;
    }

    // Validate CRC-8
    unsigned char co2_crc = buffer[0] | (buffer[1] << 8);
    unsigned char temperature_crc = buffer[2] | (buffer[3] << 8);
    unsigned char humidity_crc = buffer[4] | (buffer[5] << 8);

    if (co2_crc != buffer[6] || temperature_crc != buffer[7] || humidity_crc != buffer[8]) {
        fprintf(stderr, "CRC check failed for CO2, Temperature, or Humidity\n");
        log_error("CRC check failed for CO2, Temperature, or Humidity");
        return -1;
    }

    // Convert data
    *co2 = (float)buffer[0] | (float)(buffer[1] << 8);
    *temperature = -45 + 175 * (float)buffer[2] | (float)((buffer[3] << 8) >> 8);
    *humidity = 100 * (float)buffer[4] | (float)((buffer[5] << 8) >> 8);

    return 0;
}

// Function to add a reading to the circular buffer
void add_reading(float co2, float temperature, float humidity) {
    buffer[buffer_index].co2 = co2;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_CAPACITY;
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE_PATH, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE_PATH);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to log data to a CSV file
void log_data(float co2, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_PATH);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co2, temperature, humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        float co2, temperature, humidity;

        // Read sensor data
        if (read_scd40(&co2, &temperature, &humidity) == 0) {
            // Add reading to circular buffer
            add_reading(co2, temperature, humidity);

            // Log data
            log_data(co2, temperature, humidity);

            // Print data to console
            printf("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

