#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the ICP-10110 sensor
#define ICP10110_I2C_ADDR 0x63

// Define the register addresses for calibration coefficients
#define ICP10110_WHO_AM_I_REG 0x08
#define ICP10110_CAL_COEFF_REG 0x05
#define ICP10110_CAL_COEFF_DATA 0x06

// Define the register address for the measurement command
#define ICP10110_MEASURE_REG 0x00

// Define the measurement command (trigger a single measurement)
#define ICP10110_MEASURE_CMD 0x00

// Define the number of samples to take
#define NUM_SAMPLES 5

// Define the I2C bus for the sensor
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration coefficients
typedef struct {
    int a;
    int b;
    int c;
    int d;
} calibration_coeffs_t;

// Function prototypes
int initialize_i2c();
int read_calibration_coeffs(calibration_coeffs_t *coeffs);
int read_sensor_data(calibration_coeffs_t *coeffs, int *pressure, int *temperature);
double convert_pressure(int raw_pressure);
double convert_temperature(int raw_temperature);
void log_data(double pressure, double temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration coefficients from the sensor
int read_calibration_coeffs(calibration_coeffs_t *coeffs) {
    char buffer[8];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10110_CAL_COEFF_REG, buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    coeffs->a = (buffer[1] << 8) | buffer[0];
    coeffs->b = (buffer[3] << 8) | buffer[2];
    coeffs->c = (buffer[5] << 8) | buffer[4];
    coeffs->d = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Read sensor data from the ICP-10110
int read_sensor_data(calibration_coeffs_t *coeffs, int *pressure, int *temperature) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10110_MEASURE_REG, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Convert raw pressure data to hPa
double convert_pressure(int raw_pressure) {
