#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Define the I2C address of the ICP-10125 sensor
#define ICP10125_I2C_ADDR 0x63

// Define the register addresses for calibration coefficients
#define ICP10125_CALIB_0 0x00
#define ICP10125_CALIB_1 0x01
#define ICP10125_CALIB_2 0x02
#define ICP10125_CALIB_3 0x03

// Define the command to trigger a measurement
#define ICP10125_MEASURE_CMD 0x4011

// Define the GPIO pin for the warning LED
#define WARNING_LED_GPIO 17

// Define the delay time in milliseconds
#define DELAY_TIME_MS 200

// Define the pressure threshold for high altitude
#define PRESSURE_THRESHOLD 95000.0

// Define the frequency of the warning LED blink
#define WARNING_LED_FREQUENCY 100 // Hz

// Global variables
int i2c_fd;
int warning_led_gpio;

// Structure to hold calibration coefficients
typedef struct {
    uint16_t calib_0;
    uint16_t calib_1;
    uint16_t calib_2;
    uint16_t calib_3;
} icp10125_calib_t;

// Function prototypes
int init_i2c(int i2c_bus, int i2c_addr);
int read_calibration_coeffs(int fd, icp10125_calib_t *calib);
int write_command(int fd, uint16_t command);
int read_raw_data(int fd, uint16_t *pressure, uint16_t *temperature, uint16_t *crc);
float calculate_pressure(uint16_t pressure, icp10125_calib_t calib);
float calculate_temperature(uint16_t temperature, icp10125_calib_t calib);
void blink_warning_led(int gpio, int frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (warning_led_gpio != -1) {
        gpio_set_direction(warning_led_gpio, GPIOD_OUTPUT);
        gpio_set_value(warning_led_gpio, 0); // Turn off LED
        gpio_unexport(warning_led_gpio);
    }
    gpio_set_direction(17, GPIOD_OUTPUT); // Set GPIO 17 as output
    gpio_set_value(17, 0); // Turn off LED
    gpio_unexport(17);
    exit(0);
}

// Initialize I2C communication
int init_i2c(int i2c_bus, int i2c_addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration coefficients from OTP memory
int read_calibration_coeffs(int fd, icp10125_calib_t *calib) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading calibration coefficients");
        return -1;
    }

    calib->calib_0 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    calib->calib_1 = (uint16_t)((buffer[2] << 8) | buffer[3]);
    calib->calib_2 = (uint16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Write a command to the ICP-10125 sensor
int write_command(int fd, uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = command;
    buffer[1] = 0; // Dummy byte
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing command to sensor");
        return -1;
    }
    return 0;
}

// Read raw data from the ICP-10125 sensor
int read_raw_data(int fd, uint16_t *pressure, uint16_t *temperature, uint16_t *crc) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[2] << 8) | buffer[3];
    *crc = (buffer[4] << 8) | buffer[5];

    return 0;
}

// Calculate pressure in Pascals
float calculate_pressure(uint16_t pressure, icp10125_calib_t calib) {
    return (float)pressure / (float)calib.calib_0;
}

// Calculate temperature in Celsius
float calculate_temperature(uint16_t temperature, icp10125_calib_t calib) {
    return (float)temperature / (float)calib.calib_2;
}

// Blink the warning LED
void blink_warning_led(int gpio, int frequency) {
    gpio_set_direction(gpio, GPIOD_OUTPUT);
    gpio_set_value(gpio, 1); // Turn on LED
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = frequency * 1000000; // Convert Hz to nanoseconds
    while (1) {
        gpio_set_value(gpio, 0); // Turn off LED
        nanosleep(&delay, NULL);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(1, ICP10125_I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coeffs(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO 17 as output
    warning_led_gpio = 17;
    gpio_set_direction(warning_led_gpio, GPIOD_OUTPUT);
    gpio_set_value(warning_led_gpio, 0); // Ensure LED is off initially

    // Main loop
    while (1) {
        // Read raw data
        uint16_t pressure, temperature, crc;
        if (read_raw_data(i2c_fd, &pressure, &temperature, &crc) != 0) {
            fprintf(stderr, "Failed to read raw data. Retrying.\n");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = DELAY_TIME_MS * 1000}, NULL);
            continue;
        }

        // Calculate pressure and temperature
        float pressure_pascals = calculate_pressure(pressure, calib);
        float temperature_celsius = calculate_temperature(temperature, calib);

        // Check for high altitude
        if (pressure_pascals < PRESSURE_THRESHOLD) {
            printf("Warning: Pressure dropping below 95000 Pa. High altitude warning.\n");
            blink_warning_led(warning_led_gpio, WARNING_LED_FREQUENCY);
        }

        // Print pressure and temperature
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure_pascals, temperature_celsius);

        // Delay for 1 second
        nanosleep(&(struct timespec){.tv_sec = 1, .tv_nsec = 0}, NULL);
    }

    return 0;
}

