#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30.0
#define TEMP_MIN_THRESHOLD 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *ambient_temp, float *object_temp);
int validate_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Function to read temperature from MLX90614
int read_temperature(int i2c_handle, float *ambient_temp, float *object_temp) {
    char buf[2];
    int result;

    // Read ambient temperature (RAM register 0x06)
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *ambient_temp = (float)((buf[0] << 8) | buf[1]) / 10.0;

    // Read object temperature (RAM register 0x07)
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *object_temp = (float)((buf[0] << 8) | buf[1]) / 10.0;

    return 0;
}

// Function to validate temperature readings
int validate_temperature(float ambient_temp, float object_temp) {
    if (object_temp < TEMP_MIN_THRESHOLD || object_temp > TEMP_THRESHOLD) {
        fprintf(stderr, "Invalid object temperature: %.2f\n", object_temp);
        return -1;
    }
    return 0;
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    if (object_temp > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Function to log temperature readings to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Ambient: %.2f, Object: %.2f\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float ambient_temp, object_temp;
    int result;

