// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// HTTP port
#define HTTP_PORT 8080

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int sht40_read_data(int i2c_handle, float *temperature, float *humidity);
int sht40_write_command(int i2c_handle, unsigned char command);
int sht40_read_data_block(int i2c_handle, unsigned char *data, int len);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read data from SHT40 sensor
int sht40_read_data(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int result;

    // Send measurement command
    result = sht40_write_command(i2c_handle, 0xFD);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send measurement command (result = %d)\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = sht40_read_data_block(i2c_handle, data, 6);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to read data (result = %d)\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = -45.0 + 175.0 * (float)data[0] / 65535.0;
    *humidity = -6.0 + 125.0 * (float)data[1] / 65535.0;

    return 0;
}

// Function to write data to SHT40 sensor
int sht40_write_command(int i2c_handle, unsigned char command) {
    int result = i2cWriteByteData(i2c_handle, 0, command);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write command (result = %d)\n", result);
        return -1;
    }
    return 0;
}

// Function to read data block from SHT40 sensor
int sht40_read_data_block(int i2c_handle, unsigned char *data, int len) {
    int result = i2cReadI2CBlockData(i2c_handle, 0, data, len);
    if (result != len) {
        fprintf(stderr, "Error: Failed to read data (result = %d)\n", result);
        return -1;
    }
    return 0;
}

int main() {
    float temperature, humidity;
    int retries = 3;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (handle = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("SHT40 Temperature and Humidity Monitoring\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (sht40_read_data(i2c_handle, &temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

