#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 registers
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_MSB 0x00
#define TEMP_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to read a single byte from an I2C register
int read_i2c_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1; // Indicate error
    }
    return 0;
}

// Function to read temperature and humidity from the HDC2010
int read_hdc2010(int handle, float *temperature, float *humidity) {
    int raw_temp, raw_humidity;

    // Trigger measurement
    if (write_i2c_register(handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read temperature and humidity data
    raw_temp = read_i2c_register(handle, TEMP_MSB);
    raw_humidity = read_i2c_register(handle, HUMIDITY_MSB);

    if (raw_temp < 0 || raw_humidity < 0) {
        fprintf(stderr, "Error reading temperature or humidity data\n");
        return -1;
    }

