#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_CHECK_SIZE 2
#define READ_INTERVAL_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sdp800(sensor_data_t *data);
int verify_checksum(const uint8_t *data, int data_len);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads data from the SDP800 sensor
int read_sdp800(sensor_data_t *data) {
    char buf[6];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, MEASUREMENT_COMMAND, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read data from sensor: %d\n", bytes_read);
        return -1;
    }

    // CRC check
    if (!verify_checksum(buf, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

// Verifies the CRC checksum
int verify_checksum(const uint8_t *data, int data_len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[data_len - CRC_CHECK_SIZE]);
}

// Logs the sensor data to the console
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Pressure: %d Pa, Temperature: %d °C\n", timestamp, data.pressure, data.temperature);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sdp800(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(READ_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

