#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define HUMIDITY_THRESHOLD 60.0
#define DEHUMIDIFIER_GPIO 17
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define LOG_FILE "humidity_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure for sensor data
typedef struct {
    float humidity;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_aht20_data(sensor_data_t *data);
int check_sensor_status(int status);
void control_dehumidifier(int gpio_pin, int state);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, AHT20_ADDR, 0); // Bus 1, address 0x38, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from AHT20 sensor
int read_aht20_data(sensor_data_t *data) {
    char buf[6];
    int bytes_read;

    // Trigger measurement
    char trigger_cmd[2] = {0xAC, 0x33};
    bytes_read = i2cWriteDevice(i2c_handle, trigger_cmd, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error writing trigger command: %d\n", bytes_read);
        return -1;
    }
    gpioDelay(80); // Wait for measurement (at least 80ms)

    // Read data
    bytes_read = i2cReadDevice(i2c_handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading data: %d\n", bytes_read);
        return -1;
    }

    // Convert data
    int humidity_raw = (buf[0] << 8) | buf[1];
    int temperature_raw = (buf[3] << 8) | buf[4];

    // Convert humidity (from datasheet)
    data->humidity = (float)humidity_raw / 10.0;

    // Check status byte
    if (!check_sensor_status(humidity_raw)) {
        fprintf(stderr, "Sensor status check failed\n");
        return -1;
    }

    return 0;
}

// Function to check sensor status
int check_sensor_status(int status) {
    return (status == 0x00) ? 1 : 0; // Calibrated and not busy
}

// Function to control dehumidifier relay
void control_dehumidifier(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Humidity: %.2f%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.humidity);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_aht20_data(&sensor_data) == 0) {
            // Check sensor status
            if (check_sensor_status(sensor_data.status)) {
                // Control dehumidifier
                control_dehumidifier(DEHUMIDIFIER_GPIO, 1); // Turn on
                printf("Humidity: %.2f%%\n", sensor_data.humidity);
                log_data(sensor_data);
            } else {
                // Control dehumidifier
                control_dehumidifier(DEHUMIDIFIER_GPIO, 0); // Turn off
                printf("Humidity: %.2f%%\n", sensor_data.humidity);
                log_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    control_dehumidifier(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

