#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define POST_URL "http://api.example.com/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_SEC 60

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float humidity;
    int status;
} SensorData;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_htu21d(int fd, float *humidity);
int post_data(const char *url, const char *data);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
        program_running = 0;
    }
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read humidity from HTU21D sensor
int read_htu21d(int fd, float *humidity) {
    unsigned char cmd[2] = {0x2C, 0x06}; // High repeatability measurement command
    unsigned char data[6];
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        if (write(fd, cmd, 2) != 2) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        if (read(fd, data, 6) != 6) {
            syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        // Convert data to humidity (example, adjust based on datasheet)
        unsigned int humidity_raw = (data[0] << 8) | data[1];
        *humidity = (float)humidity_raw / 16384.0 * 100.0;

        status = 0; // Success
        break; // Exit retry loop on success
    }

    if (retries == MAX_RETRIES) {
        syslog(LOG_ERR, "Failed to read humidity after multiple retries.");
        return -1; // Indicate failure
    }

    return status;
}

// Post data to HTTP server
int post_data(const char *url, const char *data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
