int read_htu21d(int fd, float *humidity) {
    unsigned char cmd[2] = {0x2C, 0x06}; // High repeatability measurement command
    unsigned char data[6];
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        if (write(fd, cmd, 2) != 2) {
