            pressure = compensate_pressure(raw_pressure, temperature, calib);

            // Get current timestamp
            time_t current_time = time(NULL);

            // Check for pressure threshold breaches
            if (pressure > 1020.0 || pressure < 980.0) {
                if (current_time - last_log_time > 60) { // Check every 60 seconds
                    log_pressure_threshold(pressure);
                    last_log_time = current_time;
                }
            }

            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

