#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD_DURATION 5 // seconds
#define MOTOR_BACKWARD_DURATION 5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_init(int gpio_pin, int direction);
int gpio_read(int gpio_pin);
int gpio_write(int gpio_pin, int value);
int rain_detected(int gpio_pin);
void control_motor(int enable_pin, int direction, int duration_seconds);
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize a GPIO pin
int gpio_init(int gpio_pin, int direction) {
    if (gpioSetMode(gpio_pin, direction) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio_pin, int value) {
    return gpioWrite(gpio_pin, value);
}

// Function to detect rain by reading the rain sensor
int rain_detected(int gpio_pin) {
    return gpio_read(gpio_pin);
}

// Function to control the motor
void control_motor(int enable_pin, int direction, int duration_seconds) {
    gpioWrite(enable_pin, 1); // Enable motor
    gpioDelay(duration_seconds * 1000000); // Delay for specified duration
    gpioWrite(enable_pin, 0); // Disable motor
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (gpio_init(RAIN_SENSOR_PIN, PI_INPUT) != 0 ||
        gpio_init(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0 ||
        gpio_init(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpio_init(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int rain_detected_value = rain_detected(RAIN_SENSOR_PIN);

        if (rain_detected_value == 0) {
            printf("Rain detected!\n");
            control_motor(MOTOR_ENABLE_PIN, PI_OUTPUT, MOTOR_FORWARD_DURATION);
            log_event("Rain detected and motor started.");
            sleep(2); // Wait for 5 seconds
            control_motor(MOTOR_ENABLE_PIN, PI_OUTPUT, MOTOR_BACKWARD_DURATION);
            log_event("Rain stopped and motor stopped.");
        } else {
            printf("No rain detected.\n");
        }

        gpioDelay(2000000); // Wait for 2 seconds
    }

    // Cleanup
    control_motor(MOTOR_ENABLE_PIN, PI_OUTPUT, 0); // Ensure motor is stopped
