    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (gpio_init(RAIN_SENSOR_PIN, PI_INPUT) != 0 ||
        gpio_init(MOTOR_ENABLE_PIN, PI_OUTPUT) != 0 ||
        gpio_init(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpio_init(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
