#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define color gradient
#define RED_COLOR 0
#define YELLOW_COLOR 255

// Define color gradient steps
#define RED_STEPS (255 / (RED_COLOR - 0))
#define YELLOW_STEPS (255 / (RED_COLOR - RED_COLOR))

// Global variable to track CPU load
float cpu_load = 0.0;

// Function prototypes
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to turn off the LED
void cleanup() {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
}

// Function to set the RGB LED color
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to map CPU load to a color
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    // Map CPU load to RGB values
    *red = (int)(cpu_load * RED_STEPS);
    *green = (int)(cpu_load * YELLOW_STEPS);
    *blue = (int)(cpu_load * RED_STEPS);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read CPU load from /proc/stat
        FILE *fp = fopen("/proc/stat", "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening /proc/stat\n");
            cleanup();
            return 1;
        }

        // Read CPU load from /proc/stat
        char line[256];
        if (fgets(line, sizeof(line), fp) == NULL) {
            fprintf(stderr, "Error reading /proc/stat\n");
            cleanup();
            return 1;
        }

        // Parse CPU load from /proc/stat
        char *token;
        float load = 0.0;
        int red = 0, green = 0, blue = 0;

        // Find the first space character after the load value
        token = strtok(line, " ");
        while (token != NULL && strcmp(token, "cpu") != 0) {
            if (strcmp(token, "cpu") == 0) {
                load = atof(token + 3);
                break;
            }
            token = strtok(NULL, " ");
        }

        // Map CPU load to color
        map_cpu_load_to_color(load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup (should not reach here due to signal handler)
    cleanup();
    return 0;
}

