#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 registers
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_CONFIG_TEMP 0xF2
#define BMP280_REG_CONFIG_PRESS 0xF3

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
int compensate_data(int32_t raw_temperature, int32_t raw_pressure, bmp280_calib_data calib, float *temperature, float *pressure);
char *format_json(float temperature, float pressure);
int send_udp_message(const char *json_string);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data function
int read_calibration_data(bmp280_calib_data *calib) {
    char buf[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, buf, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    calib->dig_T2 = (int16_t)buf[2] | ((int16_t)buf[3] << 8);
    calib->dig_T3 = (int16_t)buf[4] | ((int16_t)buf[5] << 8);
    calib->dig_P1 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    calib->dig_P2 = (int16_t)buf[8] | ((int16_t)buf[9] << 8);
    calib->dig_P3 = (int16_t)buf[10] | ((int16_t)buf[11] << 8);
    calib->dig_P4 = (int16_t)buf[12] | ((int16_t)buf[13] << 8);
    calib->dig_P5 = (int16_t)buf[14] | ((int16_t)buf[15] << 8);
    calib->dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib->dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib->dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    calib->dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Read raw data function
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)buf[0] << 12 | (int32_t)buf[1] << 4 | (int32_t)buf[2] >> 4;
    *temperature = (int32_t)buf[3] << 12 | (int32_t)buf[4] << 4 | (int32_t)buf[5] >> 4;

    return 0;
}

// Compensate data function
int compensate_data(int32_t raw_temperature, int32_t raw_pressure, bmp280_calib_data calib, float *temperature, float *pressure) {
    double var1, var2, T;
    double p;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    *temperature = (t_fine / 5120.0);

    p = (t_fine / 2.0) - 64000.0;
    var1 = p * p * ((double)calib.dig_P6) / 32768.0;
    var2 = var1 + p * ((double)calib.dig_P5) * p / 32768.0;
    var1 = (p * ((double)calib.dig_P4) / 32768.0) + (p * p / 524288.0 + var2);
    *pressure = 1048576.0 - p * p / 65536.0 - (p * p / 524288.0 + var1);
    *pressure = (*pressure > 0) ? (*pressure) / 2147483648.0 : (*pressure) / 2147483648.0;
    *pressure = (*pressure < 0) ? (*pressure) / 2147483648.0 : (*pressure) / 2147483648.0;

    return 0;
}

// Format JSON string function
char *format_json(float temperature, float pressure) {
    char *json_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Send UDP message function
int send_udp_message(const char *json_string) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)json_string, strlen(json_string), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        float temperature, pressure;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate data
            if (compensate_data(raw_temperature, raw_pressure, calib, &temperature, &pressure) == 0) {
                // Format JSON string
                char *json_string = format_json(temperature, pressure);
                if (json_string != NULL) {
                    // Send UDP message
                    if (send_udp_message(json_string) != 0) {
                        fprintf(stderr, "Failed to send UDP message\n");
                    }
                    free(json_string); // Free the allocated memory
                } else {
                    fprintf(stderr, "Failed to format JSON string\n");
                }
            } else {
                fprintf(stderr, "Failed to compensate data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

