    calib->dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib->dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib->dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
