    double t_fine = (var1 + var2);
    *temperature = (t_fine / 5120.0);

    p = (t_fine / 2.0) - 64000.0;
    var1 = p * p * ((double)calib.dig_P6) / 32768.0;
    var2 = var1 + p * ((double)calib.dig_P5) * p / 32768.0;
    var1 = (p * ((double)calib.dig_P4) / 32768.0) + (p * p / 524288.0 + var2);
