    *pressure = (*pressure < 0) ? (*pressure) / 2147483648.0 : (*pressure) / 2147483648.0;

    return 0;
}

// Format JSON string function
char *format_json(float temperature, float pressure) {
    char *json_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Send UDP message function
int send_udp_message(const char *json_string) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)json_string, strlen(json_string), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        float temperature, pressure;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate data
            if (compensate_data(raw_temperature, raw_pressure, calib, &temperature, &pressure) == 0) {
                // Format JSON string
                char *json_string = format_json(temperature, pressure);
                if (json_string != NULL) {
                    // Send UDP message
                    if (send_udp_message(json_string) != 0) {
                        fprintf(stderr, "Failed to send UDP message\n");
                    }
                    free(json_string); // Free the allocated memory
                } else {
                    fprintf(stderr, "Failed to format JSON string\n");
                }
            } else {
                fprintf(stderr, "Failed to compensate data\n");
            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

