#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FAN_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define TEMP_BUFFER_SIZE 20

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255

// Define MAX31855 registers
#define MAX31855_REG_TEMP 0x00
#define MAX31855_REG_FAULT 0x01
#define MAX31855_REG_OC 0x02
#define MAX31855_REG_SCG 0x03
#define MAX31855_REG_SCV 0x04
#define MAX31855_REG_CV 0x05

// Define fault types
#define MAX31855_FAULT_TYPE_NORMAL 0
#define MAX31855_FAULT_TYPE_HIGH_TEMP 1
#define MAX31855_FAULT_TYPE_LOW_TEMP 2

// Define temperature thresholds
#define TEMP_THRESHOLD_LOW 25.0
#define TEMP_THRESHOLD_HIGH 60.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static int fan_duty_cycle = 0;
static int temp_buffer[TEMP_BUFFER_SIZE];
static int buffer_index = 0;
static volatile int spi_error = 0;

// Function prototypes
int read_max31855(int spi_handle, int *temperature);
int process_max31855_data(int temperature, int fault_type);
void set_fan_duty_cycle(int duty_cycle);
void log_data(int temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, int *temperature) {
    unsigned char data[4];
    int result;

    result = spiXfer(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    *temperature >>= 4; // Shift right by 4 bits

    return 0;
}

// Function to process MAX31855 data
int process_max31855_data(int temperature, int fault_type) {
    int valid_temp = 0;
    int valid_fault = 0;

    if (fault_type == MAX31855_FAULT_TYPE_NORMAL) {
        valid_temp = (temperature & 0x3FFF) >> 4; // Extract 14-bit temperature
        valid_fault = 0; // No fault
    } else if (fault_type == MAX31855_FAULT_TYPE_HIGH_TEMP) {
        valid_temp = (temperature & 0x3FFF) >> 4; // Extract 14-bit temperature
        valid_fault = 1; // High temperature fault
    } else if (fault_type == MAX31855_FAULT_TYPE_LOW_TEMP) {
        valid_temp = (temperature & 0x3FFF) >> 4; // Extract 14-bit temperature
        valid_fault = 2; // Low temperature fault
    }

    if (valid_temp) {
        return valid_temp;
    } else {
        fprintf(stderr, "Invalid temperature data: %d\n", temperature);
        return -1;
    }
}

// Function to set fan duty cycle
void set_fan_duty_cycle(int duty_cycle) {
    gpioPWM(FAN_PIN, duty_cycle);
}

// Function to log data to a circular buffer
void log_data(int temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (buffer_index < TEMP_BUFFER_SIZE) {
        temp_buffer[buffer_index] = temperature;
        buffer_index++;
    } else {
        fprintf(stderr, "Circular buffer overflow!\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    set_fan_duty_cycle(0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int temperature, fault_type;
    int max31855_result;
    int max31855_fault_type;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature from MAX31855
        max31855_result = read_max31855(spi_handle, &temperature);
        if (max31855_result != 0) {
            fprintf(stderr, "Error reading MAX31855 data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process MAX31855 data
        fault_type = process_max31855_data(temperature, 0); // Fault type is not used
        if (fault_type == -1) {
            fprintf(stderr, "Error processing MAX31855 data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for fault
        if (fault_type != MAX31855_FAULT_TYPE_NORMAL) {
            fprintf(stderr, "Fault detected: %d\n", fault_type);
            spi_error = 1; // Set SPI error flag
            break;
        }

        // Set fan duty cycle
        set_fan_duty_cycle(fan_duty_cycle);

        // Log data
        log_data(temperature, fan_duty_cycle);

        // Wait for 1 second
        gpioDelay(1000); // 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

