#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define OSS 3
#define GPIO_PIN 2
#define LOG_FILE "altitude_log.txt"

// BMP180 Registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 Calibration Data Structure
typedef struct {
    short ac1;
    short ac2;
    short ac3;
    unsigned short ac4;
    unsigned short ac5;
    unsigned short ac6;
    short b1;
    short b2;
    short mb;
    short mc;
    short md;
} bmp180_calibration_data;

// Global Variables
int i2c_handle;
bmp180_calibration_data calib;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data *calib);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss);
double calculate_temperature(int raw_temperature, bmp180_calibration_data calib);
double calculate_pressure(int raw_pressure, int raw_temperature, int oss, bmp180_calibration_data calib);
char* get_timestamp();
int log_data(const char *timestamp, double temperature, double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data *calib) {
    char buf[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->ac1 = (buf[1] << 8) | buf[0];
    calib->ac2 = (buf[3] << 8) | buf[2];
    calib->ac3 = (buf[5] << 8) | buf[4];
    calib->ac4 = (buf[7] << 8) | buf[6];
    calib->ac5 = (buf[9] << 8) | buf[8];
    calib->ac6 = (buf[11] << 8) | buf[10];
    calib->b1 = (buf[13] << 8) | buf[12];
    calib->b2 = (buf[15] << 8) | buf[14];
    calib->mb = (buf[17] << 8) | buf[16];
    calib->mc = (buf[19] << 8) | buf[18];
    calib->md = (buf[21] << 8) | buf[20];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int i2c_handle, int oss) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, oss) != 0) {
        fprintf(stderr, "Error setting OSS\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    return (buf[0] << 16 | buf[1] << 8 | buf[2]) >> (8 - oss);
}

// Function to calculate temperature in Celsius
double calculate_temperature(int raw_temperature, bmp180_calibration_data calib) {
    double x1 = ((double)raw_temperature - (double)calib.ac6) * ((double)calib.ac5) / pow(2, 15);
    double x2 = ((double)calib.mc * pow(2, 11)) / (x1 + calib.md);
    double b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temperature, int oss, bmp180_calibration_data calib) {
    double x1 = ((double)raw_temperature - (double)calib.ac6) * ((double)calib.ac5) / pow(2, 15);
    double x2 = ((double)calib.mc * pow(2, 11)) / (x1 + calib.md);
    double b5 = x1 + x2;
    double b6 = b5 - 4000;
    double x3 = ((double)calib.b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    double x4 = ((double)calib.ac2 * b6) / pow(2, 11);
    double b3 = (((double)calib.ac1 * 4 + x3 + x4) + 2) / 4;
    double x5 = ((double)calib.ac3 * b6) / pow(2, 13);
    double b4 = ((double)calib.b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    double pressure = b3 + (x5 + (x5 > 0) ? (b4 + x5 * x5 / pow(2, 16)) : 0) * pow(2, -oss);
    return pressure;
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log data to a file
int log_data(const char *timestamp, double temperature, double pressure) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fclose(log_file);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        char *timestamp = get_timestamp();
        if (timestamp != NULL) {
            double temperature = calculate_temperature(read_raw_temperature(i2c_handle), calib);
            double pressure = calculate_pressure(read_raw_pressure(i2c_handle, OSS), read_raw_temperature(i2c_handle), OSS, calib);
            log_data(timestamp, temperature, pressure);
            free(timestamp);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor on GPIO pin
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Register interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        gpioDelay(1000); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

