#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pigpio.h>

// Configuration
#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MAX31865_CS_GPIO 8
#define MAX31865_BiasVoltage 0.5
#define RTD_RESOLUTION 0.1
#define LOG_FILE "rtd_log.csv"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_bus;
    int spi_channel;
    int spi_speed;
    int max31865_cs_gpio;
    float max31865_bias_voltage;
    float rtd_resolution;
    char log_file[256];
    char server_ip[64];
    int server_port;
} config_t;

// Function prototypes
int spi_init(int spi_bus, int spi_channel, int spi_speed);
int read_max31865(int spi_fd, int cs_gpio, float *temperature);
float calculate_temperature(int raw_temperature);
int log_data(FILE *log_file, float temperature);
int send_data(const char *server_ip, int server_port, float temperature);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init(int spi_bus, int spi_channel, int spi_speed) {
    int fd = spiOpen(spi_bus, spi_channel, spi_speed);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read data from MAX31865
int read_max31865(int spi_fd, int cs_gpio, float *temperature) {
    unsigned char tx_buffer[4];
    unsigned char rx_buffer[4];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        tx_buffer[0] = 0x01; // Start bit
        tx_buffer[1] = 0x00; // Dummy byte
        tx_buffer[2] = 0x00; // Dummy byte
        tx_buffer[3] = 0x00; // Dummy byte

        gpioWrite(cs_gpio, 0); // Select MAX31865
        result = spiXfer(spi_fd, tx_buffer, rx_buffer, 4);
        gpioWrite(cs_gpio, 1); // Deselect MAX31865

        if (result == 0) {
            // Check fault status register
            unsigned char fault_status = (rx_buffer[2] << 8) | rx_buffer[3];
            if (fault_status & 0x01) {
                fprintf(stderr, "MAX31865 Fault: %d\n", fault_status);
                return -1; // Fault
            }

            // Read RTD data
            unsigned char rtd_data[2];
            result = spiXfer(spi_fd, rx_buffer + 1, rtd_data, 2);
            if (result != 2) {
                fprintf(stderr, "Error reading RTD data: %s\n", strerror(errno));
                return -1; // Error reading RTD data
            }

            // Convert RTD data to temperature
            int raw_temperature = (rtd_data[0] << 8) | rtd_data[1];
            *temperature = calculate_temperature(raw_temperature);

            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure after all retries
}

// Function to calculate temperature using Callendar-Van Dusen equation
float calculate_temperature(int raw_temperature) {
    float temperature = raw_temperature * RTD_RESOLUTION;
    return temperature;
}

// Function to log data to CSV file
int log_data(FILE *log_file, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to send data to server
int send_data(const char *server_ip, int server_port, float temperature) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect failed");
        close(sockfd);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%.2f", temperature);
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        perror("send failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close SPI device and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .spi_bus = SPI_BUS,
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .max31865_cs_gpio = MAX31865_CS_GPIO,
        .max31865_bias_voltage = MAX31865_BiasVoltage,
        .rtd_resolution = RTD_RESOLUTION,
        .log_file = LOG_FILE,
        .server_ip = SERVER_IP,
        .server_port = SERVER_PORT
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS GPIO as output
    gpioSetMode(config.max31865_cs_gpio, PI_OUTPUT);
    gpioWrite(config.max31865_cs_gpio, 1); // Deselect MAX31865 initially

    // Initialize SPI
    spi_fd = spi_init(config.spi_bus, config.spi_channel, config.spi_speed);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature;
        int retries = 0;
        int result;

        while (retries < MAX_RETRIES) {
            result = read_max31865(spi_fd, config.max31865_cs_gpio, &temperature);
            if (result == 0) {
                break; // Success
            } else {
                fprintf(stderr, "Error reading MAX31865, retrying...\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "MAX31865 read failed after %d retries\n", MAX_RETRIES);
            log_data(log_file, -1.0); // Log error
            continue; // Skip to the next iteration
        }

        if (temperature != -1.0) {
            log_data(log_file, temperature);
            result = send_data(config.server_ip, config.server_port, temperature);
            if (result != 0) {
                fprintf(stderr, "Error sending data to server\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
            log_data(log_file, -1.0); // Log error
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

