                fprintf(stderr, "Error sending data to server\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
            log_data(log_file, -1.0); // Log error
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

