#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_I2C_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// OSS (OverSampling Setting)
#define OSS 0x03 // Ultra-low power

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size
#define BUFFER_SIZE 60

// Calibration data structure
typedef struct {
    uint16_t ac1;
    uint16_t ac2;
    uint16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calib_data;

// Circular buffer
bmp180_calib_data calib_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calib_data *calib);
int read_raw_temperature(int32_t *temperature);
int read_raw_pressure(int32_t *pressure);
double calculate_temperature(int32_t ut);
double calculate_pressure(int32_t up, int32_t ut);
double calculate_temperature_difference(double temperature1, double temperature2);
double calculate_pressure_difference(double pressure1, double pressure2);
void alert_callback(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calib_data *calib) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->ac1 = (buf[0] << 8) | buf[1];
    calib->ac2 = (buf[2] << 8) | buf[3];
    calib->ac3 = (buf[4] << 8) | buf[5];
    calib->ac4 = (buf[6] << 8) | buf[7];
    calib->ac5 = (buf[8] << 8) | buf[9];
    calib->ac6 = (buf[10] << 8) | buf[11];
    calib->b1 = (buf[12] << 8) | buf[13];
    calib->b2 = (buf[14] << 8) | buf[15];
    calib->mb = (buf[16] << 8) | buf[17];
    calib->mc = (buf[18] << 8) | buf[19];
    calib->md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int32_t *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int32_t *pressure) {
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    *pressure = (buf[0] << 16 | buf[1] << 8 | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - calib_buffer[buffer_index].ac6) * calib_buffer[buffer_index].ac5) >> 15;
    int32_t x2 = ((calib_buffer[buffer_index].mc << 11) / (x1 + calib_buffer[buffer_index].md)) >> 11;
    int32_t b5 = x1 + x2;
    double temperature = (b5 + 8) >> 4;
    return temperature / 10.0;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - calib_buffer[buffer_index].ac6) * calib_buffer[buffer_index].ac5) >> 15;
    int32_t x2 = ((calib_buffer[buffer_index].mc << 11) / (x1 + calib_buffer[buffer_index].md)) >> 11;
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = (calib_buffer[buffer_index].b2 * (b6 * b6) >> 12) >> 11;
    int32_t x4 = calib_buffer[buffer_index].ac2 * b6;
    int32_t b3 = (((((calib_buffer[buffer_index].ac1 * 4 + x3) << oss) + 2) >> 2) * (calib_buffer[buffer_index].ac3 * 2 + x4)) >> 15;
    int32_t b4 = (calib_buffer[buffer_index].ac4 * (b6 >> 11));
    int32_t p = (b3 + (calib_buffer[buffer_index].ac7 * b4)) >> 15;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to calculate temperature difference
double calculate_temperature_difference(double temperature1, double temperature2) {
    return abs(temperature1 - temperature2);
}

// Function to calculate pressure difference
double calculate_pressure_difference(double pressure1, double pressure2) {
    return abs(pressure1 - pressure2);
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick, void *userdata) {
    if (gpio == ALERT_PIN) {
        double temperature_diff = calculate_temperature_difference(calculate_temperature(calib_buffer[buffer_index].temperature), calculate_temperature(calib_buffer[buffer_index].temperature));
        double pressure_diff = calculate_pressure_difference(calculate_pressure(calib_buffer[buffer_index].pressure, calib_buffer[buffer_index].temperature), calculate_pressure(calib_buffer[buffer_index].pressure, calib_buffer[buffer_index].temperature));

        printf("ALERT: Temperature Difference = %.2f C, Pressure Difference = %.2f hPa\n", temperature_diff, pressure_diff);

        // Check if the difference exceeds the threshold
        if (temperature_diff > 5.0 || pressure_diff > 5.0) {
            gpioWrite(ALERT_PIN, 1); // Set GPIO HIGH
            gpioDelay(500000);       // Wait for 500ms
            gpioWrite(ALERT_PIN, 0); // Set GPIO LOW
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alert pin as output
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure it's initially LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib_buffer[0]) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer function
    if (gpioSetTimerFuncEx(0, 50, alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        int32_t ut, up;
        if (read_raw_temperature(&ut) != 0 || read_raw_pressure(&up) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(ut);
        double pressure = calculate_pressure(up, ut);

        // Calculate temperature difference and pressure difference
        double temperature_diff = calculate_temperature_difference(temperature, calib_buffer[buffer_index].temperature);
        double pressure_diff = calculate_pressure_difference(pressure, calib_buffer[buffer_index].pressure);

        // Check if the difference exceeds the threshold
        if (temperature_diff > 5.0 || pressure_diff > 5.0) {
            gpioWrite(ALERT_PIN, 1); // Set GPIO HIGH
            gpioDelay(500000);       // Wait for 500ms
            gpioWrite(ALERT_PIN, 0); // Set GPIO LOW
        }

        // Update buffer index
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Print sensor data
        printf("Temperature: %.2f C, Pressure: %.2f hPa, Temperature Difference: %.2f C, Pressure Difference: %.2f hPa\n",
               temperature, pressure, temperature_diff, pressure_diff);

        gpioDelay(100000); // Wait 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALERT_PIN, 0); // Ensure GPIO is LOW before exiting
    gpioTerminate();

    return 0;
}

