#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000 // 25 kHz
#define PWM_RANGE 255
#define TEMP_THRESHOLD 40.0 // 40°C
#define TEMP_THRESHOLD_HIGH 70.0 // 70°C
#define TEMP_THRESHOLD_LOW 60.0 // 60°C
#define TEMP_SCALE_FACTOR 0.1 // 0.1°C per unit

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_temperature();
int map_temperature(int temp);
int set_fan_speed(int duty_cycle);
int log_data(int temp, int duty_cycle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    int temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_celsius;
}

// Function to map temperature to duty cycle
int map_temperature(int temp) {
    if (temp < TEMP_THRESHOLD_LOW) {
        return 0; // 0% duty cycle
    } else if (temp < TEMP_THRESHOLD_HIGH) {
        return PWM_RANGE; // 100% duty cycle
    } else {
        return PWM_RANGE * (temp - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW);
    }
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle out of range (0-255)\n");
        return -1;
    }

    gpioPWM(FAN_GPIO, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(int temp, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Temp: %d, Duty Cycle: %d\n", timestamp, temp, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int temp, duty_cycle;
    int previous_duty_cycle = 0;
    int previous_temp = -1; // Initialize to an invalid value

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        temp = read_temperature();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Map temperature to duty cycle
        duty_cycle = map_temperature(temp);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Log data
        if (log_data(temp, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
        }

        // Check for temperature threshold
        if (temp < TEMP_THRESHOLD_LOW || temp > TEMP_THRESHOLD_HIGH) {
            if (temp < TEMP_THRESHOLD_LOW) {
                fprintf(stderr, "Temperature below threshold, stopping fan.\n");
                set_fan_speed(0); // Stop the fan
                running = 0; // Stop the loop
            } else if (temp > TEMP_THRESHOLD_HIGH) {
                fprintf(stderr, "Temperature above threshold, stopping fan.\n");
                set_fan_speed(0); // Stop the fan
                running = 0; // Stop the loop
            }
        }

        // Check for previous duty cycle
        if (previous_duty_cycle != duty_cycle) {
            printf("Temperature: %d, Duty Cycle: %d\n", temp, duty_cycle);
            previous_duty_cycle = duty_cycle;
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Stop the fan and close the log file before exiting
    set_fan_speed(0); // Stop the fan
    fclose(log_file);
    gpioTerminate();

    printf("Fan control stopped.\n");

    return 0;
}

