#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static int running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_temperature(int i2c_handle, int *temperature);
float convert_to_celsius(int raw_temperature);
void add_to_buffer(CircularBuffer *buffer, float temperature);
float calculate_running_average(CircularBuffer *buffer);
void control_led(float temperature);
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer temperature_buffer = {0};

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75 sensor
int read_temperature(int i2c_handle, int *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temperature) {
    return (float)raw_temperature / 16384.0 * 165.0;
}

// Function to add temperature to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float temperature) {
    buffer->buffer[buffer->head] = temperature;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the running average of the temperatures in the buffer
float calculate_running_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_temperature;
        float temperature;

        // Read temperature from LM75 sensor
        if (read_temperature(i2c_handle, &raw_temperature) == 0) {
            // Convert raw temperature to Celsius
            temperature = convert_to_celsius(raw_temperature);

            // Add temperature to circular buffer
            add_to_buffer(&temperature_buffer, temperature);

            // Calculate running average
            float avg_temperature = calculate_running_average(&temperature_buffer);

            // Control LED based on temperature
            control_led(temperature);

            // Print temperature and running average to console
            printf("Temperature: %.2f C, Running Average: %.2f C\n", temperature, avg_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

