#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

// Define GPIO pins
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// Define I2C address for MCP3008
#define I2C_ADDRESS 0x40

// Define temperature thresholds
#define TEMP_LOW_THRESHOLD 40000
#define TEMP_HIGH_THRESHOLD 60000

// Define PWM frequency
#define PWM_FREQUENCY 25000

// Define PWM range
#define PWM_RANGE 255

// Define PWM duty cycle range
#define PWM_DUTY_RANGE PWM_RANGE

// Define PWM duty cycle values
#define PWM_DUTY_LOW 0
#define PWM_DUTY_MEDIUM 128
#define PWM_DUTY_HIGH 255

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd;

// Function prototypes
int read_temperature();
void set_led_color(int red, int green, int blue);
void cleanup();
void signal_handler(int signal);

// Function to read temperature from /sys/class/thermal/thermal_zone0/temp
int read_temperature() {
    char buffer[5];
    int fd;

    fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, 5) != 5) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(buffer);
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    int duty_cycle = (int)((red * PWM_RANGE) / PWM_DUTY_RANGE);
    int pwm_value = (duty_cycle > PWM_DUTY_HIGH) ? PWM_DUTY_HIGH : duty_cycle;
    int pwm_range = (int)((PWM_RANGE - PWM_DUTY_HIGH) / (PWM_DUTY_HIGH - PWM_DUTY_LOW));

    gpioPWM(RED_PIN, pwm_value);
    gpioPWM(GREEN_PIN, pwm_value);
    gpioPWM(BLUE_PIN, pwm_value);
}

// Function to cleanup GPIO and I2C resources
void cleanup() {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    close(i2c_fd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, skipping update.\n");
            sleep(1);
            continue;
        }

        int red = temperature / 10;
        int green = (temperature - red) / 10;
        int blue = 0;

        set_led_color(red, green, blue);

        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);
        sleep(0.5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

