#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define RETRY_COUNT 3
#define MAX_RETRIES 3
#define MAX_READ_RETRIES 3
#define MAX_READ_SIZE 40
#define CHECKSUM_SIZE 8
#define MAX_CHECKSUM_SIZE 8

// Global variables
static volatile int running = 1;
static int retry_count = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT22Data;

// Function prototypes
int read_dht22(int gpio, DHT22Data *data);
int validate_checksum(const unsigned char *data, int data_size, int checksum_size);
int send_http_request(const char *url, const char *payload);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, DHT22Data *data) {
    unsigned char data[MAX_READ_SIZE];
    unsigned char response[MAX_READ_SIZE];
    int i, j;
    int retries = 0;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 1);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms

    // Read response
    for (i = 0; i < MAX_READ_RETRIES; i++) {
        retries++;
        gpioSetMode(gpio, PI_INPUT);
        gpioSetPullUpDown(gpio, PI_PUD_UP); // Use pull-up resistor

        gpioDelay(1); // 1ms

        if (gpioRead(gpio) == 0) {
            // Read 40 bits of data
            for (j = 0; j < MAX_READ_SIZE; j++) {
                gpioDelay(1); // 1us
                data[j] = gpioRead(gpio);
            }
            break; // Exit loop on success
        } else {
            gpioDelay(1); // 1ms
            retries--;
        }
    }

    if (retries == MAX_READ_RETRIES) {
        fprintf(stderr, "Error: DHT22 read failed after %d retries.\n", MAX_READ_RETRIES);
        return -1; // Indicate failure
    }

    // Validate checksum
    if (validate_checksum(data, MAX_READ_SIZE, CHECKSUM_SIZE) != 0) {
        fprintf(stderr, "Error: DHT22 checksum validation failed.\n");
        return -1; // Indicate failure
    }

    // Extract humidity and temperature
    data->humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    data->temperature = (float)((data[2] << 8) | data[3]) / 10.0;

    // Validate temperature
    if (data->temperature < -40.0 || data->temperature > 80.0) {
        fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", data->temperature);
        return -1; // Indicate failure
    }

    // Validate humidity
    if (data->humidity < 0.0 || data->humidity > 100.0) {
        fprintf(stderr, "Error: Humidity reading out of range: %.2f\n", data->humidity);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to validate checksum
int validate_checksum(const unsigned char *data, int data_size, int checksum_size) {
    unsigned char checksum_calculated[checksum_size];
    for (int i = 0; i < checksum_size; i++) {
        checksum_calculated[i] = data[data_size - checksum_size + i];
    }

    unsigned char calculated_checksum[checksum_size];
    for (int i = 0; i < checksum_size; i++) {
        calculated_checksum[i] = data[data_size - checksum_size + i];
    }

    if (memcmp(calculated_checksum, checksum_calculated, checksum_size) != 0) {
        fprintf(stderr, "Error: Checksum mismatch.\n");
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to send HTTP request
int send_http_request(const char *url, const char *payload) {
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = system(f"curl -X POST -d \"%s\" -s \"%s\"", payload, url);
        if (result == 0) {
            printf("HTTP POST request sent successfully.\n");
            return 0; // Indicate success
        } else {
            fprintf(stderr, "Error: HTTP POST request failed (attempt %d/%d). Error: %d\n", retries + 1, MAX_RETRIES, result);
            retries++;
            sleep(1); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: HTTP POST request failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO mode for DHT22
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0); // Pull low initially

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        DHT22Data dht22_data;
        if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
            printf("Humidity: %.2f, Temperature: %.2f\n", dht22_data.humidity, dht22_data.temperature);

            // Validate checksum
            if (validate_checksum(&dht22_data.data, MAX_READ_SIZE, CHECKSUM_SIZE) == 0) {
                // Send HTTP request
                if (send_http_request(SERVER_URL, "{\"humidity\": %.2f, \"temperature\": %.2f}") == 0) {
                    printf("Humidity: %.2f, Temperature: %.2f\n", dht22_data.humidity, dht22_data.temperature);
                } else {
                    fprintf(stderr, "Error: Failed to send HTTP request.\n");
                }
            } else {
                fprintf(stderr, "Error: Checksum validation failed.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read DHT22 sensor.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

