#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 calibration data
typedef struct {
    short ac1;
    short ac2;
    short ac3;
    unsigned short ac4;
    unsigned short ac5;
    unsigned short ac6;
    short b1;
    short b2;
    short mb;
    short mc;
    short md;
} bmp180_calibration_data;

// Global variables
int i2c_handle;
bmp180_calibration_data calibration;
volatile int logging_enabled = 0;

// Function prototypes
int read_bmp180_calibration_data(int i2c_handle, bmp180_calibration_data *cal);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss, int *raw_pressure);
double compensate_temperature(int raw_temperature, bmp180_calibration_data cal);
double compensate_pressure(int raw_pressure, int oss, double temperature, bmp180_calibration_data cal);
int log_pressure(double pressure, int oss);
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_bmp180_calibration_data(int i2c_handle, bmp180_calibration_data *cal) {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CONTROL, data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->ac1 = (data[1] << 8) | data[0];
    cal->ac2 = (data[3] << 8) | data[2];
    cal->ac3 = (data[5] << 8) | data[4];
    cal->ac4 = (data[7] << 8) | data[6];
    cal->ac5 = (data[9] << 8) | data[8];
    cal->ac6 = (data[11] << 8) | data[10];
    cal->b1 = (data[13] << 8) | data[12];
    cal->b2 = (data[15] << 8) | data[14];
    cal->mb = (data[17] << 8) | data[16];
    cal->mc = (data[19] << 8) | data[18];
    cal->md = (data[21] << 8) | data[20];

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int i2c_handle) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Function to read raw pressure from BMP180
int read_raw_pressure(int i2c_handle, int oss, int *raw_pressure) {
    char data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, oss) != 0) {
        fprintf(stderr, "Error setting OSS\n");
        return -1;
    }
    gpioDelay(5); // Wait for conversion (at least 4.5ms)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = (data[0] << 16 | data[1] << 8 | data[2]) >> (8 - oss);
    return 0;
}

// Function to compensate temperature
double compensate_temperature(int raw_temperature, bmp180_calibration_data cal) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)cal.ac6) / 16.0) * ((double)cal.ac5) / 32768.0;
    var2 = ((double)cal.ac3) / 524288.0 * var1;
    double t = var1 + var2;
    return t / 100.0;
}

// Function to compensate pressure
double compensate_pressure(int raw_pressure, int oss, double temperature, bmp180_calibration_data cal) {
    double var1, var2, p;
    var1 = ((double)temperature / 16384.0 - (double)cal.ac6 / 16.0) * ((double)cal.ac5) / 131072.0;
    var2 = ((double)cal.ac2 * var1) / 32768.0;
    var1 = ((double)cal.ac1 * var1) / 524288.0 + ((double)cal.ac3 * var1) / 524288.0;
    double t = var1 + var2;
    double p = (t / 25600.0) * (oss * 2.0);
    return p;
}

// Function to log pressure to a file
int log_pressure(double pressure, int oss) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    logging_enabled = !logging_enabled;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    logging_enabled = 0; // Disable logging on exit
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_bmp180_calibration_data(i2c_handle, &calibration) != 0) {
        fprintf(stderr, "Error reading BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    gpioSetMode(4, PI_INPUT); // GPIO4 is the interrupt pin
    gpioSetPullUpDown(4, PI_PUD_UP); // Enable pull-up resistor
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, interrupt_handler, NULL); // Set falling-edge interrupt

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(i2c_handle) != 0) {
            fprintf(stderr, "Error reading raw temperature\n");
            continue; // Skip to the next iteration
        }
        if (read_raw_pressure(i2c_handle, 3, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw pressure\n");
            continue; // Skip to the next iteration
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calibration);
        pressure = compensate_pressure(raw_pressure, 3, temperature, calibration);

        // Log pressure if logging is enabled
        if (logging_enabled) {
            if (log_pressure(pressure, 3) != 0) {
                fprintf(stderr, "Error logging pressure\n");
            }
        }

        // Print pressure reading
        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        // Delay for 2 seconds
        gpioDelay(2000000); // 2 seconds = 2000000 us
    }

    return 0;
}

