#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define LOG_FILE "cooling_log.csv"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_temperature();
int map_temperature(int temp);
int set_pwm(int duty_cycle);
int log_data(int temp, int duty_cycle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    int temp_milli;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli;
}

// Function to map temperature to duty cycle
int map_temperature(int temp) {
    if (temp < 40) {
        return 0; // 0% duty cycle
    } else if (temp < 70) {
        return 100; // 100% duty cycle
    } else {
        return (int)(((float)temp - 40.0) / (70.0 - 40.0)) * 100.0; // Linear interpolation
    }
}

// Function to set PWM duty cycle
int set_pwm(int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }
    gpioPWM(FAN_GPIO, duty_cycle);
    return duty_cycle;
}

// Function to log data to CSV file
int log_data(int temp, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1; // Indicate error
        }
        fprintf(log_file, "Timestamp,Temperature,Duty Cycle\n");
        fclose(log_file);
        log_file = NULL; // Reset after closing
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, temp, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    int temp_milli, duty_cycle;
    int temp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(FAN_GPIO, 100);

    // Set PWM duty cycle range (0-100)
    gpioSetPWMrange(FAN_GPIO, 100);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature-controlled fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        temp_milli = read_temperature();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading temperature, exiting...\n");
            break;
        }

        // Map temperature to duty cycle
        duty_cycle = map_temperature(temp_milli);

        // Set PWM duty cycle
        set_pwm(duty_cycle);

        // Log data
        if (log_data(temp_milli, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Delay for 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 microseconds
    }

    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Release resources
    gpioTerminate();

    printf("Temperature-controlled fan control stopped.\n");

    return 0;
}

