#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define constants
#define PULSES_PER_REVOLUTION 360
#define QUADRATURE_DELAY_US 10000 // 10ms delay

// Global variables
static volatile int pulse_count = 0;
static volatile int last_state = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_encoder_state();
int calculate_angle(int pulse_count);
void log_data(int angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

