    int current_state = gpioRead(SENSOR_A_PIN);
    int new_state = gpioRead(SENSOR_B_PIN);

    if (current_state != last_state) {
        pulse_count++;
        last_state = current_state;
    }

    return new_state;
}

// Calculate angle in degrees
int calculate_angle(int pulse_count) {
    return (pulse_count * 360) / PULSES_PER_REVOLUTION;
}

// Log data to file
void log_data(int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Angle: %d degrees\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

