        return 1;
    }

    // Open log file
    log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int new_state = read_encoder_state();
        if (new_state != last_state) {
            pulse_count = 0;
            last_state = new_state;
            int angle = calculate_angle(pulse_count);
            log_data(angle);
            printf("Angle: %d degrees\n", angle);
            pulse_count = 0; // Reset pulse count after logging
        }
        gpioDelay(QUADRATURE_DELAY_US); // Delay to avoid busy-waiting
    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

