#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define RED_FIFO_REG 0x60
#define IR_FIFO_REG 0x61
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_red_channel(int fd);
int read_ir_channel(int fd);
int process_data(int red_value, int ir_value);
void control_led(int gpio_pin, int state);
void log_data(int red, int ir);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read red channel data from ADPD144RI
int read_red_channel(int fd) {
    char buf[2];
    int red_value = -1; // Initialize to an invalid value

    if (i2cReadI2CBlockData(fd, RED_FIFO_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading red channel data\n");
        return -1;
    }

    red_value = (buf[0] << 8) | buf[1];
    return red_value;
}

// Function to read IR channel data from ADPD144RI
int read_ir_channel(int fd) {
    char buf[2];
    int ir_value = -1; // Initialize to an invalid value

    if (i2cReadI2CBlockData(fd, IR_FIFO_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading IR channel data\n");
        return -1;
    }

    ir_value = (buf[0] << 8) | buf[1];
    return ir_value;
}

// Function to process raw sensor data
int process_data(int red_value, int ir_value) {
    // Simple threshold check
    if (ir_value > IR_THRESHOLD) {
        return 1; // IR reading above threshold
    } else {
        return 0; // IR reading below threshold
    }
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to a file
void log_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADPD144RI Red/IR Sensor Reader\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int red_value = read_red_channel(i2c_fd);
        int ir_value = read_ir_channel(i2c_fd);

        if (red_value == -1 || ir_value == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process data
        int processed_red = process_data(red_value, ir_value);

        // Control LED
        control_led(LED_GPIO, processed_red);

        // Log data
        log_data(red_value, ir_value);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

