#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_PIN_1 12
#define SENSOR_PIN_2 13
#define SENSOR_PIN_3 14

// Define constants
#define PULSE_PER_REVOLUTION 1
#define SAMPLE_INTERVAL_MS 1000
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count_1 = 0;
static volatile int pulse_count_2 = 0;
static volatile int pulse_count_3 = 0;
static volatile int running = 1;
static pthread_mutex_t pulse_counter_mutex;

// Function prototypes
void *sensor_isr(void *arg);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm);
void signal_handler(int signal);
int initialize_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    pthread_mutex_destroy(&pulse_counter_mutex);
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);

    // Set pull-down resistor on sensor pins
    gpioSetPullUpDown(SENSOR_PIN_1, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_PIN_2, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_PIN_3, PI_PUD_DOWN);

    // Register ISR for rising edge detection
    if (gpioSetISRFuncEx(SENSOR_PIN_1, RISING_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_PIN_2, RISING_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_PIN_3, RISING_EDGE, 0, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 3\n");
        gpioTerminate();
        return 1;
    }

    // Create mutex
    if (pthread_mutex_init(&pulse_counter_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// ISR function for rising edge detection
void *sensor_isr(void *arg) {
    static volatile int pulse_count = 0;
    pthread_mutex_lock(&pulse_counter_mutex);
    pulse_count += PULSE_PER_REVOLUTION;
    pthread_mutex_unlock(&pulse_counter_mutex);
    return NULL;
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    if (pulse_count == 0) {
        return 0.0;
    }
    return (double)pulse_count * PULSE_PER_REVOLUTION / SAMPLE_INTERVAL_MS;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, rpm);
    fclose(fp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create thread for sensor 1
    pthread_t sensor1_thread;
    if (pthread_create(&sensor1_thread, NULL, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor 1 thread\n");
        gpioTerminate();
        return 1;
    }

    // Create thread for sensor 2
    pthread_t sensor2_thread;
    if (pthread_create(&sensor2_thread, NULL, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor 2 thread\n");
        gpioTerminate();
        pthread_join(sensor1_thread, NULL);
        return 1;
    }

    // Create thread for sensor 3
    pthread_t sensor3_thread;
    if (pthread_create(&sensor3_thread, NULL, sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor 3 thread\n");
        gpioTerminate();
        pthread_join(sensor1_thread, NULL);
        pthread_join(sensor2_thread, NULL);
        return 1;
    }

    // Wait for threads to finish
    pthread_join(sensor1_thread, NULL);
    pthread_join(sensor2_thread, NULL);
    pthread_join(sensor3_thread, NULL);

    return 0;
}

