        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

int main() {
    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int audio_input = read_audio_input();
        if (audio_input < 0) {
            fprintf(stderr, "Error reading audio input, exiting...\n");
            break;
        }

        if (detect_peak(&rising_edges, num_rising_edges)) {
            if (log_peak(num_rising_edges, rising_edges) != 0) {
                fprintf(stderr, "Error logging peak event\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US); // Delay to achieve 10 ms interval
    }

    // Cleanup and exit
    cleanup();
    printf("Audio peak detection stopped.\n");
    return 0;
}

