#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the SLF3S-4000B sensor
#define SLF3S_I2C_ADDR 0x36

// Define the command to start continuous measurement
#define START_MEASUREMENT_CMD 0x3608

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the flow rate threshold (uL/min)
#define FLOW_RATE_THRESHOLD 0.5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
float convert_to_flow_rate(sensor_data_t data);
int log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the SLF3S-4000B sensor
int initialize_sensor() {
    // Send the start measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, START_MEASUREMENT_CMD) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command.\n");
        return -1;
    }
    gpioDelay(10); // Wait for the sensor to be ready

    return 0;
}

// Read 3 bytes of data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[3];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error: Failed to read data from sensor. Bytes read: %d\n", bytes_read);
        return -1;
    }

    // Combine the bytes into a 16-bit signed integer
    data->raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc = buffer[2];

    return 0;
}

// Convert the raw flow value to flow rate in uL/min
float convert_to_flow_rate(sensor_data_t data) {
    return (float)data.raw_flow / 1000.0;
}

// Log the flow rate to a CSV file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Flow rate monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data;

        // Read the sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert the raw flow value to flow rate
            float flow_rate = convert_to_flow_rate(sensor_data);

            // Log the flow rate
            if (log_data(flow_rate) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 1000 milliseconds
        gpioDelay(1000);
    }

    // Close the log file and terminate pigpio
    fclose(log_file);
    gpioTerminate();

    return 0;
}

