#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x70
#define TVOC_REG 0x00
#define eCO2_REG 0x02
#define LOG_FILE "air_quality_log.csv"
#define IAQ_INDEX_THRESHOLD 100.0
#define IAQ_SCALE_FACTOR 10.0
#define IAQ_OFFSET 400.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int tvoc;
    int eco2;
} SensorData;

// Function prototypes
int i2c_read_register(int handle, int reg);
int i2c_write_register(int handle, int reg, int value);
int read_sensor_data(int handle, SensorData *data);
float calculate_iaq(int tvoc, int eco2);
void log_data(float iaq, int tvoc, int eco2);
void signal_handler(int signal);

// Function to read a single byte from the I2C device
int i2c_read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to the I2C device
int i2c_write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the MICS-VZ-89TE
int read_sensor_data(int handle, SensorData *data) {
    int tvoc_reg = TVOC_REG;
    int eco2_reg = eCO2_REG;

    // Read TVOC
    int tvoc_value = i2c_read_register(handle, tvoc_reg);
    if (tvoc_value < 0) {
        fprintf(stderr, "Error reading TVOC register 0x%02X: %d\n", tvoc_reg, tvoc_value);
        return -1;
    }

    // Read eCO2
    int eco2_value = i2c_read_register(handle, eco2_reg);
    if (eco2_value < 0) {
        fprintf(stderr, "Error reading eCO2 register 0x%02X: %d\n", eco2_reg, eco2_value);
        return -1;
    }

    // Clamp values
    data->tvoc = (int)tvoc_value;
    data->eco2 = (int)eco2_value;

    return 0;
}

// Function to calculate the IAQ index
float calculate_iaq(int tvoc, int eco2) {
    float iaq = IAQ_INDEX_THRESHOLD - (float)tvoc / IAQ_SCALE_FACTOR + IAQ_OFFSET;
    if (iaq < 0) iaq = 0;
    if (iaq > IAQ_INDEX_THRESHOLD) iaq = IAQ_INDEX_THRESHOLD;
    return iaq;
}

// Function to log data to a CSV file
void log_data(float iaq, int tvoc, int eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    SensorData sensor_data;
    float iaq;
    int tvoc, eco2;

    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Calculate IAQ index
            iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

            // Log data
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %d, eCO2: %d\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000); // 5 seconds = 5000 milliseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

