#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Configuration
#define I2C_ADDR 0x68
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_SAMPLES (SAMPLE_RATE * 2) // 16-bit samples
#define FILE_NAME "audio_capture.pcm"
#define BUFFER_SIZE (NUM_SAMPLES * 2) // 2 bytes per sample

// Global variables
int i2c_fd;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold I2C register addresses
typedef struct {
    int lpf_control;
    int lpf_data;
    int rpf_control;
    int rpf_data;
} i2c_regs_t;

// Function prototypes
int init_i2c(int addr);
int init_gpio(int pin);
int read_i2c_data(int fd, unsigned char *data, int len);
int convert_i2c_data(unsigned char *data, int len, int16_t *samples);
int write_pcm_data(FILE *fp, int16_t *samples, int num_samples);
void signal_handler(int sig);
int cleanup();

// I2C initialization function
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int init_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0); // Set LPF control pin to LOW initially
    return 0;
}

// I2C data reading function
int read_i2c_data(int fd, unsigned char *data, int len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    // Read LPF control register
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    data[0] = (unsigned char)((fd >> 8) & 0xFF);
    data[1] = (unsigned char)(fd & 0xFF);

    // Read LPF data register
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    data[2] = (unsigned char)((fd >> 8) & 0xFF);
    data[3] = (unsigned char)(fd & 0xFF);

    // Read RPF control register
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    data[4] = (unsigned char)((fd >> 8) & 0xFF);
    data[5] = (unsigned char)(fd & 0xFF);

    // Read RPF data register
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    data[6] = (unsigned char)((fd >> 8) & 0xFF);
    data[7] = (unsigned char)(fd & 0xFF);

    return 0;
}

// I2C data conversion function
int convert_i2c_data(unsigned char *data, int len, int16_t *samples) {
    for (int i = 0; i < len; i++) {
        // Assuming LPF data is 16-bit signed
        samples[i] = (int16_t)((data[i] << 8) | data[i + 1]);
    }
    return 0;
}

// I2C data writing function
int write_pcm_data(FILE *fp, int16_t *samples, int num_samples) {
    if (fwrite(samples, sizeof(int16_t), num_samples, fp) != num_samples) {
        perror("Error writing PCM data to file");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
int cleanup() {
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        return 1;
    }

    // Open file for writing
    fp = fopen(FILE_NAME, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        cleanup();
        return 1;
    }

    // Main loop
    unsigned char data[BUFFER_SIZE];
    int16_t samples[NUM_SAMPLES];
    int num_samples = 0;
    int16_t left_channel_data;
    int16_t right_channel_data;

    while (!terminate) {
        // Read I2C data
        if (read_i2c_data(i2c_fd, data, sizeof(data)) == 0) {
            // Convert I2C data to PCM samples
            if (convert_i2c_data(data, sizeof(data), samples) == 0) {
                // Write PCM data to file
                if (write_pcm_data(fp, samples, NUM_SAMPLES) == 0) {
                    num_samples = NUM_SAMPLES;
                } else {
                    fprintf(stderr, "Error writing PCM data to file\n");
                }
            } else {
                fprintf(stderr, "Error converting I2C data to PCM samples\n");
            }
        } else {
            fprintf(stderr, "Error reading I2C data\n");
        }

        // Delay for the specified sample rate
        gpioDelay(1000000 / SAMPLE_RATE); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

