#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 1000

// Define flame duration threshold (in seconds)
#define FLAME_DURATION_THRESHOLD 2.0

// Define PWM duty cycle range (0-80)
#define PWM_DUTY_CYCLE_RANGE (0.0 * PWM_RANGE / PWM_RANGE) // Ensure 0-1

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int read_fan_state();
void set_fan_state(int state);
void log_event(const char *event);
void cleanup();
void signal_handler(int signal);

// Structure to hold flame state and duration
typedef struct {
    int flame_detected;
    double flame_duration;
} FlameState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM mode for FAN_PIN
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);
    gpioSetPWMclock(PI_PWM_CLOCK_DEFAULT);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read the fan state
int read_fan_state() {
    return gpioRead(FAN_PIN);
}

// Function to set the fan state
void set_fan_state(int state) {
    gpioWrite(FAN_PIN, state);
}

// Function to log events to a file
void log_event(const char *event) {
    FILE *fp = fopen("flame_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

// Function to cleanup GPIO pins and terminate pigpio
void cleanup() {
    gpioTerminate();
    set_fan_state(0); // Turn off the fan
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d. Exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Debounce
        gpioDelay(50); // 50ms delay

        if (flame_detected == 0) {
            // Flame detected
            printf("Flame detected!\n");

            // Read fan state
            int fan_state = read_fan_state();

            // Determine flame duration
            double flame_duration = 0.0;
            if (fan_state == 1) {
                flame_duration = (double)gpioRead(FLAME_SENSOR_PIN) - 1; // Assuming LOW is 0
            }

            // Apply exponential curve
            flame_duration = flame_duration * (1.0 - (flame_duration / FLAME_DURATION_THRESHOLD));

            // Set fan state
            set_fan_state(1); // Turn on the fan

            // Log event
            log_event("Flame detected");

            // Wait for flame duration to elapse
            while (flame_duration > 0.0) {
                gpioDelay(1); // Small delay to prevent busy-waiting
                flame_duration -= 1.0; // Decrease flame duration
            }

            // Turn off the fan
            set_fan_state(0); // Turn off the fan

            // Log event
            log_event("Flame ended");
        } else {
            // No flame detected
            set_fan_state(0); // Turn off the fan
        }

        // Wait for 50ms
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

