#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000 // 1 MHz
#define GPIO_TRIGGER_PIN 23
#define GPIO_DATA_READY_PIN 24
#define LOG_FILE_NAME "radar_log.bin"
#define FRAME_PERIOD_MS 100
#define CHIRPS 64
#define SAMPLES 256
#define CONFIG_STRUCT_SIZE (CHIRPS * SAMPLES * 2) // 2 bytes per sample (complex 16-bit)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure for configuration
typedef struct {
    int start_frequency;
    int end_frequency;
    int chirps;
    int samples;
    int frame_period_ms;
} radar_config_t;

// Function prototypes
int spi_init(int channel, int frequency, int mode);
int spi_transfer(int handle, char *tx_buf, char *rx_buf, int len);
int log_frame(int frame_number, int chirp_index, int start_frequency, int end_frequency, int samples, int frame_period_ms);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init(int channel, int frequency, int mode) {
    spi_handle = spiOpen(channel, frequency, mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, spi_handle);
        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int handle, char *tx_buf, char *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }
    return 0;
}

// Logging function
int log_frame(int frame_number, int chirp_index, int start_frequency, int end_frequency, int samples, int frame_period_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, frame_number, chirp_index, start_frequency, end_frequency, samples, frame_period_ms);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO for trigger pin
    gpioSetMode(GPIO_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_CHANNEL, SPI_FREQUENCY, SPI_MODE) != 0) {
        fprintf(stderr, "SPI initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int frame_number = 0;
    int chirp_index = 0;
    int start_frequency = 0;
    int end_frequency = 0;
    int samples = 0;
    int frame_period_ms = FRAME_PERIOD_MS;

    while (program_running) {
        // Request frame
        gpioWrite(GPIO_TRIGGER_PIN, 1);
        gpioDelay(10); // 10ms trigger delay
        gpioWrite(GPIO_TRIGGER_PIN, 0);

        // Read frame data
        char tx_buf[CHIRPS * SAMPLES * 2];
        char rx_buf[CHIRPS * SAMPLES * 2];
        int bytes_read = spi_transfer(spi_handle, tx_buf, rx_buf, CHIRPS * SAMPLES * 2);
        if (bytes_read != CHIRPS * SAMPLES * 2) {
            fprintf(stderr, "Error reading frame data, bytes read: %d\n", bytes_read);
            continue; // Skip to the next iteration
        }

        // Log frame
        log_frame(frame_number, chirp_index, start_frequency, end_frequency, samples, frame_period_ms);

        // Increment frame number and chirp index
        frame_number++;
        chirp_index = (chirp_index + 1) % CHIRPS;
        start_frequency = end_frequency;
        end_frequency = (end_frequency + 1) % (end_frequency + 1);
        samples = 0;
        frame_period_ms = FRAME_PERIOD_MS;

        // Delay
        gpioDelay(frame_period_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

