        }

        // Log frame
        log_frame(frame_number, chirp_index, start_frequency, end_frequency, samples, frame_period_ms);

        // Increment frame number and chirp index
        frame_number++;
        chirp_index = (chirp_index + 1) % CHIRPS;
        start_frequency = end_frequency;
        end_frequency = (end_frequency + 1) % (end_frequency + 1);
        samples = 0;
        frame_period_ms = FRAME_PERIOD_MS;

        // Delay
        gpioDelay(frame_period_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
