#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x00
#define CONVERSION_REG 0x01
#define CONVERSION_START 0x02
#define CONVERSION_DONE 0x03
#define DATA_REG 0x04
#define DATA_LENGTH 2
#define LUX_SCALE_FACTOR 0.01
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int i2c_bus;
    int i2c_handle;
    int config_reg;
    int conversion_reg;
    int conversion_start;
    int conversion_done;
    int data_reg;
    int data_length;
    int data_start;
    int data_done;
    int data_reg_value;
} sensor_config_t;

// Function prototypes
int init_sensor(sensor_config_t *config);
int read_sensor_data(sensor_config_t *config, unsigned int *data);
int process_sensor_data(unsigned int raw_data, int exponent, int mantissa, float *lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Function to initialize the OPT3001 sensor
int init_sensor(sensor_config_t *config) {
    config->i2c_address = OPT3001_ADDR;
    config->i2c_bus = 1; // I2C bus 1
    config->i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (config->i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", config->i2c_handle);
        return -1;
    }

    // Configure the sensor (continuous conversion mode, 100ms conversion time)
    if (i2cWriteByteData(config->i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Start conversion
    if (i2cWriteByteData(config->i2c_handle, CONVERSION_REG, 0x00) < 0) {
        fprintf(stderr, "Error starting conversion\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_config_t *config, unsigned int *data) {
    int result = i2cReadI2CBlockData(config->i2c_handle, DATA_REG, (char *)data, DATA_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process sensor data
int process_sensor_data(unsigned int raw_data, int exponent, int mantissa, float *lux) {
    // Extract exponent and mantissa from raw data
    unsigned int exponent_raw = (raw_data >> 12) & 0x0F;
    unsigned int mantissa_raw = raw_data & 0x0FFF;

    // Check for invalid data (e.g., exponent out of range)
    if (exponent_raw < 0 || exponent_raw > 15) {
        fprintf(stderr, "Invalid exponent value: %d\n", exponent_raw);
        return -1;
    }

    // Scale the exponent and mantissa
    *lux = (float)exponent_raw * LUX_SCALE_FACTOR;

    // Check for overflow/underflow
    if (exponent_raw & 0x8000) {
        fprintf(stderr, "Exponent overflow\n");
        return -1;
    }
    if (exponent_raw & 0x4000) {
        fprintf(stderr, "Exponent underflow\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    sensor_config_t sensor_config = {
        .i2c_address = OPT3001_ADDR,
        .i2c_bus = 1,
        .i2c_handle = -1,
        .config_reg = CONFIG_REG,
        .conversion_reg = CONVERSION_REG,
        .conversion_start = CONVERSION_START,
        .conversion_done = CONVERSION_DONE,
        .data_reg = DATA_REG,
        .data_length = DATA_LENGTH,
        .data_start = DATA_START,
        .data_done = DATA_DONE,
        .data_reg_value = 0,
    };

    // Initialize the sensor
    if (init_sensor(&sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    unsigned int raw_data;
    float lux;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_config, &raw_data) == 0) {
            // Process sensor data
            if (process_sensor_data(raw_data, 0, 0, &lux) == 0) {
                // Log data
                log_data(lux);
            } else {
                fprintf(stderr, "Error processing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

