#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define LEFT_GPIO 17
#define CENTER_GPIO 18
#define RIGHT_GPIO 27

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int left_value, center_value, right_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_GPIO, PI_INPUT);
    gpioSetMode(CENTER_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_GPIO, PI_INPUT);

    printf("Tracing sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        left_value = gpioRead(LEFT_GPIO);
        center_value = gpioRead(CENTER_GPIO);
        right_value = gpioRead(RIGHT_GPIO);

        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        usleep(50000); // 50ms delay
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

