#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensors
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 4
#define GPIO_PIN_4 5
#define GPIO_PIN_5 6
#define GPIO_PIN_6 7
#define GPIO_PIN_7 8
#define GPIO_PIN_8 9

// Define the number of channels
#define NUM_CHANNELS 8

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track the last touched state
int last_touched_state[NUM_CHANNELS] = {0, 0, 0, 0, 0, 0, 0, 0};

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(GPIO_PIN_1 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_1 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_2 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_2 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_3 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_3 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_4 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_4 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_5 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_5 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_6 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_6 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_7 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_7 + i, PI_PUD_DOWN);
        gpioSetMode(GPIO_PIN_8 + i, PI_INPUT);
        gpioSetPullUpDown(GPIO_PIN_8 + i, PI_PUD_DOWN);
    }

    return 0; // Indicate success
}

// Function to read the state of a single channel
int read_channel(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to validate the state of a channel
int validate_state(int state, int gpio_pin) {
    return (state == 0) ? 1 : 0; // Assuming 0 means touched
}

// Function to log the state of a channel
void log_state(int channel_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] CH%d=%d\n", timestamp, channel_number, state);
}

// Function to read the state of all channels
void read_all_channels() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int state = read_channel(GPIO_PIN_1 + i);
        if (validate_state(state, GPIO_PIN_1 + i)) {
            log_state(i, state);
        }
    }
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        read_all_channels();
        gpioDelay(DEBOUNCE_DELAY); // Debounce delay
    }

    return 0;
}

