#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_state(int sensor_number);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor state
void log_sensor_state(int sensor_number) {
    printf("Sensor %d: %s\n", sensor_number, (sensor_number == 1) ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-up/down resistors (optional, but good practice)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log sensor states
        log_sensor_state(sensor1_value);
        log_sensor_state(sensor2_value);

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

