#define SENSOR_2_PIN 3
#define SENSOR_3_PIN 4
#define SENSOR_4_PIN 17
#define SENSOR_5_PIN 27
#define SENSOR_6_PIN 22
#define SENSOR_7_PIN 10
#define SENSOR_8_PIN 9

// Define the number of channels
#define NUM_CHANNELS 8

// Define the polling interval in milliseconds
#define POLL_INTERVAL_MS 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to request a GPIO line
int request_gpio_line(int pin) {
    int line = gpioSetMode(pin, PI_INPUT);
    if (line < 0) {
        fprintf(stderr, "Error setting GPIO %d as input: %d\n", pin, line);
        return -1;
    }
    return 0;
}

// Function to request a GPIO line with bias disabled
int request_gpio_line_with_bias(int pin) {
    int line = gpioSetMode(pin, PI_INPUT);
    if (line < 0) {
        fprintf(stderr, "Error setting GPIO %d as input with bias disabled: %d\n", pin, line);
        return -1;
    }
    return 0;
}

// Function to read the state of a single sensor channel
int read_sensor_channel(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pin, value);
        return -1;
    }
    return value;
}

// Function to log the state of a single sensor channel
void log_sensor_state(int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Sensor %d: %s\n", timestamp, pin, (state == 1) ? "HIGH" : "LOW");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Request the GPIO lines
    if (request_gpio_line(SENSOR_1_PIN) < 0 ||
        request_gpio_line(SENSOR_2_PIN) < 0 ||
        request_gpio_line(SENSOR_3_PIN) < 0 ||
        request_gpio_line(SENSOR_4_PIN) < 0 ||
        request_gpio_line(SENSOR_5_PIN) < 0 ||
        request_gpio_line(SENSOR_6_PIN) < 0 ||
        request_gpio_line(SENSOR_7_PIN) < 0 ||
        request_gpio_line(SENSOR_8_PIN) < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll all 8 channels
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int channel_pin = (SENSOR_1_PIN + i) % NUM_CHANNELS;
            int state = read_sensor_channel(channel_pin);
            if (state < 0) {
                fprintf(stderr, "Error reading sensor channel %d\n", channel_pin);
                continue; // Skip to the next channel
            }
            log_sensor_state(channel_pin, state);
        }

        // Wait for the next poll
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    return 0;
}

