#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TILT_PIN 4
#define DEBOUNCE_DELAY_MS 50

static volatile int keepRunning = 1;

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    keepRunning = 0;
    printf("\nExiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* getTimestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message with a timestamp
void logMessage(const char *message) {
    char *timestamp = getTimestamp();
    printf("%s: %s\n", timestamp, message);
    free(timestamp);
}

// Function to read the tilt sensor
int readTiltSensor() {
    return gpioRead(TILT_PIN);
}

// Function to handle tilt state changes
void handleTiltStateChange(int newState) {
    if (newState == 0) {
        logMessage("Tilted");
    } else {
        logMessage("Not Tilted");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input
    gpioSetMode(TILT_PIN, PI_INPUT);

    // Set pull-up resistor (optional, but recommended)
    gpioSetPullUpDown(TILT_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        int currentState = readTiltSensor();

        // Debounce the sensor reading
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

        if (readTiltSensor() == currentState) {
            handleTiltStateChange(currentState);
        }
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

