#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define HW_KEY 0x17
#define CHLIST 0x01
#define ALS_FORCE 0x06
#define UV_INDEX_REG 0x2A
#define UV_VIS_REG 0x2B
#define CSV_FILE "uv_als_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_si1145();
int read_si1145_data(int *uv_index, int *als_visible);
void log_data(int uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int initialize_si1145() {
    int status;

    // Verify PART ID
    status = i2cWriteByteData(i2c_handle, 0x00, 0x45); // Verify PART ID
    if (status < 0) {
        fprintf(stderr, "Error: Could not write to PART ID register (0x00)\n");
        return -1;
    }
    gpioDelay(10); // Small delay after writing to PART ID register

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, HW_KEY, HW_KEY);
    if (status < 0) {
        fprintf(stderr, "Error: Could not write to HW_KEY register (0x17)\n");
        return -1;
    }
    gpioDelay(10);

    // Configure CHLIST
    status = i2cWriteByteData(i2c_handle, CHLIST, 0x01); // Enable UV and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error: Could not write to CHLIST register (0x01)\n");
        return -1;
    }
    gpioDelay(10);

    // Trigger ALS FORCE command
    status = i2cWriteByteData(i2c_handle, ALS_FORCE, 0x06);
    if (status < 0) {
        fprintf(stderr, "Error: Could not write to ALS_FORCE register (0x06)\n");
        return -1;
    }
    gpioDelay(10);

    return 0;
}

// Read UV Index and Visible ALS data from the sensor
int read_si1145_data(int *uv_index, int *als_visible) {
    int status;
    unsigned char data[2];

    // Read UV Index
    status = i2cReadI2CBlockData(i2c_handle, UV_INDEX_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read UV Index data (0x%02X)\n", data[0]);
        return -1;
    }
    *uv_index = (data[0] << 8) | data[1];

    // Read Visible ALS data
    status = i2cReadI2CBlockData(i2c_handle, UV_VIS_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read Visible ALS data (0x%02X)\n", data[0]);
        return -1;
    }
    *als_visible = (data[0] << 8) | data[1];

    return 0;
}

// Log data to CSV file
void log_data(int uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int uv_index, als_visible;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (0x%02X)\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (initialize_si1145() < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV_Index,ALS_Visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&uv_index, &als_visible) == 0) {
            // Log data
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

