#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

// Define circular buffer size
#define BUFFER_SIZE 100

// Define sensor thresholds
#define OBSTACLE_THRESHOLD_1 500
#define OBSTACLE_THRESHOLD_2 700
#define OBSTACLE_THRESHOLD_3 900

// Global variables
static volatile int sensor_states[BUFFER_SIZE] = {0};
static volatile int sensor_readings[BUFFER_SIZE] = {0};
static volatile int buffer_index = 0;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void add_reading(int gpio_pin, int reading);
void print_buffer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_3_PIN, PI_PUD_UP);

    return 0;
}

// Read the sensor value from the specified GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Add a reading to the circular buffer
void add_reading(int gpio_pin, int reading) {
    sensor_states[buffer_index] = reading;
    sensor_readings[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("Circular Buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_states[i] != 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] Sensor %d: %d\n", timestamp, gpio_pin, sensor_states[i]);
        }
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        int sensor1_reading = read_sensor(SENSOR_1_PIN);
        int sensor2_reading = read_sensor(SENSOR_2_PIN);
        int sensor3_reading = read_sensor(SENSOR_3_PIN);

        // Check for obstacle detection
        if (sensor1_reading == 0 && sensor2_reading == 0 && sensor3_reading == 0) {
            // Obstacle detected
            printf("Obstacle detected!\n");
            add_reading(SENSOR_1_PIN, sensor1_reading);
            add_reading(SENSOR_2_PIN, sensor2_reading);
            add_reading(SENSOR_3_PIN, sensor3_reading);
            print_buffer();
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

