#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Define obstacle detection threshold (in cm)
#define OBSTACLE_THRESHOLD 10

// Global variable to track LED state
int led_state = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for sensors (optional, depends on sensor wiring)
    // gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    // gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for obstacle detection
        if (sensor1_value == 0 && sensor2_value == 0) {
            // Obstacle detected
            control_led(1); // Turn LED ON
            gpioDelay(100);   // Wait 100ms
            control_led(0); // Turn LED OFF
        } else {
            // No obstacle detected
            control_led(0); // Turn LED OFF
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(100);
    }

    return 0;
}

