#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int check_stall(int sensor1_value, int sensor2_value);
int log_stall(int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to check for stall
int check_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log the stall event
int log_stall(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (log_file != stdout) {
        fprintf(log_file, "%s - Stall detected by sensor 1: %d, sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not stdout.\n");
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("Stall detected!\n");
            if (check_stall(sensor1_value, sensor2_value)) {
                if (log_stall(sensor1_value, sensor2_value) != 0) {
                    fprintf(stderr, "Error logging stall event.\n");
                }
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

