    gpioDelay(60);
    gpioWrite(SENSOR_GPIO, 1); // Set GPIO high
    gpioDelay(60);
    gpioWrite(SENSOR_GPIO, 0); // Ensure GPIO is low
    gpioDelay(60);
    log_alert("GPIO re-initialization complete.");
}

