    exit(0);
}

// Function to read the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the RPM to a file
void log_rpm(char *timestamp, int rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s RPM: %d\n", timestamp, rpm);
    fclose(fp);
}

// Function to calculate RPM from pulse count
float calculate_rpm(unsigned int pulse_count) {
    if (pulse_count == 0) {
        return 0.0;
    }
    return (float)pulse_count * 60.0 / SAMPLE_INTERVAL_SEC;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    if (level == RISING_EDGE) {
        unsigned int current_time = gpioTick();
        if (current_time - last_pulse_time > SAMPLE_INTERVAL_SEC * 1000) { // Convert seconds to microseconds
            pulse_count++;
            last_pulse_time = current_time;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(SENSOR_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char timestamp[20];
    float rpm;

    // Main loop
    while (1) {
        get_timestamp(timestamp);
        rpm = calculate_rpm(pulse_count);

        if (rpm > 0) {
            log_rpm(timestamp, rpm);
            printf("[%s] RPM: %.2f\n", timestamp, rpm);
        } else {
            fprintf(stderr, "Sensor absent or not rotating, RPM: 0\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    return 0;
}

