#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int open_chip(const char *chip_name);
int open_line(struct gpiod_chip *chip, const char *line_name);
int write_value(struct gpiod_line *line, int value);
int read_value(struct gpiod_line *line);
int is_touched(int line);
void log_event(const char *message);
void cleanup_gpio();
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received SIGINT or SIGTERM, shutting down...");
        program_running = 0;
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpiod_chip_create(&chip, "touch_sensor_chip") < 0) {
        fprintf(stderr, "Error: Failed to create chip\n");
        return -1;
    }

    if (gpiod_chip_add_line(chip, "touch_sensor", TOUCH_SENSOR_PIN,
                              GPIOD_LINE_INPUT, 0) < 0) {
        fprintf(stderr, "Error: Failed to add line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_chip_add_line(chip, "led", LED_PIN,
                              GPIOD_LINE_OUTPUT, 0) < 0) {
        fprintf(stderr, "Error: Failed to add line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    touch_line = gpiod_chip_get_line(chip, "touch_sensor");
    led_line = gpiod_chip_get_line(chip, "led");

    if (!touch_line || !led_line) {
        fprintf(stderr, "Error: Failed to get lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to open a GPIO line
int open_line(struct gpiod_chip *chip, const char *line_name) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        fprintf(stderr, "Error: Failed to get line\n");
        return -1;
    }

    if (gpiod_line_request(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to request line\n");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to write a value to a GPIO line
int write_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Failed to set value\n");
        return -1;
    }
    return 0;
}

// Function to read a value from a GPIO line
int read_value(struct gpiod_line *line) {
    return gpiod_line_get_value(line);
}

// Function to determine if the sensor is touched
int is_touched(int line) {
    return gpiod_line_get_value(line) == 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Initialize syslog
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_value(touch_line);

        // Check if sensor is touched
        if (is_touched(sensor_value)) {
            // Turn on LED
            if (write_value(led_line, 1) < 0) {
                fprintf(stderr, "Error: Failed to turn on LED\n");
            }
            log_event("Touch detected!");
        } else {
            // Turn off LED
            if (write_value(led_line, 0) < 0) {
                fprintf(stderr, "Error: Failed to turn off LED\n");
            }
        }

        // Delay for 50 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

