#define DEBOUNCE_TIME_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_chip_error());
        return -1;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", TOUCH_SENSOR_PIN, gpiod_line_error());
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO line as input
    if (gpiod_line_request_input(line, "touch_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting input on line %d: %s\n", TOUCH_SENSOR_PIN, gpiod_line_error());
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO line as output
    if (gpiod_line_request_output(line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting output on line %d: %s\n", TOUCH_SENSOR_PIN, gpiod_line_error());
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

