        fprintf(stderr, "Error setting pull-down resistor on line %d: %s\n", TOUCH_SENSOR_PIN, gpiod_line_error());
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

