        return 1;
    }

    printf("Touch sensor and LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            toggle_led();
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t now = tv.tv_sec;
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", tv.tv_usec);

        printf("[%s] Touch detected on line %d\n", timestamp, TOUCH_SENSOR_PIN);
        usleep(DEBOUNCE_TIME_MS * 1000); // Debounce
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

