#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static volatile int *log_buffer = NULL;
static int log_buffer_size = 0;
static int overflow_counter = 0;
static volatile int running = 1;

// Function prototypes
void cleanup();
void signal_handler(int signal);
int read_sensor(int gpio_pin);
void write_led(int gpio_pin, int state);
void log_event(int sensor_pin, int state);
void circular_buffer_push(int sensor_pin, int state);
int circular_buffer_pop(int *buffer, int *size);

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to write LED state
void write_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log event to circular buffer
void log_event(int sensor_pin, int state) {
    if (log_buffer == NULL) {
        log_buffer = (int *)malloc(BUFFER_SIZE * sizeof(int));
        if (log_buffer == NULL) {
            perror("Failed to allocate memory for circular buffer");
            return;
        }
        log_buffer_size = BUFFER_SIZE;
    }

    circular_buffer_push(sensor_pin, state);
    if (overflow_counter < log_buffer_size) {
        log_buffer[overflow_counter] = sensor_pin;
        overflow_counter++;
    } else {
        log_buffer[0] = sensor_pin;
        log_buffer_size = 1;
    }
}

// Function to push event to circular buffer
int circular_buffer_push(int sensor_pin, int state) {
    if (log_buffer == NULL) {
        log_buffer = (int *)malloc(BUFFER_SIZE * sizeof(int));
        if (log_buffer == NULL) {
            perror("Failed to allocate memory for circular buffer");
            return -1;
        }
        log_buffer_size = BUFFER_SIZE;
    }

    if (log_buffer_size == BUFFER_SIZE) {
        log_buffer[0] = sensor_pin;
        log_buffer_size = 1;
    } else {
        log_buffer[log_buffer_size] = sensor_pin;
        log_buffer_size++;
    }
    return 0;
}

// Function to pop event from circular buffer
int circular_buffer_pop(int *buffer, int *size) {
    if (*size == 0) {
        return -1; // Buffer is empty
    }

    *size--;
    *buffer[(*size)] = 0; // Assuming 0 indicates end of buffer
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (log_buffer != NULL) {
        free(log_buffer);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Initialize circular buffer
    log_buffer = (int *)malloc(BUFFER_SIZE * sizeof(int));
    if (log_buffer == NULL) {
        perror("Failed to allocate memory for circular buffer");
        gpioTerminate();
        return 1;
    }
    log_buffer_size = BUFFER_SIZE;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        // Check for debounce
        if (sensor1_state == 1 && sensor2_state == 1) {
            // Debounce
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds

            // Check sensor states again
            sensor1_state = read_sensor(SENSOR_1_PIN);
            sensor2_state = read_sensor(SENSOR_2_PIN);

            if (sensor1_state == 1 && sensor2_state == 1) {
                // Both sensors are touched simultaneously
                write_led(LED_1_PIN, 1);
                write_led(LED_2_PIN, 1);
                log_event(SENSOR_1_PIN, 1);
                log_event(SENSOR_2_PIN, 1);
                gpioDelay(500 * 1000); // Wait for 500ms
                write_led(LED_1_PIN, 0);
                write_led(LED_2_PIN, 0);
                log_event(SENSOR_1_PIN, 0);
                log_event(SENSOR_2_PIN, 0);
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

