#include <unistd.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 5

// Define the RPM calculation parameters
#define PULSES_PER_REVOLUTION 2
#define PULSES_PER_REVOLUTION_PER_SECOND (PULSES_PER_REVOLUTION * 60)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
double calculate_rpm(int pulses);
void log_data(double rpm);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0;
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to calculate the RPM
double calculate_rpm(int pulses) {
    return (double)pulses / PULSES_PER_REVOLUTION;
}

// Function to log the data to a CSV file
void log_data(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, rpm, read_sensor(SENSOR1_PIN));
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor states
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Debounce the sensor states
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

        if (sensor1_state == 1) {
            sensor1_state = 0; // Reset the state if it's still high after debounce
        } else {
            sensor1_state = -1; // Reset the state if it's still low after debounce
        }

        if (sensor2_state == 1) {
            sensor2_state = 0; // Reset the state if it's still high after debounce
        } else {
            sensor2_state = -1; // Reset the state if it's still low after debounce
        }

        // Calculate the RPM
        double rpm = calculate_rpm(sensor1_state + sensor2_state);

        // Log the data
        log_data(rpm);

        // Print the RPM to the console
        printf("RPM: %.2f\n", rpm);

        // Wait for a short period
        gpioDelay(1000); // Delay for 1 second
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

