#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_si1182_data(int *heart_rate, int *spo2);
void log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from Si1182 sensor
int read_si1182_data(int *heart_rate, int *spo2) {
    char buf[2];
    int result;

    // Read heart rate data
    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read heart rate data: %d\n", result);
        return -1;
    }
    *heart_rate = (buf[0] << 8) | buf[1];

    // Read SpO2 data
    result = i2cReadI2CBlockData(i2c_handle, SPO2_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read SpO2 data: %d\n", result);
        return -1;
    }
    *spo2 = (buf[0] << 8) | buf[1];

    return 0;
}

// Log data to file
void log_data(int heart_rate, int spo2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", s, heart_rate, spo2);
    fclose(fp);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Si1182 sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int heart_rate, spo2;

        // Read sensor data
        if (read_si1182_data(&heart_rate, &spo2) == 0) {
            // Log the data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

