// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (seconds)
#define ALARM_DURATION 2

// Define tilt threshold (degrees)
#define TILT_THRESHOLD 45.0

// Define buzzer duration (seconds)
#define BUZZER_DURATION 1

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(const char *event_type, const char *timestamp);
void activate_alarm(int gpio_pin, int duration_seconds);
void deactivate_alarm(int gpio_pin);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events to a file
void log_event(const char *event_type, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to activate the alarm
void activate_alarm(int gpio_pin, int duration_seconds) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    gpioDelay(duration_seconds * 1000); // Delay for duration_seconds
    deactivate_alarm(gpio_pin);
}

// Function to deactivate the alarm
void deactivate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for tilt events
        if (sensor1_value == 1) {
            log_event("Tilt Start", time(NULL));
            activate_alarm(ALARM_PIN, ALARM_DURATION);
            gpioDelay(1000); // Debounce delay
            if (read_sensor(SENSOR1_PIN) == 1) {
                log_event("Tilt End", time(NULL));
                deactivate_alarm(ALARM_PIN);
            }
        }
        if (sensor2_value == 1) {
            log_event("Tilt Start", time(NULL));
            activate_alarm(ALARM_PIN, ALARM_DURATION);
            gpioDelay(1000); // Debounce delay
            if (read_sensor(SENSOR2_PIN) == 1) {
                log_event("Tilt End", time(NULL));
                deactivate_alarm(ALARM_PIN);
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    deactivate_alarm(ALARM_PIN);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

