#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses and thresholds
#define SENSOR1_ADDR 0x1D
#define SENSOR2_ADDR 0x1E
#define SENSOR3_ADDR 0x1F
#define THRESHOLD1 500
#define THRESHOLD2 500
#define THRESHOLD3 500
#define LED_GPIO 17

// I2C bus and handle
int i2c_bus = 1;
int i2c_handle1 = -1;
int i2c_handle2 = -1;
int i2c_handle3 = -1;

// Function prototypes
int read_sensor(int i2c_handle, int address);
int read_acceleration(int i2c_handle, int address);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(int sensor_id, float magnitude);
void control_led(int gpio, int state);
void signal_handler(int signal);

// Global variables
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, int address) {
    char buf[6];
    int result;

    // Read 6 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the bytes into a 16-bit integer
    int16_t raw_data = (buf[0] << 8) | buf[1];

    // Convert to little-endian format
