#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_1 2
#define FLAME_SENSOR_2 3
#define FLAME_SENSOR_3 4
#define FLAME_SENSOR_4 17
#define FLAME_SENSOR_5 27

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Define log file path
#define LOG_FILE "/var/log/flame_events.log"

// Global variables
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int line;
    int last_state;
    int current_state;
    int line_pointer;
} sensor_data_t;

// Array of sensor data
sensor_data_t sensor_data[5];

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int detect_flame(int gpio_pin);
void log_event(int sensor_id, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as input
    for (int i = 0; i < 5; i++) {
        gpioSetMode(sensor_data[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(sensor_data[i].gpio_pin, PI_PUD_DOWN); // Enable pull-down resistor
    }

    return 0;
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    return current_state;
}

// Function to detect flame
int detect_flame(int gpio_pin) {
    int current_state = read_sensor(gpio_pin);
    return (current_state == 1) ? 1 : 0; // Flame detected if HIGH
}

// Function to log event
void log_event(int sensor_id, int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, sensor_id, gpio_pin);
}

// Function to clean up GPIO
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO...");
    gpioTerminate();
    closelog();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        return 1;
    }

    // Initialize sensor data
    for (int i = 0; i < 5; i++) {
        sensor_data[i].gpio_pin = FLAME_SENSOR_1 + i;
        sensor_data[i].line = i;
        sensor_data[i].last_state = 0;
        sensor_data[i].current_state = 0;
        sensor_data[i].line_pointer = i;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int current_state = read_sensor(sensor_data[i].gpio_pin);
            if (current_state == 1) {
                // Flame detected
                if (detect_flame(sensor_data[i].gpio_pin) == 1) {
                    // Flame detected on sensor 1
                    log_event(1, sensor_data[i].gpio_pin);
                    // Debounce
                    gpioDelay(DEBOUNCE_DELAY);
                    current_state = read_sensor(sensor_data[i].gpio_pin);
                    if (current_state == 1) {
                        // Flame detected again
                        log_event(1, sensor_data[i].gpio_pin);
                    }
                }
            } else {
                // No flame detected
                if (detect_flame(sensor_data[i].gpio_pin) == 0) {
                    // No flame detected on sensor 1
                    log_event(1, sensor_data[i].gpio_pin);
                }
            }
        }
        gpioDelay(1000); // Check every 1 second
    }

    // Clean up and exit
    cleanup();
    return 0;
}

