#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define ALS_CONFIG_REG 0x00
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_word(int handle, int reg);
int i2c_write_word(int handle, int reg, int value);
int veml7700_init(int handle);
int veml7700_read_als(int handle, int *raw);
float convert_lux(int raw_value);
int control_led(int brightness);
int log_data(float lux, int brightness);
void signal_handler(int signal);

// Function to read a 16-bit value from I2C
int i2c_read_word(int handle, int reg) {
    int low = i2cReadByteData(handle, reg);
    int high = i2cReadByteData(handle, reg + 1);
    if (low < 0 || high < 0) {
        fprintf(stderr, "Error reading word from I2C register 0x%02X\n", reg);
        return -1;
    }
    return (high << 8) | low;
}

// Function to write a 16-bit value to I2C
int i2c_write_word(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the VEML7700 sensor
int veml7700_init(int handle) {
    // Configure ALS gain (0x00)
    if (i2c_write_word(handle, ALS_REG, 0x00) < 0) {
        fprintf(stderr, "Error configuring ALS gain\n");
        return -1;
    }

    // Configure ALS integration time (0x00)
    if (i2c_write_word(handle, ALS_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error configuring ALS integration time\n");
        return -1;
    }

    return 0;
}

// Function to read the ALS register
int veml7700_read_als(int handle, int *raw) {
    *raw = i2c_read_word(handle, ALS_REG);
    if (*raw < 0) {
        fprintf(stderr, "Error reading ALS register\n");
        return -1;
    }
    return 0;
}

// Function to convert raw ALS value to lux
float convert_lux(int raw_value) {
    return (float)raw_value * 0.0576;
}

// Function to control the LED brightness
int control_led(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    gpioPWM(PWM_GPIO, brightness);
    return 0;
}

// Function to log data to a file
int log_data(float lux, int brightness) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d\n", timestamp, lux, brightness);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (veml7700_init(i2c_handle) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, 100);

    // Set PWM mode (normal)
    gpioSetPWMmode(PWM_GPIO, PI_PWM_MODE_NORMAL);

    // Set PWM range (0-100)
    gpioSetPWMrange(PWM_GPIO, 100);

    // Set PWM duty cycle (0-100)
    gpioPWM(PWM_GPIO, 0); // Initially turn off the LED

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int raw_als;
        float lux;
        int brightness;

        // Read ALS register
        if (veml7700_read_als(i2c_handle, &raw_als) < 0) {
            fprintf(stderr, "Error reading ALS register, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert raw value to lux
        lux = convert_lux(raw_als);

        // Control LED brightness
        control_led(brightness);

        // Log data
        log_data(lux, brightness);

        // Print data to console
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

