#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONVERSION_TIME_MS 100
#define SLEEP_DURATION_MS 100
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_result();
float convert_to_lux(int exponent, int mantissa);
void log_data(float lux);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int range;
    int resolution;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    // Configure for continuous conversion mode
    char config_data[2] = {0x00, 0x00}; // Example configuration word
    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }
    return 0;
}

// Function to read the result register
int read_result() {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, RESULT_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading result register\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to convert the raw data to lux
float convert_to_lux(int exponent, int mantissa) {
    float lux = (float)mantissa * 0.01 * (1 << exponent);
    return lux;
}

// Function to log data to a file
void log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read result
        int result = read_result();
        if (result < 0) {
            fprintf(stderr, "Error reading result, retrying...\n");
            gpioDelay(SLEEP_DURATION_MS * 1000); // Wait before retrying
            continue;
        }

        // Convert to lux
        float lux = convert_to_lux(result >> 8, result & 0xFF);

        // Log data
        log_data(lux);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

