#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define ALERT_DURATION_SEC 1

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor();
void log_event(int sensor_value);
void trigger_alert();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read the flame sensor
int read_flame_sensor() {
    int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to log events to a file
void log_event(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor Value: %d\n", timestamp, sensor_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to trigger an alert
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(ALERT_DURATION_SEC * 1000000); // Delay for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Error reading flame sensor, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        log_event(sensor_value);

        if (sensor_value == 0) { // Flame detected
            printf("Flame detected! Triggering alert.\n");
            trigger_alert();
        }

        gpioDelay(500000); // Wait 0.5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

