void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read the flame sensor
int read_flame_sensor() {
    int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

