// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_PIN);
}

// Function to log the touch event to the file
int log_touch_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return 1;
