        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to debounce the touch sensor
void debounce_touch_sensor() {
    int current_state = read_touch_sensor();
    int last_state = current_state;

    if (current_state == 1) {
        if (current_state != last_state) {
            log_touch_event(time(NULL));
            last_state = current_state;
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay
        }
    }
}

