        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        debounce_touch_sensor();
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

