#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define FLOW_COMMAND 0x3608
#define FLOW_READ_DELAY_MS 2
#define FLOW_READ_MIN_MS 10
#define FLOW_READ_MAX_MS 50
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    int16_t crc;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(int16_t raw_flow, int crc);
float convert_to_flow_rate(sensor_data_t data);
void log_data(float flow_rate, int status);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int bytes_read;
    int i;

    // Send command to start continuous measurement
    if (i2cWriteByte(i2c_handle, FLOW_COMMAND) != 0) {
        fprintf(stderr, "Error writing command to I2C\n");
        return -1;
    }

    // Wait for at least 2 ms
    gpioDelay(FLOW_READ_DELAY_MS * 1000);

    // Read 6 bytes of data
    bytes_read = i2cReadDevice(i2c_handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    // Validate CRC
    if (!validate_crc(buf[0], buf[1])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw flow value and status
    data->raw_flow = (buf[0] << 8) | buf[1];
    data->crc = buf[2];
    data->status = buf[3];

    return 0;
}

// Validate CRC
int validate_crc(int16_t raw_flow, int crc) {
    int checksum = 0;
    for (int i = 0; i < 2; i++) {
        checksum += (raw_flow >> (8 * i)) & 0xFF;
    }
    return (checksum == crc);
}

// Convert raw flow to ml/min
float convert_to_flow_rate(sensor_data_t data) {
    return (float)data.raw_flow / 90.0;
}

// Log data to file
void log_data(float flow_rate, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        if (read_sensor_data(&sensor_data) == 0) {
            float flow_rate = convert_to_flow_rate(sensor_data);
            int status = sensor_data.status;

            log_data(flow_rate, status);
            printf("Flow Rate: %.2f ml/min, Status: %d\n", flow_rate, status);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

