#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define MIDDLE_SENSOR 27
#define RIGHT_SENSOR 22

// Define the path to the log file
#define LOG_FILE "path_log.csv"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the sensor readings to a CSV file
int log_sensor_data(const char *timestamp, int left, int middle, int right) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set pull-up/down resistors (optional, depends on sensor wiring)
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Monitoring obstacle sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor_value = read_sensor(LEFT_SENSOR);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR);
        int right_sensor_value = read_sensor(RIGHT_SENSOR);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue; // Skip to the next iteration
        }

        // Log the sensor data
        if (left_sensor_value == -1 || middle_sensor_value == -1 || right_sensor_value == -1) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            free(timestamp);
            continue;
        }

        if (log_sensor_data(timestamp, left_sensor_value, middle_sensor_value, right_sensor_value) != 0) {
            fprintf(stderr, "Error logging sensor data.\n");
        }

        free(timestamp);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

