    printf("Monitoring obstacle sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor_value = read_sensor(LEFT_SENSOR);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR);
        int right_sensor_value = read_sensor(RIGHT_SENSOR);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue; // Skip to the next iteration
        }

        // Log the sensor data
        if (left_sensor_value == -1 || middle_sensor_value == -1 || right_sensor_value == -1) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            free(timestamp);
            continue;
        }

        if (log_sensor_data(timestamp, left_sensor_value, middle_sensor_value, right_sensor_value) != 0) {
            fprintf(stderr, "Error logging sensor data.\n");
        }

        free(timestamp);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

