#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define LOG_FILE "flame_events.txt"

// Global variables
static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int socket_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void log_event(const char *timestamp);
void send_alert(const char *timestamp);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using libgpiod
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error());
        return -1;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", FLAME_SENSOR_GPIO, gpiod_error());
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line for input
    int ret = gpiod_line_request_input(line, "flame_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", FLAME_SENSOR_GPIO, gpiod_error());
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d value: %s\n", FLAME_SENSOR_GPIO, gpiod_error());
        return -1;
    }
    return value;
}

// Log the event to a file
void log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return;
    }

    fprintf(log_file, "%s - Flame detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Send an alert to the server
void send_alert(const char *timestamp) {
    if (socket_fd == -1) {
        fprintf(stderr, "Socket not initialized.\n");
        return;
    }

    char message[256];
    snprintf(message, sizeof(message), "%s - Flame detected", timestamp);

    if (send(socket_fd, message, strlen(message), 0) < 0) {
        fprintf(stderr, "Error sending alert to server: %s\n", strerror(errno));
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set socket options
    int opt = 1;
    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        fprintf(stderr, "Error setting socket options: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);

    // Bind socket
    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error binding socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        fprintf(stderr, "Error listening for connections: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", SERVER_PORT);

    // Main loop
    while (running) {
        int client_socket = accept(socket_fd, NULL, NULL);
        if (client_socket < 0) {
            fprintf(stderr, "Error accepting connection: %s\n", strerror(errno));
            continue; // Continue listening
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(server_addr.sin_addr), ntohs(server_addr.sin_port));

        char buffer[256];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);

            // Detect flame
            int flame_detected = read_flame_sensor();
            if (flame_detected == 1) {
                log_event(time(NULL));
                send_alert(time(NULL));
                printf("Flame detected!\n");
            }

            // Cleanup after receiving data
            close(client_socket);
        } else if (bytes_received < 0) {
            fprintf(stderr, "Error receiving data: %s\n", strerror(errno));
            close(client_socket);
        }

        // Close connection after processing
        close(client_socket);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

