#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_touch_sensor();
void toggle_led();
void log_touch_event();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
void toggle_led() {
    gpioWrite(LED_PIN, !gpioRead(LED_PIN));
}

// Function to log the touch event to a file
void log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Touch detected\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Cannot log touch event.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 0) { // Assuming touch sensor outputs LOW when touched
            toggle_led();
            log_touch_event();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
        }

        gpioDelay(10 * 1000); // Check every 10ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

