#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define HEART_RATE_SAMPLES 5
#define BPM_THRESHOLD 30.0
#define BPM_MAX 220.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *heart_rate_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int part_id;
    int hw_rev;
    int heart_rate;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_si1182_data(sensor_data_t *data);
int validate_sensor_data(sensor_data_t *data);
int configure_sensor();
int read_heart_rate(sensor_data_t *data);
int process_heart_rate(int raw_hr);
int validate_bpms(int bpm_range);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from Si1182 sensor
int read_si1182_data(sensor_data_t *data) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PART_ID_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", result);
        return -1;
    }

    data->part_id = buf[0] | (buf[1] << 8);

    result = i2cReadI2CBlockData(i2c_handle, HW_REV_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", result);
        return -1;
    }

    data->hw_rev = buf[0] | (buf[1] << 8);

    result = i2cReadI2CBlockData(i2c_handle, AVERAGING_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading AVERAGING register: %d\n", result);
        return -1;
    }

    data->avg = buf[0] | (buf[1] << 8);

    result = i2cReadI2CBlockData(i2c_handle, ENABLE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading ENABLE register: %d\n", result);
        return -1;
    }

    data->enable = buf[0] | (buf[1] << 8);

    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading HEART_RATE register: %d\n", result);
        return -1;
    }

    data->heart_rate = buf[0] | (buf[1] << 8);

    return 0;
}

// Validate sensor data
int validate_sensor_data(sensor_data_t *data) {
    if (data->part_id != 0x02 || data->hw_rev != 0x01) {
        fprintf(stderr, "Invalid sensor data: Part ID = 0x%02X, HW Rev = 0x%02X\n", data->part_id, data->hw_rev);
        return -1;
    }
    return 0;
}

// Configure the Si1182 sensor
int configure_sensor() {
    // Configure LED current (example: 100uA)
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing to LED_CURRENT_REG\n");
        return -1;
    }

    // Configure averaging (example: 4 samples)
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing to AVERAGING_REG\n");
        return -1;
    }

    // Enable the sensor (example: enable heart rate measurement)
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE_REG\n");
        return -1;
    }

    return 0;
}

// Read heart rate data
int read_heart_rate(sensor_data_t *data) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading HEART_RATE_REG: %d\n", result);
        return -1;
    }

    data->heart_rate = (buf[0] << 8) | buf[1];

    return 0;
}

// Process heart rate data
int process_heart_rate(int raw_hr) {
    return (raw_hr * 0.5);
}

// Validate BPM range
int validate_bpms(int bpm_range) {
    if (bpm_range < BPM_MIN || bpm_range > BPM_MAX) {
        fprintf(stderr, "BPM range out of bounds: %d\n", bpm_range);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(heart_rate_file, "%s,%.2f\n", timestamp, data.heart_rate);
    fflush(heart_rate_file);

    return 0;
}

