    heart_rate_file = fopen("heart_rate.csv", "a");
    if (heart_rate_file == NULL) {
        fprintf(stderr, "Error opening heart_rate.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

