                        int bpm = process_heart_rate(sensor_data.heart_rate);

                        // Validate BPM range
                        bpm_range = validate_bpms(bpm);
                        if (bpm_range != -1) {
                            // Log data
                            log_data(sensor_data);

                            // Print BPM range
                            printf("BPM Range: %d - %d\n", bpm_range, BPM_MAX);
                        } else {
                            fprintf(stderr, "Invalid BPM range: %d\n", bpm_range);
                        }
                    } else {
                        fprintf(stderr, "Failed to read heart rate data\n");
                    }
                } else {
                    fprintf(stderr, "Failed to configure sensor\n");
                }
            } else {
                fprintf(stderr, "Failed to validate sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Retry on I2C read errors
        if (retry_count < RETRY_COUNT) {
            retry_count++;
            gpioDelay(100); // 100ms delay
            continue;
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Close I2C and file
    i2cClose(i2c_handle);
    fclose(heart_rate_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

