    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            log_flame_event(sensor_value);
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

