#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define peak detection threshold
#define PEAK_THRESHOLD 500

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_mic_input();
void trigger_led();
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPullUpDown(MIC_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Read microphone input
int read_mic_input() {
    return gpioRead(MIC_PIN);
}

// Trigger LED
void trigger_led() {
    gpioWrite(LED_PIN, 1); // Turn LED ON
    gpioDelay(100);        // Wait for 100ms
    gpioWrite(LED_PIN, 0); // Turn LED OFF
}

// Cleanup GPIO pins
void cleanup() {
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read microphone input
        int mic_value = read_mic_input();

        // Check for peak detection
        if (mic_value == 1 && mic_value == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print timestamp
            printf("[%s] Peak detected\n", timestamp);

            // Trigger LED
            trigger_led();

            // Wait for 100ms
            gpioDelay(100);
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

