// Function to initialize the Si1175 sensor
int si1175_init() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1175.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure ALS visible registers
    if (i2cWriteByteData(i2c_handle, SI1175_ALS_VIS_LSB_ADDR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to ALS_VIS_LSB_ADDR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1175_ALS_VIS_MSB_ADDR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to ALS_VIS_MSB_ADDR.\n");
        return -1;
    }

    // Configure ALS continuous mode
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure ALS_CONT_MODE.\n");
        return -1;
    }

