#define LEFT_GPIO 2
#define MIDDLE_GPIO 3
#define RIGHT_GPIO 4

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int main() {
    int left_fd, middle_fd, right_fd;
    struct gpiod_line *left_line, *middle_line, *right_line;
    int left_value, middle_value, right_value;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    if ((left_fd = gpiod_chip_open("/sys/class/gpio")) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", left_fd);
        return 1;
    }

    if ((middle_fd = gpiod_chip_open("/sys/class/gpio")) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", middle_fd);
        gpiod_chip_close(left_fd);
        return 1;
    }

    if ((right_fd = gpiod_chip_open("/sys/class/gpio")) < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", right_fd);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        return 1;
    }

    // Request lines for input
    if ((left_line = gpiod_chip_request_line(left_fd, LEFT_GPIO, 0)) == NULL) {
        fprintf(stderr, "Error requesting line %d: %d\n", LEFT_GPIO, left_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        gpiod_chip_close(right_fd);
        return 1;
    }

    if ((middle_line = gpiod_chip_request_line(middle_fd, MIDDLE_GPIO, 0)) == NULL) {
        fprintf(stderr, "Error requesting line %d: %d\n", MIDDLE_GPIO, middle_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(right_fd);
        gpiod_chip_close(left_line);
        return 1;
    }

    if ((right_line = gpiod_chip_request_line(right_fd, RIGHT_GPIO, 0)) == NULL) {
        fprintf(stderr, "Error requesting line %d: %d\n", RIGHT_GPIO, right_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        gpiod_chip_close(left_line);
        gpiod_chip_close(middle_line);
        return 1;
    }

    // Set GPIO direction to input
    if (gpiod_line_set_direction(left_line, GPIOD_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error setting direction for line %d: %d\n", LEFT_GPIO, left_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        gpiod_chip_close(right_fd);
        gpiod_chip_close(left_line);
        gpiod_chip_close(middle_line);
        gpiod_chip_close(right_line);
        return 1;
    }
    if (gpiod_line_set_direction(middle_line, GPIOD_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error setting direction for line %d: %d\n", MIDDLE_GPIO, middle_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        gpiod_chip_close(right_fd);
        gpiod_chip_close(left_line);
        gpiod_chip_close(middle_line);
        gpiod_chip_close(right_line);
        return 1;
    }
    if (gpiod_line_set_direction(right_line, GPIOD_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error setting direction for line %d: %d\n", RIGHT_GPIO, right_line);
        gpiod_chip_close(left_fd);
        gpiod_chip_close(middle_fd);
        gpiod_chip_close(left_line);
        gpiod_chip_close(middle_line);
        gpiod_chip_close(right_line);
        return 1;
    }

    // Poll the lines every 100ms
    while (keep_running) {
        left_value = gpiod_line_get_value(left_line);
        middle_value = gpiod_line_get_value(middle_line);
