#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Define GPIO pins for WS2812B strip
#define LED_PIN1 18
#define LED_PIN2 19
#define LED_PIN3 20
#define LED_PIN4 21
#define LED_PIN5 22
#define LED_PIN6 23
#define LED_PIN7 24
#define LED_PIN8 25
#define LED_PIN9 26

// Define I2C address of BH1750 sensor
#define BH1750_ADDR 0x23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define PWM duty cycle (0-100%)
#define PWM_DUTY_CYCLE 100

// Define lux range (0-1000)
#define LUX_RANGE 1000

// Define log file name
#define LOG_FILE "brightness_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_bh1750_lux();
float calculate_lux(int raw_lux);
float map_lux_to_brightness(float lux);
void set_led_brightness(int gpio_pin, int brightness);
void log_brightness(int gpio_pin, int brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
