// Define GPIO pins for SPI communication
#define SPI_MOSI 10
#define SPI_SCLK 11
#define SPI_CS 9

// Define GPIO pin for APA102 strip control
#define APA102_CS 10

// Define I2C addresses for BH1750 sensors
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C

// Define global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
int brightness = 0;
int running = 1;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_lux(int i2c_handle);
int map_lux_to_brightness(float lux);
void control_apu102(int gpio_pin, int brightness);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off the LED strip
    gpioWrite(APA102_CS, 0);

    // Close I2C handles
    if (i2c_handle_low != -1) {
        i2cClose(i2c_handle_low);
    }
    if (i2c_handle_high != -1) {
        i2cClose(i2c_handle_high);
    }

    // Close SPI handle
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int lux = -1;

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750 sensor\n");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to average lux values from multiple sensors
float average_lux(int i2c_handle) {
    int sum = 0;
    int num_sensors = 0;

    // Read lux values from all available sensors
    for (int i = 0; i < 3; i++) {
        int lux = read_bh1750(i2c_handle);
        if (lux != -1) {
            sum += lux;
            num_sensors++;
        } else {
            fprintf(stderr, "Error reading from sensor %d\n", i);
        }
    }

    if (num_sensors > 0) {
        return (float)sum / num_sensors;
    } else {
        return 0.0; // Return 0 if no sensors were read
    }
}

// Function to map lux value to brightness level
int map_lux_to_brightness(float lux) {
    // Map lux value to brightness level (0-31)
    // This is a simple linear mapping.  Adjust as needed.
    return (int)((float)lux / 10.0 * 31.0);
}

// Function to control the APA102 LED strip
void control_apu102(int gpio_pin, int brightness) {
    gpioWrite(gpio_pin, 1); // Turn on LED strip
    gpioDelay(500);        // Wait 500ms
    gpioWrite(gpio_pin, 0); // Turn off LED strip
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for SPI communication
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);

    // Set GPIO pin for APA102 strip control as output
    gpioSetMode(APA102_CS, PI_OUTPUT);

    // Open I2C handles for BH1750 sensors
    i2c_handle_low = i2cOpen(1, BH1750_ADDR_LOW, 0); // Bus 1, address 0x23, flags 0
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error opening I2C low address: %d\n", i2c_handle_low);
        cleanup(0); // Exit if I2C fails
    }

    i2c_handle_high = i2cOpen(1, BH1750_ADDR_HIGH, 0); // Bus 1, address 0x5C, flags 0
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error opening I2C high address: %d\n", i2c_handle_high);
        cleanup(0); // Exit if I2C fails
    }

    // Open SPI handle
    spi_handle = spiOpen(1, 1000000, 0); // SPI channel 1, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        cleanup(0); // Exit if SPI fails
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (running) {
        // Read lux values from sensors
        float lux_low = average_lux(i2c_handle_low);
        float lux_high = average_lux(i2c_handle_high);

        // Map lux values to brightness levels
        int brightness_low = map_lux_to_brightness(lux_low);
        int brightness_high = map_lux_to_brightness(lux_high);

        // Control APA102 LED strip
        control_apu102(APA102_CS, brightness_low);

        // Delay for 500ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

