#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define BLINK_RATE_MIN 0.5
#define BLINK_RATE_MAX 5.0
#define BLINK_PERIOD_MIN 0.5
#define BLINK_PERIOD_MAX 5.0
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 1000
#define MAX_I2C_RETRIES 3

// Global variables
static int i2c_fd = -1;
static int led_gpio = LED_GPIO;
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    uint16_t raw_value;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_bh1750(int fd, uint16_t *raw_value);
float convert_to_lux(uint16_t raw_value);
void control_led(int gpio, int on);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C interface
int init_i2c(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t cmd = 0x10; // High resolution mode
    uint8_t buf[2];

    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Control LED using GPIO
void control_led(int gpio, int on) {
    if (gpio == LED_GPIO) {
        if (on) {
            gpio_set_direction(gpio, GPIO_OUTPUT);
            gpio_set_value(gpio, 1); // Turn LED on
        } else {
            gpio_set_value(gpio, 0); // Turn LED off
        }
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    control_led(led_gpio, 0); // Turn off LED
    unexport_device(I2C_BUS);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Set LED GPIO as output
    gpio_set_direction(led_gpio, GPIO_OUTPUT);
    gpio_set_value(led_gpio, 0); // Ensure LED is off initially

    // Initialize circular buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i].raw_value = 0;
        buffer[i].lux = 0.0;
    }

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        float lux;

        // Read sensor data
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Convert raw value to lux
            lux = convert_to_lux(raw_value);

            // Store data in circular buffer
            buffer[buffer_index].raw_value = raw_value;
            buffer[buffer_index].lux = lux;

            // Update circular buffer index
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average lux
            float sum = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                sum += buffer[i].lux;
            }
            float avg_lux = sum / BUFFER_SIZE;

            // Calculate blink rate
            float lux_ratio = avg_lux / MAX_I2C_RETRIES;
            float ratio = (lux_ratio > 0.0) ? lux_ratio : 1.0;
            float ratio_clamped = (ratio > BLINK_PERIOD_MIN) ? ratio : BLINK_PERIOD_MIN;
            float ratio_clamped_max = (ratio > BLINK_PERIOD_MAX) ? ratio : BLINK_PERIOD_MAX;

            // Calculate blink period
            float period = (ratio_clamped_max - ratio) * BLINK_RATE_MIN;

            // Control LED
            control_led(led_gpio, (ratio > BLINK_PERIOD_MIN) ? 1 : 0); // Turn on LED

            // Print sensor data
            printf("Raw Value: 0x%04X, Lux: %.2f, Average Lux: %.2f, Blink Period: %.2f\n", raw_value, lux, avg_lux, period);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
            gpio_set_value(led_gpio, 0); // Ensure LED is off
            sleep(1); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

