// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variables
int running = 1;

// Function prototypes
int gpio_init();
void gpio_cleanup();
int gpio_request_line(int pin);
int gpio_set_line(int pin, int value);
int gpio_get_line(int pin);
int gpio_request_event(int line, int callback, void *userdata);
int gpio_unrequest_event(int line);
int gpio_unset_line(int pin);
void blink_led(int duration_ms);
void button_event_handler(int line, int level, int tick);
void signal_handler(int signal);

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpio_unset_line(LED_PIN);
    gpio_unset_line(BUTTON_PIN);
    gpio_cleanup();
    exit(0);
}

// Initialize GPIO
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpio_set_mode(LED_PIN, PI_OUTPUT);
    gpio_set_mode(BUTTON_PIN, PI_INPUT);
    gpio_set_pull_up_down(BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Cleanup GPIO resources
void gpio_cleanup() {
    gpio_set_mode(LED_PIN, PI_INPUT);
    gpio_set_mode(BUTTON_PIN, PI_INPUT);
    gpio_unset_line(LED_PIN);
    gpio_unset_line(BUTTON_PIN);
    gpioTerminate();
}

// Request a GPIO line
int gpio_request_line(int pin) {
    if (gpio_request_line(pin) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", pin);
        return 1;
    }
    return 0;
}

// Set a GPIO line
int gpio_set_line(int pin, int value) {
    if (gpio_set_line(pin, value) != 0) {
        fprintf(stderr, "Failed to set GPIO line %d to %d\n", pin, value);
        return 1;
    }
    return 0;
}

// Get a GPIO line
int gpio_get_line(int pin) {
    return gpio_get_line(pin);
}

// Request an event line
int gpio_request_event(int line, int callback, void *userdata) {
    if (gpio_request_event(line, callback, userdata) != 0) {
        fprintf(stderr, "Failed to request event line %d\n", line);
        return 1;
    }
    return 0;
}

