#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 29
#define DELAY_MS 750

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        time_sleep(DELAY_MS);
        gpioWrite(LED_PIN, 0); // Turn LED off
        time_sleep(DELAY_MS);
    }

    gpioTerminate();
    return 0;
}

