#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM period (us)
#define PWM_PERIOD_US 1000000

// Define PWM range (0-100)
#define PWM_RANGE 100

// Define PWM duty cycle range (0-100)
#define PWM_DUTY_CYCLE_RANGE 100

// Global variable to track program state
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle out of range (0-100)\n");
        return;
    }

    int period_us = PWM_PERIOD_US / (duty_cycle + 1);
    int period_ms = period_us / 1000;

    gpioPWM(gpio, duty_cycle);
}

// Function to generate a random RGB value (0-100)
int generate_random_rgb(int *r, int *g, int *b) {
    *r = rand() % PWM_RANGE;
    *g = rand() % PWM_RANGE;
    *b = rand() % PWM_RANGE;
    return *r + *g + *b;
}

// Function to set the RGB color using PWM
void set_rgb_color(int red, int green, int blue) {
    set_pwm_duty_cycle(RED_PIN, red);
    set_pwm_duty_cycle(GREEN_PIN, green);
    set_pwm_duty_cycle(BLUE_PIN, blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random RGB values
        int red, green, blue;
        generate_random_rgb(&red, &green, &blue);

        // Set RGB color
        set_rgb_color(red, green, blue);

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Cleanup GPIO lines before exiting
    gpioTerminate();

    return 0;
}

