#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RGB_LSB_REG 0x66
#define RGB_MSB_REG 0x68
#define RGB_C_REG 0x6A
#define LED_GPIO 18
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_ambient_light();
int read_color_data();
void log_data(int als, int r, int g, int b);
void control_led(int als);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the ADPD188BI sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set mode to normal operation
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Could not set mode.\n");
        return -1;
    }

    return 0;
}

// Function to read ambient light data
int read_ambient_light() {
    int als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    int als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);

    if (als_msb < 0 || als_lsb < 0) {
        fprintf(stderr, "Error: Could not read ALS data.\n");
        return -1;
    }

    return (als_msb << 8) | als_lsb;
}

// Function to read color data
int read_color_data() {
    int r_msb = i2cReadByteData(i2c_handle, RGB_MSB_REG);
    int r_lsb = i2cReadByteData(i2c_handle, RGB_LSB_REG);
    int g_msb = i2cReadByteData(i2c_handle, RGB_MSB_REG + 1);
    int g_lsb = i2cReadByteData(i2c_handle, RGB_LSB_REG + 1);
    int b_msb = i2cReadByteData(i2c_handle, RGB_MSB_REG + 2);
    int b_lsb = i2cReadByteData(i2c_handle, RGB_LSB_REG + 2);

    if (r_msb < 0 || r_lsb < 0 || g_msb < 0 || g_lsb < 0 || b_msb < 0 || b_lsb < 0) {
        fprintf(stderr, "Error: Could not read color data.\n");
        return -1;
    }

    return (r_msb << 16) | (r_lsb << 8) | r_msb | (g_msb << 16) | (g_lsb << 8) | g_msb | (b_msb << 16) | (b_lsb << 8) | b_msb;
}

// Function to log data to a CSV file
void log_data(int als, int r, int g, int b) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, als, r, g);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED brightness using PWM
void control_led(int als) {
    int duty_cycle = PWM_DUTY_CYCLE_MIN + (int)((float)als / 65535.0 * (PWM_DUTY_CYCLE_MAX - PWM_DUTY_CYCLE_MIN));
    gpioPWM(LED_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ambient light data
        int als = read_ambient_light();
        if (als < 0) {
            fprintf(stderr, "Error: Could not read ambient light data.\n");
        } else {
            // Read color data
            int r = read_color_data();
            if (r < 0) {
                fprintf(stderr, "Error: Could not read color data.\n");
            } else {
                // Control LED brightness
                control_led(als);

                // Log data
                log_data(als, r, r, r);

                printf("ALS: %d, R: %d, G: %d, B: %d\n", als, r, r, r);
            }
        }

        // Wait 500 milliseconds
        gpioDelay(500);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

