#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define DEVID 0x00
#define CTRL_REG1 0x2D
#define OUT_X_L 0x32
#define OUT_X_H 0x33
#define OUT_Y_L 0x34
#define OUT_Y_H 0x35
#define OUT_Z_L 0x36
#define OUT_Z_H 0x37

// GPIO pin for LED
#define LED_PIN 17

// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void check_acceleration(int16_t x, int16_t y, int16_t z);
void control_led(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int init_adxl345() {
    // Enable accelerometer (full-resolution, +/-2g range)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0B) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Log the acceleration data to a file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check if the acceleration exceeds the threshold
void check_acceleration(int16_t x, int16_t y, int16_t z) {
    if (fabs(x) > ACCEL_THRESHOLD || fabs(y) > ACCEL_THRESHOLD || fabs(z) > ACCEL_THRESHOLD) {
        printf("Acceleration exceeds threshold! X: %d, Y: %d, Z: %d\n", x, y, z);
        control_led(x, y, z);
    }
}

// Control the LED based on acceleration
void control_led(int16_t x, int16_t y, int16_t z) {
    if (fabs(x) > ACCEL_THRESHOLD || fabs(y) > ACCEL_THRESHOLD || fabs(z) > ACCEL_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    while (program_running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            check_acceleration(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

