    // Read status
    result = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_STATUS);
    if (result < 0) {
        fprintf(stderr, "Error reading status: %d\n", result);
        return -1;
    }

    // Read final range
    result = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE);
    if (result < 0) {
        fprintf(stderr, "Error reading final range: %d\n", result);
        return -1;
    }

    // Read high byte
    result = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_HIGH);
