#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus and register addresses
#define I2C_BUS 1
#define SENSOR1_REG 0x01
#define SENSOR2_REG 0x02

// Define control register values
#define CONTINUOUS_MEASUREMENT 0x80

// Define constants
#define SAMPLE_INTERVAL_MS 10
#define SAMPLE_SIZE 2
#define SAMPLE_COUNT (SAMPLE_INTERVAL_MS * SAMPLE_INTERVAL_MS * SAMPLE_SIZE)
#define SAMPLE_SIZE_MS (SAMPLE_INTERVAL_MS * SAMPLE_INTERVAL_MS * SAMPLE_SIZE)
#define SAMPLE_SIZE_MS_2 (SAMPLE_INTERVAL_MS * SAMPLE_INTERVAL_MS * SAMPLE_SIZE)

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int address;
    int handle;
    int data_reg;
    int control_reg;
    int data_buffer[SAMPLE_SIZE];
    int data_index;
    int tdoa;
} sensor_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize a sensor
int init_sensor(int handle, int address) {
    // Initialize I2C
    i2c_handle1 = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1 at address 0x%02x: %d\n", address, i2c_handle1);
        return -1;
    }

    // Initialize control register
    if (i2cWriteByteData(i2c_handle1, SENSOR1_REG, CONTINUOUS_MEASUREMENT) < 0) {
        fprintf(stderr, "Error writing to control register for sensor 1 at address 0x%02x\n", address);
        i2cClose(i2c_handle1);
        return -1;
    }

    // Initialize data buffer
    sensor_t sensor1 = {
        .sensor_id = 1,
        .address = address,
        .handle = i2c_handle1,
        .data_reg = SENSOR1_REG,
        .control_reg = SENSOR1_REG,
        .data_buffer = (int*)malloc(SAMPLE_SIZE * sizeof(int)),
        .data_index = 0,
        .tdoa = 0
    };

    // Initialize data buffer for sensor 2
    sensor_t sensor2 = {
        .sensor_id = 2,
        .address = address,
        .handle = i2c_handle2,
        .data_reg = SENSOR2_REG,
        .control_reg = SENSOR2_REG,
        .data_buffer = (int*)malloc(SAMPLE_SIZE * sizeof(int)),
        .data_index = 0,
        .tdoa = 0
    };

    return 0;
}

// Function to read data from a sensor
int read_sensor(int handle, int data_reg) {
    int data = i2cReadByteData(handle, data_reg);
    if (data < 0) {
        fprintf(stderr, "Error reading data from register 0x%02x: %d\n", data_reg, data);
        return -1;
    }
    return data;
}

// Function to process sensor data
int process_sensor_data(int sensor_id, int data_buffer[], int data_index, int *tdoa) {
    int16_t raw_data = (int16_t)((data_buffer[data_index] << 8) | data_buffer[data_index + 1]);
    *tdoa = (int)((raw_data - 0x8000) / 0x200); // Assuming 0x8000 is the maximum raw value
    return 0;
}

// Function to log data to a file
int log_data(int sensor_id, int data_buffer[], int data_index, int tdoa) {
    FILE *fp = fopen("audio_log.dat", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, sensor_id, data_buffer[data_index], data_id, tdoa);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize sensors
    if (init_sensor(i2c_handle1, SENSOR1_ADDR) < 0 || init_sensor(i2c_handle2, SENSOR2_ADDR) < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int data_buffer1[SAMPLE_SIZE];
        int data_buffer2[SAMPLE_SIZE];
        int data_index1 = 0;
        int data_index2 = 0;
        int tdoa1 = 0, tdoa2 = 0;

        for (int i = 0; i < SAMPLE_SIZE; i++) {
            int raw_data = read_sensor(i2c_handle1, SENSOR1_REG);
            if (raw_data < 0) {
                fprintf(stderr, "Error reading sensor 1 data, skipping sample %d\n", i);
                continue;
            }
            data_buffer1[i] = raw_data;
            data_index1++;
            if (data_index1 == SAMPLE_SIZE) {
                data_index1 = 0;
                tdoa1 = process_sensor_data(sensor1.sensor_id, data_buffer1, data_index1, &tdoa1);
            }
        }

        for (int i = 0; i < SAMPLE_SIZE; i++) {
            int raw_data = read_sensor(i2c_handle2, SENSOR2_REG);
            if (raw_data < 0) {
                fprintf(stderr, "Error reading sensor 2 data, skipping sample %d\n", i);
                continue;
            }
            data_buffer2[i] = raw_data;
            data_index2++;
            if (data_index2 == SAMPLE_SIZE) {
                data_index2 = 0;
                tdoa2 = process_sensor_data(sensor2.sensor_id, data_buffer2, data_index2, &tdoa2);
            }
        }

        // Log data
        if (log_data(sensor1.sensor_id, data_buffer1, data_index1, tdoa1) < 0 || log_data(sensor2.sensor_id, data_buffer2, data_index2, tdoa2) < 0) {
            fprintf(stderr, "Error logging data, skipping logging\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

