#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCEL_REG 0x0A
#define Y_ACCEL_REG 0x0C
#define Z_ACCEL_REG 0x0E

// SPI Channel
#define SPI_CHANNEL 0

// SPI Flags
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000

// Global Variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t running = 1;

// Function Prototypes
int spi_transfer(int handle, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_register(int handle, unsigned char reg_addr);
int write_register(int handle, unsigned char reg_addr, unsigned char data);
int read_gyro_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z);
int read_accel_data(int handle, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// Function to transfer data over SPI
int spi_transfer(int handle, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADIS16488A
int read_register(int handle, unsigned char reg_addr) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // MSB = 1 for read, address
    tx_buf[1] = 0x00; // Dummy byte

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[0];
}

// Function to write a register in the ADIS16488A
int write_register(int handle, unsigned char reg_addr, unsigned char data) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // MSB = 1 for write, address
    tx_buf[1] = data; // Data to write

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z) {
    unsigned char data[6];
    int result = read_register(handle, X_GYRO_REG);
    if (result < 0) {
        return -1;
    }

    data[0] = read_register(handle, X_GYRO_REG + 1); // Read MSB first
    data[1] = read_register(handle, X_GYRO_REG + 2);
    data[2] = read_register(handle, X_GYRO_REG + 3);
    data[3] = read_register(handle, X_GYRO_REG + 4);
    data[4] = read_register(handle, X_GYRO_REG + 5);
    data[5] = read_register(handle, X_GYRO_REG + 6);

    *gyro_x = (float)data[0] * 0.005;
    *gyro_y = (float)data[1] * 0.005;
    *gyro_z = (float)data[2] * 0.005;

    return 0;
}

// Function to read accelerometer data
int read_accel_data(int handle, float *accel_x, float *accel_y, float *accel_z) {
    unsigned char data[6];
    int result = read_register(handle, X_ACCEL_REG);
    if (result < 0) {
        return -1;
    }

    data[0] = read_register(handle, X_ACCEL_REG + 1); // Read MSB first
    data[1] = read_register(handle, X_ACCEL_REG + 2);
    data[2] = read_register(handle, X_ACCEL_REG + 3);
    data[3] = read_register(handle, X_ACCEL_REG + 4);
    data[4] = read_register(handle, X_ACCEL_REG + 5);
    data[5] = read_register(handle, X_ACCEL_REG + 6);

    *accel_x = (float)data[0] * 0.00025;
    *accel_y = (float)data[1] * 0.00025;
    *accel_z = (float)data[2] * 0.00025;

    return 0;
}

// Function to log data to a CSV file
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup function to close SPI and CSV file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("imu_data.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fclose(csv_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    time_t last_log_time = 0;

    while (running) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Read accelerometer data
            if (read_accel_data(spi_handle, &accel_x, &accel_y, &accel_z) == 0) {
                // Get current timestamp
                time_t current_time = time(NULL);

                // Check if enough time has passed since the last log
                if (difftime(current_time, last_log_time) >= 0.1) {
                    // Log the data
                    log_data(csv_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
                    last_log_time = current_time;
                }
            } else {
                fprintf(stderr, "Failed to read accelerometer data\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

