#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Channel
#define SPI_CHANNEL 0

// SPI Flags
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope and accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} gyro_accel_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi_channel(int channel) {
    spi_handle = spiOpen(channel, SPI_MODE, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from ADIS16448
gyro_accel_data_t read_adis16448(int spi_handle, int channel) {
    gyro_accel_data_t data;
    char tx_buffer[2];
    char rx_buffer[2];

    // Send read command (register address with bit 15 set)
    tx_buffer[0] = 0x80 | (channel & 0x07); // Command for channel 0
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        data.x = 0.0; // Set to 0.0 in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Read 16-bit data
    int16_t raw_data = ((rx_buffer[0] & 0x7F) << 8) | rx_buffer[1];

    // Convert to signed 16-bit integer
    data.x = (float)raw_data * 0.05; // Scaling factor
    data.y = (float)raw_data * 0.00025; // Scaling factor
    data.z = (float)raw_data * 0.05;

    return data;
}

// Function to print gyroscope and accelerometer data
void print_gyro_accel_data(gyro_accel_data_t data) {
    printf("X: %.3f deg/s, Y: %.3f deg/s, Z: %.3f g\n", data.x, data.y, data.z);
}

// Function to close SPI channel
void close_spi_channel(int spi_handle) {
    spiClose(spi_handle);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel(SPI_CHANNEL) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from ADIS16448
        gyro_accel_data_t gyro_accel_data = read_adis16448(spi_handle, SPI_CHANNEL);

        // Print gyroscope and accelerometer data
        print_gyro_accel_data(gyro_accel_data);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI channel and terminate pigpio
    close_spi_channel(spi_handle);
    gpioTerminate();

    return 0;
}

