#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define PWR_MGMT_1   0x6B
#define DATA_FORMAT  0x1C
#define DATAX0       0x32
#define DATAX1       0x33
#define DATAY0       0x34
#define DATAY1       0x35
#define DATAZ0       0x36
#define DATAZ1       0x37

// GPIO pin for LED
#define LED_PIN 17

// Impact threshold (g)
#define IMPACT_THRESHOLD 2.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_adxl345();
int read_adxl345_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(float magnitude);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 sensor
int init_adxl345() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up ADXL345\n");
        return -1;
    }

    // Set data format to full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set data format\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the ADXL345
int read_adxl345_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log the impact event to a file
void log_impact(float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_adxl345_data(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                control_led(1);

                // Log impact
                log_impact(magnitude);

                // Delay for 500ms
                gpioDelay(500000); // 500ms = 500000 microseconds

                // Turn off LED
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error: Could not read accelerometer data\n");
        }

        // Wait 10ms
        gpioDelay(10000); // 10ms = 10000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    control_led(0); // Turn off LED
    gpioTerminate();

    return 0;
}

