// I2C address of the IMU
#define ICM20602_ADDR 0x68

// Register addresses
#define WHO_AM_I 0x75
#define ACCEL_CONFIG 0x00
#define GYRO_CONFIG 0x00
#define WHO_AM_I_REG 0x75

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the IMU (set PWR_MGMT_1 to 0x00)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read IMU data using burst reads
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[6];

    // Read 6 bytes of accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, 0x3B, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read IMU data\n");
        data.accel_x = 0; data.accel_y = 0; data.accel_z = 0;
        data.gyro_x = 0; data.gyro_y = 0; data.gyro_z = 0;
        return data;
    }

    // Combine the bytes to form 16-bit integers
    data.accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    data.gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    data.gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    data.gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return data;
}

