#include <pigpio.h>

// MMA8451Q Register Addresses
#define MMA8451Q_WHO_AM_I 0x0D
#define MMA8451Q_X_OUT_L 0x08
#define MMA8451Q_X_OUT_H 0x09
#define MMA8451Q_Y_OUT_L 0x0A
#define MMA8451Q_Y_OUT_H 0x0B
#define MMA8451Q_Z_OUT_L 0x0C
#define MMA8451Q_Z_OUT_H 0x0D

// LED GPIO Pin
#define LED_PIN 17

// Impact Threshold (g)
#define IMPACT_THRESHOLD 2.0

// I2C Bus and Address
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D

// Global Variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_i2c(int bus, int addr);
int read_register(int fd, uint8_t reg, uint8_t *data, int len);
int write_register(int fd, uint8_t reg, uint8_t data);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_impact(const char *timestamp);
void control_led(int state);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a register from the MMA8451Q
int read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading register data");
        return -1;
    }

    return 0;
}

// Function to write a register to the MMA8451Q
int write_register(int fd, uint8_t reg, uint8_t data) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (write(fd, &data, 1) != 1) {
        perror("Error writing register data");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the MMA8451Q
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (read_register(fd, MMA8451Q_X_OUT_L, &x_l, 1) != 0) return -1;
    if (read_register(fd, MMA8451Q_X_OUT_H, &x_h, 1) != 0) return -1;
    if (read_register(fd, MMA8451Q_Y_OUT_L, &y_l, 1) != 0) return -1;
    if (read_register(fd, MMA8451Q_Y_OUT_H, &y_h, 1) != 0) return -1;
    if (read_register(fd, MMA8451Q_Z_OUT_L, &z_l, 1) != 0) return -1;
    if (read_register(fd, MMA8451Q_Z_OUT_H, &z_h, 1) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Function to log impact events to a file
void log_impact(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s Impact Detected\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    time_t current_time;
    char timestamp[20];

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude of acceleration
            int16_t magnitude = (int16_t)((x * x) + (y * y) + (z * z));

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Get current timestamp
                current_time = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

                // Log impact event
                log_impact(timestamp);

                // Control LED
                control_led(1); // Turn LED on
                gpioDelay(500);   // Keep LED on for 500ms
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(0); // Turn off LED
    gpioTerminate();

    return 0;
}

