#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pigpio.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_DATAX0 0x32

// GPIO pin for interrupt
#define GPIO_PIN 11

// I2C file descriptor
int i2c_fd;

// Global variables
int i2c_fd_old;
int running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int init_gpiod();
int read_adxl345(float *x, float *y, float *z);
int log_data(float x, float y, float z);
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize libgpiod
int init_gpiod() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from ADXL345
int read_adxl345(float *x, float *y, float *z) {
    unsigned char data[6];
    int result;

    // Read 6 bytes from DATAX0 register
    result = i2cReadI2CBlockData(i2c_fd, ADXL345_DATAX0, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine the first two bytes to form the 16-bit signed integer
    int16_t raw_x = (data[0] << 8) | data[1];
    int16_t raw_y = (data[2] << 8) | data[3];
    int16_t raw_z = (data[4] << 8) | data[5];

    // Convert to g-force units
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

