    if (fsize == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }

    // Write data to the log file
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);

    // Close the file
    fclose(fp);

    return 0;
}

// Interrupt handler function
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    float x, y, z;
    sensor_data_t data;

    if (level == 1) { // Rising edge detected
        if (read_adxl345(&data.x, &data.y, &data.z) == 0) {
            log_data(data.x, data.y, data.z);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Disable interrupts
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close GPIO file descriptor
    if (i2c_fd_old != -1) {
        close(i2c_fd_old);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize libgpiod
    if (init_gpiod() != 0) {
        cleanup();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, freefall_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_adxl345(&data.x, &data.y, &data.z) == 0) {
            // Log data
            log_data(data.x, data.y, data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Wait for a short period
        gpioDelay(100); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

