#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define WHO_AM_I 0x00
#define X_GYRO_OUT 0x14
#define X_GYRO_OUT_LSB 0x14

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE_PIN 8

// Scaling Factor (degrees/sec/LSB)
#define SCALE_FACTOR 0.0305

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, int reg);
int spi_write_register(int handle, int reg, int value);
int read_gyro_data(int handle, int *x_gyro_out, int *x_gyro_out_lsb);
float scale_gyro_data(int x_gyro_out, int x_gyro_out_lsb);
void log_data(float angular_rate);
void signal_handler(int signal);

// Function to read a single register from the ADIS16266
int spi_read_register(int handle, int reg) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00;       // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    return rx_buf[1];
}

// Function to write a single register to the ADIS16266
int spi_write_register(int handle, int reg, int value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to read 16-bit data from the ADIS16266
int read_gyro_data(int handle, int *x_gyro_out, int *x_gyro_out_lsb) {
    int x_gyro_out_lsb_raw = spi_read_register(handle, X_GYRO_OUT_LSB);
    if (x_gyro_out_lsb_raw < 0) {
        return -1;
    }

    *x_gyro_out_lsb = x_gyro_out_lsb_raw;
    *x_gyro_out = spi_read_register(handle, X_GYRO_OUT);
    if (x_gyro_out < 0) {
        return -1;
    }

    return 0;
}

// Function to scale the gyro data
float scale_gyro_data(int x_gyro_out, int x_gyro_out_lsb) {
    return (float)x_gyro_out * SCALE_FACTOR;
}

// Function to log the angular rate data to a CSV file
void log_data(float angular_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, angular_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 3
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Angular_Rate\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int x_gyro_out, x_gyro_out_lsb;
        float angular_rate;

        // Read gyro data
        if (read_gyro_data(spi_handle, &x_gyro_out, &x_gyro_out_lsb) == 0) {
            // Scale gyro data
            angular_rate = scale_gyro_data(x_gyro_out, x_gyro_out_lsb);

            // Log data
            log_data(angular_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Wait for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

