            // Log data
            log_data(angular_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Wait for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

