#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to log events to a file
int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == -1) {
            fprintf(stderr, "Error reading flame sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (flame_detected == 0) { // Flame detected (LOW signal)
            printf("Flame detected: YES\n");
            log_event("Flame detected");
            gpioDelay(500); // Debounce delay
        } else {
            printf("Flame detected: NO\n");
        }
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

