#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_sensor_data(int sensor_1_state, int sensor_2_state);
void check_conveyor_halt(int sensor_1_state, int sensor_2_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Log sensor data to file
void log_sensor_data(int sensor_1_state, int sensor_2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor_1_state, sensor_2_state);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Check for conveyor halt
void check_conveyor_halt(int sensor_1_state, int sensor_2_state) {
    if (sensor_1_state == 1 && sensor_2_state == 1) {
        printf("Conveyor halt triggered!\n");
        log_sensor_data(sensor_1_state, sensor_2_state);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Conveyor safety system monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_1_state = read_sensor(SENSOR_1_GPIO);
        int sensor_2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor_1_state == -1 || sensor_2_state == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        log_sensor_data(sensor_1_state, sensor_2_state);
        check_conveyor_halt(sensor_1_state, sensor_2_state);

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

