#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_PARTID 0x01
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int read_acceleration(int handle, int *x, int *y, int *z);
void log_data(FILE *fp, int x, int y, int z);
void signal_handler(int signal);

// Function to read a single byte from the ADXL354B over SPI
int spi_read_register(int handle, uint8_t reg) {
    char tx_buf[1];
    char rx_buf[1];

    tx_buf[0] = reg | 0x80; // Set MSB for read

    if (spiXfer(handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    return rx_buf[0];
}

// Function to write a single byte to the ADXL354B over SPI
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int read_acceleration(int handle, int *x, int *y, int *z) {
    uint8_t x_data, y_data, z_data;

    x_data = spi_read_register(handle, ADXL354B_XDATA);
    y_data = spi_read_register(handle, ADXL354B_YDATA);
    z_data = spi_read_register(handle, ADXL354B_ZDATA);

    if (x_data < 0 || y_data < 0 || z_data < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x_data << 8) | (x_data >> 8));
    *y = (int16_t)((y_data << 8) | (y_data >> 8));
    *z = (int16_t)((z_data << 8) | (z_data >> 8));

    return 0;
}

// Function to log acceleration data to a file
void log_data(FILE *fp, int x, int y, int z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset ADXL354B
    if (spi_write_register(spi_handle, ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1); // Wait for reset to complete

    // Set measurement mode
    if (spi_write_register(spi_handle, ADXL354B_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

