#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCL_REG 0x0A
#define Y_ACCL_REG 0x0C
#define Z_ACCL_REG 0x0E

// ADIS16362 Commands
#define CMD_START_CONVERSION 0x01
#define CMD_STOP_CONVERSION 0x02
#define CMD_READ_REGISTER 0x03
#define CMD_READ_REGISTER_WITH_DATA 0x04

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a 16-bit value from the ADIS16362
int read_adis16362(int handle, int reg) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    tx_buf[0] = CMD_READ_REGISTER | (reg << 1); // MSB for register address
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    return (rx_buf[1] << 8) | rx_buf[0]; // Combine MSB and LSB
}

// Function to read gyroscope data
int read_gyroscope(int handle, int reg) {
    int value = read_adis16362(handle, reg);
    if (value < 0) {
        return -1; // Indicate error
    }
    return value;
}

