// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// GPIO initialization function
int gpio_init(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// GPIO set direction function
int gpio_set_direction(int gpio_pin, const char *direction) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pin);
        return -1;
    }
    return 0;
}

// GPIO read function
int gpio_read_value(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Self-parking sequence function
void self_parking_sequence(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Self-parking sequence started\n", timestamp);
    gpioDelay(2000); // 2 seconds
    printf("[%s] Self-parking sequence completed\n", timestamp);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) != 0) {
        return 1;
    }

    // Request GPIO chip
    if (gpioChipOpen(4, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Request GPIO line for input direction
    if (gpioLineRequestInput(GPIO_PIN) != 0) {
        gpioChipClose(4);
        gpioTerminate();
        return 1;
    }

    printf("GPIO17 initialized. Monitoring...\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = gpio_read_value(GPIO_PIN);

        if (obstacle_detected == 0) { // Assuming LOW indicates obstacle detected
            self_parking_sequence();
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    gpioChipClose(4);
    gpioTerminate();

    return 0;
}

