#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define libgpiod constants
#define LINE_REQUEST_SIZE 1
#define LINE_REQUEST_TYPE LINE_REQUEST_TYPE_GPIO
#define LINE_REQUEST_FLAGS 0

// Global variables
static volatile int running = 1;
static int lines_requested = 0;
static int lines_read = 0;
static int lines_available = 0;
static int lines_available_last_read = 0;

// Function prototypes
int request_lines(int lines, int flags);
int read_lines(int lines, int *values);
int check_obstacle(int value);
void log_obstacle_status(int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Requests lines from the libgpiod chip
int request_lines(int lines, int flags) {
    int result;
    int line_request[LINE_REQUEST_SIZE];
    int line_request_index = 0;

    // Create the line request
    line_request[line_request_index++] = LINE_REQUEST_TYPE;
    line_request[line_request_index++] = LINE_REQUEST_FLAGS;

    // Add the requested lines to the request
    for (int i = 0; i < lines; i++) {
        line_request[line_request_index++] = i;
    }

    // Request the lines
    result = gpiod_chip_request_lines(1, line_request, LINE_REQUEST_SIZE);
    if (result < 0) {
        fprintf(stderr, "Error requesting lines: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads lines from the libgpiod chip
int read_lines(int lines, int *values) {
    int result;
    int line_index = 0;

    // Read the lines
    for (int i = 0; i < lines; i++) {
        int line_request_index = line_index;
        line_index++;

        // Read the line
        result = gpiod_chip_get_line(i, &values[line_request_index]);
        if (result < 0) {
            fprintf(stderr, "Error reading line %d: %d\n", i, result);
            return -1;
        }

        // Update the line index
        line_request_index++;
    }

    return 0;
}

// Checks if an obstacle is detected
int check_obstacle(int value) {
    return (value == 0);
}

// Logs the obstacle status to the console
void log_obstacle_status(int sensor1_value, int sensor2_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s - Sensor 1: %d, Sensor 2: %d\n", buf, sensor1_value, sensor2_value);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Request lines from the chip
    if (request_lines(2, LINE_REQUEST_FLAGS) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read lines from the chip
        if (read_lines(2, &lines_read) != 0) {
            fprintf(stderr, "Error reading lines, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for obstacles
        for (int i = 0; i < 2; i++) {
            int sensor1_value = lines_read & (1 << i);
            int sensor2_value = (lines_read >> i) & 1;

            if (check_obstacle(sensor1_value)) {
                log_obstacle_status(sensor1_value, sensor2_value);
            }
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

