#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_X_GYRO 0x04
#define ADIS16266_REG_Y_GYRO 0x06
#define ADIS16266_REG_Z_GYRO 0x08
#define ADIS16266_REG_CTRL 0x24

// ADIS16266 Commands
#define ADIS16266_CMD_START 0x01
#define ADIS16266_CMD_STOP 0x02
#define ADIS16266_CMD_READ 0x03
#define ADIS16266_CMD_WRITE 0x04

// SPI Device Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Gyroscope Scale Factor (deg/sec/LSB)
#define SCALE_FACTOR 0.02

// Global Variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function Prototypes
int spi_init(int spi_device, int spi_mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t tx_data[], uint8_t rx_data[], int len);
int adis16266_read_register(int fd, uint8_t reg_addr);
int adis16266_write_register(int fd, uint8_t reg_addr, uint8_t value);
int adis16266_read_register_with_address(int fd, uint8_t address, uint8_t reg_addr);
int adis16266_read_register_with_address_with_data(int fd, uint8_t address, uint8_t reg_addr, uint8_t *data);
gyro_data_t adis16266_read_gyro_data(int fd);
void log_gyro_data(gyro_data_t data);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT. Exiting gracefully.\n");
        program_running = 0;
    }
}

// SPI Initialization
int spi_init(int spi_device, int spi_mode, int bits_per_word, int speed) {
    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = (spi_mode == SPI_MODE) ? 0 : 1; // SPI_MODE_0 or SPI_MODE_1
    uint8_t bits = (bits_per_word == 8) ? 0 : 1; // 8 bits per word or 16 bits per word
    uint8_t speed_hz = (speed == 1000000) ? 0 : 1; // 1 MHz or 2 MHz

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t tx_data[], uint8_t rx_data[], int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_data,
        .rx_buf = (unsigned long)rx_data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .delay_usecs = 0,
    };

