#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR registers
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22

// Gyro sensitivity in dps/LSB
#define GYRO_SENSITIVITY 0.00875

// Accelerometer sensitivity in mg/LSB
#define ACCEL_SENSITIVITY 0.061

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_accel_gyro(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    int16_t x, y, z, gx, gy;

    // Burst read to get 12 bytes of data
    int16_t data[12];
    for (int i = 0; i < 12; i++) {
        data[i] = i2c_read_byte(handle, OUTX_L_G + i);
        if (data[i] < 0) {
            fprintf(stderr, "Error reading OUTX_L_G register %d\n", i);
            return -1;
        }
    }

    // Convert to physical units
    *accel_x = (int16_t)((data[0] << 8) | data[1]);
    *accel_y = (int16_t)((data[2] << 8) | data[3]);
    *accel_z = (int16_t)((data[4] << 8) | data[5]);
    *gyro_x = (int16_t)((data[6] << 8) | data[7]);
    *gyro_y = (int16_t)((data[8] << 8) | data[9]);
    *gyro_z = (int16_t)((data[10] << 8) | data[11]);

    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle) {
    // Set CTRL1_XL to +-2g, 104 Hz
    if (i2c_write_byte(handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error setting CTRL1_XL\n");
        return -1;
    }

    // Set CTRL2_G to +-250 dps, 104 Hz
    if (i2c_write_byte(handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error setting CTRL2_G\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    time_t last_read_time = time(NULL);

    while (!terminate) {
        // Read accelerometer and gyroscope data
        if (read_accel_gyro(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Get current time
            time_t current_time = time(NULL);

            // Check WHO_AM_I register
            int who_am_i = i2c_read_byte(i2c_handle, 0x0F);
            if (who_am_i != 0x6B) {
                fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
                continue; // Skip to the next iteration
            }

            // Print data with timestamp
            time_t current_time = time(NULL);
            struct tm *timeinfo = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n",
                   timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Print sensor ID
            printf("Sensor ID: 0x%02X\n", who_am_i);

            // Print sensor data every 100ms
            if (difftime(current_time, last_read_time) >= 0.1) {
                last_read_time = current_time;
                gpioDelay(100); // Delay for 100ms
            }
        } else {
            fprintf(stderr, "Error reading accelerometer and gyroscope data\n");
        }
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

