int init_fxos8700() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0D);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I register value mismatch: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG2
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Configure M_CTRL_REG1
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }

    // Configure M_CTRL_REG2
