#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Tilt threshold
#define TILT_THRESHOLD 30.0

// Global variables
int i2c_fd;
bool running = true;

// Function prototypes
int init_adxl345();
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angles(int16_t x, int16_t y, int16_t z);
float atan2(float y, float x);
void log_tilt_event(float tilt_angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("\nExiting gracefully...\n");
}

// Initialize the ADXL345 accelerometer
int init_adxl345() {
    // Wake up the device
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device.\n");
        return -1;
    }
    if (i2c_write_byte(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not write to POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_read_device(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate tilt angles using atan2
float calculate_tilt_angles(int16_t x, int16_t y, int16_t z) {
    float x_mag = sqrt(x * x);
    float y_mag = sqrt(y * y);
    float z_mag = sqrt(z * z);

    float tilt_x = atan2(y_mag, x_mag);
    float tilt_y = atan2(-z_mag, sqrt(x_mag * x_mag + y_mag * y_mag));

    if (fabs(tilt_x) > M_PI_2) {
        tilt_x = -tilt_x;
    }
    if (fabs(tilt_y) > M_PI_2) {
        tilt_y = -tilt_y;
    }

    return tilt_x + tilt_y;
}

// Log tilt event to file
void log_tilt_event(float tilt_angle) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Tilt Angle: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, tilt_angle);

    fclose(fp);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device. Check permissions and I2C bus.\n");
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized successfully.\n");

    // Main loop
    while (running) {
        int16_t x, y, z;
        float tilt_angle;

        // Read acceleration data
        if (read_acceleration_data(&x, &y, &z) == 0) {
            // Calculate tilt angles
            tilt_angle = calculate_tilt_angles(x, y, z);

            // Log tilt event
            log_tilt_event(tilt_angle);

            // Check for tilt event
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                printf("Tilt angle exceeded threshold: %.2f degrees\n", tilt_angle);
            }
        } else {
            fprintf(stderr, "Error: Could not read acceleration data.\n");
        }

        // Delay for 100 ms
        usleep(100000); // 100 ms
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

