int read_sound_sensor();
int count_high_readings(int threshold);
void print_alert(int count);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to count high-readings within a window
int count_high_readings(int threshold) {
    int count = 0;
    for (int i = 0; i < SAMPLE_COUNT_WINDOW_SIZE; i++) {
        if (read_sound_sensor() == 1) {
            count++;
            gpioDelay(SAMPLE_INTERVAL_MS); // Delay to avoid busy-waiting
        }
    }
    return count >= threshold;
}

// Function to print an alert
void print_alert(int count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (count > ALERT_THRESHOLD) {
        printf("%s ALERT: %d high-readings detected!\n", timestamp, count);
    } else {
        printf("%s Normal: %d high-readings detected.\n", timestamp, count);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring sound levels... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        if (sound_level == 1) {
            // Count high-readings within the window
            int count = count_high_readings(threshold);

            // Print alert if threshold is exceeded
            if (count > ALERT_THRESHOLD) {
                print_alert(count);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay to avoid busy-waiting
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

