    } else if (strcmp(code, "44444") == 0) {
        return 6; // Success
    } else if (strcmp(code, "55555") == 0) {
        return 7; // Success
    } else if (strcmp(code, "66666") == 0) {
        return 8; // Success
    } else if (strcmp(code, "77777") == 0) {
        return 9; // Success
    } else {
        return 0; // Invalid code
    }
}

// Function to set the lock state (Door A or Door B)
int set_lock_state(int door_pin, int state) {
    if (state == 1) {
        gpioWrite(door_pin, 1); // Lock
    } else {
        gpioWrite(door_pin, 0); // Unlock
    }
    return 0;
}

// Function to get the current lock state (Door A or Door B)
int get_lock_state(int door_pin) {
    return gpioRead(door_pin);
}

