    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_PIN, PI_OUTPUT);
    gpioSetMode(DOOR_B_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate a random code
        char code[CODE_LENGTH];
        sprintf(code, "%06d", generate_random_code());

        // Validate the code
        if (validate_code(code) == 0) {
            // Log the code
            log_access(code);

            // Set the lock state
            set_lock_state(DOOR_A_PIN, 1);
            set_lock_state(DOOR_B_PIN, 1);

            // Wait for 5 seconds
            gpioDelay(5000000); // 5 seconds = 5000000 microseconds

            // Unlock the doors
            set_lock_state(DOOR_A_PIN, 0);
            set_lock_state(DOOR_B_PIN, 0);

            // Log the successful entry
            log_access(code);
        } else {
            // Log the failed entry attempt
            log_access("Invalid Code");
        }

        // Wait for a short period
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    gpioWrite(DOOR_A_PIN, 0); // Ensure doors are locked
    gpioWrite(DOOR_B_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

