#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23

// Define the sensor command
#define BH1750_CMD_HIGH_RES_MODE 0x21

// Define the log file name
#define LOG_FILE "light_log.txt"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a command to the BH1750FVI sensor
int write_bh1750(int fd, uint8_t command) {
    uint8_t buf[2];
    buf[0] = command;
    buf[1] = 0x00; // Dummy byte for high-resolution mode
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750FVI sensor
int read_bh1750(int fd, uint8_t *data) {
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to calculate illuminance in lux
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log data to a file
int log_data(const char *filename, time_t timestamp, float lux) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%ld,%.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        uint8_t raw_value;
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Calculate illuminance
            float lux = calculate_lux(raw_value);

            // Get current timestamp
            time_t now = time(NULL);

            // Log the data
            if (log_data(LOG_FILE, now, lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Timestamp: %ld, Lux: %.2f\n", now, lux);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

