#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define SAMPLE_RATE 200 // Hz
#define LOG_FILE "frequency_log.txt"
#define PORT 12345
#define SECRET "MySecretKey"
#define MAX_ELECTRODE 12
#define MAX_FILTERED_DATA_VALUE (1 << 16) // Maximum filtered data value
#define MAX_FREQUENCY 880.0
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY MAX_FREQUENCY
#define MIN_FREQUENCY MIN_FREQUENCY
#define LOG_INTERVAL_MS 200

// MPR121 Configuration
#define MPR121_CONFIG_REG 0x5E
#define MPR121_ELECTRODE_CONFIG_REG 0x5B
#define MPR121_TOUCH_THRESHOLD_REG 0x5C
#define MPR121_TOUCH_THRESHOLD_VALUE 0x00
#define MPR121_RELEASE_THRESHOLD_REG 0x5D
#define MPR121_RELEASE_THRESHOLD_VALUE 0x00
#define MPR121_TOUCH_DATA_REG 0x5E
#define MPR121_RELEASE_DATA_REG 0x5F
#define MPR121_TOUCH_DATA_VALUE_REG 0x5E
#define MPR121_RELEASE_DATA_VALUE_REG 0x5F
#define MPR121_TOUCH_DATA_VALUE_MAX (MAX_FILTERED_DATA_VALUE - 1)
#define MPR121_RELEASE_DATA_VALUE_MAX (MAX_FILTERED_DATA_VALUE - 1)

// Tone Parameters
#define TONE_FREQUENCY_MIN_HZ 220.0
#define TONE_FREQUENCY_MAX_HZ 880.0
#define TONE_DURATION_MS 5000

// Global Variables
int i2c_handle;
int pwm_gpio;
FILE *log_file;
int running = 1;

// Function Prototypes
int initialize_mpr121();
int read_mpr121_touch_data();
int read_mpr121_release_data();
int map_filtered_data_to_frequency(int filtered_data);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);
void cleanup();

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to soft reset MPR121.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrodes
    for (int i = 0; i < MAX_ELECTRODE; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_REG, i) < 0) {
            fprintf(stderr, "Error: Failed to configure electrode %d.\n", i);
            return -1;
        }
        gpioDelay(10); // Delay after configuring each electrode
    }

    // Configure touch and release thresholds
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD_REG, MPR121_TOUCH_THRESHOLD_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", 0);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD_REG, MPR121_RELEASE_THRESHOLD_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", 0);
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_mpr121_touch_data() {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCH_DATA_REG, buffer, 2) < 0) {
        fprintf(stderr, "Error: Failed to read touch data.\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to read release data from the MPR121
int read_mpr121_release_data() {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_RELEASE_DATA_REG, buffer, 2) < 0) {
        fprintf(stderr, "Error: Failed to read release data.\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to map filtered data to frequency
int map_filtered_data_to_frequency(int filtered_data) {
    // Linear mapping
    int frequency = (int)(filtered_data * (TONE_FREQUENCY_MAX_HZ - TONE_FREQUENCY_MIN_HZ) / (MAX_FILTERED_DATA_VALUE - MIN_FILTERED_DATA_VALUE) + MIN_FREQUENCY);
    if (frequency < TONE_FREQUENCY_MIN_HZ) frequency = TONE_FREQUENCY_MIN_HZ;
    if (frequency > TONE_FREQUENCY_MAX_HZ) frequency = TONE_FREQUENCY_MAX_HZ;
    return frequency;
}

// Function to play a tone
void play_tone(int frequency) {
    gpioPWM(pwm_gpio, frequency, 0); // Set PWM duty cycle to 0 for duration
}

// Function to log frequency data
void log_frequency(int frequency) {
    fprintf(log_file, "Frequency: %d Hz\n", frequency);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (pwm_gpio >= 0) {
        gpioPWM(pwm_gpio, 0, 0); // Stop PWM
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
