#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE_REG 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Y_MSB 0x05
#define HMC5883L_DATA_Y_LSB 0x06
#define HMC5883L_DATA_Z_MSB 0x07
#define HMC5883L_DATA_Z_LSB 0x08

// Configuration values
#define HMC5883L_GAIN_1_3 0x00
#define HMC5883L_MODE_CONT 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void calculate_hard_iron_offsets(magnetometer_data_t *data, magnetometer_data_t *running_average);
void apply_offsets(magnetometer_data_t *data, magnetometer_data_t *running_average);
void print_offsets(magnetometer_data_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the HMC5883L magnetometer
int initialize_hmc5883l() {
    // Configure the magnetometer
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, HMC5883L_GAIN_1_3) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, HMC5883L_MODE_REG) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set gain to 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_GAIN_1_3, HMC5883L_GAIN_1_3) < 0) {
        fprintf(stderr, "Error writing to gain register\n");
        return -1;
    }

    // Set mode to continuous mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE_REG, HMC5883L_MODE_REG) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data from the HMC5883L
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X, Y, Z, X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = data.y = data.z = 0; // Set to 0 on error
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate hard-iron offsets
void calculate_hard_iron_offsets(magnetometer_data_t *data, magnetometer_data_t *running_average) {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int16_t x_sum_prev = 0, y_sum_prev = 0, z_sum_prev = 0;

    for (int i = 0; i < 100; i++) {
        magnetometer_data_t current_data = *running_average;
        x_sum += current_data.x;
        y_sum += current_data.y;
        z_sum += current_data.z;
        x_sum_prev = x_sum;
        y_sum_prev = y_sum;
        z_sum_prev = z_sum;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    running_average->x = (int16_t)((x_sum_prev + x_sum) / 100);
    running_average->y = (int16_t)((y_sum_prev + y_sum) / 100);
    running_average->z = (int16_t)((z_sum_prev + z_sum) / 100);
}

// Apply offsets to the latest raw reading
void apply_offsets(magnetometer_data_t *data, magnetometer_data_t *running_average) {
    data->x -= running_average->x;
    data->y -= running_average->y;
    data->z -= running_average->z;
}

// Print the offset-corrected X, Y, and Z values
void print_offsets(magnetometer_data_t *data) {
    printf("X: %d, Y: %d, Z: %d\n", data->x, data->y, data->z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    magnetometer_data_t running_average;
    magnetometer_data_t data;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    while (!terminate) {
        // Read magnetometer data
        data = read_magnetometer_data();

        // Calculate hard-iron offsets
        calculate_hard_iron_offsets(&data, &running_average);

        // Apply offsets
        apply_offsets(&data, &running_average);

        // Print offsets
        print_offsets(&data);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and offset-corrected values
        printf("%s: X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

