// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27

// Define UART ports
#define UART0_PORT "/dev/serial0"
#define UART1_PORT "/dev/serial1"

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Define the expected code
#define EXPECTED_CODE "123456"

// Define the log file
#define LOG_FILE "authentication.log"

// Global variables
int uart0_fd, uart1_fd;
FILE *log_file;

// Function prototypes
int initialize_gpio();
int initialize_uart(int port, int baudrate);
int read_uart(int fd, char *buffer, int max_len);
int validate_code(const char *code);
int unlock_doors(int lock1_pin, int lock2_pin);
int log_message(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    unlock_doors(LOCK1_PIN, LOCK2_PIN); // Unlock both doors
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);

    gpioWrite(LOCK1_PIN, 0); // Initially lock both doors
    gpioWrite(LOCK2_PIN, 0);

    return 0;
}

// Initialize UART ports
int initialize_uart(int port, int baudrate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baudrate);
    cfsetispeed(&tty, baudrate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG | IEXTEN);
    tty.c_lflag &= ~(ECHOCTL | ECHOKE | FLUSHO);

    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART port
int read_uart(int fd, char *buffer, int max_len) {
