#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN_1 4
#define PIR_PIN_2 17
#define RELAY_PIN_1 27
#define RELAY_PIN_2 22

// Define constants
#define MOTION_THRESHOLD_MS 1000 // 1 second
#define DEFAULTS_FILE "defaults.txt"

// Global variables
static struct gpiod_line *pir_lines[2];
static struct gpiod_line *relay_lines[2];
static int relay_state[2] = {0, 0}; // 0 = off, 1 = on
static int motion_detected[2] = {0, 0}; // 0 = no motion, 1 = motion
static int failsafe_triggered = 0;
static int running = 1;

// Function prototypes
int initialize_gpio();
int request_input(int line);
int request_output(int line);
int get_value(int line);
int set_value(int line, int value);
void motion_detected_callback(int line, int value);
void signal_handler(int signum);
void cleanup();

// Function to initialize GPIO lines
int initialize_gpio() {
    if (gpiod_line_request_input(pir_lines[0], "PIR_1") < 0) {
        syslog(LOG_ERR, "Failed to request input for PIR_1");
        return -1;
    }
    if (gpiod_line_request_input(pir_lines[1], "PIR_2") < 0) {
        syslog(LOG_ERR, "Failed to request input for PIR_2");
        return -1;
    }
    if (gpiod_line_request_output(relay_lines[0], "Relay_1") < 0) {
        syslog(LOG_ERR, "Failed to request output for Relay_1");
        return -1;
    }
    if (gpiod_line_request_output(relay_lines[1], "Relay_2") < 0) {
        syslog(LOG_ERR, "Failed to request output for Relay_2");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[0], 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay_1 to off");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[1], 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay_2 to off");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[0], 1) < 0) {
        syslog(LOG_ERR, "Failed to set relay_1 to on");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[1], 1) < 0) {
        syslog(LOG_ERR, "Failed to set relay_2 to on");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[0], 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay_1 to off");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[1], 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay_2 to off");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[0], 1) < 0) {
        syslog(LOG_ERR, "Failed to set relay_1 to on");
        return -1;
    }
    if (gpiod_line_set_value(relay_lines[1], 1) < 0) {
        syslog(LOG_ERR, "Failed to set relay_2 to on");
        return -1;
    }
    return 0;
}

// Function to request input from a GPIO line
int request_input(int line) {
    if (gpiod_line_request_input(line, NULL) < 0) {
        syslog(LOG_ERR, "Failed to request input on line %d", line);
        return -1;
    }
    return 0;
}

// Function to request output from a GPIO line
int request_output(int line) {
    if (gpiod_line_request_output(line, NULL) < 0) {
        syslog(LOG_ERR, "Failed to request output on line %d", line);
        return -1;
    }
    return 0;
}

// Function to get the current value of a GPIO line
int get_value(int line) {
    return gpiod_line_get_value(line);
}

// Function to set the value of a GPIO line
int set_value(int line, int value) {
    return gpiod_line_set_value(line, value);
}

// Callback function for motion detection
void motion_detected_callback(int line, int value) {
    if (value == 1) {
        if (!failsafe_triggered) {
            syslog(LOG_INFO, "Motion detected on PIR_%d", line);
            failsafe_triggered = 1;
            if (request_output(relay_lines[0]) < 0) {
                syslog(LOG_ERR, "Failed to energize relay on PIR_%d", line);
            }
        }
    } else if (value == 0) {
        if (failsafe_triggered) {
            syslog(LOG_INFO, "Motion stopped on PIR_%d", line);
            failsafe_triggered = 0;
            if (request_output(relay_lines[0]) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay on PIR_%d", line);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release GPIO lines
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO lines...");
    for (int i = 0; i < 2; i++) {
        if (pir_lines[i]) {
            gpiod_line_release(pir_lines[i]);
        }
        if (relay_lines[i]) {
            gpiod_line_release(relay_lines[i]);
        }
    }
    syslog(LOG_INFO, "GPIO lines released.");
    closelog();
    exit(0);
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        return 1;
    }

    // Request input for PIR sensors
    if (request_input(PIR_PIN_1) < 0 || request_input(PIR_PIN_2) < 0) {
        syslog(LOG_ERR, "Failed to request input for PIR sensors");
        cleanup();
        return 1;
    }

    // Set up motion detection callbacks
    if (gpiod_line_request_event(pir_lines[0], 0, motion_detected_callback, NULL) < 0 ||
        gpiod_line_request_event(pir_lines[1], 0, motion_detected_callback, NULL) < 0) {
        syslog(LOG_ERR, "Failed to request event for PIR sensors");
        cleanup();
        return 1;
    }

    // Set up relay control callbacks
    if (gpiod_line_request_event(relay_lines[0], 0, motion_detected_callback, NULL) < 0 ||
        gpiod_line_request_event(relay_lines[1], 0, motion_detected_callback, NULL) < 0) {
        syslog(LOG_ERR, "Failed to request event for relay control");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Check if motion is detected on any PIR sensor
        if (motion_detected[0] || motion_detected[1]) {
            // De-energize the relay
            if (failsafe_triggered) {
                syslog(LOG_WARNING, "Failsafe triggered, de-energizing relay");
                set_value(relay_lines[0], 0);
                set_value(relay_lines[1], 0);
                failsafe_triggered = 0;
            }
            failsafe_triggered = 0; // Reset failsafe
        } else {
            // Energize the relay
            if (!failsafe_triggered) {
                syslog(LOG_INFO, "Motion detected, energizing relay");
                set_value(relay_lines[0], 1);
                set_value(relay_lines[1], 1);
                failsafe_triggered = 1;
            }
        }

        // Sleep for a short interval
        usleep(500000); // 0.5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

