                set_value(relay_lines[0], 0);
                set_value(relay_lines[1], 0);
                failsafe_triggered = 0;
            }
            failsafe_triggered = 0; // Reset failsafe
        } else {
            // Energize the relay
            if (!failsafe_triggered) {
                syslog(LOG_INFO, "Motion detected, energizing relay");
                set_value(relay_lines[0], 1);
                set_value(relay_lines[1], 1);
                failsafe_triggered = 1;
            }
        }

        // Sleep for a short interval
        usleep(500000); // 0.5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

