#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 3

// Define debounce time (in seconds)
#define DEBOUNCE_TIME 1

// Global variables
static volatile int relay_active = 0;
static volatile int sound_detected = 0;
static volatile int last_sound_state = 0;
static volatile int debounce_count = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay(int duration_seconds);
void log_alarm();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    // Set sound sensor pin as input
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Read the sound sensor
int read_sound_sensor() {
    int sensor_value = gpioRead(SOUND_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sound sensor value\n");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Activate the relay for a specified duration
void activate_relay(int duration_seconds) {
    if (duration_seconds <= 0) {
        fprintf(stderr, "Invalid duration for relay activation\n");
        return;
    }

    if (running) {
        printf("Relay already active, exiting.\n");
        return;
    }

    printf("Activating relay for %d seconds...\n", duration_seconds);
    gpioWrite(RELAY_PIN, 1); // Turn on the relay
    gpioDelay(duration_seconds * 1000); // Delay for duration_seconds
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    printf("Relay deactivated.\n");
}

// Log the alarm event to a file
void log_alarm() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Alarm triggered\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected_value = read_sound_sensor();
        if (sound_detected_value < 0) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break;
        }

        if (sound_detected_value == 1) {
            // Debounce mechanism
            if (sound_detected_value == last_sound_state) {
                debounce_count++;
                if (debounce_count >= DEBOUNCE_TIME) {
                    printf("Sound detected, activating relay.\n");
                    activate_relay(ALARM_DURATION);
                    log_alarm();
                    sound_detected = 1; // Set flag to indicate alarm
                    last_sound_state = sound_detected_value;
                    debounce_count = 0; // Reset debounce count
                }
            }
        } else {
            sound_detected_value = 0; // Reset sound_detected_value
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

