#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define ERROR_LOG_FILE "co2_error.log"
#define CO2_LOG_FILE "co2_log.json"
#define TIMEOUT_MS 100

int uart_fd;
FILE *log_file;

// Function to calculate checksum
unsigned char calculate_checksum(unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Function to read data from UART
int read_uart(int fd, unsigned char *buffer, int len) {
    int bytes_read = serDataAvailable(fd);
    if (bytes_read > 0) {
        int bytes_to_read = bytes_read < len ? bytes_read : len;
        if (serRead(fd, buffer, bytes_to_read) == bytes_to_read) {
            return bytes_read;
        } else {
            fprintf(stderr, "Error reading from UART: %d bytes read, expected %d\n", bytes_read, len);
            return -1; // Indicate error
        }
    } else {
        return 0; // Indicate no data available
    }
}

// Function to parse CO2 data
int parse_co2_data(unsigned char *data, int len, float *co2) {
    if (len != 9) {
        fprintf(stderr, "Error: Invalid data length: %d\n", len);
        return -1;
    }

    *co2 = (float)((data[0] << 8) | data[1]) / 10.0; // CO2 concentration in ppm

    // Validate checksum
    if (calculate_checksum(data, 2) != data[2]) {
        fprintf(stderr, "Error: Checksum mismatch\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(float ppm, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%s\n", timestamp, ppm, error_message);
        fflush(log_file); // Flush to ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    serClose(uart_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open UART port
    uart_fd = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for default flags
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CO2_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO2_LOG_FILE);
        serClose(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char buffer[9];
    float co2;
    char error_message[100];

    printf("CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read data from UART
        if (read_uart(uart_fd, buffer, 9) == 9) {
            // Parse CO2 data
            if (parse_co2_data(buffer, 9, &co2) == 0) {
                // Log data
                if (log_data(co2, error_message) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error parsing CO2 data\n");
            }
        } else {
            fprintf(stderr, "Error reading from UART\n");
        }

        // Wait for a short period
        gpioDelay(5000); // 5 seconds
    }

    return 0;
}

