void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_fd) {
    char buf[2];
    int raw_value;

    // Send start measurement command (Continuous High Resolution Mode)
    if (i2cWriteByte(i2c_fd, 0x00) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete (at least 120 ms)
    gpioDelay(120);

    // Read 2 bytes of data
    if (i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine the two bytes to form the raw lux value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

