    i2c_fd = i2cOpen(BH1750_I2C_BUS, BH1750_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read lux value from BH1750 sensor
        int raw_value = read_bh1750(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
            continue; // Skip to the next iteration
        }

        // Convert lux value to lux
        float lux = convert_lux(raw_value);

        // Control relays based on lux threshold
        control_relays(0, 0, 0); // Turn off all relays initially

        // Check if lux is below threshold
        if (lux < LUX_THRESHOLD_RED) {
            control_relays(1, 0, 0); // Turn on RED relay
        } else if (lux < LUX_THRESHOLD_GREEN) {
            control_relays(0, 1, 0); // Turn on GREEN relay
        } else if (lux < LUX_THRESHOLD_BLUE) {
            control_relays(0, 0, 1); // Turn on BLUE relay
        } else {
            control_relays(0, 0, 0); // Turn off all relays
        }

        // Log data
        time_t now = time(NULL);
        log_data(now, lux, 0, 0, 0);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

