#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Distance thresholds
#define DISTANCE_THRESHOLD_A 10
#define DISTANCE_THRESHOLD_B 50

// PWM frequency
#define PWM_FREQUENCY 1000

// Motor speed ranges
#define MOTOR_A_SPEED_MIN 0
#define MOTOR_A_SPEED_MAX 255

#define MOTOR_B_SPEED_MIN 0
#define MOTOR_B_SPEED_MAX 255

// Function prototypes
int read_distance(int gpio);
int map_distance_to_speed(int distance);
void set_motor_speed(int motor_gpio, int speed);
void stop_motors();
void signal_handler(int signal);

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Function to read distance from a sensor
int read_distance(int gpio) {
    // Simulate distance reading based on a simple linear relationship
    // with distance (10-100 cm)
    int distance = (int)((100 - gpio) / 10.0); // Linear mapping
    if (distance < 0) distance = 0;
    if (distance > 100) distance = 100;
    return distance;
}

// Function to map distance to motor speed
int map_distance_to_speed(int distance) {
    // Linear mapping: closer distance -> higher speed
    int speed_range = MOTOR_A_SPEED_MAX - MOTOR_A_SPEED_MIN;
    int speed = MOTOR_A_SPEED_MIN + (int)((distance - DISTANCE_THRESHOLD_A) / (DISTANCE_THRESHOLD_B - DISTANCE_THRESHOLD_A) * (MOTOR_A_SPEED_MAX - MOTOR_A_SPEED_MIN));
    if (speed < 0) speed = 0;
    if (speed > MOTOR_A_SPEED_MAX) speed = MOTOR_A_SPEED_MAX;
    return speed;
}

// Function to set motor speed
void set_motor_speed(int motor_gpio, int speed) {
    if (speed < 0) speed = 0;
    if (speed > MOTOR_A_SPEED_MAX) speed = MOTOR_A_SPEED_MAX;

    gpioPWM(motor_gpio, speed);
}

// Function to stop motors
void stop_motors() {
    set_motor_speed(MOTOR_A_IN1, 0);
    set_motor_speed(MOTOR_A_IN2, 0);
    set_motor_speed(MOTOR_B_IN3, 0);
    set_motor_speed(MOTOR_B_IN4, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set initial motor speeds
    set_motor_speed(MOTOR_A_IN1, MOTOR_A_SPEED_MIN);
    set_motor_speed(MOTOR_A_IN2, MOTOR_A_SPEED_MIN);
    set_motor_speed(MOTOR_B_IN3, MOTOR_B_SPEED_MIN);
    set_motor_speed(MOTOR_B_IN4, MOTOR_B_SPEED_MIN);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance sensor control program. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int distance = read_distance(MOTOR_A_IN1);
        int speed_a = map_distance_to_speed(distance);
        int speed_b = map_distance_to_speed(distance);

        set_motor_speed(MOTOR_A_IN1, speed_a);
        set_motor_speed(MOTOR_A_IN2, speed_a);
        set_motor_speed(MOTOR_B_IN3, speed_b);
        set_motor_speed(MOTOR_B_IN4, speed_b);

        gpioDelay(100); // Delay for 100ms
    }

    // Stop motors before exiting
    stop_motors();

    return 0;
}

