#include <sys/time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Servo GPIO pin
#define SERVO_PIN 18

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_mpu6050(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void control_servo(int gpio, int duty_cycle);
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int gpio, int duty_cycle);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signum);
    }
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int fd;
    char buf[2];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00; // Wake up the MPU-6050
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from MPU-6050
int read_mpu6050(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    if (read(fd, buf, 14) != 14) {
        perror("Failed to read MPU-6050 data");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    raw_gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    raw_gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    raw_gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    // Convert to g's and degrees per second
    *accel_x = (int16_t)((raw_accel_x / 16384.0) * 9.81);
    *accel_y = (int16_t)((raw_accel_y / 16384.0) * 9.81);
    *accel_z = (int16_t)((raw_accel_z / 16384.0) * 9.81);
    *gyro_x = (int16_t)((raw_gyro_x / 131.0) * 1000); // Assuming gyro is calibrated in degrees/sec
    *gyro_y = (int16_t)((raw_gyro_y / 131.0) * 1000);
    *gyro_z = (int16_t)((raw_gyro_z / 131.0) * 1000);

    return 0;
}

// Control servo
void control_servo(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and 100\n");
        return;
    }

    // Map duty cycle to PWM frequency (0-1000)
    int pwm_frequency = (int)((duty_cycle / 100.0) * PWM_FREQUENCY);

    if (ioctl(gpio, PWM_SET_FREQ, &pwm_frequency) < 0) {
        perror("Failed to set PWM frequency");
    }
}

// Log data to file
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int gpio, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d, %d, %d, %d\n",
            timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, gpio, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    int16_t duty_cycle;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_servo_duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(1, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize servo
    if (ioctl(SERVO_PIN, PWM_SET_FREQ, PWM_FREQUENCY) < 0) {
        perror("Failed to set PWM frequency");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(SERVO_PIN, PWM_SET_MODE, PWM_MODE) < 0) {
        perror("Failed to set PWM mode");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(SERVO_PIN, PWM_SET_MAX, PWM_FREQUENCY) < 0) {
        perror("Failed to set PWM max");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(SERVO_PIN, PWM_SET_MIN, PWM_FREQUENCY) < 0) {
        perror("Failed to set PWM min");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_mpu6050(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Control servo
            control_servo(SERVO_PIN, duty_cycle);

            // Log data
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, SERVO_PIN, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

