#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 200.0     // cm
#define MIN_DISTANCE 2.0       // cm
#define MAX_FREQUENCY 2000.0   // Hz
#define MIN_FREQUENCY 200.0    // Hz
#define SAMPLE_RATE_HZ 50.0     // Hz
#define SAMPLE_DELAY_US 50000.0 // microseconds
#define BUZZER_DURATION_US 10000 // microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int read_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void set_buzzer_duration(float duration);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Read distance from HC-SR04 sensor
int read_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    long start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_tick) < 1000000) {
        // Wait for echo to go high
    }
    long end_tick = gpioTick();

    long pulse_width = end_tick - start_tick;

    if (pulse_width < 0) {
        fprintf(stderr, "Error: Invalid pulse width\n");
        return -1; // Indicate error
    }

    return pulse_width;
}

// Map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return (float)distance / MAX_DISTANCE * MAX_FREQUENCY;
    }
}

// Set buzzer frequency
void set_buzzer_frequency(float frequency) {
    gpioPWM(BUZZER_PIN, frequency);
}

// Set buzzer duration
void set_buzzer_duration(float duration) {
    gpioPWM(BUZZER_PIN, 0); // Turn off buzzer
    gpioDelay(duration * 1000000); // Delay for duration in microseconds
    gpioPWM(BUZZER_PIN, 255); // Turn on buzzer
}

// Cleanup resources
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read distance
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US); // Wait before retrying
            continue;
        }

        // Map distance to frequency
        float frequency = map_distance_to_frequency(distance);

        // Set buzzer frequency
        set_buzzer_frequency(frequency);

        // Set buzzer duration
        set_buzzer_duration(BUZZER_DURATION_US);

        // Delay for SAMPLE_DELAY_US
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

