    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

// Function to set the color of the LED
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to set the proximity value
void set_proximity_value(float value) {
    // Simulate proximity value with sine wave
    float amplitude = 0.5; // Amplitude of the sine wave
    float frequency = PWM_FREQUENCY; // Frequency of the sine wave
    float phase = 0.0; // Phase of the sine wave

    // Calculate the sine wave value
    float sine_value = amplitude * sin(frequency * phase);

    // Map the sine wave value to the proximity range
    proximity = (sine_value + 1.0) / 2.0; // Clamp the value to the range 0.0 to 1.0

    // Update the proximity value
    proximity = proximity * 0.5 + 0.5; // Scale the value to the range 0.0 to 1.0
}

