#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define EARTHQUAKE_THRESHOLD 3
#define TIMEOUT_MS 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int line_fd, line_value;
    time_t last_event_time = 0;
    int event_count = 0;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Poll for events
        line_fd = gpioLineRequestInput(GPIO_PIN);
        if (line_fd < 0) {
            fprintf(stderr, "Error requesting line input: %d\n", line_fd);
            continue; // Continue to the next iteration
        }

        line_value = gpioRead(GPIO_PIN);
        if (line_value < 0) {
            fprintf(stderr, "Error reading line value: %d\n", line_value);
            gpioLineClose(line_fd);
            continue;
        }

        // Check for rising edge
        if (line_value == 1 && last_event_time == 0) {
            time_t current_time = time(NULL);
            if (current_time - last_event_time > TIMEOUT_MS) {
                event_count++;
                last_event_time = current_time;
                printf("Event detected at %ld\n", current_time);
                fprintf(log_file, "%s: Event detected at %ld\n", __TIME__, current_time);
                fflush(log_file);
            }
        }

        // Check for falling edge
        if (line_value == 0 && last_event_time > 0) {
            time_t current_time = time(NULL);
            if (current_time - last_event_time > TIMEOUT_MS) {
                event_count++;
                last_event_time = current_time;
                printf("Event detected at %ld\n", current_time);
                fprintf(log_file, "%s: Event detected at %ld\n", __TIME__, current_time);
                fflush(log_file);
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup
    gpioLineClose(line_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

