#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define relay state
#define RELAY_OFF 0
#define RELAY_ON 1

// Define JSON object structure
typedef struct {
    char timestamp[30];
    char relay_state[10];
} RelayLogEntry;

// Global variables
RelayLogEntry relay_log[10]; // Array to store relay log entries
int relay_log_index = 0;
int relay_state = RELAY_OFF;
int last_touch_time = 0;
int last_relay_state = RELAY_OFF;

// Function prototypes
int read_touch_sensor();
int toggle_relay();
int log_relay_event();
void signal_handler(int signal);
void cleanup();

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay() {
    if (relay_state == RELAY_ON) {
        relay_state = RELAY_OFF;
        gpioWrite(RELAY_PIN, RELAY_OFF);
        printf("Relay turned OFF\n");
    } else {
        relay_state = RELAY_ON;
        gpioWrite(RELAY_PIN, RELAY_ON);
        printf("Relay turned ON\n");
    }
    return 0;
}

// Function to log a relay event to the log file
int log_relay_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (relay_log_index < 10) {
        strcpy(relay_log[relay_log_index].timestamp, timestamp);
        strcpy(relay_log[relay_log_index].relay_state, relay_state == RELAY_ON ? "ON" : "OFF");
        relay_log_index++;
    } else {
        fprintf(stderr, "Error: Log file is full. Cannot log event.\n");
        return -1;
    }

    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening relay_log.json for writing!\n");
        return -1;
    }

    fprintf(fp, "{\"timestamp\":\"%s\", \"relay_state\":\"%s\"}", timestamp, relay_state == RELAY_ON ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, RELAY_OFF); // Turn off the relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on TOUCH_SENSOR_PIN
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Register ISR for touch sensor
    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, EITHER_EDGE, 0, touch_isr) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == RELAY_ON) {
            toggle_relay();
            log_relay_event();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

