#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Gyroscope sensitivity factor (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// I2C file descriptor
int i2c_fd;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_i2c(int bus, int addr);
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_gyro_data(int16_t raw_data, float *gyro_x, float *gyro_y, float *gyro_z);
void log_data(float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize I2C interface
int init_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    ssize_t bytes_read = read(fd, buf, sizeof(buf));
    if (bytes_read != sizeof(buf)) {
        perror("Error reading gyro data");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw gyroscope data to degrees/second
void convert_gyro_data(int16_t raw_data, float *gyro_x, float *gyro_y, float *gyro_z) {
    *gyro_x = (float)raw_data / GYRO_SENSITIVITY;
    *gyro_y = (float)raw_data / GYRO_SENSITIVITY;
    *gyro_z = (float)raw_data / GYRO_SENSITIVITY;
}

// Log gyroscope data to file
void log_data(float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(1, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Wake the sensor
    if (write(i2c_fd, &PWR_MGMT_1, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    float gyro_x, gyro_y, gyro_z;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &raw_gyro_x, &raw_gyro_y, &raw_gyro_z) == 0) {
            // Convert to degrees/second
            convert_gyro_data(raw_gyro_z, &gyro_x, &gyro_y, &gyro_z);

            // Log the data
            log_data(gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        usleep(10000); // 10 Hz
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

