    gpioSetMode(LOCK_PIN, PI_OUTPUT);
    gpioSetMode(UNLOCK_PIN, PI_OUTPUT);
    gpioSetMode(IN1_PIN, PI_OUTPUT);
    gpioSetMode(IN2_PIN, PI_OUTPUT);
    gpioSetMode(IN3_PIN, PI_OUTPUT);
    gpioSetMode(IN4_PIN, PI_OUTPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(IN1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(IN2_PIN, PI_PUD_UP);
    gpioSetPullUpDown(IN3_PIN, PI_PUD_UP);
    gpioSetPullUpDown(IN4_PIN, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Automatic Door Lock Program\n");

    // Main loop
    while (program_running) {
        // Debounce button input
        debounce_button();

        // Check for LOCK button press
        if (gpioRead(LOCK_PIN) == 0) {
            printf("Locking...\n");
            lock_motor();
        }

        // Check for UNLOCK button press
        if (gpioRead(UNLOCK_PIN) == 0) {
            printf("Unlocking...\n");
            unlock_motor();
        }

        gpioDelay(50); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works)
    gpioTerminate();
    return 0;
}

