// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SOUND_SPEED 343.0 // m/s
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 200.0 // cm
#define MIN_GUARD 60.0    // ms
#define MAX_GUARD 60.0    // ms
#define TIMEOUT_US 50000    // 50 ms timeout

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_init();
int gpio_deinit();
int gpio_set_direction(int pin, const char *direction);
int gpio_set_edge(int pin, const char *edge);
int gpio_get_edge(int pin, char *edge, int len);
int gpio_get_value(int pin);
float calculate_distance(int pulse_width);
int log_distance(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpio_set_direction(TRIGGER_PIN, "out") != 0) {
        fprintf(stderr, "Failed to set trigger pin direction\n");
        gpioTerminate();
        return -1;
    }

    if (gpio_set_direction(ECHO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set echo pin direction\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Deinitialize GPIO pins
int gpio_deinit() {
    gpioTerminate();
    return 0;
}

// Set GPIO pin direction
int gpio_set_direction(int pin, const char *direction) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%c", direction);
    if (gpioWrite(pin, gpioRead(pin)) != 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        return -1;
    }
    return 0;
}

// Set GPIO pin edge
int gpio_set_edge(int pin, const char *edge) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%c", edge);
    if (gpioWrite(pin, gpioRead(pin)) != 0) {
        fprintf(stderr, "Failed to set GPIO edge\n");
        return -1;
    }
    return 0;
}

// Get GPIO pin value
int gpio_get_value(int pin) {
    return gpioRead(pin);
}

// Get GPIO pin edge
int gpio_get_edge(int pin, char *edge, int len) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%c", gpioRead(pin));
    if (gpioStrCat(edge, buffer, len) != 0) {
        fprintf(stderr, "Failed to get GPIO edge\n");
        return -1;
    }
    return 0;
}

// Get GPIO pin value with timeout
int gpio_get_value_with_timeout(int pin, int timeout_us) {
    int value = gpio_get_value(pin);
    if (value == -1) {
        fprintf(stderr, "Error reading GPIO value\n");
        return -1;
    }
    gpioDelay(timeout_us);
    return gpio_get_value(pin);
}

// Calculate distance in centimeters
float calculate_distance(int pulse_width) {
    return (float)pulse_width * 0.01715;
}

// Log distance to file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_deinit();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (program_running) {
        int pulse_width;
        int timeout_count = 0;

        // Wait for trigger to be released (active-high)
        while (gpio_get_value_with_timeout(TRIGGER_PIN, TIMEOUT_US) == 1) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
            if (timeout_count > 100) {
                fprintf(stderr, "Timeout waiting for trigger release\n");
                break; // Exit loop if timeout occurs
            }
        }

        if (gpio_get_value_with_timeout(TRIGGER_PIN, TIMEOUT_US) == 0) {
            gpio_set_edge(TRIGGER_PIN, "rising"); // Set rising edge
            gpioDelay(10); // Wait for echo
            gpio_set_edge(TRIGGER_PIN, "falling"); // Set falling edge

            // Measure pulse width
            timeout_count = 0;
            while (gpio_get_value_with_timeout(TRIGGER_PIN, TIMEOUT_US) == 0) {
                timeout_count++;
                if (timeout_count > 100) {
                    fprintf(stderr, "Timeout waiting for echo\n");
                    break; // Exit loop if timeout occurs
                }
            }

            pulse_width = gpio_get_value_with_timeout(ECHO_PIN, TIMEOUT_US);
            if (pulse_width == -1) {
                fprintf(stderr, "Error reading pulse width\n");
                break; // Exit loop if pulse width read fails
            }

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Log distance
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }

            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Timeout waiting for trigger release\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_deinit();

    printf("Exiting.\n");
    return 0;
}

