// Initialize VL53L1X sensor
int init_vl53l1x() {
    int result;

    // Reset the sensor
    result = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error resetting VL53L1X: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set ranging mode
    result = i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error setting ranging mode: %d\n", result);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int result;
    int distance;

    // Read distance data
    result = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_MSB);
    if (result < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", result);
        return -1;
    }
    distance = (result << 8) | result;

    // Read distance data LSB
    result = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_LSB);
    if (result < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", result);
        return -1;
    }
    distance |= (result << 8) | result;

