#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define PWM duty cycle (0-255)
#define PWM_DUTY_CYCLE 255

// Define the number of relays
#define NUM_RELAYS 4

// Define the PWM period (microseconds)
#define PWM_PERIOD_US 1000000 // 1ms

// Define the number of steps in the sunrise simulation
#define NUM_STEPS 30

// Define the PWM period (milliseconds)
#define PWM_PERIOD_MS 1000 // 1ms

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY_HZ 1000

// Define the PWM range (0-255)
#define PWM_RANGE_HZ 255

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_relay_state(int gpio, int state);
int set_pwm(int gpio, int duty_cycle);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as output
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(RELAY1_GPIO + i, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_GPIO + i);
            gpioTerminate();
            return -1;
        }
        if (gpioSetMode(RELAY2_GPIO + i, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_GPIO + i);
            gpioTerminate();
            return -1;
        }
        if (gpioSetMode(RELAY3_GPIO + i, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY3_GPIO + i);
            gpioTerminate();
            return -1;
        }
        if (gpioSetMode(RELAY4_GPIO + i, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY4_GPIO + i);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Set the state of a relay
int set_relay_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Set the PWM duty cycle
int set_pwm(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Log an event to the smart_lighting.log file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", s, message);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Lighting Simulation Started\n");

    // Main loop
    while (program_running) {
        // Set relay states
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (set_relay_state(RELAY1_GPIO + i, PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Failed to set relay state for GPIO %d\n", RELAY1_GPIO + i);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_relay_state(RELAY2_GPIO + i, PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Failed to set relay state for GPIO %d\n", RELAY2_GPIO + i);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_relay_state(RELAY3_GPIO + i, PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Failed to set relay state for GPIO %d\n", RELAY3_GPIO + i);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_relay_state(RELAY4_GPIO + i, PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Failed to set relay state for GPIO %d\n", RELAY4_GPIO + i);
                program_running = 0; // Exit if any relay fails
                break;
            }
        }

        // Simulate sunrise
        for (int i = 0; i < NUM_STEPS; i++) {
            // Calculate the duty cycle based on the current time
            int duty_cycle = PWM_RANGE_HZ * (i / NUM_STEPS) * (PWM_RANGE_HZ / PWM_PERIOD_HZ);

            // Set the PWM duty cycle
            if (set_pwm(RELAY1_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", RELAY1_GPIO);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_pwm(RELAY2_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", RELAY2_GPIO);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_pwm(RELAY3_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", RELAY3_GPIO);
                program_running = 0; // Exit if any relay fails
                break;
            }
            if (set_pwm(RELAY4_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", RELAY4_GPIO);
                program_running = 0; // Exit if any relay fails
                break;
            }

            // Wait for 1 second
            gpioDelay(PWM_PERIOD_MS);
        }
    }

    // Cleanup
    gpioTerminate();
    printf("Smart Lighting Simulation Stopped\n");

    return 0;
}

