#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    time_t timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_mpu6050(int i2c_handle);
int read_gyroscope_data(int i2c_handle, gyro_data_t *data);
void store_gyro_data(gyro_data_t data);
void process_gyro_data(gyro_data_t data);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int initialize_mpu6050(int i2c_handle) {
    // Wake the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyroscope_data(int i2c_handle, gyro_data_t *data) {
    char buf[6];
    int bytes_read;

    // Read 6 bytes of data starting from GYRO_XOUT_H
    bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data (read %d bytes)\n", bytes_read);
        return -1;
    }

    // Combine the two 16-bit values into a single signed 16-bit value
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    // Convert to degrees/second
    data->x = (int16_t)((raw_x / 16384.0) * 250.0);
    data->y = (int16_t)((raw_y / 16384.0) * 250.0);
    data->z = (int16_t)((raw_z / 16384.0) * 250.0);

    // Store the timestamp
    data->timestamp = time(NULL);

    return 0;
}

// Function to store gyroscope data in the circular buffer
void store_gyro_data(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to process gyroscope data and calculate angular velocity
