#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CE_PIN 8
#define SENSITIVITY 200.0
#define SAMPLE_RATE_HZ 100
#define LOG_FILE "gyro_data.csv"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyro data
typedef struct {
    int16_t x;
    int16_t y;
} gyro_data_t;

// Function prototypes
int spi_read_register(int handle, int reg);
int spi_write_register(int handle, int reg, int value);
int read_gyro_data(int handle, gyro_data_t *data);
void log_data(time_t timestamp, gyro_data_t data);
void signal_handler(int signal);
int initialize_spi(int channel, int speed, int mode);
int initialize_gpio(int pin);
void cleanup();

// Function to read a register from the ADXRS290
int spi_read_register(int handle, int reg) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    tx_buf[0] = (reg & 0x80) | 0x00; // Read bit
    tx_buf[1] = 0x00;

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    return rx_buf[1];
}

// Function to write a register to the ADXRS290
int spi_write_register(int handle, int reg, int value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg & 0x7F) | 0x80; // Write bit
    tx_buf[1] = value;

    if (spiWrite(handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write failed: %d\n", spiWrite(handle, tx_buf, 2));
        return -1;
    }

    return 0;
}

// Function to read gyro data from the ADXRS290
int read_gyro_data(int handle, gyro_data_t *data) {
    int16_t x_raw, y_raw;

    x_raw = spi_read_register(handle, 0x02);
    y_raw = spi_read_register(handle, 0x04);

    if (x_raw < 0 || y_raw < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    data->x = (int16_t)(x_raw >> 8);
    data->y = (int16_t)(y_raw >> 8);

    return 0;
}

// Function to log gyro data to a CSV file
void log_data(time_t timestamp, gyro_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d\n", timestamp_str, data.x, data.y);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

