#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000 // 1 MHz
#define LED_GPIO 17
#define RATE_THRESHOLD 20.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_INTERVAL_MS)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float x_axis_rate;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_gyro_data(int spi_handle, int16_t *x_axis_rate, int16_t *y_axis_rate);
float convert_to_degrees_per_second(int16_t x_axis_rate, int16_t y_axis_rate);
void add_to_buffer(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to read gyroscope data from the ADXRS290
int read_gyro_data(int spi_handle, int16_t *x_axis_rate, int16_t *y_axis_rate) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00}; // Start bit, dummy byte
    char rx_buffer[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *x_axis_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[0]);
    *y_axis_rate = (int16_t)((rx_buffer[3] << 8) | rx_buffer[2]);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t x_axis_rate, int16_t y_axis_rate) {
    return (float)x_axis_rate * 200.0; // 200 LSB/deg/s
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    time(&data.timestamp);
    data.x_axis_rate = convert_to_degrees_per_second(data.x_axis_rate, data.y_axis_rate);
    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(100);        // Delay for 100ms
    gpioWrite(LED_GPIO, 0); // Turn off LED
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();        // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t x_axis_rate, y_axis_rate;
        if (read_gyro_data(spi_handle, &x_axis_rate, &y_axis_rate) == 0) {
            add_to_buffer(gyro_buffer[buffer_index]);
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(SAMPLE_PERIOD_US); // Delay for sample period
    }

    cleanup();
    return 0;
}

