#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 3600

// Define lamp states (0-100% brightness)
int lamp1_state = 100;
int lamp2_state = 100;
int lamp3_state = 100;

// Function prototypes
void lamp1_fade(int duration);
void lamp2_fade(int duration);
void lamp3_fade(int duration);
void cleanup();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to fade a lamp from full brightness to off
void lamp1_fade(int duration) {
    int start_duty_cycle = 100;
    int end_duty_cycle = 0;
    int current_duty_cycle = start_duty_cycle;

    printf("Fading lamp 1 from %d to 0 for %d seconds...\n", start_duty_cycle, duration);

    while (current_duty_cycle > 0 && program_running) {
        gpioPWM(LAMP1_PIN, current_duty_cycle);
        current_duty_cycle -= 1;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    printf("Lamp 1 fully off.\n");
}

// Function to fade a lamp from full brightness to off
void lamp2_fade(int duration) {
    int start_duty_cycle = 100;
    int end_duty_cycle = 0;
    int current_duty_cycle = start_duty_cycle;

    printf("Fading lamp 2 from %d to 0 for %d seconds...\n", start_duty_cycle, duration);

    while (current_duty_cycle > 0 && program_running) {
        gpioPWM(LAMP2_PIN, current_duty_cycle);
        current_duty_cycle -= 1;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    printf("Lamp 2 fully off.\n");
}

// Function to fade a lamp from full brightness to off
void lamp3_fade(int duration) {
    int start_duty_cycle = 100;
    int end_duty_cycle = 0;
    int current_duty_cycle = start_duty_cycle;

    printf("Fading lamp 3 from %d to 0 for %d seconds...\n", start_duty_cycle, duration);

    while (current_duty_cycle > 0 && program_running) {
        gpioPWM(LAMP3_PIN, current_duty_cycle);
        current_duty_cycle -= 1;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    printf("Lamp 3 fully off.\n");
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    gpioPWM(LAMP1_PIN, 0); // Turn off lamp 1
    gpioPWM(LAMP2_PIN, 0); // Turn off lamp 2
    gpioPWM(LAMP3_PIN, 0); // Turn off lamp 3
    gpioTerminate(); // Terminate pigpio
}

int main(int argc, char *argv[]) {
    // Check if the user provided a duration
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the duration
    if (strtol(argv[1], NULL, 10) < 1 || strtol(argv[1], NULL, 10) > 3600) {
        fprintf(stderr, "Invalid duration.  Must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM output
    gpioSetMode(LAMP1_PIN, PI_OUTPUT);
    gpioSetMode(LAMP2_PIN, PI_OUTPUT);
    gpioSetMode(LAMP3_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_PIN, 255);
    gpioSetPWMrange(LAMP2_PIN, 255);
    gpioSetPWMrange(LAMP3_PIN, 255);

    // Set PWM frequency (100 Hz)
    gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade each lamp sequentially
    printf("Fading lamps...\n");
    lamp1_fade(FADE_DURATION);
    lamp2_fade(FADE_DURATION);
    lamp3_fade(FADE_DURATION);

    // Cleanup and exit
    cleanup();
    return 0;
}

