#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pin for the relay
#define RELAY_GPIO 17

// Define I2C address of the MPR121
#define MPR121_ADDR 0x5A

// Define the MPR121 registers
#define MPR121_RESET 0x80
#define MPR121_STOP 0x5E
#define MPR121_ENABLE_ELECTRODE0 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE_TIME 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_RUN_MODE 0x5E

// Define the GPIO pin for the relay
#define RELAY_GPIO_PIN 17

// Define the I2C bus for the MPR121
#define I2C_BUS 1

// Define the log file name
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_mpr121();
int read_mpr121_touch_status();
int write_mpr121_touch_status(int status);
int toggle_relay();
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("I2C initialisation failed");
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Reset the MPR121
    if (write_mpr121_touch_status(0x00) != 0) {
        log_event("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the MPR121
    if (write_mpr121_touch_status(MPR121_ENABLE_ELECTRODE0) != 0) {
        log_event("Failed to enable electrode 0");
        return -1;
    }
    gpioDelay(10); // Wait for enable to complete

    if (write_mpr121_touch_status(MPR121_TOUCH_THRESHOLD) != 0) {
        log_event("Failed to set touch threshold");
        return -1;
    }
    gpioDelay(10); // Wait for threshold to update

    if (write_mpr121_touch_status(MPR121_RELEASE_THRESHOLD) != 0) {
        log_event("Failed to set release threshold");
        return -1;
    }
    gpioDelay(10); // Wait for release threshold to update

    if (write_mpr121_touch_status(MPR121_DEBOUNCE_TIME) != 0) {
        log_event("Failed to set debounce time");
        return -1;
    }
    gpioDelay(10); // Wait for debounce time to update

    if (write_mpr121_touch_status(MPR121_CHARGE_TIME) != 0) {
        log_event("Failed to set charge time");
        return -1;
    }
    gpioDelay(10); // Wait for charge time to update

    if (write_mpr121_touch_status(MPR121_RUN_MODE) != 0) {
        log_event("Failed to set run mode");
        return -1;
    }
    gpioDelay(10); // Wait for run mode to update

    return 0;
}

// Function to read the touch status from the MPR121
int read_mpr121_touch_status() {
    char buffer[2];
    int touch_status = 0;

    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCH_THRESHOLD, buffer, 2) != 2) {
        log_event("Failed to read touch status");
        return -1;
    }

    touch_status = (buffer[0] << 8) | buffer[1];
    return touch_status;
}

// Function to write the touch status to the MPR121
int write_mpr121_touch_status(int status) {
    char buffer[2];
    int result;

    buffer[0] = (status >> 8) & 0xFF;
    buffer[1] = status & 0xFF;

    result = i2cWriteI2CBlockData(i2c_handle, MPR121_TOUCH_THRESHOLD, buffer, 2);
    if (result != 2) {
        log_event("Failed to write touch status");
        return -1;
    }
    return 0;
}

// Function to toggle the relay state
int toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO_PIN);
    gpioWrite(RELAY_GPIO_PIN, !current_state);
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the MPR121
    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the relay GPIO as output
    gpioSetMode(RELAY_GPIO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int touch_status = read_mpr121_touch_status();
        if (touch_status < 0) {
            log_event("Failed to read touch status");
        } else {
            if (touch_status & 0x01) {
                toggle_relay();
            }
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup
    log_event("Program terminated");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

