#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int flame_detected = 0;
static volatile int last_flame_detected = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
void log_event(const char *message);
void signal_handler(int signal);

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[3];
    int len;
    int fd;

    len = snprintf(buffer, sizeof(buffer), "/sys/class/gpio/export");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[3];
    int len;
    int fd;

    len = snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char buffer[3];
    int fd;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char buffer[3];
    int fd;
    char value_str[3];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(buffer, O_RDONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char buffer[3];
    int fd;
    char value_str[3];

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        perror("gpio/value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log an event to a file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(FLAME_SENSOR_PIN) < 0 ||
        gpio_export(BUZZER_PIN) < 0 ||
        gpio_export(LED_PIN) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(FLAME_SENSOR_PIN, "in") < 0 ||
        gpio_set_direction(BUZZER_PIN, "out") < 0 ||
        gpio_set_direction(LED_PIN, "out") < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read flame sensor value
        int flame_detected_value = gpio_read(FLAME_SENSOR_PIN);
        if (flame_detected_value < 0) {
            fprintf(stderr, "Error reading flame sensor value\n");
            continue; // Continue to the next iteration
        }

        // Debounce the sensor reading
        int delay_ms = DEBOUNCE_DELAY;
        int delay_count = 0;
        while (gpio_read(FLAME_SENSOR_PIN) == 0 && delay_count < delay_ms) {
            delay_count++;
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (delay_count >= delay_ms) {
            flame_detected = 1;
            printf("Flame detected!\n");
            log_event("Flame Detected");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            gpioDelay(500); // Buzzer on for 500ms
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            flame_detected = 0;
        }

        // Check if flame is still detected after the delay
        delay_ms = DEBOUNCE_DELAY;
        delay_count = 0;
        while (flame_detected && delay_count < delay_ms) {
            delay_count++;
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (delay_count >= delay_ms) {
            flame_detected = 0;
            printf("Flame cleared!\n");
            log_event("Flame Cleared");
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpio_unexport(FLAME_SENSOR_PIN);
    gpio_unexport(BUZZER_PIN);
    gpio_unexport(LED_PIN);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

