            fprintf(stderr, "Failed to set solenoid 1 pin low.\n");
        }
        if (set_solenoid_pin(SOLENOID2_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set solenoid 2 pin low.\n");
        }
