        if (set_solenoid_pin(SOLENOID1_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set solenoid 1 pin high.\n");
        }
        if (set_solenoid_pin(SOLENOID2_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set solenoid 2 pin high.\n");
        }
        gpioDelay(DEACTIVATE_DURATION_MS);
