int set_solenoid_pin(int pin, int state) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return 1;
    }
    if (state == 1) {
        gpioWrite(pin, 1); // Turn on solenoid
    } else {
        gpioWrite(pin, 0); // Turn off solenoid
    }
    return 0;
}

