int log_dispose_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Solenoid %d - Dispense: %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

// Deactivate solenoids
void deactivate_solenoids() {
    gpioWrite(SOLENOID1_PIN, 0);
    gpioWrite(SOLENOID2_PIN, 0);
}

// Cleanup resources
void cleanup() {
    deactivate_solenoids();
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

