#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define PID parameters
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Define obstacle avoidance parameters
#define OBSTACLE_THRESHOLD 20.0

// Define distance sensor parameters
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0

// Define log file name
#define LOG_FILE "balance_log.txt"

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
float simulate_tilt_error();
float simulate_distance_sensor();
void motor_a_forward(int speed);
void motor_a_backward(int speed);
void motor_b_forward(int speed);
void motor_b_backward(int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Function to simulate tilt error
float simulate_tilt_error() {
    float error = rand() % (10 - -10 + 1) + -10;
    if (error < -10) error = -10;
    if (error > 10) error = 10;
    return error;
}

// Function to simulate distance sensor
float simulate_distance_sensor() {
    float distance = rand() % (DISTANCE_MAX - DISTANCE_MIN + 1) + DISTANCE_MIN;
    if (distance < 0) distance = 0;
    if (distance > DISTANCE_MAX) distance = DISTANCE_MAX;
    return distance;
}

// Function to control motor A
void motor_a_forward(int speed) {
    gpioPWM(MOTOR_A_FORWARD, speed);
}

// Function to control motor A backward
void motor_a_backward(int speed) {
    gpioPWM(MOTOR_A_BACKWARD, speed);
}

// Function to control motor B
void motor_b_forward(int speed) {
    gpioPWM(MOTOR_B_FORWARD, speed);
}

// Function to control motor B backward
void motor_b_backward(int speed) {
    gpioPWM(MOTOR_B_BACKWARD, speed);
}

// Function to stop motors
void stop_motors() {
    motor_a_forward(0);
    motor_a_backward(0);
    motor_b_forward(0);
    motor_b_backward(0);
}

// Function to log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Simulate tilt error
        float tilt_error = simulate_tilt_error();

        // Simulate distance sensor
        float distance = simulate_distance_sensor();

        // Calculate motor speeds
        int motor_a_speed = (int)((distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_RANGE);
        int motor_b_speed = (int)((distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * PWM_RANGE);

        // Apply PID control
        float error = Kp * tilt_error + Ki * distance + Kd * (distance - OBSTACLE_THRESHOLD);
        int motor_a_speed_clamped = (int)(error + PWM_RANGE / 2.0);
        int motor_b_speed_clamped = (int)(error + PWM_RANGE / 2.0);

        // Control motors
        motor_a_forward(motor_a_speed_clamped);
        motor_a_backward(motor_a_speed_clamped);
        motor_b_forward(motor_b_speed_clamped);
        motor_b_backward(motor_b_speed_clamped);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50); // 50ms
    }

    // Stop motors before exiting
    stop_motors();

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

