#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define SENSOR_3_PIN 22

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 200

// Log file path
#define LOG_FILE "/home/pi/logs/motion_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_motion(int sensor_number);
void motion_detected_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log motion event
void log_motion(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Motion detected on GPIO %d\n", timestamp, gpio_pin);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge (motion detected)
        log_motion(gpio + 1); // Log motion for each sensor
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);

    // Set pull-up/down resistors (optional, depends on sensor)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_3_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFuncEx(SENSOR_1_PIN, motion_detected_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, motion_detected_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_3_PIN, motion_detected_callback, NULL);

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Wait for a debounce delay
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds

        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);
        int sensor3_value = read_sensor(SENSOR_3_PIN);

        // Check for motion
        if (sensor1_value == 1) {
            log_motion(1);
        }
        if (sensor2_value == 1) {
            log_motion(2);
        }
        if (sensor3_value == 1) {
            log_motion(3);
        }

        gpioDelay(100 * 1000); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_3_PIN, NULL, NULL);

    fclose(log_file);
    gpioTerminate();

    return 0;
}

