#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_XOUT_L 0x44
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_YOUT_L 0x46
#define MPU6050_REG_GYRO_ZOUT_H 0x47
#define MPU6050_REG_GYRO_ZOUT_L 0x48

// Sensitivity (LSB/°/s)
#define SENSITIVITY 131.0

// Sample rate (Hz)
#define SAMPLE_RATE 100

// Log file name
#define LOG_FILE "gyro_log.csv"

// I2C handle
int i2c_handle;

// File pointer for the log file
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    // Wake the MPU-6050
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050\n");
        return -1;
    }

    // Configure gyroscope range
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    // Configure sample rate divider
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error: Could not configure sample rate divider\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_raw_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_degps(int16_t raw_data) {
    return (float)raw_data * SENSITIVITY;
}

// Function to log data to a file
int log_data(float x_degps, float y_degps, float z_degps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_degps, y_degps, z_degps);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        float x_degps, y_degps, z_degps;

        // Read raw gyroscope data
        if (read_raw_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_degps = convert_to_degps(raw_x);
            y_degps = convert_to_degps(raw_y);
            z_degps = convert_to_degps(raw_z);

            // Log the data
            log_data(x_degps, y_degps, z_degps);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

