#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Function prototypes
int read_moisture_sensor();
int control_relay(int gpio_pin, int state);
int log_data(int zone_number, int moisture_level, int relay_state);
void signal_handler(int signal);

// Global variable to track the program state
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to read the moisture sensor
int read_moisture_sensor() {
    int moisture_level = rand() % 101;
    return moisture_level;
}

// Function to control a relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log data to a file
int log_data(int zone_number, int moisture_level, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Zone %d: Moisture Level = %d, Relay State = %d\n", timestamp, zone_number, moisture_level, relay_state);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY_1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_4_PIN, PI_OUTPUT);

    // Set initial relay states to LOW
    control_relay(RELAY_1_PIN, 0);
    control_relay(RELAY_2_PIN, 0);
    control_relay(RELAY_3_PIN, 0);
    control_relay(RELAY_4_PIN, 0);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();

        // Control relays based on moisture level
        for (int i = 1; i <= 4; i++) {
            control_relay(RELAY_i_PIN, moisture_level < 30 ? 0 : 1); // LOW if moisture is low
        }

        // Log data
        if (log_data(i, moisture_level, control_relay(RELAY_1_PIN, 1)) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Clean up and exit
    printf("Cleaning up and exiting.\n");
    control_relay(RELAY_1_PIN, 0);
    control_relay(RELAY_2_PIN, 0);
    control_relay(RELAY_3_PIN, 0);
    control_relay(RELAY_4_PIN, 0);
    gpioTerminate();

    return 0;
}

