#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from the ADXL345
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to the ADXL345
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    int x_raw, y_raw, z_raw;

    x_raw = read_register(handle, DATAX0);
    y_raw = read_register(handle, DATAX1);
    z_raw = read_register(handle, DATAX2);

    if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
        return -1;
    }

    *x = (int16_t)((x_raw << 8) | 0x00); // Combine high and low bytes
    *y = (int16_t)((y_raw << 8) | 0x00);
    *z = (int16_t)((z_raw << 8) | 0x00);

    return 0;
}

// Function to convert raw data to g-force
float convert_to_g(int16_t x, int16_t y, int16_t z) {
    return (float)x / 16384.0f * 2.0f; // ±2g range
}

// Function to detect freefall
int detect_freefall(int16_t x, int16_t y, int16_t z) {
    return (fabs(x) < FREEFALL_THRESHOLD || fabs(y) < FREEFALL_THRESHOLD || fabs(z) < FREEFALL_THRESHOLD);
}

// Function to log data to file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for alarm
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure pin is initially low

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t x, y, z;
    float g_x, g_y, g_z;
    int16_t freefall_detected = 0;

    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_handle, &x, &y, &z) == 0) {
            // Convert to g-force
            g_x = convert_to_g(x, y, z);

            // Detect freefall
            freefall_detected = detect_freefall(x, y, z);

            // Log data
            log_data(log_file, x, y, z);

            // Check for freefall
            if (freefall_detected) {
                printf("Freefall detected!\n");
                gpioWrite(ALARM_PIN, 1); // Set alarm high
                gpioDelay(500000);        // Wait for 5 seconds
                gpioWrite(ALARM_PIN, 0); // Set alarm low
                gpioDelay(500000);        // Wait for 5 seconds
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

