#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Impact threshold (g)
#define IMPACT_THRESHOLD 1.5

// Buzzer duration (seconds)
#define BUZZER_DURATION 1

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(float magnitude);
int detect_impact(float magnitude);
void activate_buzzer();
void cleanup();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;
        int16_t raw_x, raw_y, raw_z;

        // Read acceleration data
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert raw data to g
            float magnitude = convert_to_g(raw_x);

            // Detect freefall
            if (detect_freefall(magnitude)) {
                printf("Freefall detected!\n");
                activate_buzzer();
            }

            // Detect impact
            if (detect_impact(magnitude)) {
                printf("Impact detected!\n");
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return 1;
    }

    // Combine the two bytes for each axis
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Convert raw data to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 16384.0f;
}

// Detect freefall
int detect_freefall(float magnitude) {
    return (magnitude < FREEFALL_THRESHOLD);
}

// Detect impact
int detect_impact(float magnitude) {
    return (magnitude > IMPACT_THRESHOLD);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set buzzer pin HIGH
    gpioDelay(BUZZER_DURATION * 1000000); // Delay for 1 second
    gpioWrite(BUZZER_PIN, 0); // Set buzzer pin LOW
}

// Cleanup resources
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Terminating...\n");
    terminate = 1;
}

