#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define constants
#define BUFFER_SIZE 5
#define LINE_THRESHOLD 500
#define ALERT_DURATION 2
#define MAX_READINGS 5

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer line_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void add_to_buffer(int reading);
int is_line_detected(int reading);
void alert_system();
void stop_line_following();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to add reading to circular buffer
void add_to_buffer(int reading) {
    line_buffer.buffer[line_buffer.head] = reading;
    line_buffer.head = (line_buffer.head + 1) % BUFFER_SIZE;
    if (line_buffer.count < MAX_READINGS) {
        line_buffer.count++;
    }
}

// Function to check if line is detected
int is_line_detected(int reading) {
    return reading == LINE_THRESHOLD;
}

// Function to trigger alert system
void alert_system() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION * 1000); // Delay for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
}

// Function to stop line-following
void stop_line_following() {
    gpioWrite(ALERT_PIN, 0); // Ensure alert is off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(ALERT_PIN, 0); // Ensure alert is off
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    line_buffer.head = 0;
    line_buffer.count = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_reading = read_sensor(LEFT_SENSOR);
        int center_reading = read_sensor(CENTER_SENSOR);
        int right_reading = read_sensor(RIGHT_SENSOR);

        // Add readings to circular buffer
        add_to_buffer(left_reading);
        add_to_buffer(center_reading);
        add_to_buffer(right_reading);

        // Check for line detection
        if (is_line_detected(left_reading)) {
            printf("LEFT SENSOR: %d\n", left_reading);
        }
        if (is_line_detected(center_reading)) {
            printf("CENTER SENSOR: %d\n", center_reading);
        }
        if (is_line_detected(right_reading)) {
            printf("RIGHT SENSOR: %d\n", right_reading);
        }

        // Stop if all sensors are no line
        if (is_line_detected(left_reading) && is_line_detected(center_reading) && is_line_detected(right_reading)) {
            printf("All sensors are no line. Stopping.\n");
            stop_line_following();
            break;
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

