    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

// Function to open a socket
int open_socket(const char *hostname, int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, hostname, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to send a command to the server
int send_command(int sockfd, const char *command) {
    if (send(sockfd, command, strlen(command), 0) < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

// Function to receive a command from the server
int receive_command(int sockfd, char *command, size_t command_size) {
    char buffer[command_size + 1];
    buffer[command_size] = '\0';
    ssize_t bytes_received = recv(sockfd, buffer, command_size, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return -1;
    }
    buffer[bytes_received] = '\0';
    strncpy(command, buffer, bytes_received);
    command[bytes_received] = '\0';
    return 0;
}

// Function to control the relay
int control_relay(int sockfd, int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        perror("GPIO write failed");
        return -1;
    }
    relay_state.relay_state = state;
    log_event("Relay state changed to " + relay_state.relay_state);
    return 0;
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (server_socket != -1) {
        close(server_socket);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open socket
    server_socket = open_socket("localhost", PORT);
    if (server_socket < 0) {
        gpioTerminate();
        return 1;
    }

    char buffer[256];
    int bytes_received;

    // Main loop
    while (1) {
        // Receive command
        if (receive_command(server_socket, buffer, sizeof(buffer)) == 0) {
            printf("Received command: %s\n", buffer);

            // Validate command
            if (strcmp(buffer, "ON") == 0 || strcmp(buffer, "OFF") == 0) {
                // Validate relay state
                if (relay_state.relay_state == 0) {
                    // Turn relay ON
                    if (control_relay(server_socket, 1) != 0) {
                        fprintf(stderr, "Failed to turn relay ON\n");
                    }
                } else if (relay_state.relay_state == 1) {
                    // Turn relay OFF
                    if (control_relay(server_socket, 0) != 0) {
                        fprintf(stderr, "Failed to turn relay OFF\n");
                    }
                } else {
                    fprintf(stderr, "Invalid relay state: %d\n", relay_state.relay_state);
                }
            } else {
                fprintf(stderr, "Invalid command: %s\n", buffer);
            }
        } else {
            fprintf(stderr, "Failed to receive command\n");
        }

        // Sleep for a short period
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(server_socket);
    gpioTerminate();
    return 0;
}

