#define RELAY_GPIO 18

// Define I2C bus and handle
#define I2C_BUS 1
#define I2C_HANDLE 1

// Define scale factor (ml/min)
#define SCALE_FACTOR 1.0

// Define CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define flow threshold (ml/min)
#define FLOW_THRESHOLD 5.0

// Global variables
volatile int relay_state = 0; // 0 = off, 1 = on
FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int handle);
int send_command(int handle, int command);
int read_data(int handle, int *data, int *crc);
float convert_raw_to_flow(int raw_value);
int energize_relay(int state);
int deenergize_relay(int state);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
