    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    denergize_relay(relay_state);
    exit(0);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int initialize_i2c(int bus, int handle) {
    int result = i2cOpen(bus, handle, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", result);
        return -1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, 0x00, command);
    if (result < 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from sensor
int read_data(int handle, int *data, int *crc) {
    int result = i2cReadI2CBlockData(handle, 0x00, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    *crc = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw value to flow rate
float convert_raw_to_flow(int raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Energize relay
int energize_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// De-energize relay
int deenergize_relay(int state) {
    gpioWrite(RELAY_GPIO, !state);
    return 0;
}

