        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, I2C_HANDLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    int sensor1_data[2], sensor2_data[2];
    int sensor1_crc, sensor2_crc;
    float flow1, flow2;

    printf("Starting flow measurement...\n");

    // Main loop
    while (1) {
        // Send start measurement command to sensor 1
        if (send_command(I2C_HANDLE, 0x36) != 0) {
            fprintf(stderr, "Failed to send start measurement command to sensor 1\n");
            log_flow_data(-1.0, -1.0); // Log error
            continue;
        }

        // Wait for sensor 1 to complete measurement (at least 100ms)
        gpioDelay(100);

        // Read data from sensor 1
        if (read_data(I2C_HANDLE, sensor1_data, &sensor1_crc) != 0) {
            fprintf(stderr, "Failed to read data from sensor 1\n");
            log_flow_data(-1.0, -1.0); // Log error
            continue;
        }

        // Read data from sensor 2
        if (read_data(I2C_HANDLE, sensor2_data, &sensor2_crc) != 0) {
            fprintf(stderr, "Failed to read data from sensor 2\n");
            log_flow_data(-1.0, -1.0); // Log error
            continue;
        }

        // Validate CRC-8 for sensor 1
        if (sensor1_crc != (sensor1_data[0] << 8) | sensor1_data[1]) {
            fprintf(stderr, "Sensor 1 CRC check failed\n");
            log_flow_data(-1.0, -1.0); // Log error
            continue;
        }

        // Validate CRC-8 for sensor 2
        if (sensor2_crc != (sensor2_data[0] << 8) | sensor2_data[1]) {
            fprintf(stderr, "Sensor 2 CRC check failed\n");
            log_flow_data(-1.0, -1.0); // Log error
            continue;
        }

        // Convert raw values to flow rates
        flow1 = convert_raw_to_flow(sensor1_data[0]);
        flow2 = convert_raw_to_flow(sensor2_data[0]);

        // Check flow thresholds
        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            // Energize relay
            if (energize_relay(relay_state) != 0) {
                fprintf(stderr, "Failed to energize relay\n");
            }
            relay_state = 1; // Set relay to active state
        } else if (flow1 > FLOW_THRESHOLD && flow2 > FLOW_THRESHOLD) {
            // De-energize relay
            if (deenergize_relay(relay_state) != 0) {
                fprintf(stderr, "Failed to de-energize relay\n");
            }
            relay_state = 0; // Set relay to inactive state
        }

        // Log flow data
        if (log_flow_data(flow1, flow2) != 0) {
            fprintf(stderr, "Failed to log flow data\n");
        }

        // Wait 100ms
        gpioDelay(100);
    }

    return 0;
}

