#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define DRY_THRESHOLD_MS 200
#define MOTOR_RUN_TIME_MS 5000
#define DRY_THRESHOLD_COUNT 3

// Global variables
volatile sig_atomic_t running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_message(int severity, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) { // Closing
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioDelay(MOTOR_RUN_TIME_MS);
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else if (direction == -1) { // Opening
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioDelay(MOTOR_RUN_TIME_MS);
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else {
        log_message(LOG_ERR, "Invalid motor direction: %d", direction);
    }
}

// Function to log messages with syslog
void log_message(int severity, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s - %s", timestamp, message);

    syslog(severity, "%s", log_message_buffer);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to perform cleanup before exiting
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    gpioWrite(MOTOR_ENA_PIN, 0); // Ensure motor is off
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Rain window controller started");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 1) {
            log_message(LOG_INFO, "Rain detected!");
            control_motor(1); // Closing
            gpioDelay(DRY_THRESHOLD_MS);
            control_motor(-1); // Opening
            gpioDelay(DRY_THRESHOLD_MS);
        } else if (rain_detected == 0) {
            log_message(LOG_INFO, "No rain detected");
        }

        gpioDelay(200); // Check every 200ms
    }

    cleanup();
    return 0;
}

