#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event);
void cleanup();
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Activate floodlight for 60 seconds
void activate_floodlight() {
    gpioWrite(LED_PIN, 1); // Turn on floodlight
    gpioDelay(DEACTIVATION_DURATION * 1000000); // Delay for 60 seconds
    gpioWrite(LED_PIN, 0); // Turn off floodlight
}

// Deactivate floodlight
void deactivate_floodlight() {
    gpioWrite(LED_PIN, 0); // Ensure floodlight is off
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_floodlight();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Smart Security Light started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_event("Motion detected");
            activate_floodlight();
            sleep(5); // Debounce
            deactivate_floodlight();
            log_event("Motion stopped");
        }
        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

