#define ELECTRODE_GPIO_10 9
#define ELECTRODE_GPIO_11 10
#define ELECTRODE_GPIO_12 11

// Define I2C addresses
#define MPR121_ADDR_1 0x5A
#define MPR121_ADDR_2 0x5B

// Define GPIO pins for MPR121
#define MPR121_GPIO_1 ELECTRODE_GPIO_1
#define MPR121_GPIO_2 ELECTRODE_GPIO_2
#define MPR121_GPIO_3 ELECTRODE_GPIO_3
#define MPR121_GPIO_4 ELECTRODE_GPIO_4
#define MPR121_GPIO_5 ELECTRODE_GPIO_5
#define MPR121_GPIO_6 ELECTRODE_GPIO_6
#define MPR121_GPIO_7 ELECTRODE_GPIO_7
#define MPR121_GPIO_8 ELECTRODE_GPIO_8
#define MPR121_GPIO_9 ELECTRODE_GPIO_9
#define MPR121_GPIO_10 ELECTRODE_GPIO_10
#define MPR121_GPIO_11 ELECTRODE_GPIO_11
#define MPR121_GPIO_12 ELECTRODE_GPIO_12

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define relay state
enum RelayState {
    RELAY_OFF,
    RELAY_ON,
    RELAY_UNKNOWN
};

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int relay_state = RELAY_UNKNOWN;

// Function prototypes
int initialize_mpr121(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin, int state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Close I2C connections
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize the MPR121
int initialize_mpr121(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to soft reset MPR121\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to configure baseline filtering\n");
        return -1;
    }
    gpioDelay(10);

    // Configure electrode filtering
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to configure electrode filtering\n");
        return -1;
    }
    gpioDelay(10);

    // Configure electrode FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to configure electrode FFI/SFI/CDT\n");
        return -1;
    }
    gpioDelay(10);

    // Configure electrode auto-config
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to configure electrode auto-config\n");
        return -1;
    }
    gpioDelay(10);

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }
    gpioDelay(10);

    return 0;
}

// Function to read touch status from the MPR121
int read_touch_status(int i2c_handle) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit word
    int touch_status = (buffer[0] << 8) | buffer[1];

    return touch_status;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin, int state) {
    if (state == RELAY_ON) {
        gpioWrite(gpio_pin, 1); // Turn on the relay
    } else if (state == RELAY_OFF) {
        gpioWrite(gpio_pin, 0); // Turn off the relay
    } else {
        fprintf(stderr, "Error: Invalid relay state: %d\n", state);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(ELECTRODE_GPIO_1, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_2, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_3, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_4, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_5, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_6, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_7, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_8, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_9, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_10, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_11, PI_INPUT);
    gpioSetMode(ELECTRODE_GPIO_12, PI_INPUT);

    // Open I2C connections
    i2c_handle_1 = i2cOpen(1, MPR121_ADDR_1, 0); // Bus 1
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device 1 at address 0x5A\n");
        cleanup(0); // Call cleanup before exiting
    }

    i2c_handle_2 = i2cOpen(1, MPR121_ADDR_2, 0); // Bus 1
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device 2 at address 0x5B\n");
        cleanup(0); // Call cleanup before exiting
    }

    // Initialize MPR121
    if (initialize_mpr121(i2c_handle_1) < 0) {
        fprintf(stderr, "Error: Failed to initialize MPR121 on device 1\n");
        cleanup(0); // Call cleanup before exiting
    }
    if (initialize_mpr121(i2c_handle_2) < 0) {
        fprintf(stderr, "Error: Failed to initialize MPR121 on device 2\n");
        cleanup(0); // Call cleanup before exiting
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (1) {
        // Read touch status
        int touch_status = read_touch_status(i2c_handle_1);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status from device 1\n");
        } else {
            // Check if any electrode is touched
            if (touch_status & 0x0F) {
                // Toggle relay
                toggle_relay(RELAY_PIN, !relay_state);
                relay_state = !relay_state;
                printf("Relay toggled to %s\n", relay_state == RELAY_ON ? "ON" : "OFF");
            }
        }

        // Read touch status from device 2
        touch_status = read_touch_status(i2c_handle_2);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status from device 2\n");
        } else {
            // Check if any electrode is touched
            if (touch_status & 0x0F) {
                // Toggle relay
                toggle_relay(RELAY_PIN, !relay_state);
                relay_state = !relay_state;
                printf("Relay toggled to %s\n", relay_state == RELAY_ON ? "ON" : "OFF");
            }
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time
    }

    return 0;
}

