#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1
#define I2C_HANDLE -1
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle, int *lux);
int control_relay(int gpio_pin, int state);
int log_data(int lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, int *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 120 ms)
    gpioDelay(120);

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to lux
    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Lux: %d\n", timestamp, lux);
    fclose(log_file);
    return 0;
}

int main() {
    int lux;
    int retries = 3;
    int i2c_address = BH1750_ADDR;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(i2c_handle, &lux) == 0) {
            // Control relay
            if (lux < LUX_THRESHOLD) {
                if (control_relay(RELAY_PIN, 1) != 0) {
                    fprintf(stderr, "Error controlling relay!\n");
                }
            } else {
                if (control_relay(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error controlling relay!\n");
                }
            }

            // Log data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Grow light control system terminated.\n");
    return 0;
}

