#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17
#define RELAY_STATE 0
#define RELAY_ON "ON"
#define RELAY_OFF "OFF"
#define LOG_FILE "/var/log/relay_controller.log"
#define LOG_LEVEL LOG_USER

// Global variables
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function prototypes
int connect_mqtt(const char *broker_address, int broker_port, const char *client_id);
int subscribe_mqtt(struct mosquitto *mosq, const char *topic, const char *qos);
int publish_mqtt(struct mosquitto *mosq, const char *topic, const char *payload);
void message_callback(void *userdata, const struct mosquitto *mosq, void *msg);
void signal_handler(int signum);
void cleanup();

// Function to connect to the MQTT broker
int connect_mqtt(const char *broker_address, int broker_port, const char *client_id) {
    mosquitto_lib_init();
    mosq = mosquitto_new(client_id, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, broker_address, broker_port, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Function to subscribe to the MQTT topic
int subscribe_mqtt(struct mosquitto *mosq, const char *topic, int qos) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Function to publish a message to the MQTT broker
int publish_mqtt(struct mosquitto *mosq, const char *topic, const char *payload) {
    int rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message to MQTT topic: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Callback function for message processing
void message_callback(void *userdata, const struct mosquitto *mosq, void *msg) {
    if (msg) {
        char *payload = (char *)msg->payload;
        if (payload && strlen(payload) > 0) {
            if (strcmp(payload, RELAY_ON) == 0) {
                syslog(LOG_INFO, "Received ON message on GPIO %d", GPIO_PIN);
                gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
                publish_mqtt(mosq, MQTT_TOPIC, payload);
            } else if (strcmp(payload, RELAY_OFF) == 0) {
                syslog(LOG_INFO, "Received OFF message on GPIO %d", GPIO_PIN);
                gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
                publish_mqtt(mosq, MQTT_TOPIC, payload);
            } else {
                syslog(LOG_WARNING, "Received invalid payload on GPIO %d: %s", GPIO_PIN, payload);
            }
        } else {
            syslog(LOG_WARNING, "Received empty payload on GPIO %d", GPIO_PIN);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    mosquitto_loop_stop(mosq);
    mosquitto_loop_cleanup();
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    syslog(LOG_INFO, "Cleanup complete");
}

int main() {
    // Initialize syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially off

    // Connect to MQTT broker
    if (connect_mqtt(MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID) != 0) {
        cleanup();
        return 1;
    }

    // Subscribe to MQTT topic
    if (subscribe_mqtt(mosq, MQTT_TOPIC, MQTT_QOS) != 0) {
        cleanup();
        return 1;
    }

    // Set up message callback
    if (mosquitto_set_message_callback(mosq, message_callback) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set message callback");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Check if the relay state is set to ON
        if (strcmp(payload, RELAY_ON) == 0) {
            syslog(LOG_INFO, "Relay ON");
            gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            publish_mqtt(mosq, MQTT_TOPIC, payload);
        } else if (strcmp(payload, RELAY_OFF) == 0) {
            syslog(LOG_INFO, "Relay OFF");
            gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            publish_mqtt(mosq, MQTT_TOPIC, payload);
        } else {
            syslog(LOG_WARNING, "Invalid payload received: %s", payload);
        }

        sleep(1); // Check every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

