void message_callback(void *userdata, const struct mosquitto *mosq, void *msg) {
    if (msg) {
        char *payload = (char *)msg->payload;
        if (payload && strlen(payload) > 0) {
            if (strcmp(payload, RELAY_ON) == 0) {
                syslog(LOG_INFO, "Received ON message on GPIO %d", GPIO_PIN);
                gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
                publish_mqtt(mosq, MQTT_TOPIC, payload);
            } else if (strcmp(payload, RELAY_OFF) == 0) {
                syslog(LOG_INFO, "Received OFF message on GPIO %d", GPIO_PIN);
                gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
                publish_mqtt(mosq, MQTT_TOPIC, payload);
            } else {
                syslog(LOG_WARNING, "Received invalid payload on GPIO %d: %s", GPIO_PIN, payload);
            }
        } else {
            syslog(LOG_WARNING, "Received empty payload on GPIO %d", GPIO_PIN);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    mosquitto_loop_stop(mosq);
    mosquitto_loop_cleanup();
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    syslog(LOG_INFO, "Cleanup complete");
}

int main() {
    // Initialize syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially off

    // Connect to MQTT broker
    if (connect_mqtt(MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_ID) != 0) {
        cleanup();
        return 1;
    }

    // Subscribe to MQTT topic
    if (subscribe_mqtt(mosq, MQTT_TOPIC, MQTT_QOS) != 0) {
        cleanup();
        return 1;
    }

    // Set up message callback
    if (mosquitto_set_message_callback(mosq, message_callback) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set message callback");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Check if the relay state is set to ON
        if (strcmp(payload, RELAY_ON) == 0) {
            syslog(LOG_INFO, "Relay ON");
            gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            publish_mqtt(mosq, MQTT_TOPIC, payload);
        } else if (strcmp(payload, RELAY_OFF) == 0) {
            syslog(LOG_INFO, "Relay OFF");
            gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            publish_mqtt(mosq, MQTT_TOPIC, payload);
        } else {
            syslog(LOG_WARNING, "Invalid payload received: %s", payload);
        }

        sleep(1); // Check every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

