    gpioSetPWMrange(SERVO1_PIN, SERVO_PULSE_WIDTH_MAX);
    gpioSetPWMrange(SERVO2_PIN, SERVO_PULSE_WIDTH_MAX);
    gpioSetPWMrange(SERVO3_PIN, SERVO_PULSE_WIDTH_MAX);
    gpioSetPWMrange(SERVO4_PIN, SERVO_PULSE_WIDTH_MAX);
    gpioSetPWMrange(SERVO5_PIN, SERVO_PULSE_WIDTH_MAX);

    // Set servo positions
    set_servo_position(SERVO1_PIN, SERVO1_POS);
    set_servo_position(SERVO2_PIN, SERVO2_POS);
    set_servo_position(SERVO3_PIN, SERVO3_POS);
    set_servo_position(SERVO4_PIN, SERVO4_POS);
    set_servo_position(SERVO5_PIN, SERVO5_POS);

    // Keep the program running until a signal is received
    while (program_running) {
        sleep(1);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

