#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD 50
#define LUX_HIGH 200
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_bh1750(int i2c_handle);
int control_relay(int gpio_pin, int state);
int log_data(int lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int lux = -1;

    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) { // One-time high-resolution mode
        fprintf(stderr, "Failed to set BH1750 to high resolution mode\n");
        return -1;
    }

    gpioDelay(200); // Wait for measurement (datasheet specifies 180ms)

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read data from BH1750\n");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Control the relay GPIO
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Log data to file
int log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System\n");

    while (program_running) {
        int lux = read_bh1750(i2c_handle);
        if (lux >= 0) {
            printf("Lux: %d\n", lux);

            if (lux < LUX_THRESHOLD && !relay_state) {
                printf("Dusk detected, turning relay ON\n");
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
            } else if (lux > LUX_HIGH && relay_state) {
                printf("Dawn detected, turning relay OFF\n");
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
            }

            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

