#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int touch_state = 0; // 0 = LOW, 1 = HIGH
static volatile int last_touch_state = 0; // Last touch state
static volatile int debounce_count = 0; // Debounce count
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay(int new_state);
void log_relay_state(int new_state);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, depends on sensor)
    //gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay(int new_state) {
    relay_state = new_state;
    gpioWrite(RELAY_PIN, relay_state);
    return 0; // Indicate success
}

// Function to log the relay state change
void log_relay_state(int new_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Relay state changed to %s\n", timestamp, (new_state == 1) ? "ON" : "OFF");
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
    cleanup();       // Release GPIO resources
    exit(0);         // Exit the program
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate();         // Terminate pigpio
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor() == 1; // Check if touch is detected

        if (touch_detected) {
            if (touch_state == 0) {
                // Debounce
                if (debounce_count < DEBOUNCE_DELAY) {
                    debounce_count++;
                    gpioDelay(10); // Small delay to prevent rapid state changes
                    continue;
                } else {
                    debounce_count = 0; // Reset debounce count
                }
            }

            if (touch_detected && touch_state == 0) {
                if (toggle_relay(1) == 0) {
                    touch_state = 1;
                    last_touch_state = touch_detected;
                }
            } else if (touch_detected && touch_state == 1) {
                if (toggle_relay(0) == 0) {
                    touch_state = 0;
                    last_touch_state = touch_detected;
                }
            }
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

