static volatile int pulse_count = 0;
static pthread_mutex_t pulse_count_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int solenoid_open = 1;
static volatile int solenoid_closed = 0;

// Function prototypes
