#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define TOUCH_SENSOR_THRESHOLD 500  // Touch sensor threshold (adjust as needed)
#define TOUCH_SENSOR_RELEASE_TIME 10 // Time in seconds to release touch (adjust as needed)
#define RELAY_ON_TIME 5 // Time in seconds to keep relay ON (adjust as needed)
#define RELAY_OFF_TIME 5 // Time in seconds to keep relay OFF (adjust as needed)

// Global variables
volatile sig_atomic_t relay_state = 0; // Flag to track relay state
volatile sig_atomic_t touch_state = 0; // Flag to track touch state
volatile sig_atomic_t touch_released = 0; // Flag to track if touch released

// Function prototypes
int read_touch_sensor();
int toggle_relay();
void cleanup();
void signal_handler(int signal);

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay() {
    if (relay_state == 0) {
        gpioWrite(RELAY_PIN, 1); // Turn relay ON
        relay_state = 1;
        return 0; // Success
    } else {
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        relay_state = 0;
        return 1; // Failure
    }
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("GPIO resources released.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_state = 0; // Set relay state to OFF
    touch_state = 0;  // Reset touch state
    touch_released = 0; // Reset touch released flag
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            if (touch_state == 0) {
                if (toggle_relay() == 0) {
                    touch_state = 1;
                    touch_released = 0; // Reset touch released flag
                } else {
                    touch_state = 0;
                    touch_released = 0; // Reset touch released flag
                }
            } else {
                touch_state = 0;
                touch_released = 0; // Reset touch released flag
            }
        } else {
            touch_state = 0;
            touch_released = 0; // Reset touch released flag
        }

        // Check for touch release
        if (touch_released && touch_state == 0) {
            touch_released = 0; // Reset touch released flag
        }

        // Delay to avoid busy-waiting
        gpioDelay(50); // 50ms delay
    }

    return 0;
}

