void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count);
void set_valve_position(int duty_cycle);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine (ISR) for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate flow rate from pulse count
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / FLOW_RATE_SCALE_FACTOR;
}

// Function to set the valve position using PWM
void set_valve_position(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(VALVE_ENABLE_PIN, duty_cycle);
    gpioPWM(VALVE_DIRECTION_PIN, 1); // Enable valve
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%d\n", s, flow_rate, valve_position);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
