#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define RFID_READ_PIN 17
#define BUTTON_PIN 22
#define LOCK_1_PIN 27
#define LOCK_2_PIN 24

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI parameters
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define log file name
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;

// Function prototypes
int read_rfid_tag();
int check_rfid_response(const unsigned char *response);
int check_button_press();
int engage_locks();
int disengage_locks();
void log_access_attempt(int factor1_valid, int factor2_valid, int button_pressed);
void signal_handler(int signal);

// Function to read RFID tag data
int read_rfid_tag() {
    unsigned char buffer[4];
    int bytes_read = spiRead(spi_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "SPI read failed: %d\n", bytes_read);
        return -1; // Indicate failure
    }

    // Check for all-zero response
    if (memcmp(buffer, 0x01, 4) == 0) {
        return 0; // Tag present
    } else {
        return -1; // Tag not present
    }
}

// Function to check RFID response
int check_rfid_response(const unsigned char *response) {
    if (memcmp(response, 0x01, 4) != 0) {
        fprintf(stderr, "Invalid RFID response: %02X %02X %02X %02X\n", response[0], response[1], response[2], response[3]);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to check button press
int check_button_press() {
    int button_state = gpioRead(BUTTON_PIN);
    if (button_state == 1) {
        return 1; // Button pressed
    } else {
        return 0; // Button not pressed
    }
}

// Function to engage locks
int engage_locks() {
    gpioWrite(LOCK_1_PIN, 0);
    gpioWrite(LOCK_2_PIN, 0);
    gpioDelay(5000000); // 5 seconds
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
    return 0; // Indicate success
}

// Function to disengage locks
int disengage_locks() {
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
    gpioDelay(5000000); // 5 seconds
    gpioWrite(LOCK_1_PIN, 0);
    gpioWrite(LOCK_2_PIN, 0);
    return 0; // Indicate success
}

// Function to log access attempts
void log_access_attempt(int factor1_valid, int factor2_valid, int button_pressed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - RFID: %d, Button: %d\n", timestamp, factor1_valid, button_pressed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_access_attempt(0, 0, 0); // Log no tag present
    disengage_locks();
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RFID_READ_PIN, PI_INPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);

    // Set pull-up resistor for button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door access system started. Press button to access.\n");

    // Main loop
    while (1) {
        // Read RFID tag
        int tag_valid = read_rfid_tag();
        if (tag_valid == 0) {
            // Check RFID response
            int rfid_response = check_rfid_response(tag_valid ? tag_response : NULL);
