                    // Engage locks
                    if (engage_locks() != 0) {
                        fprintf(stderr, "Failed to engage locks\n");
                    }
                }
            }
        }

        gpioDelay(100000); // Check every 100ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

