#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define MPR121_CTRL_REG1 0x80
#define MPR121_CTRL_REG2 0x81
#define MPR121_ELECTRODE_CONFIG_REG 0x5B
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_RELEASED_STATUS_REG 0x01
#define MPR121_RELAY_GPIO 17
#define RELAY_ON_TIME_MS 5000
#define RELAY_OFF_TIME_MS 5000
#define I2C_BUS 1
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_mpr121();
int read_mpr121_touch_status();
void toggle_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: Run mode enable failed\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_mpr121_touch_status() {
    int touch_status = i2cReadWordData(i2c_handle, MPR121_TOUCH_STATUS_REG);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Function to toggle the relay state
void toggle_relay(int state) {
    gpioWrite(MPR121_RELAY_GPIO, state);
}

// Function to log the relay state to a file
void log_relay_state(int state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(MPR121_RELAY_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = read_mpr121_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
            continue; // Continue to the next iteration
        }

        // Check for touch
        if (touch_status & 0x01) {
            toggle_relay(1);
            log_relay_state(1);
        } else {
            toggle_relay(0);
            log_relay_state(0);
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

