// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the duration of each step in milliseconds
#define STEP_DURATION_MS 50

// Define the range of duty cycles for the motors
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Define the number of steps in each pattern
#define PATTERN_LENGTH 5

// Define the number of patterns to generate
#define NUM_PATTERNS 10

// Define the maximum number of steps in a pattern
#define MAX_PATTERN_STEPS (PATTERN_LENGTH * 2)

// Define the maximum duration of a pattern in milliseconds
#define MAX_PATTERN_DURATION (PATTERN_LENGTH * 2)

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure to hold motor state
typedef struct {
    int motor1_state;
    int motor2_state;
} MotorState;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_motor_speed(int motor_pin, int duty_cycle);
void generate_pattern(MotorState *state, int pattern_length);
void play_pattern(MotorState *state, int pattern_length);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    return 0;
}

