    for (int i = 0; i < pattern_length; i++) {
        set_motor_speed(MOTOR1_PIN, state->motor1_state);
        set_motor_speed(MOTOR2_PIN, state->motor2_state);
        gpioDelay(STEP_DURATION_MS * 1000); // Convert ms to microseconds
        set_motor_speed(MOTOR1_PIN, 0);
        set_motor_speed(MOTOR2_PIN, 0);
        gpioDelay(STEP_DURATION_MS * 1000);
    }
}

