    MotorState motor_states[NUM_PATTERNS];
    for (int i = 0; i < NUM_PATTERNS; i++) {
        motor_states[i].motor1_state = 0;
        motor_states[i].motor2_state = 0;
    }

    // Generate patterns for each motor
    for (int i = 0; i < NUM_PATTERNS; i++) {
        generate_pattern(motor_states + i, PATTERN_LENGTH);
        play_pattern(motor_states + i, PATTERN_LENGTH);
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop to generate and play patterns
    while (program_running) {
        // Generate a new pattern
        generate_pattern(motor_states, PATTERN_LENGTH);

        // Play the pattern
        play_pattern(motor_states, PATTERN_LENGTH);

        // Delay to avoid overwhelming the system
        gpioDelay(MAX_PATTERN_DURATION * 1000); // Convert ms to microseconds
    }

    // Clean up resources before exiting
    cleanup_gpio();

    return 0;
}

