#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define DEFAULT_THRESHOLD 10.0
#define DEFAULT_LOG_FILE "weight_log.txt"
#define DEFAULT_SLEEP_TIME 500 // milliseconds
#define DEFAULT_CALIBRATION_COUNT 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Calibration data structure
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
double read_hx711(int data_pin, int clock_pin);
double convert_to_weight(double raw_value, double scale_factor, double offset);
void control_solenoid(int solenoid_pin, double weight);
void log_weight(double weight);
void signal_handler(int signal);
CalibrationData load_calibration_data(const char *filename);
void save_calibration_data(const CalibrationData *data, const char *filename);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read data from HX711
double read_hx711(int data_pin, int clock_pin) {
    int i;
    int count = 0;
    int value = 0;

    gpioWrite(clock_pin, 0); // Ensure clock is low initially

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout reading data pin\n");
        return 0.0; // Indicate error
    }

    gpioWrite(clock_pin, 1); // Set clock high

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Small delay
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Small delay
    }

    gpioWrite(clock_pin, 1); // Set clock high
    gpioWrite(clock_pin, 0); // Set clock low

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    // Apply scaling factor and offset
    return (double)value * scale_factor + offset;
}

// Function to convert raw value to weight
double convert_to_weight(double raw_value, double scale_factor, double offset) {
    return raw_value + offset;
}

// Function to control the solenoid lock
void control_solenoid(int solenoid_pin, double weight) {
    if (weight > DEFAULT_THRESHOLD) {
        gpioWrite(solenoid_pin, 1); // Activate solenoid
    } else {
        gpioWrite(solenoid_pin, 0); // Deactivate solenoid
    }
}

// Function to log weight to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
CalibrationData load_calibration_data(const char *filename) {
    CalibrationData data;
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file: %s\n", filename);
        data.scale_factor = DEFAULT_SCALE;
        data.offset = DEFAULT_OFFSET;
        return data;
    }

    if (fscanf(fp, "%lf,%lf\n", &data.scale_factor, &data.offset) != 2) {
        fprintf(stderr, "Error reading calibration data from file\n");
        fclose(fp);
        data.scale_factor = DEFAULT_SCALE;
        data.offset = DEFAULT_OFFSET;
        return data;
    }

    fclose(fp);
    return data;
}

// Function to save calibration data to file
void save_calibration_data(const CalibrationData *data, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return;
    }

    fprintf(fp, "%lf,%lf\n", data->scale_factor, data->offset);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *filename = argv[1];
        if (strcmp(filename, "calibration.txt") == 0) {
            calibration_file = stdout;
        } else {
            calibration_file = fopen(filename, "w");
            if (calibration_file == NULL) {
                fprintf(stderr, "Error opening calibration file for writing: %s\n", filename);
                return 1;
            }
            fprintf(calibration_file, "scale=1.0,offset=0.0\n");
            fclose(calibration_file);
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration data
    CalibrationData calibration = load_calibration_data(calibration_file);

    // Open log file
    log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", DEFAULT_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        double raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711, retrying...\n");
            gpioDelay(DEFAULT_SLEEP_TIME * 1000); // Wait before retrying
            continue;
        }

        double weight = convert_to_weight(raw_value, calibration.scale_factor, calibration.offset);
        log_weight(weight);
        control_solenoid(SOLENOID_PIN, weight);

        gpioDelay(DEFAULT_SLEEP_TIME * 1000); // Wait for 500ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    fclose(log_file);
    fclose(calibration_file);
    gpioTerminate();

    return 0;
}

