    while (program_running) {
        // Read rain sensors
        int rain1 = read_rain_sensor(RAIN_SENSOR_1);
        int rain2 = read_rain_sensor(RAIN_SENSOR_2);

        // Debounce
        int rain_detected = 0;
        for (int i = 0; i < DEBOUNCE_TIME_MS; i++) {
            if (rain1 == 0 && rain2 == 0) {
                rain_detected = 1;
                break;
            }
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Check if rain is detected
        if (rain_detected) {
            log_event("Rain detected!");
            if (close_window(MOTOR_IN1) != 0) {
                log_event("Failed to close window.");
            }
            if (open_window(MOTOR_IN2) != 0) {
                log_event("Failed to open window.");
            }
        }

        // Wait for 60 seconds
        gpioDelay(60000);
    }

    // Cleanup
    gpioWrite(MOTOR_ENABLE, 0); // Ensure motor is off
    gpioTerminate();
    closelog();

    return 0;
}

