#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_LOCK_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define TIMEOUT_THRESHOLD 100 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Calibration factor
static float calibration_factor = 1.0;

// Function prototypes
int read_hx711(int data_pin, int clock_pin);
float calibrate_weight(int data_pin, int clock_pin, float known_weight);
void control_solenoid(int lock_pin, int state);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711(int data_pin, int clock_pin) {
    int i;
    int data = 0;
    int clock_high = 1;
    int clock_low = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for clock pin to go high
    while (gpioRead(clock_pin) == clock_high) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Sign extend if necessary
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate weight
float calibrate_weight(int data_pin, int clock_pin, float known_weight) {
    float raw_value = read_hx711(data_pin, clock_pin);
    float calibration_factor = (raw_value / known_weight) - 1.0;
    return calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int lock_pin, int state) {
    gpioWrite(lock_pin, state);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Unlock the solenoid
    control_solenoid(SOLENOID_LOCK_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_LOCK_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
