// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define relay state constants
#define RELAY_OFF 0
#define RELAY_ON 1

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int toggle_relay(int new_state);
int log_event(int relay_state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Toggle relay state
int toggle_relay(int new_state) {
    if (new_state == RELAY_OFF) {
        gpioWrite(RELAY_PIN, 1); // Turn relay ON
    } else if (new_state == RELAY_ON) {
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    }
    return 0;
}

// Log event to file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay: %s\n", timestamp, relay_state == RELAY_ON ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("relay_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Monitoring IR sensor and relay... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        int relay_state = RELAY_OFF; // Initialize to OFF

        if (sensor_value == 0) { // Obstacle detected
            printf("Obstacle detected!\n");
            relay_state = toggle_relay(relay_state);
            if (relay_state == RELAY_ON) {
                gpioWrite(RELAY_PIN, 1); // Turn relay ON
            } else if (relay_state == RELAY_OFF) {
                gpioWrite(RELAY_PIN, 0); // Turn relay OFF
            }
            if (log_event(relay_state) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Exiting.\n");
    return 0;
}

