    if (chip < 0) {
        fprintf(stderr, "Error opening chip %s: %d\n", chip_name, chip);
        return -1;
    }
    return chip;
}

// Function to request a GPIO line for input
int gpiod_line_request_input(int chip, int line, int direction) {
    int line_num = gpiod_chip_get_line_by_number(chip, line);
    if (line_num < 0) {
        fprintf(stderr, "Error getting line %d: %d\n", line, line_num);
        return -1;
    }

    int ret = gpiod_line_request_input(chip, line_num, direction);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %d\n", line, ret);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int gpiod_line_set_value(int chip, int line, int value) {
    int ret = gpiod_line_set_value(chip, line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting line %d to value %d: %d\n", line, value, ret);
        return -1;
    }
    return 0;
}

// Function to close a GPIO chip
int gpiod_chip_close(int chip) {
    int ret = gpiod_chip_close(chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing chip: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO line
int gpiod_line_get_value(int chip, int line) {
    int ret = gpiod_line_get_value(chip, line);
    if (ret < 0) {
        fprintf(stderr, "Error getting line %d value: %d\n", line, ret);
        return -1;
    }
    return ret;
}

// Function to log motion events to a file
void log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

