    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    int chip = gpiod_chip_open("gpiochip1");
    if (chip < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", chip);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Request the PIR sensor line for input
    if (gpiod_line_request_input(chip, PIR_GPIO, 1) < 0) {
        fprintf(stderr, "Error requesting PIR sensor line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Request the buzzer line for output
    if (gpiod_line_request_output(chip, BUZZER_GPIO, 1) < 0) {
        fprintf(stderr, "Error requesting buzzer line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the PIR sensor as input
    if (gpiod_line_set_value(chip, PIR_GPIO, 1) < 0) {
        fprintf(stderr, "Error setting PIR sensor line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read the PIR sensor value
        int pir_value = gpiod_line_get_value(chip, PIR_GPIO);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor value\n");
            break;
        }

        // Check for motion
        if (pir_value == 0) {
            // Activate the buzzer
            if (gpiod_line_set_value(chip, BUZZER_GPIO, 1) < 0) {
                fprintf(stderr, "Error activating buzzer\n");
                break;
            }

            // Log the motion event
            log_motion(time(NULL));

            // Wait for 2 seconds
            time_sleep(2.0);

            // Deactivate the buzzer
            if (gpiod_line_set_value(chip, BUZZER_GPIO, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer\n");
                break;
            }
        }

        // Delay to avoid busy-waiting
        time_sleep(0.1); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioTerminate();
    fclose(log_file);

    return 0;
}

