#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
int control_relay(int gpio_pin, int state);
int log_data(int lux_reading, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read illuminance from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int lux = -1;

    // Send measurement command (high resolution mode)
    if (i2cWriteByte(i2c_handle, 0x00) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // pigpio's delay function takes microseconds

    // Read two bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine the two bytes to form the lux value
    lux = (buf[0] << 8) | buf[1];

    return lux;
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO pin %d.\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int lux_reading, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux_reading, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int lux_reading = read_bh1750(i2c_handle);
        if (lux_reading >= 0) {
            int relay_state = control_relay(RELAY_GPIO, 1); // Turn relay ON
            log_data(lux_reading, relay_state);

            if (lux_reading < LUX_THRESHOLD) {
                printf("Lux reading: %d, Relay ON\n", lux_reading);
            } else {
                printf("Lux reading: %d, Relay OFF\n", lux_reading);
            }
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for 180ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // Turn relay OFF
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

