#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse width range
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define servo pulse width increment/decrement
#define PULSE_WIDTH_INCREMENT 50

// Define debounce delay
#define DEBOUNCE_DELAY 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_button(int gpio_pin);
int write_servo(int pulse_width);
void lock_servo();
void unlock_servo();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set lock button pin as input with pull-up resistor
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    // Set unlock button pin as input with pull-up resistor
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0;
}

// Function to read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to write servo pulse width
int write_servo(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return 1;
    }

    // Convert pulse width to microseconds
    int microseconds = (int)(pulse_width * 1000.0 / 2.0);

    // Write pulse width to servo
    gpioServo(SERVO_PIN, microseconds);

    return 0;
}

// Function to lock the servo
void lock_servo() {
    if (write_servo(1000) != 0) {
        fprintf(stderr, "Failed to lock servo\n");
    }
}

// Function to unlock the servo
void unlock_servo() {
    if (write_servo(2000) != 0) {
        fprintf(stderr, "Failed to unlock servo\n");
    }
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door Lock Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Debounce button presses
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to us

        if (lock_pressed) {
            lock_servo();
        } else if (unlock_pressed) {
            unlock_servo();
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup and exit
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    printf("Door Lock Program terminated.\n");
    return 0;
}

