#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <zmq.h>
#include <errno.h>

// Configuration
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT 5555
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define SOUND_THRESHOLD 500
#define ALARM_DURATION 1
#define SOUND_SENSOR_INTERVAL 10 // ms

// Global variables
static volatile int running = 1;
static int sockfd;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;
static struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio);
int read_sound_sensor(int gpio);
void publish_alert(const char *topic, int sound_detected);
void alarm_node_callback(void *context, void *socket, struct zmq_msg *msg, size_t msg_size);
void cleanup_gpio(int gpio);
void cleanup_gpio_chip(struct gpiod_chip *chip);
void cleanup_zeromq(void);
void signal_handler(int signum);

// Function to initialize a GPIO pin
int initialize_gpio(int gpio) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request_output(chip, line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output line %d for GPIO %d\n", gpio, gpio);
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_set_active(chip, line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line %d active for GPIO %d\n", gpio, gpio);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor(int gpio) {
    struct gpiod_line *line = gpiod_line_get(chip, gpio);
    struct gpiod_line_request *request = gpiod_line_request_get(chip, line, 1);
    struct gpiod_line_request *request_ptr = request;
    int ret;
    int value = 0;

    if (!line || !request) {
        fprintf(stderr, "Error: Could not get line or request for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request_request(request, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for GPIO %d\n", gpio, gpio);
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_request_set_active(request, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line %d active for GPIO %d\n", gpio, gpio);
        gpiod_line_release(line);
