#include <syslog.h>
#include <pthread.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "airflow_log.txt"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 12345
#define MAX_RETRIES 3
#define MAX_RETRIES_DELAY_MS 1000

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int flow_raw;
    float flow_slpm;
} SensorData;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor_data(int fd, int *flow_raw, float *flow_slpm);
void log_data(float flow_slpm);
void send_data_to_server(float flow_slpm);
void signal_handler(int sig);
void *sensor_thread(void *arg);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, int *flow_raw, float *flow_slpm) {
    char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < I2C_RETRY_COUNT) {
        bytes_read = read(fd, buf, 2);
        if (bytes_read == 2) {
            *flow_raw = (buf[0] << 8) | buf[1];
            *flow_slpm = (float)(*flow_raw) / 10.0; // Convert to SLPM
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C read failed, retrying (%d/%d): %s", retries + 1, I2C_RETRY_COUNT, strerror(errno));
            retries++;
            usleep(MAX_RETRIES_DELAY_MS * 1000); // Delay before retrying
        }
    }

    syslog(LOG_ERR, "I2C read failed after multiple retries: %s", strerror(errno));
    return -1; // Failure
}

// Function to log data to file
void log_data(float flow_slpm) {
    pthread_mutex_lock(&log_mutex);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, flow_slpm);
        fflush(log_file); // Ensure data is written immediately
    } else {
        syslog(LOG_ERR, "Log file is not open");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Function to send data to server
void send_data_to_server(float flow_slpm) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];
    int bytes_sent;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sockfd);
        return;
    }

    snprintf(buffer, sizeof(buffer), "%.2f", flow_slpm);
    bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Failed to send data to server: %s", strerror(errno));
    } else if (bytes_sent == 0) {
        syslog(LOG_WARNING, "Server disconnected before receiving data");
    } else {
        syslog(LOG_INFO, "Sent data to server: %s", buffer);
    }

    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Thread function for sensor data acquisition
void *sensor_thread(void *arg) {
    int flow_raw;
    float flow_slpm;
    while (program_running) {
        if (read_sensor_data(i2c_fd, &flow_raw, &flow_slpm) == 0) {
            log_data(flow_slpm);
            send_data_to_server(flow_slpm);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data, retrying...");
        }
        usleep(SAMPLE_INTERVAL_SEC * 1000); // Sleep for 1 second
    }
    return NULL;
}

int main() {
    // Initialize syslog
    openlog("airflow_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C, exiting");
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create sensor thread: %s", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup
    pthread_join(sensor_thread_id, NULL);
    fclose(log_file);
    close(i2c_fd);
    closelog();

    return 0;
}

