#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5000
#define I2C_SLAVE_ADDR 0x23
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float lux;
} sensor_data_t;

// Function prototypes
int open_i2c_device(const char *bus, int addr);
int read_bh1750(int fd, unsigned short *raw_value);
float convert_to_lux(unsigned short raw_value);
int send_udp_multicast(const char *address, const char *port, const char *multicast_addr, int ttl);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to open the I2C device
int open_i2c_device(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the BH1750 sensor
int read_bh1750(int fd, unsigned short *raw_value) {
    unsigned char cmd[2] = {0x10, 0x00}; // High resolution mode command
    unsigned char data[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, cmd, 2) != 2) {
            perror("Error writing to I2C device");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        if (read(fd, data, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        *raw_value = (data[0] << 8) | data[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send UDP multicast message
int send_udp_multicast(const char *address, const char *port, const char *multicast_addr, int ttl) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = inet_addr(multicast_addr);
    servaddr.sin_port = htons(port);

    if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, (char *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(SO_SNDTIMEO) failed");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)data, strlen(data), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open_i2c_device(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        unsigned short raw_value;
        float lux;

        // Read raw value from BH1750
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Convert raw value to lux
            lux = convert_to_lux(raw_value);

            // Send UDP multicast message
            if (send_udp_multicast(UDP_MULTICAST_ADDR, UDP_MULTICAST_PORT, UDP_MULTICAST_ADDR, 1) != 0) {
                fprintf(stderr, "Failed to send UDP multicast message.\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750.\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

