#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 1024
#define MAGIC_WORD_SIZE 4
#define MAGIC_WORD_OFFSET 0
#define DATA_OFFSET MAGIC_WORD_OFFSET + MAGIC_WORD_SIZE
#define DATA_SIZE (MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 4)

int uart_fd;
FILE *csv_file;

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range;
    float velocity;
} RadarData;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, char *buffer, int max_len);
int parse_tlv_data(const char *buffer, int buffer_len, RadarData *data);
int validate_tlv_data(const char *data, int data_len, int *range, float *velocity);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    uart_fd = serOpen(device, baud_rate, 0); // 0 for no flags
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return 0;
}

// Read UART data
int read_uart_data(int fd, char *buffer, int max_len) {
    int bytes_read = serRead(fd, buffer, max_len);
    if (bytes_read < 0) {
        log_error("Error reading from UART");
        return -1;
    }
    return bytes_read;
}

// Parse TLV data
int parse_tlv_data(const char *buffer, int buffer_len, RadarData *data) {
    int i;
    int tlv_len = buffer_len - DATA_OFFSET;

    if (tlv_len < (MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 4)) {
        log_error("TLV data too short to parse");
        return -1;
    }

    // Extract magic word
    if (memcmp(buffer + DATA_OFFSET, "0204", MAGIC_WORD_SIZE) != 0) {
        log_error("Invalid magic word");
        return -1;
    }
    if (memcmp(buffer + DATA_OFFSET + MAGIC_WORD_SIZE, "0306", MAGIC_WORD_SIZE) != 0) {
        log_error("Invalid magic word");
        return -1;
    }
    if (memcmp(buffer + DATA_OFFSET + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE, "0805", MAGIC_WORD_SIZE) != 0) {
        log_error("Invalid magic word");
        return -1;
    }
    if (memcmp(buffer + DATA_OFFSET + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE, "0709", MAGIC_WORD_SIZE) != 0) {
        log_error("Invalid magic word");
        return -1;
    }

    // Extract range and velocity
    memcpy(data, buffer + DATA_OFFSET + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE, sizeof(float) * 2);

    return 0;
}

// Validate TLV data
int validate_tlv_data(const char *data, int data_len, int *range, float *velocity) {
    if (data_len < (MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 4)) {
        log_error("TLV data too short to validate");
        return -1;
    }

    // Verify TLV type
    if (data[0] != 0x01) {
        log_error("Invalid TLV type");
        return -1;
    }

    // Verify TLV length
    if (data[1] != 0x02) {
        log_error("Invalid TLV length");
        return -1;
    }

    // Verify TLV length
    if (data[2] != 0x03) {
        log_error("Invalid TLV length");
        return -1;
    }

    // Verify TLV length
    if (data[3] != 0x04) {
        log_error("Invalid TLV length");
        return -1;
    }

    // Verify range
    if (*range < 0.1 || *range > 10.0) {
        log_error("Invalid range");
        return -1;
    }

    // Verify velocity
    if (*velocity < -10.0 || *velocity > 10.0) {
        log_error("Invalid velocity");
        return -1;
    }

    return 0;
}

// Log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    RadarData radar_data;
    char buffer[BUFFER_SIZE];
    int bytes_read;
    int range, velocity;

    // Register signal handlers
