#include <sys/stat.h>
#include <sys/types.h>
#include <sys/errno.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define INTER_BYTE_TIMEOUT 200 // milliseconds
#define MAX_LINE_LENGTH 1024
#define MAX_BUFFER_SIZE (MAX_LINE_LENGTH + 100) // 100 bytes for header + buffer
#define MAX_RETRIES 3
#define TIMEOUT_US 200000 // 200ms

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    float range;
} RadarData;

// Global variables
int uart_fd = -1;
RadarData line_buffer[MAX_BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int open_uart(const char *device, speed_t baud_rate);
int configure_uart(int fd);
int read_uart(int fd, char *buffer, int max_len);
int parse_radar_data(const char *buffer, int len);
void log_radar_data(const RadarData *data);
void signal_handler(int sig);
void cleanup();

// Function to open the UART
int open_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD; // 8N1, no parity, ignore modem control lines
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0; // Read doesn't block
    tty.c_cc[VTIME] = 0; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the UART
int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 115200 baud, 8N1, ignore modem control lines
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_oflag = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        return -1;
    }

    return 0;
}

// Function to read data from the UART
int read_uart(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_US / 1000;
    timeout.tv_usec = (TIMEOUT_US % 1000) * 1000;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        bytes_read = read(fd, buffer, max_len);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        } else {
            return 0;
        }
    }
}

// Function to parse radar data
int parse_radar_data(const char *buffer, int len) {
    if (len < 2) {
        return 0; // Not enough data for a valid line
    }

    char *token = strtok(buffer, ",");
    if (token == NULL) {
        return 0; // Invalid line format
    }

    if (sscanf(token, "%lf", &line_buffer[buffer_index].range) != 1) {
        return 0; // Invalid range value
    }

    buffer_index++;
    if (buffer_index == MAX_BUFFER_SIZE) {
        buffer_count = 0;
        buffer_index = 0;
    }

    return 1;
}

// Function to log radar data
void log_radar_data(const RadarData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Range: %.2f meters\n", timestamp, data->range);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

// Cleanup function to close the UART and terminate the program
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    printf("UART closed.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the UART
    uart_fd = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to open UART. Exiting.\n");
        return 1;
    }

    // Configure the UART
    if (configure_uart(uart_fd) == -1) {
        fprintf(stderr, "Failed to configure UART. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("UART opened successfully. Reading data...\n");

    // Main loop
    while (program_running) {
        char buffer[MAX_LINE_LENGTH];
        int bytes_read;

        // Read data from the UART
        bytes_read = read_uart(uart_fd, buffer, MAX_LINE_LENGTH);
        if (bytes_read > 0) {
            // Parse the data
            RadarData radar_data;
            if (parse_radar_data(buffer, bytes_read) == 1) {
                // Log the data
                log_radar_data(&radar_data);
                printf("Radar data: Range = %.2f meters\n", radar_data.range);
            } else {
                fprintf(stderr, "Failed to parse radar data.\n");
            }
        } else if (bytes_read == 0) {
            // Timeout occurred
            printf("Timeout occurred.\n");
        } else {
            // Error reading from UART
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Add to the buffer
        line_buffer[buffer_index].timestamp = time(NULL);
        line_buffer[buffer_index].range = radar_data.range;
        buffer_index++;
        if (buffer_index == MAX_BUFFER_SIZE) {
            buffer_count = 0;
            buffer_index = 0;
        }

        usleep(INTER_BYTE_TIMEOUT * 1000); // Check for data availability
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

